def configure_text_streams() -> None:
    """Prevent Windows codepage failures from killing the measurement worker."""
    for stream in (sys.stdout, sys.stderr):
        try:
            stream.reconfigure(encoding="utf-8", errors="replace")
        except Exception:
            pass


