def _finite_float_or_none(value) -> float | None:
    try:
        value = float(value)
    except (TypeError, ValueError):
        return None
    return value if math.isfinite(value) else None


def validate_smu_compliance_a(value) -> float:
    """Return a safe SMU compliance value expressed in amperes."""
    compliance_a = _finite_float_or_none(value)
    if compliance_a is None or compliance_a <= 0.0:
        raise ValueError("SMU compliance current must be finite and greater than zero.")
    return float(compliance_a)


def smu_compliance_a_from_ma(value) -> float:
    """Convert the operator-facing milliamperes setting to instrument amperes."""
    compliance_ma = _finite_float_or_none(value)
    if compliance_ma is None or compliance_ma <= 0.0:
        raise ValueError(
            "SMU compliance current must be a finite number greater than zero mA."
        )
    return validate_smu_compliance_a(float(compliance_ma) * 1e-3)


def _wrap180(angle_deg: float) -> float:
    return float(angle_deg) % 180.0


def _load_lab_angle_mapping(path: Path) -> dict | None:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        axis_ref = data["calibrated_lab_axis_reference"]
        raw = axis_ref["raw_setpoints_deg"]
        signs = data.get("raw_to_lab_formulas", {}).get("signs", {})
        mapping = {
            "path": str(path.resolve()),
            "created_at": data.get("created_at"),
            "trusted": bool(data.get("trusted", False)),
            "trusted_reason": data.get("trusted_reason", ""),
            "calibration_json_path": data.get("calibration_json_path"),
            "source_calibration_json": data.get("source_calibration_json"),
            "H_y_raw": float(raw["HWP_incident_y"]),
            "Q_y_raw": float(raw["QWP_axis_y"]),
            "A_y_raw": float(raw["ANL_transmit_y"]),
            "s_H": int(signs.get("s_H", 1)),
            "s_Q": int(signs.get("s_Q", 1)),
            "s_A": int(signs.get("s_A", 1)),
        }
        for key in ("s_H", "s_Q", "s_A"):
            if mapping[key] not in (-1, 1):
                mapping[key] = 1
        return mapping
    except Exception as exc:
        print(f"[WARN] Lab-frame angle mapping unavailable ({path}): {type(exc).__name__}: {exc}")
        return None


LAB_ANGLE_MAPPING = _load_lab_angle_mapping(Path(__file__).with_name(LAB_MAPPING_JSON))


def legacy_theta_i_from_hwp(hwp_deg: float) -> float:
    raw = _finite_float_or_none(hwp_deg)
    if raw is None:
        return float("nan")
    return float(2.0 * raw) % 180.0


def lab_theta_i_from_hwp(hwp_deg: float) -> float:
    raw = _finite_float_or_none(hwp_deg)
    if raw is None:
        return float("nan")
    mapping = LAB_ANGLE_MAPPING
    if not mapping:
        return legacy_theta_i_from_hwp(raw)
    return _wrap180(90.0 + 2.0 * mapping["s_H"] * (raw - mapping["H_y_raw"]))


def raw_hwp_from_lab_theta_i(theta_i_deg: float) -> float:
    lab = _finite_float_or_none(theta_i_deg)
    if lab is None:
        return float("nan")
    mapping = LAB_ANGLE_MAPPING
    if not mapping:
        raise RuntimeError(
            f"Lab-frame HWP sweep requested, but {LAB_MAPPING_JSON} could not be loaded."
        )
    raw = mapping["H_y_raw"] + mapping["s_H"] * (lab - 90.0) / 2.0
    wrapped = wrap360(raw)
    # Avoid representing a floating-point underflow below zero as 360 deg.
    # This matters for calibrated presets that deliberately target raw 0 deg.
    if math.isclose(wrapped, 0.0, rel_tol=0.0, abs_tol=1e-9) or math.isclose(
        wrapped, 360.0, rel_tol=0.0, abs_tol=1e-9
    ):
        return 0.0
    return wrapped


def hwp_grid_preset_settings(preset_name: str) -> dict | None:
    """Return CLI-compatible HWP fields for a named GUI quick preset."""
    name = str(preset_name or "").strip()
    if name == HWP_GRID_PRESET_CURRENT:
        return {
            "hwp_input_frame": "lab",
            "hwp_sweep_mode": DEFAULT_HWP_SWEEP_MODE,
            "hwp_start": lab_theta_i_from_hwp(DEFAULT_HWP_GRID_CENTER_RAW_DEG),
            "hwp_stop": 165.0,
            "hwp_step": 15.0,
            "hwp_center_step": DEFAULT_HWP_CENTER_THETA_STEP_DEG,
            "hwp_points": DEFAULT_HWP_CENTER_SWEEP_POINTS,
        }
    if name not in (
        HWP_GRID_PRESET_20260515_INTERPOLATED_9,
        HWP_GRID_PRESET_20260515,
    ):
        return None

    mapping = LAB_ANGLE_MAPPING
    if not mapping:
        raise RuntimeError(
            f"The 15 May comparison preset needs {LAB_MAPPING_JSON} so its old "
            "raw HWP positions can be expressed in the current lab convention."
        )

    raw_start = HWP_COMPARISON_20260515_RAW_START_DEG
    raw_stop = HWP_COMPARISON_20260515_RAW_STOP_DEG
    if name == HWP_GRID_PRESET_20260515_INTERPOLATED_9:
        point_count = HWP_COMPARISON_20260515_INTERPOLATED_POINTS
        raw_step = (raw_stop - raw_start) / (point_count - 1)
    else:
        raw_step = HWP_COMPARISON_20260515_RAW_STEP_DEG
        point_count = int(round((raw_stop - raw_start) / raw_step)) + 1
    sign = float(mapping["s_H"])
    hwp_y_raw = float(mapping["H_y_raw"])

    # Keep theta_i unwrapped across 180 degrees.  A monotonic unwrapped lab
    # start/stop grid round-trips through raw_hwp_from_lab_theta_i() to the
    # exact old physical sequence, including its acquisition order.
    lab_start = 90.0 + 2.0 * sign * (raw_start - hwp_y_raw)
    lab_stop = 90.0 + 2.0 * sign * (raw_stop - hwp_y_raw)
    lab_step = 2.0 * sign * raw_step
    return {
        "hwp_input_frame": "lab",
        "hwp_sweep_mode": "start-stop",
        "hwp_start": round(lab_start, 6),
        "hwp_stop": round(lab_stop, 6),
        "hwp_step": round(lab_step, 6),
        "hwp_center_step": abs(round(lab_step, 6)),
        "hwp_points": point_count,
    }


def qwp_axis_lab_from_raw(qwp_deg: float) -> float:
    raw = _finite_float_or_none(qwp_deg)
    if raw is None:
        return float("nan")
    mapping = LAB_ANGLE_MAPPING
    if not mapping:
        return float("nan")
    return _wrap180(90.0 + mapping["s_Q"] * (raw - mapping["Q_y_raw"]))


def analyser_lab_from_raw(anl_deg: float) -> float:
    raw = _finite_float_or_none(anl_deg)
    if raw is None:
        return float("nan")
    mapping = LAB_ANGLE_MAPPING
    if not mapping:
        return float("nan")
    return _wrap180(90.0 + mapping["s_A"] * (raw - mapping["A_y_raw"]))


def _theta_i_for_paper_convention(hwp_deg: float | None = None, theta_i_deg: float | None = None) -> float:
    theta_i = _finite_float_or_none(theta_i_deg)
    if theta_i is not None:
        return _wrap180(theta_i)
    return lab_theta_i_from_hwp(hwp_deg)


def qwp_theta_wav_from_raw(
    qwp_deg: float,
    hwp_deg: float | None = None,
    theta_i_deg: float | None = None,
) -> float:
    """Paper convention: QWP axis relative to incident linear polarization."""
    qwp_lab = qwp_axis_lab_from_raw(qwp_deg)
    theta_i = _theta_i_for_paper_convention(hwp_deg, theta_i_deg)
    if not (math.isfinite(float(qwp_lab)) and math.isfinite(float(theta_i))):
        return float("nan")
    return _wrap180(float(qwp_lab) - float(theta_i))


def analyser_theta_ana_from_lab(analyser_axis_lab_deg: float, theta_i_deg: float) -> float:
    """Paper convention: theta_ANA=0 when the analyser blocks the incident beam."""
    axis_lab = _finite_float_or_none(analyser_axis_lab_deg)
    theta_i = _theta_i_for_paper_convention(theta_i_deg=theta_i_deg)
    if axis_lab is None or not math.isfinite(float(theta_i)):
        return float("nan")
    return _wrap180(float(axis_lab) - float(theta_i) - 90.0)


def analyser_theta_ana_from_raw(
    anl_deg: float,
    hwp_deg: float | None = None,
    theta_i_deg: float | None = None,
) -> float:
    """Paper convention: analyser angle relative to crossed/blocked condition."""
    return analyser_theta_ana_from_lab(analyser_lab_from_raw(anl_deg), _theta_i_for_paper_convention(hwp_deg, theta_i_deg))


def lab_angle_mapping_config() -> dict:
    if not LAB_ANGLE_MAPPING:
        return {
            "mode": "legacy_uncalibrated",
            "theta_i_deg": "2 * HWP_raw modulo 180",
            "mapping_path": str(Path(__file__).with_name(LAB_MAPPING_JSON)),
        }
    return {
        "mode": "calibrated_lab_frame",
        "mapping_path": LAB_ANGLE_MAPPING.get("path"),
        "created_at": LAB_ANGLE_MAPPING.get("created_at"),
        "trusted": LAB_ANGLE_MAPPING.get("trusted"),
        "trusted_reason": LAB_ANGLE_MAPPING.get("trusted_reason"),
        "calibration_json_path": LAB_ANGLE_MAPPING.get("calibration_json_path"),
        "source_calibration_json": LAB_ANGLE_MAPPING.get("source_calibration_json"),
        "raw_references_deg": {
            "HWP_incident_y": LAB_ANGLE_MAPPING["H_y_raw"],
            "QWP_axis_y": LAB_ANGLE_MAPPING["Q_y_raw"],
            "ANL_transmit_y": LAB_ANGLE_MAPPING["A_y_raw"],
        },
        "signs": {
            "s_H": LAB_ANGLE_MAPPING["s_H"],
            "s_Q": LAB_ANGLE_MAPPING["s_Q"],
            "s_A": LAB_ANGLE_MAPPING["s_A"],
        },
        "formulas": {
            "theta_i_deg": "wrap180(90 + 2*s_H*(H_raw - H_y_raw))",
            "hwp_raw_from_theta_i_deg": "wrap360(H_y_raw + s_H*(theta_i - 90)/2)",
            "qwp_axis_lab_deg": "wrap180(90 + s_Q*(Q_raw - Q_y_raw))",
            "analyser_lab_deg": "wrap180(90 + s_A*(A_raw - A_y_raw))",
            "theta_WAV_deg": "wrap180(qwp_axis_lab_deg - theta_i_deg)",
            "theta_ANA_deg": "wrap180(analyser_lab_deg - theta_i_deg - 90); 0=blocked/crossed, 90=parallel",
        },
    }


def lab_angle_mapping_label() -> str:
    if not LAB_ANGLE_MAPPING:
        return "legacy uncalibrated HWP theta_i=2*raw"
    path = Path(str(LAB_ANGLE_MAPPING.get("path", LAB_MAPPING_JSON))).name
    trusted = "trusted" if LAB_ANGLE_MAPPING.get("trusted") else "untrusted"
    return f"{path} ({trusted})"


def add_lab_angles_to_gui_updates(updates: dict) -> dict:
    augmented = dict(updates)
    angle_fields = (
        ("current_hwp_deg", "current_hwp_lab_theta_i_deg", lab_theta_i_from_hwp),
        ("current_hwp_target_deg", "current_hwp_target_lab_theta_i_deg", lab_theta_i_from_hwp),
        ("current_hwp_null_deg", "current_hwp_null_lab_theta_i_deg", lab_theta_i_from_hwp),
        ("current_qwp_deg", "current_qwp_lab_axis_deg", qwp_axis_lab_from_raw),
        ("current_qwp_target_deg", "current_qwp_target_lab_axis_deg", qwp_axis_lab_from_raw),
        ("current_qwp_null_deg", "current_qwp_null_lab_axis_deg", qwp_axis_lab_from_raw),
        ("current_anl_deg", "current_anl_lab_deg", analyser_lab_from_raw),
        ("current_anl_target_deg", "current_anl_target_lab_deg", analyser_lab_from_raw),
        ("current_anl_null_deg", "current_anl_null_lab_deg", analyser_lab_from_raw),
    )
    for raw_key, lab_key, converter in angle_fields:
        if raw_key not in augmented:
            continue
        lab_value = converter(augmented.get(raw_key))
        augmented[lab_key] = float(lab_value) if math.isfinite(float(lab_value)) else None
    theta_i_current = _finite_float_or_none(augmented.get("current_hwp_lab_theta_i_deg"))
    if theta_i_current is None:
        theta_i_current = _finite_float_or_none(lab_theta_i_from_hwp(augmented.get("current_hwp_deg")))
    theta_i_target = _finite_float_or_none(augmented.get("current_hwp_target_lab_theta_i_deg"))
    if theta_i_target is None:
        theta_i_target = theta_i_current
    paper_fields = (
        ("current_qwp_deg", "current_qwp_theta_wav_deg", qwp_theta_wav_from_raw, theta_i_current),
        ("current_qwp_target_deg", "current_qwp_target_theta_wav_deg", qwp_theta_wav_from_raw, theta_i_target),
        ("current_qwp_null_deg", "current_qwp_null_theta_wav_deg", qwp_theta_wav_from_raw, theta_i_current),
        ("current_anl_deg", "current_anl_theta_ana_deg", analyser_theta_ana_from_raw, theta_i_current),
        ("current_anl_target_deg", "current_anl_target_theta_ana_deg", analyser_theta_ana_from_raw, theta_i_target),
        ("current_anl_null_deg", "current_anl_null_theta_ana_deg", analyser_theta_ana_from_raw, theta_i_current),
    )
    for raw_key, paper_key, converter, theta_i in paper_fields:
        if raw_key not in augmented:
            continue
        paper_value = converter(augmented.get(raw_key), theta_i_deg=theta_i)
        augmented[paper_key] = float(paper_value) if math.isfinite(float(paper_value)) else None
    return augmented


GUI_ALIGNMENT_STATE: dict = {
    "active": False,
    "pixel": None,
    "points": [],
}
GUI_ALIGNMENT_TRACKER: dict = {
    "installed": False,
    "active": False,
    "pixel": None,
    "phase": "",
    "last_x_mm": None,
    "last_y_mm": None,
    "last_axis": "",
    "point_index": 0,
}


def resolve_hardcoded_gds_image() -> Path | None:
    return next((path for path in HARDCODED_GDS_IMAGE_PATHS if path.exists()), None)


def gui_update_state(**updates) -> None:
    updates = add_lab_angles_to_gui_updates(updates)
    GUI_STATE.update(updates)
    GUI_STATE["updated"] = datetime.now().isoformat()
    GUI_STATE["updated_ts"] = time.time()
    if GUI_STATE_FILE is None:
        return
    try:
        GUI_STATE_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = GUI_STATE_FILE.with_suffix(".tmp.json")
        tmp.write_text(json.dumps(GUI_STATE, indent=2), encoding="utf-8")
        os.replace(str(tmp), str(GUI_STATE_FILE))
    except Exception:
        pass


def gui_write_alignment_state(**updates) -> None:
    if GUI_ALIGNMENT_FILE is None:
        return
    GUI_ALIGNMENT_STATE.update(updates)
    GUI_ALIGNMENT_STATE["updated"] = datetime.now().isoformat()
    try:
        GUI_ALIGNMENT_FILE.parent.mkdir(parents=True, exist_ok=True)
        tmp = GUI_ALIGNMENT_FILE.with_suffix(".tmp.json")
        tmp.write_text(json.dumps(GUI_ALIGNMENT_STATE, indent=2), encoding="utf-8")
        os.replace(str(tmp), str(GUI_ALIGNMENT_FILE))
    except Exception:
        pass


def gui_update_laser_state(status: str | None = None) -> None:
    payload = {
        "laser_on": bool(GUI_LASER_ON),
        "laser_available": GUI_LASER is not None,
        "laser_power_mW": float(GUI_LASER_POWER_MW),
        "laser_serial": GUI_LASER_SERIAL,
    }
    if status is not None:
        payload["laser_status"] = status
    gui_update_state(**payload)


def gui_laser_set_power(power_mw: float) -> None:
    global GUI_LASER_POWER_MW
    power = float(power_mw)
    if not np.isfinite(power) or power < 0.0:
        raise ValueError(f"Invalid laser power: {power_mw!r}")
    GUI_LASER_POWER_MW = power
    if GUI_LASER is None:
        gui_update_laser_state(f"Laser unavailable; setpoint {power:g} mW")
        return
    with GUI_LASER_LOCK:
        GUI_LASER.set_power_absolute(power)
    gui_update_laser_state(f"Laser power set to {power:g} mW")


def gui_laser_set_output(on: bool) -> None:
    global GUI_LASER_ON
    if GUI_LASER is None:
        GUI_LASER_ON = False
        gui_update_laser_state("Laser unavailable")
        return
    with GUI_LASER_LOCK:
        if on:
            GUI_LASER.on()
            GUI_LASER_ON = True
            gui_update_laser_state(f"Laser ON @ {GUI_LASER_POWER_MW:g} mW")
        else:
            GUI_LASER.off()
            GUI_LASER_ON = False
            gui_update_laser_state("Laser OFF")


def gui_connect_laser(args):
    global GUI_LASER, GUI_LASER_ON, GUI_LASER_POWER_MW, GUI_LASER_SERIAL
    GUI_LASER = None
    GUI_LASER_ON = False
    GUI_LASER_POWER_MW = float(args.laser_power_mw)
    GUI_LASER_SERIAL = str(args.laser_serial or "")
    gui_update_laser_state("Laser disabled" if not args.use_laser else "Connecting KLS1550")
    if not args.use_laser:
        return None
    if KLS1550 is None:
        gui_update_laser_state("KLS1550 driver unavailable")
        print("[LASER] KLS1550 driver unavailable; continuing without laser control.")
        return None
    laser = None
    try:
        serial = GUI_LASER_SERIAL or KLS1550.find_first()
        if not serial:
            gui_update_laser_state("No KLS1550 found")
            print("[LASER] No KLS1550 found; continuing without laser control.")
            return None
        laser = KLS1550(serial)
        laser.connect()
        GUI_LASER = laser
        GUI_LASER_SERIAL = str(serial)
        gui_laser_set_power(GUI_LASER_POWER_MW)
        if args.laser_on_start:
            gui_laser_set_output(True)
        else:
            gui_update_laser_state(f"Laser ready OFF @ {GUI_LASER_POWER_MW:g} mW")
        print(
            f"[LASER] KLS1550 connected ({GUI_LASER_SERIAL}); "
            f"setpoint {GUI_LASER_POWER_MW:g} mW; output {'ON' if GUI_LASER_ON else 'OFF'}."
        )
        return laser
    except Exception as exc:
        if laser is not None:
            try:
                laser.close()
            except Exception:
                pass
        GUI_LASER = None
        GUI_LASER_ON = False
        gui_update_laser_state(f"Laser unavailable: {type(exc).__name__}")
        print(f"[LASER] Could not open KLS1550 ({type(exc).__name__}: {exc}); continuing without laser control.")
        return None


def gui_process_laser_command() -> None:
    global GUI_LASER_COMMAND_MTIME
    path = GUI_LASER_COMMAND_FILE
    if path is None:
        return
    try:
        mtime = path.stat().st_mtime
    except FileNotFoundError:
        return
    except Exception:
        return
    if mtime <= GUI_LASER_COMMAND_MTIME:
        return
    GUI_LASER_COMMAND_MTIME = mtime
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception as exc:
        gui_update_laser_state(f"Bad laser command: {type(exc).__name__}")
        return
    command = str(data.get("command", "") or "").strip().lower()
    power = data.get("power_mw")
    try:
        if command == "set_power":
            gui_laser_set_power(float(power))
        elif command == "on":
            if power is not None:
                gui_laser_set_power(float(power))
            gui_laser_set_output(True)
        elif command == "off":
            gui_laser_set_output(False)
        elif command == "toggle":
            gui_laser_set_output(not GUI_LASER_ON)
        else:
            gui_update_laser_state(f"Unknown laser command: {command or 'blank'}")
    except Exception as exc:
        gui_update_laser_state(f"Laser command failed: {type(exc).__name__}")
        print(f"[LASER] Command failed ({type(exc).__name__}: {exc})")


def gui_cleanup_laser() -> None:
    global GUI_LASER, GUI_LASER_ON
    laser = GUI_LASER
    if laser is None:
        return
    with GUI_LASER_LOCK:
        try:
            laser.off()
        except Exception:
            pass
        GUI_LASER_ON = False
        try:
            laser.close()
        except Exception:
            pass
        GUI_LASER = None
    gui_update_laser_state("Laser OFF + closed")


def gui_alignment_reset(pixel: int, nominal_x_mm=None, nominal_y_mm=None) -> None:
    GUI_ALIGNMENT_STATE.clear()
    GUI_ALIGNMENT_STATE.update({
        "active": True,
        "pixel": int(pixel),
        "nominal_x_mm": nominal_x_mm,
        "nominal_y_mm": nominal_y_mm,
        "points": [],
        "best": None,
        "started": datetime.now().isoformat(),
    })
    GUI_ALIGNMENT_TRACKER.update({
        "active": True,
        "pixel": int(pixel),
        "phase": "alignment",
        "last_x_mm": nominal_x_mm,
        "last_y_mm": nominal_y_mm,
        "last_axis": "",
        "point_index": 0,
    })
    gui_write_alignment_state()


def gui_alignment_add_point(voltage_v, *, label: str = "") -> None:
    if not GUI_ALIGNMENT_TRACKER.get("active"):
        return
    x_mm = GUI_ALIGNMENT_TRACKER.get("last_x_mm")
    y_mm = GUI_ALIGNMENT_TRACKER.get("last_y_mm")
    if x_mm is None and y_mm is None:
        return
    try:
        v = float(voltage_v)
    except Exception:
        v = float("nan")
    GUI_ALIGNMENT_TRACKER["point_index"] = int(GUI_ALIGNMENT_TRACKER.get("point_index", 0)) + 1
    point = {
        "index": int(GUI_ALIGNMENT_TRACKER["point_index"]),
        "x_mm": x_mm,
        "y_mm": y_mm,
        "axis": GUI_ALIGNMENT_TRACKER.get("last_axis", ""),
        "label": label or GUI_ALIGNMENT_TRACKER.get("phase", ""),
        "voltage_v": v,
        "voltage_mV": v * 1000.0 if np.isfinite(v) else float("nan"),
        "timestamp": time.time(),
    }
    points = GUI_ALIGNMENT_STATE.setdefault("points", [])
    points.append(point)
    if len(points) > 800:
        del points[:len(points) - 800]
    best = GUI_ALIGNMENT_STATE.get("best")
    if best is None or (np.isfinite(v) and v > float(best.get("voltage_v", -float("inf")))):
        GUI_ALIGNMENT_STATE["best"] = point
    gui_write_alignment_state(active=True)
    gui_update_state(
        phase="Stage alignment",
        alignment_point_index=point["index"],
        alignment_voltage_mV=point["voltage_mV"],
    )


def install_gui_alignment_export(detector, alignment_file: Path | None) -> None:
    global GUI_ALIGNMENT_FILE
    GUI_ALIGNMENT_FILE = alignment_file
    if alignment_file is None or getattr(detector, "_gui_alignment_export", False):
        return

    original_move = stage._safe_scan_move

    def gui_safe_scan_move(device, target_mm, label=""):
        gui_pixel_checkpoint()
        result = original_move(device, target_mm, label)
        if GUI_ALIGNMENT_TRACKER.get("active"):
            upper_label = str(label).upper()
            axis = (
                "X" if upper_label.startswith("X") or upper_label.endswith("-X") or "-X-" in upper_label
                else "Y" if upper_label.startswith("Y") or upper_label.endswith("-Y") or "-Y-" in upper_label
                else ""
            )
            try:
                pos = float(result)
            except Exception:
                try:
                    pos = float(target_mm)
                except Exception:
                    pos = None
            if axis == "X":
                GUI_ALIGNMENT_TRACKER["last_x_mm"] = pos
            elif axis == "Y":
                GUI_ALIGNMENT_TRACKER["last_y_mm"] = pos
            if axis:
                GUI_ALIGNMENT_TRACKER["last_axis"] = axis
            GUI_ALIGNMENT_TRACKER["phase"] = str(label)
            gui_write_alignment_state(
                active=True,
                current_label=str(label),
                current_x_mm=GUI_ALIGNMENT_TRACKER.get("last_x_mm"),
                current_y_mm=GUI_ALIGNMENT_TRACKER.get("last_y_mm"),
            )
        gui_pixel_checkpoint()
        return result

    if not getattr(original_move, "_gui_alignment_export", False):
        gui_safe_scan_move._gui_alignment_export = True
        stage._safe_scan_move = gui_safe_scan_move

    original_read_averaged = getattr(detector, "read_averaged", None)
    if original_read_averaged is not None:
        def gui_read_averaged(*args, **kwargs):
            gui_pixel_checkpoint()
            result = original_read_averaged(*args, **kwargs)
            try:
                mean_v = result[0]
                power_w = result[2]
                if mean_v is not None:
                    gui_update_state(
                        detector_mV=float(mean_v) * 1e3,
                        detector_power_W=float(power_w) if power_w is not None else float("nan"),
                        active_optic="DETECTOR",
                    )
            except Exception:
                pass
            if GUI_ALIGNMENT_TRACKER.get("active"):
                try:
                    voltage_v = result[0]
                except Exception:
                    voltage_v = None
                if voltage_v is not None:
                    gui_alignment_add_point(voltage_v)
            gui_pixel_checkpoint()
            return result

        detector.read_averaged = gui_read_averaged

    GUI_ALIGNMENT_TRACKER["installed"] = True
    detector._gui_alignment_export = True


def install_gui_rotator_export(rot_hwp, rot_qwp, rot_anl) -> None:
    """Stream rotator moves to the PLC panel without changing the move logic."""
    for rot, name, prefix in (
        (rot_hwp, "HWP", "hwp"),
        (rot_qwp, "QWP", "qwp"),
        (rot_anl, "ANL", "anl"),
    ):
        if rot is None or getattr(rot, "_gui_state_set_angle_wrapped", False):
            continue
        original_set_angle = getattr(rot, "set_angle", None)
        if original_set_angle is None:
            continue

        def gui_set_angle(target, *args, _name=name, _prefix=prefix, _original=original_set_angle, **kwargs):
            try:
                target_deg = wrap360(float(target))
            except Exception:
                target_deg = float("nan")
            gui_update_state(
                **{
                    "active_optic": _name,
                    f"current_{_prefix}_target_deg": target_deg,
                    "phase": f"Moving {_name}",
                }
            )
            result = _original(target, *args, **kwargs)
            gui_update_state(
                **{
                    "active_optic": _name,
                    f"current_{_prefix}_deg": target_deg,
                    f"current_{_prefix}_target_deg": target_deg,
                    "phase": f"{_name} move complete",
                }
            )
            return result

        try:
            rot.set_angle = gui_set_angle
            rot._gui_state_set_angle_wrapped = True
        except Exception:
            pass


def gui_scope_live_read(
    detector,
    *,
    phase: str | None = None,
    live_view=None,
) -> bool:
    """Export a fast detector sample without stealing the scope from measurements."""
    if detector is None or not hasattr(detector, "read_voltage"):
        return False
    # ``install_gui_camera_export`` replaces ``LiveView.tick``.  The original
    # tick respected LiveView.pause_scope_reads(), but the replacement used to
    # bypass that flag and issue scope VISA reads from the GUI/main thread
    # while a measurement worker was commanding other VISA instruments.  The
    # pause is an ownership boundary, not merely a display preference.
    if live_view is not None and bool(getattr(live_view, "_scope_paused", False)):
        return False
    lock = getattr(detector, "_lock", None)
    locked = False
    if lock is not None:
        try:
            locked = lock.acquire(blocking=False)
        except TypeError:
            locked = lock.acquire(False)
        except Exception:
            locked = False
        if not locked:
            return False
    try:
        # Recheck after taking the detector lock so a pause requested while we
        # were entering cannot leak one final GUI-owned VISA transaction into
        # an exclusive measurement window.
        if live_view is not None and bool(getattr(live_view, "_scope_paused", False)):
            return False
        v = detector.read_voltage(retries=0)
        if v is None:
            return False
        dark = float(getattr(stage, "DARK_VOLTAGE_OFFSET", 0.0))
        v_to_w = float(getattr(stage, "V_TO_W", 1.0))
        payload = {
            "detector_mV": float(v) * 1e3,
            "detector_power_W": (float(v) - dark) * v_to_w,
            "scope_live": True,
            "scope_live_updated": time.time(),
        }
        if phase:
            payload["scope_live_phase"] = phase
        gui_update_state(**payload)
        return True
    except Exception:
        return False
    finally:
        if lock is not None and locked:
            try:
                lock.release()
            except Exception:
                pass


def gui_align_and_capture_pixel(*args, **kwargs):
    pixel = args[1] if len(args) > 1 else kwargs.get("pixel")
    pix_num = int(pixel.get("pixel", 0)) if isinstance(pixel, dict) else 0
    gui_alignment_reset(
        pix_num,
        pixel.get("nominal_x_motor") if isinstance(pixel, dict) else None,
        pixel.get("nominal_y_motor") if isinstance(pixel, dict) else None,
    )
    gui_update_state(current_pixel=pix_num, phase="Stage alignment", alignment_point_index=0)
    try:
        kwargs["transport_error_handler"] = raise_if_fatal_hardware_transport_error
        result = auto.align_and_capture_pixel(*args, **kwargs)
        best = GUI_ALIGNMENT_STATE.get("best") or {}
        gui_write_alignment_state(active=False, completed=datetime.now().isoformat())
        gui_update_state(
            current_pixel=pix_num,
            phase="Stage alignment complete",
            alignment_voltage_mV=best.get("voltage_mV"),
        )
        return result
    except Exception:
        gui_write_alignment_state(active=False, failed=datetime.now().isoformat())
        raise
    finally:
        GUI_ALIGNMENT_TRACKER["active"] = False


def gui_stop_requested() -> bool:
    return GUI_STOP_FILE is not None and GUI_STOP_FILE.exists()


class SkipPixelRequested(BaseException):
    """Control-flow signal: clean up this pixel and continue with the next one.

    This deliberately inherits from ``BaseException`` so acquisition helpers
    cannot accidentally turn an operator skip into a warning via a broad
    ``except Exception`` handler.
    """


def gui_skip_requested() -> bool:
    if GUI_SKIP_FILE is None or not GUI_SKIP_FILE.exists():
        return False

    # The GUI tags every skip request with the pixel that was active when the
    # button was pressed.  Reject a late/stale request instead of allowing it
    # to leak into the next pixel.
    try:
        payload = json.loads(GUI_SKIP_FILE.read_text(encoding="utf-8"))
    except Exception:
        # Never let an untagged/malformed file skip an arbitrary later pixel.
        # The GUI writes atomically, so a valid request is always a JSON object.
        gui_clear_skip_request()
        return False
    if not isinstance(payload, dict):
        gui_clear_skip_request()
        return False

    requested_pixel = payload.get("current_pixel")
    active_pixel = GUI_STATE.get("current_pixel")
    try:
        requested_pixel = int(requested_pixel)
        active_pixel = int(active_pixel)
    except (TypeError, ValueError):
        gui_clear_skip_request()
        return False

    if requested_pixel > 0 and active_pixel > 0 and requested_pixel != active_pixel:
        print(
            f"  [GUI-CHILD] Discarding stale skip request for pixel "
            f"{requested_pixel:03d}; active pixel is {active_pixel:03d}.",
            flush=True,
        )
        gui_clear_skip_request()
        return False
    return True


def gui_manual_probe_confirmed(pixel: int) -> bool:
    if GUI_MANUAL_PROBE_FILE is None or not GUI_MANUAL_PROBE_FILE.exists():
        return False
    try:
        payload = json.loads(GUI_MANUAL_PROBE_FILE.read_text(encoding="utf-8"))
    except Exception:
        payload = {}
    confirmed_pixel = payload.get("current_pixel") if isinstance(payload, dict) else None
    try:
        if confirmed_pixel is not None and int(confirmed_pixel) != int(pixel):
            return False
    except Exception:
        return False
    return True


def gui_clear_manual_probe_confirmation() -> None:
    if GUI_MANUAL_PROBE_FILE is None:
        return
    try:
        GUI_MANUAL_PROBE_FILE.unlink()
    except FileNotFoundError:
        pass
    except Exception:
        pass


def gui_wait_for_manual_probe(pixel: int, live_view=None) -> None:
    if GUI_MANUAL_PROBE_FILE is None:
        input(
            f"  [MANUAL PROBE] Pixel {pixel:03d}: place probes, then press Enter to continue..."
        )
        return
    gui_clear_manual_probe_confirmation()
    print(
        f"  [MANUAL PROBE] Pixel {pixel:03d}: stage is positioned. "
        "Place probes on the pixel, then press Probed - Continue in the GUI.",
        flush=True,
    )
    gui_update_state(
        current_pixel=int(pixel),
        manual_probe_waiting=True,
        manual_probe_confirmed=False,
        dc_voltage_on=False,
        ac_voltage_on=False,
        arduino_channel=None,
        arduino_pin=None,
        phase="Manual probing required",
    )
    while not gui_manual_probe_confirmed(pixel):
        gui_sleep(0.25, poll_s=0.05, live_view=live_view, phase="Manual probing required", allow_skip=True)
    gui_clear_manual_probe_confirmation()
    print(f"  [MANUAL PROBE] Pixel {pixel:03d}: probe confirmation received; starting voltage sweep.", flush=True)
    gui_update_state(
        current_pixel=int(pixel),
        manual_probe_waiting=False,
        manual_probe_confirmed=True,
        phase="Manual probe confirmed",
    )


def gui_clear_skip_request() -> None:
    if GUI_SKIP_FILE is None:
        return
    try:
        GUI_SKIP_FILE.unlink()
    except FileNotFoundError:
        pass
    except Exception:
        pass


def gui_raise_skip_request() -> None:
    global GUI_PIXEL_SKIP_LATCHED, GUI_PIXEL_SKIP_ACKED
    GUI_PIXEL_SKIP_LATCHED = True
    gui_clear_skip_request()
    if not GUI_PIXEL_SKIP_ACKED:
        print("\n[GUI-CHILD] Skip request received; cleaning up current pixel.", flush=True)
        GUI_PIXEL_SKIP_ACKED = True
    gui_update_state(phase="Skipping current pixel")
    raise SkipPixelRequested("GUI skip current pixel requested")


def gui_stop_checkpoint() -> None:
    gui_process_laser_command()
    if gui_stop_requested():
        raise KeyboardInterrupt("GUI stop requested")


def gui_pixel_checkpoint() -> None:
    gui_stop_checkpoint()
    if GUI_PIXEL_SKIP_ENABLED and (GUI_PIXEL_SKIP_LATCHED or gui_skip_requested()):
        gui_raise_skip_request()


def install_gui_skip_hooks() -> None:
    """Add skip checkpoints inside imported fast-null helpers used by the GUI worker."""
    try:
        import pockels_campaign as campaign
    except Exception:
        return
    if getattr(campaign, "_gui_skip_hooks_installed", False):
        return

    def wrap_checkpoint(name: str) -> None:
        original = getattr(campaign, name, None)
        if original is None or getattr(original, "_gui_skip_hook", False):
            return

        def wrapped(*args, **kwargs):
            gui_pixel_checkpoint()
            try:
                return original(*args, **kwargs)
            finally:
                gui_pixel_checkpoint()

        wrapped._gui_skip_hook = True
        setattr(campaign, name, wrapped)

    for helper_name in ("_parallel_move", "_probe_read", "scope_power_w", "_safe_rot_call"):
        wrap_checkpoint(helper_name)
    campaign._gui_skip_hooks_installed = True


def gui_sleep(
    seconds: float,
    poll_s: float = 0.25,
    live_view=None,
    phase: str | None = None,
    allow_skip: bool = False,
) -> None:
    end = time.time() + max(0.0, float(seconds))
    last_state = 0.0
    last_scope = 0.0
    while time.time() < end:
        if allow_skip:
            gui_pixel_checkpoint()
        else:
            gui_stop_checkpoint()
        now = time.time()
        if phase and now - last_state >= 1.0:
            gui_update_state(phase=phase, dwell_remaining_s=max(0.0, end - now))
            last_state = now
        if live_view is not None and now - last_scope >= GUI_SCOPE_LIVE_INTERVAL_S:
            try:
                gui_scope_live_read(
                    getattr(live_view, "detector", None),
                    phase=phase,
                    live_view=live_view,
                )
                last_scope = now
            except Exception:
                last_scope = now
        if live_view is not None and getattr(live_view, "available", False):
            try:
                live_view.tick()
                time.sleep(min(0.05, max(0.0, end - time.time())))
            except Exception:
                time.sleep(min(float(poll_s), max(0.0, end - time.time())))
        else:
            time.sleep(min(float(poll_s), max(0.0, end - time.time())))
    if allow_skip:
        gui_pixel_checkpoint()
    else:
        gui_stop_checkpoint()


def install_gui_camera_export(live_view, frame_file: Path | None) -> None:
    """Export the measurement-owned camera frames for the Tk GUI.

    The hardware workflow keeps ownership of the OpenCV camera.  The GUI reads
    this periodically updated PNG instead of opening a competing camera handle.
    """
    if live_view is None or frame_file is None:
        gui_update_state(camera_live=False, camera_status="Camera disabled")
        return
    cv2 = getattr(stage, "cv2", None)
    if cv2 is None:
        gui_update_state(camera_live=False, camera_status="OpenCV unavailable")
        return
    if getattr(live_view, "camera", None) is None:
        gui_update_state(camera_live=False, camera_status="No working camera found")
    frame_file.parent.mkdir(parents=True, exist_ok=True)
    state = {
        "last": 0.0,
        "last_scope": 0.0,
        "last_export_warning": 0.0,
        "export_warning_count": 0,
    }

    try:
        cv2.destroyWindow("Stage Calibration")
        cv2.destroyWindow("Edge Detection")
        cv2.waitKey(1)
    except Exception:
        pass

    def gui_tick():
        gui_process_laser_command()
        now = time.time()
        if now - state["last_scope"] >= GUI_SCOPE_LIVE_INTERVAL_S:
            try:
                gui_scope_live_read(
                    getattr(live_view, "detector", None),
                    phase="scope live",
                    live_view=live_view,
                )
            except Exception:
                pass
            finally:
                state["last_scope"] = now

        if getattr(live_view, "camera", None) is None:
            gui_update_state(camera_live=False, camera_status="No camera handle")
            try:
                cv2.waitKey(30)
            except Exception:
                pass
            return -1

        ret, frame = live_view.camera.read()
        if not ret or frame is None:
            gui_update_state(camera_live=False, camera_status="Camera opened but no frame")
            try:
                cv2.waitKey(30)
            except Exception:
                pass
            return -1

        live_view._latest_frame = frame.copy()

        display = frame.copy()

        if now - state["last"] >= GUI_CAMERA_FRAME_INTERVAL_S:
            tmp = frame_file.with_name(
                f"{frame_file.name}.{os.getpid()}.{time.time_ns()}.tmp.png"
            )
            try:
                if not cv2.imwrite(str(tmp), display):
                    raise RuntimeError(f"cv2.imwrite failed for {tmp}")
                replaced = False
                last_exc = None
                for _attempt in range(5):
                    try:
                        os.replace(str(tmp), str(frame_file))
                        replaced = True
                        break
                    except PermissionError as exc:
                        last_exc = exc
                        time.sleep(0.035)
                    except OSError as exc:
                        last_exc = exc
                        if getattr(exc, "winerror", None) == 5:
                            time.sleep(0.035)
                            continue
                        raise
                if not replaced:
                    raise last_exc or RuntimeError("camera frame replace failed")
                state["last"] = now
                height, width = display.shape[:2]
                gui_update_state(
                    camera_live=True,
                    camera_status=f"Live camera {width}x{height}",
                    camera_frame_updated=now,
                    camera_frame_width=int(width),
                    camera_frame_height=int(height),
                )
            except Exception as exc:
                state["export_warning_count"] = int(state.get("export_warning_count", 0)) + 1
                if now - float(state.get("last_export_warning", 0.0)) >= 5.0:
                    skipped = int(state.get("export_warning_count", 0))
                    gui_update_state(
                        camera_live=True,
                        camera_status=f"Camera frame skipped ({type(exc).__name__}); continuing",
                    )
                    print(
                        f"[CAMERA] Export warning: {exc}"
                        + (f" ({skipped} frame(s) skipped)" if skipped > 1 else "")
                    )
                    state["last_export_warning"] = now
                    state["export_warning_count"] = 0
                try:
                    if tmp.exists():
                        tmp.unlink()
                except Exception:
                    pass
        return -1

    live_view.tick = gui_tick

