def wrap360(angle_deg: float) -> float:
    return float(angle_deg) % 360.0


def theta_i_from_hwp(hwp_deg: float) -> float:
    return lab_theta_i_from_hwp(hwp_deg)


def signed_lockin_from_mag_phase(
    mag_v: float,
    phase_deg: float,
    reference_phase_deg: float,
) -> float:
    if not (np.isfinite(mag_v) and np.isfinite(phase_deg)):
        return float("nan")
    return float(mag_v) * math.cos(math.radians(float(phase_deg) - float(reference_phase_deg)))


def lockin_sample_statistics_fields(
    raw_mags: list[float],
    raw_phases: list[float],
    reference_phase_deg: float,
) -> dict:
    """Return CSV fields from an unbiased complex average of lock-in samples."""
    stats = phasor_statistics(raw_mags, raw_phases, reference_phase_deg)
    ref_rad = math.radians(float(reference_phase_deg))
    signed_variance = (
        math.cos(ref_rad) ** 2 * stats["std_x_V"] ** 2
        + math.sin(ref_rad) ** 2 * stats["std_y_V"] ** 2
        + 2.0 * math.sin(ref_rad) * math.cos(ref_rad) * stats["cov_xy_V2"]
    )
    signed_std = math.sqrt(max(0.0, signed_variance)) if np.isfinite(signed_variance) else float("nan")
    signed_sem = signed_std / math.sqrt(stats["n"]) if stats["n"] > 1 else float("nan")
    return {
        "lockin_mag_V": stats["mean_mag_V"],
        "lockin_phase_deg": stats["mean_phase_deg"],
        "lockin_x_V": stats["mean_x_V"],
        "lockin_y_V": stats["mean_y_V"],
        "lockin_x_std_V": stats["std_x_V"],
        "lockin_y_std_V": stats["std_y_V"],
        "lockin_x_sem_V": stats["sem_x_V"],
        "lockin_y_sem_V": stats["sem_y_V"],
        "lockin_xy_cov_sem_V2": stats["cov_mean_xy_V2"],
        "lockin_mag_std_V": stats["magnitude_std_V"],
        "lockin_mag_sem_V": stats["magnitude_sem_V"],
        "lockin_phase_std_deg": stats["phase_std_deg"],
        "lockin_phase_sem_deg": stats["phase_sem_deg"],
        "lockin_signed_V": stats["signed_V"],
        "lockin_signed_std_V": signed_std,
        "lockin_signed_sem_V": signed_sem,
    }


def lockin_complex_from_mag_phase(mag_v: float, phase_deg: float) -> complex | None:
    mag = _finite_float_or_none(mag_v)
    phase = _finite_float_or_none(phase_deg)
    if mag is None or phase is None:
        return None
    phase_rad = math.radians(phase)
    return complex(mag * math.cos(phase_rad), mag * math.sin(phase_rad))


def lockin_mag_phase_signed_from_complex(value: complex, reference_phase_deg: float) -> tuple[float, float, float]:
    mag_v = abs(value)
    phase_deg = math.degrees(math.atan2(value.imag, value.real))
    signed_v = signed_lockin_from_mag_phase(mag_v, phase_deg, reference_phase_deg)
    return float(mag_v), float(phase_deg), float(signed_v)


def check_fixed_lockin_overload(lockin, current_idx: int) -> tuple[int, bool]:
    """Report DSP7230 overloads without changing the selected sensitivity."""
    current_idx = int(current_idx)
    try:
        overload = int(lockin.get_overload_byte())
    except Exception:
        return current_idx, False
    overloaded = bool(overload & 0x03)
    if overloaded:
        table = getattr(pockels, "SENS_TABLE_VOLTS", {})
        fullscale_v = table.get(current_idx) if isinstance(table, dict) else None
        range_text = (
            f"{float(fullscale_v) * 1e6:g} uV RMS full scale"
            if fullscale_v is not None
            else f"sensitivity index {current_idx}"
        )
        print(
            f"    [LOCKIN] OVERLOAD at fixed {range_text}; "
            "range left unchanged."
        )
    return current_idx, overloaded


def install_fixed_lockin_range_policy() -> None:
    """Keep every in-process fast-map and follow-up read on one range."""
    pockels.check_overload = check_fixed_lockin_overload

    # run_analyser_sweep_at_peak() delegates to an imported function whose
    # globals belong to analyser_sweep_voltage_series rather than to the
    # Pockels_Calibration_2026 module.  Update that one checker as well.
    run_single_sweep = getattr(pockels, "run_single_sweep", None)
    function_globals = getattr(run_single_sweep, "__globals__", None)
    if isinstance(function_globals, dict) and "check_overload" in function_globals:
        function_globals["check_overload"] = check_fixed_lockin_overload


def lockin_response_value(row: dict, net_key: str, raw_key: str) -> float:
    net = _finite_float_or_none(row.get(net_key))
    if net is not None:
        return float(net)
    raw = _finite_float_or_none(row.get(raw_key))
    return float(raw) if raw is not None else float("nan")


def lockin_response_phasor(row: dict) -> complex | None:
    for prefix in ("lockin_net", "lockin"):
        x = _finite_float_or_none(row.get(f"{prefix}_x_V"))
        y = _finite_float_or_none(row.get(f"{prefix}_y_V"))
        if x is not None and y is not None:
            return complex(x, y)
        value = lockin_complex_from_mag_phase(
            row.get(f"{prefix}_mag_V"), row.get(f"{prefix}_phase_deg")
        )
        if value is not None:
            return value
    return None


def lockin_raw_response_value(row: dict, raw_key: str, fallback_key: str | None = None) -> float:
    raw = _finite_float_or_none(row.get(raw_key))
    if raw is not None:
        return float(raw)
    if fallback_key is not None:
        fallback = _finite_float_or_none(row.get(fallback_key))
        if fallback is not None:
            return float(fallback)
    return float("nan")


def lockin_peak_metric_value(row: dict) -> float:
    """Peak-search metric: use background-corrected magnitude when available."""
    net = _finite_float_or_none(row.get("lockin_net_mag_V"))
    if net is not None:
        return float(net)
    raw = _finite_float_or_none(row.get("lockin_mag_V"))
    return float(raw) if raw is not None else float("nan")


def lockin_peak_metric_source(row: dict) -> str:
    return "net_mag" if _finite_float_or_none(row.get("lockin_net_mag_V")) is not None else "raw_mag"


def lockin_background_snr(row: dict) -> float:
    metric = lockin_peak_metric_value(row)
    noise = _finite_float_or_none(row.get("lockin_net_mag_sem_V"))
    if noise is None:
        noise = _finite_float_or_none(row.get("lockin_mag_sem_V"))
    if noise is None or noise <= 0.0 or not np.isfinite(metric):
        return float("nan")
    return float(metric) / max(float(noise), 1e-15)


def lockin_background_to_signal_ratio(row: dict) -> float:
    background = _finite_float_or_none(row.get("lockin_bg_mag_V"))
    signal = _finite_float_or_none(row.get("lockin_mag_V"))
    if background is None or signal is None or signal <= 0.0:
        return float("nan")
    return float(background) / max(float(signal), 1e-15)


def _phase_for_flip(row: dict | None) -> float | None:
    if not row:
        return None
    phase = _finite_float_or_none(row.get("lockin_net_phase_deg"))
    if phase is None:
        phase = _finite_float_or_none(row.get("lockin_phase_deg"))
    return phase


def phase_flip_score_from_rows(plus_row: dict | None, minus_row: dict | None) -> float:
    plus_phase = _phase_for_flip(plus_row)
    minus_phase = _phase_for_flip(minus_row)
    if plus_phase is None or minus_phase is None:
        return float("nan")
    return float(-math.cos(math.radians(float(plus_phase) - float(minus_phase))))


def side_symmetry_ratio_from_rows(plus_row: dict | None, minus_row: dict | None) -> float:
    if not plus_row or not minus_row:
        return float("nan")
    plus = lockin_peak_metric_value(plus_row)
    minus = lockin_peak_metric_value(minus_row)
    if not (np.isfinite(plus) and np.isfinite(minus)):
        return float("nan")
    denom = max(abs(float(plus)), abs(float(minus)))
    if denom <= 0.0:
        return float("nan")
    return min(abs(float(plus)), abs(float(minus))) / denom


def classify_peak_quality(row: dict) -> str:
    flags = row_quality_flags(row)
    bad_tokens = (
        "peak_far_from_malus_slope",
        "locked_qwp_bad_qwp_offset",
        "peak_lockin_snr_bad",
        "phase_flip_bad",
        "null_failed",
        "high_null_after_adaptive",
        "high_null_continued",
        "s9_operating_point_failed",
        "lockin_overload",
        "lockin_range_exceeded",
    )
    warn_tokens = (
        "peak_offset_warning",
        "locked_qwp_qwp_offset_warning",
        "peak_lockin_snr_warning",
        "phase_flip_suspicious",
        "marginal_seed_null",
        "marginal_null_after_adaptive",
        "lockin_range_near_fullscale",
    )
    if any(flag in flags for flag in bad_tokens):
        return "bad"
    if any(flag in flags for flag in warn_tokens):
        return "warning"
    return "ok"


def annotate_peak_readout_row(
    row: dict,
    *,
    peak_source: str,
    peak_track_mode: str,
    learned_readout_mode: str = "",
    chosen_side: str = "",
    phase_flip_score: float = float("nan"),
    side_symmetry_ratio: float = float("nan"),
    anl_refine_seed_deg: float | None = None,
) -> dict:
    if peak_source:
        row["peak_source"] = str(peak_source)
    if peak_track_mode:
        row["peak_track_mode"] = str(peak_track_mode)
    if learned_readout_mode:
        row["learned_readout_mode"] = str(learned_readout_mode)
    if chosen_side:
        row["chosen_side"] = str(chosen_side)
    row["lockin_metric_V"] = lockin_peak_metric_value(row)
    row["lockin_metric_source"] = lockin_peak_metric_source(row)
    row["snr_estimate"] = lockin_background_snr(row)
    row["background_to_signal_ratio"] = lockin_background_to_signal_ratio(row)
    if np.isfinite(float(phase_flip_score)):
        row["phase_flip_score"] = float(phase_flip_score)
    if np.isfinite(float(side_symmetry_ratio)):
        row["side_symmetry_ratio"] = float(side_symmetry_ratio)
    if anl_refine_seed_deg is not None and np.isfinite(float(anl_refine_seed_deg)):
        row["anl_refine_seed_deg"] = float(anl_refine_seed_deg)
        final_anl = _finite_float_or_none(row.get("anl_target_deg"))
        if final_anl is not None:
            row["anl_refine_shift_deg"] = periodic_delta_deg(float(anl_refine_seed_deg), final_anl, 180.0)

    q_offset = _finite_float_or_none(row.get("qwp_readout_offset_from_null_deg"))
    if q_offset is not None:
        append_row_quality(row, "qwp_locked_during_auto_analyser_peak")
        abs_q = abs(float(q_offset))
        if abs_q > 3.0:
            append_row_quality(row, "locked_qwp_bad_qwp_offset")
        elif abs_q > 1.0:
            append_row_quality(row, "locked_qwp_qwp_offset_warning")

    a_offset = _finite_float_or_none(row.get("anl_offset_from_null_deg"))
    if a_offset is not None:
        malus_error = abs(abs(float(a_offset)) - 45.0)
        if malus_error > 15.0:
            append_row_quality(row, "peak_far_from_malus_slope")
        elif malus_error > 8.0:
            append_row_quality(row, "peak_offset_warning")

    snr = _finite_float_or_none(row.get("snr_estimate"))
    if snr is not None:
        if snr < 1.5:
            append_row_quality(row, "peak_lockin_snr_bad")
        elif snr < 3.0:
            append_row_quality(row, "peak_lockin_snr_warning")

    flip = _finite_float_or_none(row.get("phase_flip_score"))
    if flip is not None:
        if flip < 0.0:
            append_row_quality(row, "phase_flip_bad")
        elif flip < 0.35:
            append_row_quality(row, "phase_flip_suspicious")

    row["quality"] = classify_peak_quality(row)
    return row


def add_lockin_background_fields(
    row: dict,
    background_row: dict | None,
    reference_phase_deg: float,
) -> dict:
    for key in (
        "lockin_bg_mag_V", "lockin_bg_phase_deg", "lockin_bg_signed_V",
        "lockin_bg_x_V", "lockin_bg_y_V", "lockin_bg_x_sem_V", "lockin_bg_y_sem_V",
        "lockin_net_mag_V", "lockin_net_phase_deg", "lockin_net_signed_V",
        "lockin_net_x_V", "lockin_net_y_V", "lockin_net_x_sem_V", "lockin_net_y_sem_V",
        "lockin_net_xy_cov_sem_V2", "lockin_net_mag_sem_V",
    ):
        row[key] = float("nan")
    row["detector_null_reference_V"] = float("nan")
    if not background_row:
        return row

    def row_phasor(source: dict) -> complex | None:
        x = _finite_float_or_none(source.get("lockin_x_V"))
        y = _finite_float_or_none(source.get("lockin_y_V"))
        if x is not None and y is not None:
            return complex(x, y)
        return lockin_complex_from_mag_phase(source.get("lockin_mag_V"), source.get("lockin_phase_deg"))

    signal = row_phasor(row)
    background = row_phasor(background_row)
    if signal is None or background is None:
        return row
    bg_mag, bg_phase, bg_signed = lockin_mag_phase_signed_from_complex(background, reference_phase_deg)
    net_mag, net_phase, net_signed = lockin_mag_phase_signed_from_complex(
        signal - background,
        reference_phase_deg,
    )
    row["lockin_bg_mag_V"] = bg_mag
    row["lockin_bg_phase_deg"] = bg_phase
    row["lockin_bg_signed_V"] = bg_signed
    null_detector_v = _finite_float_or_none(background_row.get("detector_V"))
    row["detector_null_reference_V"] = (
        null_detector_v if null_detector_v is not None else float("nan")
    )
    row["lockin_bg_x_V"] = float(background.real)
    row["lockin_bg_y_V"] = float(background.imag)
    row["lockin_net_mag_V"] = net_mag
    row["lockin_net_phase_deg"] = net_phase
    row["lockin_net_signed_V"] = net_signed
    row["lockin_net_x_V"] = float((signal - background).real)
    row["lockin_net_y_V"] = float((signal - background).imag)

    sig_x_sem = _finite_float_or_none(row.get("lockin_x_sem_V"))
    sig_y_sem = _finite_float_or_none(row.get("lockin_y_sem_V"))
    bg_x_sem = _finite_float_or_none(background_row.get("lockin_x_sem_V"))
    bg_y_sem = _finite_float_or_none(background_row.get("lockin_y_sem_V"))
    sig_cov = _finite_float_or_none(row.get("lockin_xy_cov_sem_V2"))
    bg_cov = _finite_float_or_none(background_row.get("lockin_xy_cov_sem_V2"))
    row["lockin_bg_x_sem_V"] = bg_x_sem if bg_x_sem is not None else float("nan")
    row["lockin_bg_y_sem_V"] = bg_y_sem if bg_y_sem is not None else float("nan")
    if None not in (sig_x_sem, sig_y_sem, bg_x_sem, bg_y_sem):
        net_x_sem = math.hypot(sig_x_sem, bg_x_sem)
        net_y_sem = math.hypot(sig_y_sem, bg_y_sem)
        net_cov = (sig_cov or 0.0) + (bg_cov or 0.0)
        row["lockin_net_x_sem_V"] = net_x_sem
        row["lockin_net_y_sem_V"] = net_y_sem
        row["lockin_net_xy_cov_sem_V2"] = net_cov
        if net_mag > 0.0:
            ux = row["lockin_net_x_V"] / net_mag
            uy = row["lockin_net_y_V"] / net_mag
            mag_var = (
                ux * ux * net_x_sem ** 2
                + uy * uy * net_y_sem ** 2
                + 2.0 * ux * uy * net_cov
            )
        else:
            mag_var = 0.5 * (net_x_sem ** 2 + net_y_sem ** 2)
        row["lockin_net_mag_sem_V"] = math.sqrt(max(0.0, mag_var))
    row["background_to_signal_ratio"] = lockin_background_to_signal_ratio(row)
    row["snr_estimate"] = lockin_background_snr(row)
    return row


def add_fast_map_lab_angle_fields(row: dict) -> dict:
    """Attach calibrated lab-frame angle annotations without changing raw moves."""
    hwp_deg = row.get("hwp_deg")
    hwp_actual = row.get("hwp_actual_deg")
    q_null = row.get("q_null_deg")
    q_actual = row.get("qwp_actual_deg")
    q_readout = row.get("qwp_readout_deg")
    q_readout_actual = row.get("qwp_readout_actual_deg")
    a_null = row.get("a_null_deg")
    a_null_actual = row.get("anl_null_actual_deg")
    anl_target = row.get("anl_target_deg")
    anl_actual = row.get("anl_actual_deg")
    row["theta_i_deg"] = lab_theta_i_from_hwp(hwp_deg)
    row["theta_i_legacy_deg"] = legacy_theta_i_from_hwp(hwp_deg)
    row["hwp_actual_theta_i_deg"] = lab_theta_i_from_hwp(hwp_actual)
    theta_i = row["theta_i_deg"]
    theta_i_actual = row["hwp_actual_theta_i_deg"]
    if not math.isfinite(float(theta_i_actual)):
        theta_i_actual = theta_i
    row["qwp_axis_lab_deg"] = qwp_axis_lab_from_raw(q_null)
    row["qwp_actual_axis_lab_deg"] = qwp_axis_lab_from_raw(q_actual)
    row["qwp_readout_axis_lab_deg"] = qwp_axis_lab_from_raw(q_readout)
    row["qwp_readout_actual_axis_lab_deg"] = qwp_axis_lab_from_raw(q_readout_actual)
    row["qwp_theta_wav_deg"] = qwp_theta_wav_from_raw(q_null, theta_i_deg=theta_i)
    row["qwp_actual_theta_wav_deg"] = qwp_theta_wav_from_raw(q_actual, theta_i_deg=theta_i_actual)
    row["qwp_readout_theta_wav_deg"] = qwp_theta_wav_from_raw(q_readout, theta_i_deg=theta_i)
    row["qwp_readout_actual_theta_wav_deg"] = qwp_theta_wav_from_raw(q_readout_actual, theta_i_deg=theta_i_actual)
    row["a_null_lab_deg"] = analyser_lab_from_raw(a_null)
    row["anl_null_actual_lab_deg"] = analyser_lab_from_raw(a_null_actual)
    row["anl_target_lab_deg"] = analyser_lab_from_raw(anl_target)
    row["anl_actual_lab_deg"] = analyser_lab_from_raw(anl_actual)
    row["a_null_theta_ana_deg"] = analyser_theta_ana_from_raw(a_null, theta_i_deg=theta_i)
    row["anl_null_actual_theta_ana_deg"] = analyser_theta_ana_from_raw(a_null_actual, theta_i_deg=theta_i_actual)
    row["anl_target_theta_ana_deg"] = analyser_theta_ana_from_raw(anl_target, theta_i_deg=theta_i)
    row["anl_actual_theta_ana_deg"] = analyser_theta_ana_from_raw(anl_actual, theta_i_deg=theta_i_actual)
    return row


def make_raw_lockin_row(
    *,
    pixel: int,
    hwp_deg: float,
    slope_side: str,
    vpp: float,
    sample_index: int,
    sample_timestamp: float,
    lockin_mag_v: float,
    lockin_phase_deg: float,
    lockin_signed_v: float,
) -> dict:
    phase_rad = math.radians(float(lockin_phase_deg))
    return {
        "pixel": int(pixel),
        "hwp_deg": float(hwp_deg),
        "theta_i_deg": lab_theta_i_from_hwp(hwp_deg),
        "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
        "slope_side": slope_side,
        "vpp": float(vpp),
        "sample_index": int(sample_index),
        "sample_timestamp": float(sample_timestamp),
        "lockin_mag_V": float(lockin_mag_v),
        "lockin_phase_deg": float(lockin_phase_deg),
        "lockin_x_V": float(lockin_mag_v) * math.cos(phase_rad),
        "lockin_y_V": float(lockin_mag_v) * math.sin(phase_rad),
        "lockin_signed_V": float(lockin_signed_v),
    }


def gui_init_lockin_bars(
    *,
    pixel: int,
    hwp_deg: float,
    vpp: float,
    a_null: float,
) -> None:
    gui_update_state(
        lockin_bars={
            "pixel": int(pixel),
            "hwp_deg": float(hwp_deg),
            "theta_i_deg": lab_theta_i_from_hwp(hwp_deg),
            "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
            "vpp": float(vpp),
            "a_null_deg": wrap360(a_null),
            "a_null_lab_deg": analyser_lab_from_raw(a_null),
            "values": {
                "zero": {"label": "0", "offset_deg": 0.0},
                "plus45": {"label": "+45", "offset_deg": 45.0},
                "minus45": {"label": "-45", "offset_deg": -45.0},
                "manual_peak": {"label": "raw"},
                "manual_anchor": {"label": "anchor"},
                "auto_peak": {"label": "auto"},
                "learned_zero": {"label": "learned 0"},
                "learned_anchor": {"label": "learned"},
                "learned_opposite": {"label": "opp"},
            },
        }
    )


def gui_update_lockin_bar(
    side: str,
    *,
    pixel: int,
    hwp_deg: float,
    vpp: float,
    a_null: float,
    mag_v: float,
    signed_v: float,
    phase_deg: float,
    net_mag_v: float | None = None,
    net_signed_v: float | None = None,
    bg_mag_v: float | None = None,
) -> None:
    bars = dict(GUI_STATE.get("lockin_bars") or {})
    values = dict(bars.get("values") or {})
    if side not in values:
        values[side] = {}
    entry = {
        **values[side],
        "mag_uV": float(mag_v) * 1e6 if np.isfinite(float(mag_v)) else float("nan"),
        "signed_uV": float(signed_v) * 1e6 if np.isfinite(float(signed_v)) else float("nan"),
        "phase_deg": float(phase_deg) if np.isfinite(float(phase_deg)) else float("nan"),
        "updated_ts": time.time(),
    }
    if net_mag_v is not None and np.isfinite(float(net_mag_v)):
        entry["net_mag_uV"] = float(net_mag_v) * 1e6
    if net_signed_v is not None and np.isfinite(float(net_signed_v)):
        entry["net_signed_uV"] = float(net_signed_v) * 1e6
    if bg_mag_v is not None and np.isfinite(float(bg_mag_v)):
        entry["bg_mag_uV"] = float(bg_mag_v) * 1e6
    values[side] = entry
    bars.update({
        "pixel": int(pixel),
        "hwp_deg": float(hwp_deg),
        "theta_i_deg": lab_theta_i_from_hwp(hwp_deg),
        "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
        "vpp": float(vpp),
        "a_null_deg": wrap360(a_null),
        "a_null_lab_deg": analyser_lab_from_raw(a_null),
        "values": values,
    })
    gui_update_state(lockin_bars=bars)


def append_quality(flags: list[str], condition: bool, flag: str) -> None:
    if condition and flag not in flags:
        flags.append(flag)


def append_lockin_range_quality(
    flags: list[str],
    magnitude_v: float,
    fullscale_v: float,
) -> float:
    """Annotate measurements that are too close to the fixed lock-in range.

    DSP overload status is sampled before the averaged read, so a transient or
    a newly larger signal can otherwise slip through.  The measured/full-scale
    ratio provides a second, persisted fail-closed check.
    """
    magnitude = _finite_float_or_none(magnitude_v)
    fullscale = _finite_float_or_none(fullscale_v)
    if magnitude is None or fullscale is None or fullscale <= 0.0:
        return float("nan")
    fraction = abs(float(magnitude)) / float(fullscale)
    append_quality(
        flags,
        fraction >= float(LOCKIN_FULLSCALE_WARN_FRACTION),
        "lockin_range_near_fullscale",
    )
    append_quality(
        flags,
        fraction >= float(LOCKIN_FULLSCALE_FAIL_FRACTION),
        "lockin_range_exceeded",
    )
    return float(fraction)


def append_row_quality(row: dict, flag: str) -> None:
    flags = [
        item for item in str(row.get("quality_flags", "") or "").split(";")
        if item
    ]
    append_quality(flags, True, flag)
    row["quality_flags"] = ";".join(flags)


def row_quality_flags(row: dict) -> set[str]:
    return {
        item for item in str(row.get("quality_flags", "") or "").split(";")
        if item
    }


def row_has_quality_flag(row: dict, *flags: str) -> bool:
    present = row_quality_flags(row)
    return any(flag in present for flag in flags)


def row_has_untrusted_null(row: dict) -> bool:
    """Return whether a row must not drive peak selection or learned settings.

    The historical function name is retained for CSV/resume compatibility;
    it now also rejects failed S9 operating-point certificates and invalid
    lock-in ranges.
    """
    return row_has_quality_flag(
        row,
        "high_null_continued",
        "high_null_after_adaptive",
        "null_failed",
        "null_check_nan",
        "s9_operating_point_failed",
        "lockin_overload",
        "lockin_range_exceeded",
    )


def row_has_angle_failure(row: dict) -> bool:
    """Return whether verified/recorded motor geometry failed for this row."""
    return any(
        "angle_error" in flag or "angle_verify_failed" in flag
        for flag in row_quality_flags(row)
    )


def write_rows(path: Path, rows: list[dict], fields: list[str]) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", newline="", encoding="utf-8") as f:
        writer = csv.DictWriter(f, fieldnames=fields, extrasaction="ignore")
        writer.writeheader()
        for row in rows:
            writer.writerow({key: row.get(key, "") for key in fields})
    os.replace(str(tmp), str(path))


def write_json(path: Path, data: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    tmp = path.with_suffix(path.suffix + ".tmp")
    with tmp.open("w", encoding="utf-8") as f:
        json.dump(data, f, indent=2)
    os.replace(str(tmp), str(path))


def _run_root_from_pixel_dir(pixel_dir: Path) -> Path | None:
    try:
        pixel_dir = Path(pixel_dir)
        if pixel_dir.parent.name == auto.DEFAULT_PIXELS_SUBDIR:
            return pixel_dir.parent.parent
    except Exception:
        return None
    return None


def peak_lock_table_rows_from_null_seeds(
    null_seed_by_hwp: dict,
    hwp_angles=None,
) -> list[dict]:
    rows: list[dict] = []
    allowed_keys = None
    if hwp_angles is not None:
        allowed_keys = {f"{float(hwp):.3f}" for hwp in hwp_angles}

    def _sort_key(key: str) -> float:
        value = _finite_float_or_none(key)
        return float(value) if value is not None else 0.0

    for hwp_key in sorted(null_seed_by_hwp, key=_sort_key):
        if allowed_keys is not None and hwp_key not in allowed_keys:
            continue
        entry = null_seed_by_hwp.get(hwp_key, {})
        if not isinstance(entry, dict):
            continue
        override = entry.get("readout_override")
        if not _valid_peak_readout_override(override):
            continue
        hwp = _finite_float_or_none(override.get("hwp_deg"))
        if hwp is None:
            hwp = _finite_float_or_none(hwp_key)
        if hwp is None:
            continue
        q_offset = _finite_float_or_none(override.get("qwp_readout_offset_from_null_deg"))
        a_offset = _finite_float_or_none(override.get("anl_offset_from_null_deg"))
        chosen_side = ""
        if a_offset is not None:
            chosen_side = "+45" if float(a_offset) >= 0.0 else "-45"
        metric = _finite_float_or_none(override.get("lockin_metric_V"))
        if metric is None:
            metric = _finite_float_or_none(override.get("lockin_mag_V"))
        rows.append({
            "hwp_deg": float(hwp),
            "theta_i_deg": theta_i_from_hwp(float(hwp)),
            "theta_i_legacy_deg": legacy_theta_i_from_hwp(float(hwp)),
            "pixel": override.get("pixel", entry.get("pixel", "")),
            "source": override.get("source", ""),
            "q_null_deg": override.get("q_null_deg", entry.get("q_null_deg", "")),
            "a_null_deg": override.get("a_null_deg", entry.get("a_null_deg", "")),
            "p_null_W": entry.get("p_null_W", ""),
            "p_null_mV": entry.get("p_null_mV", ""),
            "qwp_readout_deg": override.get("qwp_readout_deg", ""),
            "anl_target_deg": override.get("anl_target_deg", ""),
            "qwp_readout_offset_from_null_deg": q_offset if q_offset is not None else "",
            "anl_offset_from_null_deg": a_offset if a_offset is not None else "",
            "chosen_side": override.get("chosen_side", chosen_side),
            "lockin_metric_V": metric if metric is not None else "",
            "lockin_metric_source": override.get("lockin_metric_source", ""),
            "lockin_mag_V": override.get("lockin_mag_V", ""),
            "lockin_net_mag_V": override.get("lockin_net_mag_V", ""),
            "lockin_phase_deg": override.get("lockin_phase_deg", ""),
            "phase_flip_score": override.get("phase_flip_score", ""),
            "side_symmetry_ratio": override.get("side_symmetry_ratio", ""),
            "snr_estimate": override.get("snr_estimate", ""),
            "quality": override.get("quality", ""),
            "quality_flags": override.get("quality_flags", ""),
            "updated": override.get("updated", entry.get("updated", "")),
        })
    return rows


def write_peak_lock_table(
    pixel_dir: Path,
    null_seed_by_hwp: dict,
    hwp_angles=None,
) -> None:
    rows = peak_lock_table_rows_from_null_seeds(null_seed_by_hwp, hwp_angles)
    payload = {
        "peak_lock_table_version": 1,
        "created": datetime.now().isoformat(),
        "method": "locked-qwp-null-slope",
        "qwp_readout_offset_default_deg": DEFAULT_QWP_READOUT_OFFSET_DEG,
        "hwp_rows": rows,
    }
    pixel_dir = Path(pixel_dir)
    write_json(pixel_dir / PEAK_LOCK_TABLE_JSON, payload)
    write_rows(pixel_dir / PEAK_LOCK_TABLE_CSV, rows, PEAK_LOCK_TABLE_FIELDS)
    run_root = _run_root_from_pixel_dir(pixel_dir)
    if run_root is not None:
        write_json(run_root / PEAK_LOCK_TABLE_JSON, payload)
        write_rows(run_root / PEAK_LOCK_TABLE_CSV, rows, PEAK_LOCK_TABLE_FIELDS)


def build_fast_run_folder_name(
    chip_id: str,
    run_label: str | None = None,
    *,
    timestamp: str | None = None,
) -> str:
    """Return a timestamped, filesystem-safe run name containing the chip ID."""
    raw_chip_id = str(chip_id or "").strip()
    if not raw_chip_id:
        raise ValueError("Enter a Chip ID before starting a new measurement.")
    safe_chip_id = "_".join(
        part for part in auto.sanitize_run_name(raw_chip_id).split("_") if part
    )
    if safe_chip_id == "unnamed":
        raise ValueError("Chip ID must contain at least one letter or number.")

    timestamp = str(timestamp or datetime.now().strftime("%Y%m%d_%H%M%S"))
    parts = [timestamp, safe_chip_id]
    safe_label = "_".join(
        part
        for part in auto.sanitize_run_name(str(run_label or "").strip()).split("_")
        if part
    )
    if str(run_label or "").strip() and safe_label not in ("unnamed", safe_chip_id):
        parts.append(safe_label)
    return "_".join(parts)


def run_named_output_path(root_dir: Path, canonical_name: str) -> Path:
    """Chip/date-bearing alias for a canonical run-level output filename."""
    root_dir = Path(root_dir)
    return root_dir / f"{auto.sanitize_run_name(root_dir.name)}_{canonical_name}"


def write_run_json(root_dir: Path, canonical_name: str, data: dict) -> None:
    """Write the stable machine-readable name plus a human-identifiable alias."""
    canonical_path = Path(root_dir) / canonical_name
    write_json(canonical_path, data)
    named_path = run_named_output_path(root_dir, canonical_name)
    if named_path != canonical_path:
        write_json(named_path, data)


def preserve_historical_followup_source_metadata(root_dir: Path) -> list[Path]:
    """Keep the original run metadata before an in-place follow-up-only resume."""
    root_dir = Path(root_dir)
    backups: list[Path] = []
    for source_name in ("run_config.json", auto.PROGRESS_JSON):
        source_path = root_dir / source_name
        backup_path = root_dir / f"pre_historical_hysteresis_{source_name}"
        if not source_path.is_file():
            continue
        if not backup_path.exists():
            shutil.copy2(source_path, backup_path)
        backups.append(backup_path)
    return backups


def make_fast_run_dir(args) -> Path:
    if args.resume_run:
        root_dir = Path(args.resume_run).expanduser().resolve()
        if not root_dir.is_dir():
            raise FileNotFoundError(f"--resume-run does not exist: {root_dir}")
        return root_dir

    run_name = args.run_name
    chip_id = str(getattr(args, "chip_id", "") or "").strip()
    if chip_id:
        folder_name = build_fast_run_folder_name(chip_id, run_name)
    else:
        if not run_name:
            run_name = input("Fast-map run name: ").strip() or "fast_map"
        timestamp = datetime.now().strftime("%Y%m%d_%H%M%S")
        folder_name = f"{timestamp}_{auto.sanitize_run_name(run_name)}"
    root_dir = Path(OUTDIR_ROOT) / folder_name
    root_dir.mkdir(parents=True, exist_ok=True)
    return root_dir.resolve()


def substrate_calibration_info(path: Path | str) -> dict:
    """Read operator-facing identity and HWP-grid details from a null table."""
    calibration_path = Path(path).expanduser()
    if calibration_path.is_dir():
        calibration_path = calibration_path / auto.SUBSTRATE_CAL_FILENAME
    try:
        calibration_path = calibration_path.resolve()
    except Exception:
        pass

    data: dict = {}
    try:
        with calibration_path.open("r", encoding="utf-8") as f:
            loaded = json.load(f)
        if isinstance(loaded, dict):
            data = loaded
    except Exception:
        pass

    run_config: dict = {}
    try:
        with (calibration_path.parent / "run_config.json").open(
            "r", encoding="utf-8"
        ) as f:
            loaded_config = json.load(f)
        if isinstance(loaded_config, dict):
            run_config = loaded_config
    except Exception:
        pass

    identity = data.get("run_identity")
    if not isinstance(identity, dict):
        identity = {}
    angles = data.get("hwp_angles_deg")
    if not isinstance(angles, list):
        angles = []
    finite_angles: list[float] = []
    for value in angles:
        numeric = _finite_float_or_none(value)
        if numeric is not None:
            finite_angles.append(float(numeric))

    n_hwp = data.get("n_hwp", len(finite_angles))
    try:
        n_hwp = int(n_hwp)
    except (TypeError, ValueError):
        n_hwp = len(finite_angles)
    return {
        "path": calibration_path,
        "timestamp": str(data.get("timestamp", "") or "").strip(),
        "run_started_at": str(
            data.get("run_started_at")
            or identity.get("run_started_at")
            or ""
        ).strip(),
        "run_folder": str(
            data.get("run_folder")
            or identity.get("run_folder")
            or calibration_path.parent.name
        ).strip(),
        "chip_id": str(
            data.get("chip_id")
            or identity.get("chip_id")
            or run_config.get("chip_id")
            or ""
        ).strip(),
        "run_name": str(
            data.get("run_name")
            or identity.get("run_name")
            or run_config.get("run_name")
            or ""
        ).strip(),
        "n_hwp": n_hwp,
        "hwp_angles_deg": finite_angles,
    }


def substrate_calibration_sort_key(path: Path | str) -> tuple[float, float]:
    """Prefer the embedded calibration time; fall back to filesystem mtime."""
    calibration_path = Path(path)
    try:
        mtime = float(calibration_path.stat().st_mtime)
    except Exception:
        mtime = 0.0
    timestamp = substrate_calibration_info(calibration_path).get("timestamp", "")
    try:
        embedded = datetime.fromisoformat(str(timestamp).replace("Z", "+00:00")).timestamp()
    except Exception:
        embedded = mtime
    return float(embedded), float(mtime)


def format_substrate_calibration_label(path: Path | str) -> str:
    info = substrate_calibration_info(path)
    parts: list[str] = []
    chip_id = str(info.get("chip_id", "") or "").strip()
    run_name = str(info.get("run_name", "") or "").strip()
    if chip_id:
        parts.append(f"Chip {chip_id}")
    if run_name:
        parts.append(f"Run {run_name}")
    if not parts:
        parts.append(str(info.get("run_folder", "substrate calibration")))

    timestamp = str(info.get("timestamp", "") or "").strip()
    if timestamp:
        try:
            timestamp = datetime.fromisoformat(
                timestamp.replace("Z", "+00:00")
            ).strftime("%Y-%m-%d %H:%M:%S")
        except Exception:
            pass
        parts.append(timestamp)

    n_hwp = int(info.get("n_hwp", 0) or 0)
    angles = list(info.get("hwp_angles_deg", []) or [])
    hwp_text = f"{n_hwp} HWP" if n_hwp else "HWP count unknown"
    if angles:
        preview_limit = 12
        preview = ", ".join(
            f"{float(value):g}" for value in angles[:preview_limit]
        )
        if len(angles) > preview_limit:
            preview += ", ..."
        hwp_text += f" (raw {preview} deg)"
    parts.append(hwp_text)
    return " | ".join(parts)


def find_latest_substrate_calibration() -> Path | None:
    candidates: list[Path] = []
    for root in (Path(OUTDIR_ROOT), Path(auto.OUTDIR_ROOT)):
        if not root.exists():
            continue
        candidates.extend(root.rglob(auto.SUBSTRATE_CAL_FILENAME))
    if not candidates:
        return None
    return max(candidates, key=substrate_calibration_sort_key).resolve()


def maybe_prompt_substrate_cal(args) -> None:
    if args.phase_substrate == "do" or args.phase_substrate == "skip" or args.substrate_cal:
        return
    if args.yes:
        print("  [WARN] --phase-substrate load requested but no --substrate-cal supplied; skipping substrate seed load.")
        args.phase_substrate = "skip"
        return

    latest = find_latest_substrate_calibration()
    default_choice = "L" if latest else "D"
    print("\nSubstrate HWP null seeds")
    print("  D = do slow substrate calibration/nulling now")
    print("  L = load previous substrate_calibration.json or run folder")
    print("  S = skip seed loading; each pixel/HWP will re-null from current seed")
    if latest:
        print(f"  Latest found: {format_substrate_calibration_label(latest)}")
        print(f"                {latest}")
    choice = input(f"Choose [D/L/S] [{default_choice}]: ").strip().lower()
    if not choice:
        choice = default_choice.lower()
    if choice in ("d", "do"):
        args.phase_substrate = "do"
        return
    if choice in ("s", "skip"):
        args.phase_substrate = "skip"
        return

    if choice not in ("l", "load"):
        print("  [WARN] Unrecognised choice; doing substrate calibration/nulling now.")
        args.phase_substrate = "do"
        return

    default_path = str(latest) if latest else ""
    suffix = f" [{default_path}]" if default_path else ""
    entered = input(f"Previous substrate calibration file/run folder{suffix}: ").strip()
    if not entered and default_path:
        entered = default_path
    if entered:
        args.substrate_cal = entered
    else:
        print("  [WARN] No path entered; doing substrate calibration/nulling now.")
        args.phase_substrate = "do"


def prompt_text(prompt: str, default: str | None = None) -> str:
    suffix = f" [{default}]" if default not in (None, "") else ""
    value = input(f"{prompt}{suffix}: ").strip()
    if value:
        return value
    return "" if default is None else str(default)


def prompt_yes_no(prompt: str, default: bool = True) -> bool:
    suffix = "Y/n" if default else "y/N"
    value = input(f"{prompt} [{suffix}]: ").strip().lower()
    if not value:
        return default
    return value in ("y", "yes")


def fmt_duration(seconds: float) -> str:
    if not np.isfinite(seconds) or seconds < 0:
        return "--:--"
    seconds = int(seconds)
    h, rem = divmod(seconds, 3600)
    m, s = divmod(rem, 60)
    if h:
        return f"{h:d}:{m:02d}:{s:02d}"
    return f"{m:02d}:{s:02d}"


def prompt_float(prompt: str, default: float) -> float:
    while True:
        raw = prompt_text(prompt, str(default))
        try:
            return float(raw)
        except ValueError:
            print("  Please enter a number.")


def prompt_int(prompt: str, default: int) -> int:
    while True:
        raw = prompt_text(prompt, str(default))
        try:
            return int(raw)
        except ValueError:
            print("  Please enter an integer.")


def using_cli_args(argv: list[str] | None) -> bool:
    if argv is not None:
        return len(argv) > 0
    script_name = Path(__file__).name.lower()
    extras = [arg for arg in sys.argv[1:] if Path(str(arg)).name.lower() != script_name]
    return any(str(arg).startswith("-") for arg in extras)


def spyder_interactive_setup(args, argv: list[str] | None) -> None:
    """Spyder/no-CLI setup wizard.

    Spyder normally runs this file as runfile(...), so command-line flags are
    inconvenient.  This wizard edits the parsed defaults in-place before any
    hardware is opened.
    """
    if using_cli_args(argv) or args.yes or args.list_serial_ports:
        return

    print("\n" + "=" * 72)
    print("SPYDER FAST-MAP SETUP")
    print("=" * 72)
    print("Press Enter to accept defaults. No hardware is opened until the final Y/N.")

    args.chip_id = prompt_text("Chip ID", args.chip_id)
    args.run_name = prompt_text("Optional run label", args.run_name or "fast_map")
    args.pixels = prompt_text("Pixels to measure (all, 1, 1-10, 1,5,9)", args.pixels)

    print("\nFast-map grid")
    args.hwp_input_frame = "lab"
    sweep_choice = prompt_text("HWP sweep mode: C=centered 180 deg, S=start/stop", "C").strip().lower()
    if sweep_choice in ("s", "start", "start-stop", "start_stop"):
        args.hwp_sweep_mode = "start-stop"
        args.hwp_start = prompt_float("Incident theta_i start deg lab", args.hwp_start)
        args.hwp_stop = prompt_float("Incident theta_i stop deg lab", args.hwp_stop)
        args.hwp_step = prompt_float("Incident theta_i step deg lab", args.hwp_step)
    else:
        args.hwp_sweep_mode = "centered-180"
        args.hwp_start = prompt_float("Incident theta_i centre deg lab", args.hwp_start)
        args.hwp_points = prompt_int("Centered HWP sweep points", args.hwp_points)
    args.voltages = prompt_text("AC voltages Vpp (9 or 1,3,5,9)", args.voltages)
    args.calibration_pixel = prompt_int(
        "Physical pixel for per-HWP null + EO calibration",
        args.calibration_pixel if args.calibration_pixel is not None else 1,
    )

    latest_substrate = find_latest_substrate_calibration()
    default_substrate_choice = "D"
    print("\nSubstrate HWP null seeds")
    print("  D = do slow substrate calibration/nulling now")
    print("  L = load previous substrate_calibration.json or run folder")
    print("  S = skip seed loading; each pixel/HWP will re-null from current seed")
    if latest_substrate:
        print(
            "  Latest found: "
            + format_substrate_calibration_label(latest_substrate)
        )
        print(f"                {latest_substrate}")
    substrate_choice = prompt_text("Choose D/L/S", default_substrate_choice).strip().lower()
    if substrate_choice in ("d", "do"):
        args.phase_substrate = "do"
    elif substrate_choice in ("l", "load"):
        args.phase_substrate = "load"
        args.substrate_cal = prompt_text(
            "Previous substrate calibration file/run folder",
            str(latest_substrate) if latest_substrate else None,
        )
        if not args.substrate_cal:
            print("  No path entered; switching to do substrate calibration/nulling now.")
            args.phase_substrate = "do"
    elif substrate_choice in ("s", "skip"):
        args.phase_substrate = "skip"
    else:
        print("  Unrecognised choice; doing substrate calibration/nulling now.")
        args.phase_substrate = "do"
    print("\nPer-HWP nulling during fast map")
    print("  S = seed-only: use the stored HWP null table, fastest")
    print("  A = adaptive: use stored seed, QWP/ANL re-null only if null leakage is high")
    print("  F = fast-renull: locally optimize QWP/ANL at every pixel/HWP, slower")
    renull_choice = prompt_text("Choose S/A/F", "A").strip().lower()
    if renull_choice in ("s", "seed", "seed-only", "seed_only"):
        args.renull_mode = "seed-only"
    elif renull_choice in ("", "a", "adaptive", "adaptive-renull", "adaptive_renull"):
        args.renull_mode = "adaptive-renull"
    elif renull_choice in ("f", "fast", "fast-renull", "renull"):
        args.renull_mode = "fast-renull"
    else:
        print("  Unrecognised choice; using adaptive-renull.")
        args.renull_mode = "adaptive-renull"

    print("\nHardware and alignment")
    args.skip_stage_home = not prompt_yes_no("Home stage at startup", not args.skip_stage_home)
    args.no_camera = not prompt_yes_no("Use camera/live view", not args.no_camera)
    args.no_rotator_home = not prompt_yes_no("Home/tare rotators at startup", not args.no_rotator_home)
    args.realign_stage = prompt_yes_no("Auto-align each pixel before measurement", args.realign_stage)
    args.min_signal_mv = prompt_float("Minimum signal before retry scans mV", args.min_signal_mv)
    args.use_laser = prompt_yes_no("Use KLS1550 laser control", args.use_laser)
    if args.use_laser:
        args.laser_power_mw = prompt_float("KLS1550 laser power mW", args.laser_power_mw)
        args.laser_on_start = prompt_yes_no("Turn laser on at startup", args.laser_on_start)
    args.verify_fast_rotator_moves = prompt_yes_no("Verify fast rotator moves with readback/correct-once", args.verify_fast_rotator_moves)
    if args.verify_fast_rotator_moves:
        args.rotator_verify_tol = prompt_float("Rotator verification tolerance deg", args.rotator_verify_tol)
    args.rotator_velocity_pct = prompt_int("Rotator velocity percent", args.rotator_velocity_pct)

    print("\nLock-in timing")
    fast_defaults = prompt_yes_no(
        "Use default timing (500 ms TC, 12 dB/oct, 2s settle, 5 x 2s)",
        True,
    )
    if fast_defaults:
        args.lockin_tc_index = DEFAULT_LOCKIN_TC_INDEX
        args.lockin_filter_slope_db = DEFAULT_LOCKIN_FILTER_SLOPE_DB
        args.lockin_sensitivity_index = DEFAULT_LOCKIN_SENSITIVITY_INDEX
        args.lockin_settle = DEFAULT_LOCKIN_SETTLE_S
        args.lockin_avg_readings = DEFAULT_LOCKIN_AVG_READINGS
        args.lockin_read_delay = DEFAULT_LOCKIN_READ_DELAY_S
        args.funcgen_settle = 0.2
        args.fast_rotator_moves = True
    else:
        args.lockin_tc_index = prompt_int("DSP7230 time-constant index", args.lockin_tc_index)
        args.lockin_filter_slope_db = prompt_int("DSP7230 filter slope dB/oct", args.lockin_filter_slope_db)
        args.lockin_sensitivity_index = prompt_int("DSP7230 sensitivity index", args.lockin_sensitivity_index)
        args.lockin_settle = prompt_float("Lock-in settle s", args.lockin_settle)
        args.lockin_avg_readings = prompt_int("Lock-in averaged readings", args.lockin_avg_readings)
        args.lockin_read_delay = prompt_float("Lock-in read delay s", args.lockin_read_delay)
        args.funcgen_settle = prompt_float("Function-generator settle s", args.funcgen_settle)
        args.fast_rotator_moves = prompt_yes_no("Use fast absolute rotator moves", args.fast_rotator_moves)
    args.lockin_reference_phase = prompt_float("Signed lock-in reference phase deg", args.lockin_reference_phase)
    args.qwp_readout_offset = prompt_float("QWP readout offset from null deg", args.qwp_readout_offset)

    print("\nSafety")
    args.poling_voltage = prompt_float("Per-pixel DC poling voltage V", args.poling_voltage)
    args.poling_dwell = prompt_float("Per-pixel DC poling dwell s", args.poling_dwell)
    compliance_ma = prompt_float(
        "SMU compliance current mA",
        float(args.smu_compliance) * 1e3,
    )
    args.smu_compliance = smu_compliance_a_from_ma(compliance_ma)
    args.require_lockin = prompt_yes_no("Require real DSP7230 lock-in", args.require_lockin)
    args.require_smu = prompt_yes_no("Require real SMU4201", args.require_smu)
    args.allow_no_arduino = not prompt_yes_no("Require Arduino switch matrix", not args.allow_no_arduino)
    args.no_arduino = False if not args.allow_no_arduino else args.no_arduino


def confirm_start(args, root_dir: Path, selected_pixels: list[int], total_points: int) -> bool:
    if args.yes:
        return True
    raw_hwp = hwp_angles_from_args(args)
    lab_hwp = hwp_lab_theta_i_grid_from_args(args)
    input_hwp = hwp_input_grid_from_args(args)
    sweep_mode = hwp_sweep_mode_from_args(args)
    print("\nFast-map run summary")
    print(f"  Output dir       : {root_dir}")
    print(f"  Pixels           : {len(selected_pixels)} selected")
    if sweep_mode == "centered-180":
        step = float(input_hwp[1] - input_hwp[0]) if len(input_hwp) > 1 else float("nan")
        span_label = (
            "raw HWP +/-45 deg -> 180 deg theta_i"
            if getattr(args, "hwp_input_frame", "lab") == "raw"
            else "theta_i +/-90 deg"
        )
        print(f"  HWP sweep        : centred 180 deg ({span_label}), "
              f"centre {args.hwp_start:g}, {len(input_hwp)} points, step {step:.6g}")
    if getattr(args, "hwp_input_frame", "lab") == "lab":
        if sweep_mode == "centered-180":
            print(f"  theta_i grid     : {lab_hwp[0]:.3f} -> {lab_hwp[-1]:.3f} deg lab")
        else:
            print(f"  theta_i grid     : {args.hwp_start:g} -> {args.hwp_stop:g} deg lab, step {args.hwp_step:g}")
        print(f"  Raw HWP moves    : {raw_hwp[0]:.3f} -> {raw_hwp[-1]:.3f} deg ({len(raw_hwp)} points)")
    else:
        if sweep_mode == "centered-180":
            print(f"  Raw HWP grid     : {raw_hwp[0]:.3f} -> {raw_hwp[-1]:.3f} deg ({len(raw_hwp)} points)")
        else:
            print(f"  Raw HWP grid     : {args.hwp_start:g} -> {args.hwp_stop:g} deg, step {args.hwp_step:g}")
        print(f"  theta_i lab      : {lab_hwp[0]:.3f} -> {lab_hwp[-1]:.3f} deg ({len(lab_hwp)} points)")
    print(f"  AC Vpp           : {args.voltages}")
    print(f"  Lock-in timing   : settle {args.lockin_settle:g}s, "
          f"{args.lockin_avg_readings} x {args.lockin_read_delay:g}s")
    print(f"  DC poling        : {args.poling_voltage:+g} V for {args.poling_dwell:g}s/pixel")
    print(f"  SMU compliance   : {args.smu_compliance * 1e3:g} mA")
    print(f"  DC dwell overhead: {fmt_duration(len(selected_pixels) * args.poling_dwell)}")
    print(f"  Learned readout  : {args.learned_readout_mode}")
    print(f"  Total LI points  : {total_points}")
    print(f"  Lab angle map    : {lab_angle_mapping_label()}")
    print(f"  Substrate phase  : {args.phase_substrate}"
          + (f" ({args.substrate_cal})" if args.substrate_cal else ""))
    if args.phase_substrate == "do":
        print(f"  Substrate null   : tol {args.substrate_null_tol:g} deg, "
              f"max {args.substrate_null_max_evals} probes/HWP")
    print(f"  Per-HWP nulling  : {args.renull_mode}")
    if getattr(args, "calibration_pixel", None) is not None:
        print(
            f"  Calibration pixel: {int(args.calibration_pixel):03d} "
            "(per-HWP nulls + EO/readout calibration, measured first)"
        )
    auto_peak_pixels = max(0, int(getattr(args, "auto_peak_calibration_pixels", 0)))
    manual_peak_pixels = max(0, int(getattr(args, "manual_peak_calibration_pixels", 0)))
    if getattr(args, "calibration_pixel", None) is not None and (
        auto_peak_pixels or (
            getattr(args, "manual_peak_hwp", None) is not None
            and not bool(getattr(args, "manual_peak_only", False))
            and manual_peak_pixels
        )
    ):
        calibration_null_pixels = (
            manual_peak_pixels
            if getattr(args, "manual_peak_hwp", None) is not None
            else auto_peak_pixels
        )
        print(
            "  Theory null cal  : "
            f"{calibration_null_pixels} calibration pixel(s), starting at physical "
            f"pixel {int(args.calibration_pixel):03d}, forced full "
            "sample-in coarse+fine QWP/ANL null at every HWP"
        )
    print(f"  QWP readout bias : q_null + {args.qwp_readout_offset:g} deg")
    if getattr(args, "manual_peak_hwp", None) is not None:
        print(
            "  Manual peak scout: "
            f"HWP {float(args.manual_peak_hwp):.4f}, "
            f"QWP {float(args.manual_peak_qwp):.4f}, "
            f"ANL {float(args.manual_peak_anl):.4f} raw deg "
            f"(branch window +/-{MANUAL_PEAK_BRANCH_HWP_WINDOW_DEG:g} HWP deg)"
        )
        if not bool(getattr(args, "manual_peak_only", False)):
            print(
                "  Manual peak check: "
                f"first {max(0, int(args.manual_peak_calibration_pixels))} selected pixel(s)"
            )
    else:
        if auto_peak_pixels and getattr(args, "calibration_pixel", None) is not None:
            if (
                str(getattr(args, "learned_readout_mode", "")) == "triplet"
                and str(getattr(args, "auto_peak_track_mode", "")) == "locked-qwp"
            ):
                print(
                    "  EO/readout cal   : "
                    f"pixel {int(args.calibration_pixel):03d} first"
                    + (f" plus {auto_peak_pixels - 1} subsequent selected pixel(s)" if auto_peak_pixels > 1 else "")
                    + ", full local null + "
                    "null/+45/-45 plus balanced S9 joint AC/DC fit at every HWP"
                )
            else:
                print(
                    "  Legacy peak cal : "
                    f"first {auto_peak_pixels} selected pixel(s), "
                    f"max {int(getattr(args, 'auto_peak_max_coarse_probes', DEFAULT_AUTO_PEAK_MAX_COARSE_PROBES))} "
                    "coarse QWP/ANL seed probes, "
                    f"HWP tracking {getattr(args, 'auto_peak_track_mode', DEFAULT_AUTO_PEAK_TRACK_MODE)}"
                )
    if bool(getattr(args, "peak_diagnostic", False)):
        print(
            "  Peak diagnostic  : "
            f"enabled, {PEAK_DIAGNOSTIC_PROBE_COUNT} probes/HWP, "
            f"step {float(args.peak_diagnostic_step):g} deg, "
            f"margin {float(args.peak_diagnostic_min_margin_uv):g} uV"
        )
    followup_parts = []
    if str(getattr(args, "post_analyser_sweep_pixels", "") or "").strip():
        scope = "peak HWP only" if bool(getattr(args, "post_analyser_sweep_peak_only", True)) else "all saved HWP points"
        followup_parts.append(f"ANL pixels {args.post_analyser_sweep_pixels} ({scope})")
    if str(getattr(args, "post_ac_vpp_sweep_pixels", "") or "").strip():
        followup_parts.append(f"AC Vpp pixels {args.post_ac_vpp_sweep_pixels}")
    if str(getattr(args, "post_dc_hysteresis_pixels", "") or "").strip():
        followup_parts.append(
            f"DC hyst pixels {args.post_dc_hysteresis_pixels} "
            f"(+/-{float(args.post_dc_hysteresis_vmax):g} V)"
        )
    if followup_parts:
        print("  Post-map follow-up: per-pixel after fast map; " + "; ".join(followup_parts))
    print(
        "  KLS1550 laser    : "
        + (
            f"{args.laser_power_mw:g} mW, startup {'ON' if args.laser_on_start else 'OFF'}"
            if args.use_laser else "disabled"
        )
    )
    print(
        f"  Null check       : target {args.null_check_max_mv:g} mV, "
        f"warning > {float(args.null_check_max_mv) + float(args.null_certify_margin_mv):g} mV"
    )
    verify_desc = (
        f"ON, tol {args.rotator_verify_tol:g} deg"
        if args.verify_fast_rotator_moves else "OFF"
    )
    print(f"  Rotator verify   : {verify_desc}")
    print(f"  Rotator velocity : {args.rotator_velocity_pct}%")
    ans = input("\nStart hardware initialization and high-voltage fast map? [y/N]: ").strip().lower()
    if ans not in ("y", "yes"):
        print("Aborted before hardware initialization.")
        return False
    return True


def manual_peak_enabled_for_pixel_sequence(args, seq: int, manual_peak_raw: dict | None) -> bool:
    if not manual_peak_raw:
        return False
    if bool(getattr(args, "manual_peak_only", False)):
        return True
    try:
        n_cal = int(getattr(args, "manual_peak_calibration_pixels", 1))
    except Exception:
        n_cal = 1
    return int(seq) <= max(0, n_cal)


def auto_peak_enabled_for_pixel_sequence(args, seq: int, manual_peak_raw: dict | None) -> bool:
    if bool(getattr(args, "manual_peak_only", False)):
        return False
    if manual_peak_enabled_for_pixel_sequence(args, seq, manual_peak_raw):
        return False
    try:
        n_cal = int(
            getattr(
                args,
                "auto_peak_calibration_pixels",
                DEFAULT_AUTO_PEAK_CALIBRATION_PIXELS,
            )
        )
    except Exception:
        n_cal = DEFAULT_AUTO_PEAK_CALIBRATION_PIXELS
    return int(seq) <= max(0, n_cal)


def resolve_calibration_pixel(
    selected_pixels,
    requested_pixel,
    total_pixels: int,
    *,
    include_if_missing: bool = False,
) -> tuple[int | None, list[int]]:
    """Resolve one physical calibration pixel and put it first in the map.

    ``requested_pixel=None`` preserves the historical CLI behaviour by using
    the first selected map pixel.  The GUI supplies an explicit physical pixel
    number.  A new run rejects a calibration pixel outside the map selection;
    a resume may reinsert it so ``--skip-complete`` can verify/skip its saved
    sweep while retaining deterministic calibration ordering.
    """
    ordered: list[int] = []
    for value in selected_pixels or []:
        pixel = int(value)
        if pixel > 0 and pixel not in ordered:
            ordered.append(pixel)
    if not ordered:
        return None, []

    if requested_pixel is None or str(requested_pixel).strip() == "":
        calibration_pixel = int(ordered[0])
    else:
        try:
            calibration_pixel = int(requested_pixel)
        except (TypeError, ValueError) as exc:
            raise ValueError("Calibration pixel must be a whole pixel number.") from exc
        if str(requested_pixel).strip() not in {
            str(calibration_pixel),
            f"+{calibration_pixel}",
        }:
            raise ValueError("Calibration pixel must be a whole pixel number.")

    if calibration_pixel < 1 or calibration_pixel > int(total_pixels):
        raise ValueError(
            f"Calibration pixel must be between 1 and {int(total_pixels)}."
        )
    if calibration_pixel not in ordered:
        if not include_if_missing:
            raise ValueError(
                f"Calibration pixel {calibration_pixel} is not in the chip-map Pixels selection. "
                "Add it to Pixels or choose a selected pixel for calibration."
            )
        ordered.insert(0, calibration_pixel)
    else:
        ordered = [calibration_pixel] + [
            pixel for pixel in ordered if pixel != calibration_pixel
        ]
    return calibration_pixel, ordered


def calibration_pixel_requires_full_null(
    *,
    auto_peak_calibration: bool,
    manual_peak_raw: dict | None,
    manual_peak_only: bool,
) -> bool:
    """Return whether this pixel must establish sample-in nulls from measurements.

    Calibration pixels define the QWP/analyser null branch used by all later
    pixels.  They must therefore run the full coarse-plus-fine two-dimensional
    minimisation at every HWP, even when an inherited substrate seed happens to
    pass the fast absolute-leakage check.  Manual-peak-only diagnostics are
    excluded because they deliberately bypass the null-derived map.
    """
    if bool(manual_peak_only):
        return False
    return bool(auto_peak_calibration or manual_peak_raw)


def peak_readout_mode_requested(args, manual_peak_raw: dict | None = None) -> bool:
    if bool(getattr(args, "manual_peak_only", False)):
        return False
    if manual_peak_raw:
        return True
    try:
        return int(
            getattr(
                args,
                "auto_peak_calibration_pixels",
                DEFAULT_AUTO_PEAK_CALIBRATION_PIXELS,
            )
        ) > 0
    except Exception:
        return False


def _valid_peak_readout_override(value) -> bool:
    if not isinstance(value, dict):
        return False
    qwp = _finite_float_or_none(value.get("qwp_readout_deg"))
    anl = _finite_float_or_none(value.get("anl_target_deg"))
    return qwp is not None and anl is not None


def resolve_peak_readout_override(
    override: dict,
    *,
    q_null: float,
    a_null: float,
    q_reference: float,
    a_reference: float,
) -> tuple[float, float, bool]:
    """Return QWP/ANL readout targets, preferring offsets from the current null."""
    q_offset = _finite_float_or_none(override.get("qwp_readout_offset_from_null_deg"))
    a_offset = _finite_float_or_none(override.get("anl_offset_from_null_deg"))
    if q_offset is not None:
        q_raw = float(q_null) + float(q_offset)
    else:
        q_raw = float(override["qwp_readout_deg"])
    if a_offset is not None:
        a_raw = float(a_null) + float(a_offset)
    else:
        a_raw = float(override["anl_target_deg"])
    q_target = closest_periodic_equivalent_deg(q_raw, q_reference, 180.0)
    a_target = closest_periodic_equivalent_deg(
        a_raw,
        a_reference,
        180.0,
        analyser=True,
    )
    return float(q_target), float(a_target), bool(q_offset is not None or a_offset is not None)


def missing_peak_readout_hwp_angles(hwp_angles, null_seed_by_hwp: dict) -> list[float]:
    missing: list[float] = []
    for hwp in hwp_angles:
        hwp_f = float(hwp)
        seed = null_seed_by_hwp.get(f"{hwp_f:.3f}", {})
        if not _valid_peak_readout_override(seed.get("readout_override")):
            missing.append(hwp_f)
    return missing


def can_reuse_resume_peak_calibration(
    *,
    resume_state_loaded: bool,
    peak_readout_required: bool,
    hwp_angles,
    null_seed_by_hwp: dict,
) -> bool:
    """Return whether a resumed run already covers this exact HWP grid."""
    return bool(
        resume_state_loaded
        and peak_readout_required
        and not missing_peak_readout_hwp_angles(hwp_angles, null_seed_by_hwp or {})
    )


def merge_null_seed_tables_preserving_readout(existing: dict, incoming: dict) -> dict:
    """Fill missing substrate null seeds without clobbering learned peak readouts."""
    merged = dict(existing or {})
    for key, incoming_entry in (incoming or {}).items():
        if not isinstance(incoming_entry, dict):
            if key not in merged:
                merged[key] = incoming_entry
            continue
        current_entry = merged.get(key)
        if not isinstance(current_entry, dict):
            merged[key] = dict(incoming_entry)
            continue
        keep_readout = current_entry.get("readout_override")
        merged_entry = dict(incoming_entry)
        merged_entry.update(current_entry)
        if _valid_peak_readout_override(keep_readout):
            merged_entry["readout_override"] = dict(keep_readout)
        merged[key] = merged_entry
    return merged


def format_hwp_preview(values: list[float], *, limit: int = 6) -> str:
    preview = ", ".join(f"{float(v):.3f}" for v in values[:limit])
    if len(values) > limit:
        preview += ", ..."
    return preview


def fast_map_points_for_pixel(
    *,
    hwp_angles,
    voltages: list[float],
    manual_peak_raw: dict | None,
    manual_peak_only: bool,
    auto_peak_calibration: bool = False,
    peak_readout_required: bool = False,
    learned_readout_mode: str = DEFAULT_LEARNED_READOUT_MODE,
    peak_diagnostic: bool = False,
) -> int:
    learned_mode = str(learned_readout_mode or DEFAULT_LEARNED_READOUT_MODE).strip().lower()
    learned_points_per_hwp = {"triplet": 3, "zero-anchor": 2}.get(learned_mode, 1)
    manual_peak_points = len(voltages) if manual_peak_raw else 0
    manual_anchor_hwp_points = sum(
        1 for hwp in hwp_angles
        if manual_peak_branch_available_for_hwp(hwp, manual_peak_raw)
    )
    manual_anchor_points = (
        0 if manual_peak_only else manual_anchor_hwp_points * len(voltages)
    )
    auto_peak_hwp_points = (
        len(hwp_angles) * len(voltages) * 3
        if auto_peak_calibration and not manual_peak_raw and not manual_peak_only
        else 0
    )
    normal_hwp_points = 0 if auto_peak_hwp_points else max(0, len(hwp_angles) - manual_anchor_hwp_points)
    if manual_peak_only:
        normal_points = 0
    elif peak_readout_required and not auto_peak_hwp_points and not manual_peak_raw:
        normal_points = normal_hwp_points * len(voltages) * learned_points_per_hwp
    else:
        # The standard local readout is also a triplet: AC-on null/background
        # followed by the two exact Malus slopes.
        normal_points = normal_hwp_points * len(voltages) * 3
    peak_diagnostic_points = 0
    if bool(peak_diagnostic) and not manual_peak_only:
        if manual_peak_raw:
            peak_diagnostic_points = manual_anchor_hwp_points * len(voltages) * PEAK_DIAGNOSTIC_PROBE_COUNT
        elif auto_peak_calibration:
            peak_diagnostic_points = len(hwp_angles) * len(voltages) * PEAK_DIAGNOSTIC_PROBE_COUNT
    return int(
        manual_peak_points
        + manual_anchor_points
        + auto_peak_hwp_points
        + normal_points
        + peak_diagnostic_points
    )


def print_lockin_connection_help(exc: Exception) -> None:
    print("\n[LOCK-IN CONNECTION FAILED]")
    print(f"  Resource : {pockels.LOCKIN_RESOURCE}")
    print(f"  Error    : {type(exc).__name__}: {exc}")
    print("  Check the DSP7230 is powered, connected, and reachable at the configured VISA resource.")
    print("  The fast map requires a real signed lock-in signal unless you explicitly allow simulation.")
    try:
        import pyvisa
        resources = pyvisa.ResourceManager().list_resources()
        print("  VISA resources currently visible:")
        if resources:
            for resource in resources:
                print(f"    {resource}")
        else:
            print("    none")
    except Exception as visa_exc:
        print(f"  Could not list VISA resources: {type(visa_exc).__name__}: {visa_exc}")


def connect_rotators_for_fast_map(do_home: bool):
    state = "will home/tare next" if do_home else "no homing; preserving current positions"
    print(f"\nConnecting rotators ({state})...")
    rot_hwp = pockels.ElliptecRotator(
        port=pockels.PORT_HWP,
        address=pockels.ADDR_HWP,
        verbose=False,
        settle_time=pockels.MOVE_SETTLE_S,
    )
    rot_qwp = pockels.ElliptecRotator(
        port=pockels.PORT_QWP,
        address=pockels.ADDR_QWP,
        verbose=False,
        settle_time=pockels.MOVE_SETTLE_S,
    )
    rot_anl = pockels.ElliptecRotator(
        port=pockels.PORT_ANL,
        address=pockels.ADDR_ANL,
        verbose=False,
        settle_time=pockels.MOVE_SETTLE_S,
    )
    for rot, name in ((rot_hwp, "HWP"), (rot_qwp, "QWP"), (rot_anl, "ANL")):
        try:
            angle = rotator_read_angle_once(rot)
            if np.isfinite(angle):
                print(f"  {name}: {angle:.2f} deg")
            else:
                print(f"  {name}: readback unavailable")
        except Exception as exc:
            print(f"  {name}: readback failed ({exc})")
    return rot_hwp, rot_qwp, rot_anl


def lockin_filter_slope_index(slope_db: int) -> int:
    mapping = {6: 0, 12: 1, 18: 2, 24: 3}
    try:
        return mapping[int(slope_db)]
    except (KeyError, TypeError, ValueError) as exc:
        raise ValueError("DSP7230 filter slope must be 6, 12, 18, or 24 dB/oct.") from exc


def lockin_reference_source_index(source: str) -> int:
    mapping = {"internal": 0, "external-ttl": 1, "external-analog": 2}
    try:
        return mapping[str(source)]
    except KeyError as exc:
        raise ValueError("Lock-in reference source must be internal, external-ttl, or external-analog.") from exc


def minimum_lockin_settle_s(tc_index: int, slope_db: int) -> float:
    """DSP7230 step settling recommendation: 2 * TC * filter order."""
    if int(tc_index) not in DSP7230_TIME_CONSTANT_SECONDS:
        raise ValueError("DSP7230 time-constant index must be between 0 and 30.")
    if int(tc_index) < 8:
        raise ValueError(
            "Fast-map DSP7230 time-constant index must be at least 8 (5 ms) "
            "because reproducible fast-output mode is disabled."
        )
    order = lockin_filter_slope_index(slope_db) + 1
    return 2.0 * DSP7230_TIME_CONSTANT_SECONDS[int(tc_index)] * order


def bto_physics_config_from_args(args) -> dict:
    return {
        "geometry_confirmed": bool(args.bto_geometry_confirmed),
        "sine_drive_confirmed": bool(args.bto_sine_drive_confirmed),
        "lab_angle_mapping_trusted": bool(LAB_ANGLE_MAPPING and LAB_ANGLE_MAPPING.get("trusted", False)),
        "wavelength_nm": args.bto_wavelength_nm,
        "film_thickness_nm": args.bto_film_thickness_nm,
        "film_thickness_std_nm": args.bto_film_thickness_std_nm,
        "electrode_gap_um": args.bto_electrode_gap_um,
        "electrode_gap_std_um": args.bto_electrode_gap_std_um,
        "field_correction": args.bto_field_correction,
        "field_correction_std": args.bto_field_correction_std,
        "refractive_index": args.bto_refractive_index,
        "refractive_index_std": args.bto_refractive_index_std,
        "device_vpp_scale": args.bto_device_vpp_scale,
        "device_vpp_scale_std": args.bto_device_vpp_scale_std,
        "detector_ac_gain_over_dc_gain": args.bto_detector_ac_gain_over_dc_gain,
        "detector_ac_gain_over_dc_gain_std": args.bto_detector_ac_gain_over_dc_gain_std,
        "field_definition": "E_rms = field_correction * V_device,rms / electrode_gap",
        "coefficient_interpretation": "geometry-specific |r_eff|; not an intrinsic BTO tensor element",
    }


def update_bto_config_from_optical_calibration(optical_cal: dict) -> None:
    """Attach a correctly interpreted QWP retardance to the coefficient guard."""
    raw = optical_cal.get("raw") if isinstance(optical_cal, dict) else None
    if not isinstance(raw, dict):
        raw = optical_cal if isinstance(optical_cal, dict) else {}
    stored_delta = _finite_float_or_none(raw.get("QWP_delta_deg"))
    visibility = _finite_float_or_none(raw.get("QWP_visibility"))
    corrected_delta = None
    if visibility is not None and 0.0 <= visibility < 1.0:
        ratio = (1.0 - visibility) / (1.0 + visibility)
        _delta_rad, corrected_delta = qwp_retardance_from_parallel_ratio(ratio)
        BTO_PHYSICS_CONFIG["qwp_parallel_sweep_visibility"] = visibility
        BTO_PHYSICS_CONFIG["qwp_min_to_max_ratio"] = ratio
    if corrected_delta is None or not np.isfinite(corrected_delta):
        corrected_delta = stored_delta
    BTO_PHYSICS_CONFIG["qwp_retardance_deg"] = corrected_delta
    BTO_PHYSICS_CONFIG["qwp_retardance_deg_stored"] = stored_delta


def configure_fast_globals(args) -> list[float]:
    global BTO_PHYSICS_CONFIG, AUTO_PEAK_REFINE_MODE
    args.smu_compliance = validate_smu_compliance_a(args.smu_compliance)
    voltages = auto.configure_shared_measurement_globals(args)
    if not voltages or any(not np.isfinite(float(vpp)) or float(vpp) <= 0.0 for vpp in voltages):
        raise ValueError("Every AC drive level must be a finite, positive Vpp value.")
    AUTO_PEAK_REFINE_MODE = str(getattr(args, "peak_refine_mode", AUTO_PEAK_REFINE_MODE)).strip().lower()
    auto.BRIGHTEN_OFFSET_DEG = float(args.stage_brighten_offset)
    auto.SUBSTRATE_NULL_TOL_DEG = float(args.substrate_null_tol)
    auto.SUBSTRATE_NULL_MAX_EVALS = int(args.substrate_null_max_evals)
    auto.SUBSTRATE_ACCEPT_NULL_MV = float(args.null_check_max_mv)
    auto.SUBSTRATE_CERTIFY_MARGIN_MV = float(args.null_certify_margin_mv)
    auto.SUBSTRATE_FIRST_HWP_RETRY_MAX_MV = float(args.null_check_max_mv)
    recommended_settle = minimum_lockin_settle_s(args.lockin_tc_index, args.lockin_filter_slope_db)
    if float(args.lockin_settle) < recommended_settle:
        print(
            f"[LOCKIN] Increasing settle {float(args.lockin_settle):g} -> "
            f"{recommended_settle:g} s for TC index {args.lockin_tc_index}, "
            f"{args.lockin_filter_slope_db} dB/oct."
        )
        args.lockin_settle = recommended_settle
    if float(args.lockin_read_delay) < recommended_settle:
        print(
            f"[LOCKIN] Increasing sample spacing {float(args.lockin_read_delay):g} -> "
            f"{recommended_settle:g} s so phasor samples are approximately independent."
        )
        args.lockin_read_delay = recommended_settle
    args.lockin_avg_readings = max(2, int(args.lockin_avg_readings))
    pockels.LOCKIN_SETTLE_S = float(args.lockin_settle)
    pockels.LOCKIN_AVG_READINGS = int(args.lockin_avg_readings)
    pockels.LOCKIN_READ_DELAY_S = float(args.lockin_read_delay)
    pockels.FUNCGEN_SETTLE_S = args.funcgen_settle
    BTO_PHYSICS_CONFIG = bto_physics_config_from_args(args)
    return voltages


def configure_lockin_for_fast_map(lockin, args, *, simulated: bool) -> dict:
    """Apply a fixed-range lock-in setup with write-only startup commands.

    The lab DSP7230 accepts the configuration writes used below, but some
    firmware/transport combinations return an empty response to configuration
    queries such as ``TC.``.  The working non-v2 mapper never issued those
    strict readbacks, so they must not be allowed to abort a hardware run.
    """
    # Pockels_Calibration_2026 also uses its module-level check_overload()
    # inside the in-run AC and DC follow-ups.  Replace that range-changing
    # helper for this process so the GUI-selected sensitivity stays fixed
    # throughout the complete fast-map workflow.
    install_fixed_lockin_range_policy()
    expected_tc = DSP7230_TIME_CONSTANT_SECONDS[int(args.lockin_tc_index)]
    slope_index = lockin_filter_slope_index(args.lockin_filter_slope_db)
    reference_source_index = lockin_reference_source_index(args.lockin_reference_source)
    sensitivity_table = getattr(pockels, "SENS_TABLE_VOLTS", {})
    sensitivity_fullscale_v = (
        float(sensitivity_table[int(args.lockin_sensitivity_index)])
        if isinstance(sensitivity_table, dict)
        and int(args.lockin_sensitivity_index) in sensitivity_table
        else None
    )
    result = {
        "simulated": bool(simulated),
        "time_constant_index_requested": int(args.lockin_tc_index),
        "time_constant_s_requested": expected_tc,
        "filter_slope_db_per_oct_requested": int(args.lockin_filter_slope_db),
        "filter_slope_index_requested": slope_index,
        "settle_s_used": float(pockels.LOCKIN_SETTLE_S),
        "sample_spacing_s_used": float(pockels.LOCKIN_READ_DELAY_S),
        "averaged_phasor_samples": int(pockels.LOCKIN_AVG_READINGS),
        "sensitivity_index_requested": int(args.lockin_sensitivity_index),
        "sensitivity_fullscale_v_requested": sensitivity_fullscale_v,
        "sensitivity_mode": "fixed",
        "automatic_ac_gain_enabled": False,
        "overload_policy": "report_and_keep_fixed_range",
        "expected_reference_frequency_hz": float(args.funcgen_freq),
        "reference_source_requested": str(args.lockin_reference_source),
        "reference_source_index_requested": reference_source_index,
        "configuration_mode": "fixed_range_write_only",
        "configuration_readback_attempted": False,
        "sensitivity_index_effective": int(args.lockin_sensitivity_index),
        "reference_locked": None,
    }
    if simulated:
        result["reference_locked"] = True
        return result

    lockin.set_voltage_input_mode()
    lockin.set_ac_coupling()
    lockin.set_automatic_ac_gain(False)
    lockin.set_reference_mode_single()
    lockin.set_reference_source(reference_source_index)
    lockin.disable_synchronous_filter()
    lockin.disable_fast_output_mode()
    lockin.set_sensitivity(int(args.lockin_sensitivity_index))
    lockin.set_time_constant(int(args.lockin_tc_index))
    lockin.set_filter_slope(slope_index)
    time.sleep(0.15)
    result.update({
        "time_constant_s_effective": expected_tc,
        "filter_slope_index_effective": slope_index,
        "reference_source_index_effective": reference_source_index,
        "readback_queries_skipped": ["TC.", "SLOPE", "IE", "SEN", "FRQ."],
    })
    sensitivity_description = (
        f"{sensitivity_fullscale_v * 1e6:g} uV RMS full scale"
        if sensitivity_fullscale_v is not None
        else f"sensitivity index {int(args.lockin_sensitivity_index)}"
    )
    print(
        "[LOCKIN] Applied fixed-range write-only setup: "
        f"TC index {int(args.lockin_tc_index)} ({expected_tc:g} s), "
        f"sensitivity index {int(args.lockin_sensitivity_index)} "
        f"({sensitivity_description}), "
        f"slope {int(args.lockin_filter_slope_db)} dB/oct. "
        "Automatic AC gain and sensitivity changes disabled; "
        "strict configuration readbacks skipped."
    )
    return result


def parse_chip_pixel_selection(raw: str | None, total: int) -> list[int]:
    text = str(raw or "").strip()
    if text.lower() in ("none", "no", "off"):
        return []
    return auto.parse_pixel_selection(text, total)


def configure_rotator_velocity(args) -> int:
    pct = int(round(float(args.rotator_velocity_pct)))
    pct = max(25, min(100, pct))
    args.rotator_velocity_pct = pct
    auto.ROTATOR_VELOCITY_PCT = pct
    return pct


def _rotator_float_or_nan(value) -> float:
    try:
        out = float(value)
    except Exception:
        return float("nan")
    return out if np.isfinite(out) else float("nan")


def _call_rotator_move_variants(method, target: float, settle_s: float, *, read_back: bool):
    """Call a rotator move method while tolerating older/simpler signatures."""
    attempts = [
        lambda: method(target, settle_s=settle_s, read_back=read_back),
        lambda: method(target, settle_s=settle_s),
        lambda: method(target, settle_s),
        lambda: method(target),
    ]
    last_type_error = None
    for attempt in attempts:
        try:
            return attempt()
        except TypeError as exc:
            last_type_error = exc
            continue
    if last_type_error is not None:
        raise last_type_error
    return None


def rotator_direct_set_angle(rot, target_deg: float, settle_s: float, *, read_back: bool = False):
    """Absolute angle move across the rotator classes used in this setup."""
    target = wrap360(target_deg)
    for method_name in ("set_angle", "move_to", "move_absolute", "move_abs", "goto"):
        method = getattr(rot, method_name, None)
        if callable(method):
            return _call_rotator_move_variants(method, target, settle_s, read_back=read_back)
    raise AttributeError(f"{type(rot).__name__} has no supported absolute angle move method")


def rotator_safe_move(rot, target_deg: float, settle_s: float):
    """Use the safest available absolute move, falling back by rotator capability."""
    target = wrap360(target_deg)
    safe_move_wrap = getattr(pockels, "safe_move_wrap", None)
    if callable(safe_move_wrap) and hasattr(rot, "shift_angle") and hasattr(rot, "get_angle"):
        try:
            return safe_move_wrap(rot, target, settle_s=settle_s)
        except TypeError:
            return safe_move_wrap(rot, target)

    safe_move_abs = getattr(pockels, "safe_move_abs", None)
    if callable(safe_move_abs) and hasattr(rot, "set_angle") and hasattr(rot, "get_angle"):
        try:
            return safe_move_abs(rot, target, settle_s=settle_s)
        except TypeError:
            return safe_move_abs(rot, target)
        except AttributeError:
            pass

    return rotator_direct_set_angle(rot, target, settle_s, read_back=True)


def rotator_read_angle_once(rot) -> float:
    """Read an angle from common rotator APIs; returns NaN if unsupported/unavailable."""
    for method_name in ("get_angle", "read_angle", "get_position", "read_position"):
        method = getattr(rot, method_name, None)
        if callable(method):
            try:
                return _rotator_float_or_nan(method()) % 360.0
            except Exception:
                continue
    for attr_name in ("angle", "position", "current_angle"):
        try:
            if hasattr(rot, attr_name):
                return _rotator_float_or_nan(getattr(rot, attr_name)) % 360.0
        except Exception:
            continue
    return float("nan")


def rotator_verified_readback(
    rot,
    target_deg: float,
    tol_deg: float,
    *,
    samples: int = ANGLE_READBACK_SAMPLES,
    delay_s: float = ANGLE_READBACK_DELAY_S,
) -> tuple[float, float, int, int]:
    """Return the latest angle and count consecutive final in-tolerance reads.

    An early good sample must not certify a motor that subsequently drifts or
    loses telemetry. A stale first sample is tolerated once the motor settles.
    """
    target = wrap360(target_deg)
    actual = float("nan")
    error = float("nan")
    valid_reads = 0
    ok_reads = 0
    n_samples = max(1, int(samples))
    for idx in range(n_samples):
        gui_pixel_checkpoint()
        actual = rotator_read_angle_once(rot)
        error = float("nan")
        if np.isfinite(actual):
            valid_reads += 1
            error = float(pockels.angular_error(actual, target))
            if error <= float(tol_deg):
                ok_reads += 1
            else:
                ok_reads = 0
        else:
            ok_reads = 0
        if idx < n_samples - 1:
            gui_sleep(max(0.0, float(delay_s)), allow_skip=True)
    gui_pixel_checkpoint()
    return actual, error, valid_reads, ok_reads


def rotator_verified_move_result(rot, target_deg: float, tol_deg: float) -> dict:
    actual, error, valid_reads, ok_reads = rotator_verified_readback(rot, target_deg, tol_deg)
    required_ok_reads = min(2, max(1, int(ANGLE_READBACK_SAMPLES)))
    return {
        "target_deg": wrap360(target_deg),
        "actual_deg": actual,
        "error_deg": error,
        "readback_samples": int(valid_reads),
        "readback_ok_samples": int(ok_reads),
        "ok": np.isfinite(error) and ok_reads >= required_ok_reads,
    }


def rotator_move_needs_boundary_safe_path(rot, target_deg: float) -> tuple[bool, float, str]:
    """True only when the direct shortest path would cross the 0/360 boundary."""
    current = rotator_read_angle_once(rot)
    if not np.isfinite(current):
        return False, current, "readback unavailable"
    current = wrap360(current)
    target = wrap360(target_deg)
    short_delta = shortest_delta_deg(current, target)
    endpoint = current + short_delta
    crosses = endpoint < 0.0 or endpoint > 360.0
    if crosses:
        return True, current, "short path crosses 0/360"
    return False, current, "direct path clear"


def fast_move_to_null_seed(
    rot_qwp,
    rot_anl,
    q_seed: float,
    a_seed: float,
    *,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
) -> tuple[dict, dict]:
    """Move to the precomputed null seed without running an optimizer."""
    gui_pixel_checkpoint()
    q_move = fast_rotator_move_or_fallback(
        rot_qwp,
        q_seed,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label="QWP null",
    )
    gui_pixel_checkpoint()
    a_move = fast_rotator_move_or_fallback(
        rot_anl,
        a_seed,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label="ANL null",
    )
    gui_pixel_checkpoint()
    return q_move, a_move


def verify_renull_landing(rot_qwp, rot_anl, q_null, a_null, tol_deg, *, label):
    """Correct a missed optimizer landing before accepting its optical null.

    Null searches use short moves and cached positions. Re-read the final
    position, then use the bounded verified-move retries for any missed axis.
    Unresolved faults unwind to the pixel handler for isolation and recovery.
    """
    results = []
    for rot, target, optic in ((rot_qwp, q_null, "QWP"), (rot_anl, a_null, "ANL")):
        gui_pixel_checkpoint()
        move = rotator_verified_move_result(rot, target, tol_deg)
        if not move["ok"]:
            print(
                f"    [ANGLE] {optic} {label} missed its landing at {float(target):.3f} deg; "
                "correcting from the measured position."
            )
            move = fast_rotator_move_or_fallback(
                rot, target, fast=False, verify=True, tol_deg=tol_deg,
                label=f"{optic} {label}",
            )
            move["corrected"] = True
        require_verified_move(move, f"{optic} {label}")
        results.append(move)
    return tuple(results)


def _null_scope_detector(raw_detector):
    """Return the real scope object if this detector wrapper exposes one."""
    if raw_detector is None:
        return None
    if hasattr(raw_detector, "_set_vdiv"):
        return raw_detector
    for attr in ("detector", "_sc"):
        inner = getattr(raw_detector, attr, None)
        if inner is not None and hasattr(inner, "_set_vdiv"):
            return inner
    return None


def prepare_null_scope_scale(raw_detector) -> None:
    """Start null reads on the most sensitive useful scope range."""
    scope = _null_scope_detector(raw_detector)
    if scope is None:
        return
    try:
        scope._set_vdiv(float(NULL_SCOPE_START_VDIV))
    except Exception:
        pass


def _null_scope_range_is_settled(mean_v, vdiv) -> bool:
    if mean_v is None or vdiv is None:
        return True
    try:
        mean_v = float(mean_v)
        vdiv = float(vdiv)
    except Exception:
        return True
    if not np.isfinite(mean_v) or not np.isfinite(vdiv) or vdiv <= 0.0:
        return True

    options_mV = getattr(stage, "SCOPE_VDIV_OPTIONS_MV", None)
    try:
        options = [float(v) / 1000.0 for v in options_mV]
    except Exception:
        options = [float(NULL_SCOPE_START_VDIV), vdiv]
    options = [v for v in options if np.isfinite(v) and v > 0.0]
    if not options:
        return True

    signal_v = abs(mean_v)
    min_vdiv = min(options)
    max_vdiv = max(options)
    multiplier = float(getattr(stage, "SMART_RANGE_MULTIPLIER", 4.0))
    min_fill = float(getattr(stage, "SMART_RANGE_MIN_FILL", 0.20))

    too_big = signal_v > vdiv * multiplier * 0.98
    if too_big and vdiv < max_vdiv:
        return False

    too_small = signal_v < vdiv * min_fill * 0.70
    if too_small and vdiv > min_vdiv:
        return False

    return True


def read_null_check(detector, raw_detector=None) -> tuple[float, float]:
    """Fast null check returning finite ``(power_W, detector_mV)`` telemetry.

    A scope transport failure must not be converted into a NaN/high-null data
    point.  The caller can safely flag a *finite* high null and keep measuring,
    but missing detector telemetry invalidates the whole instrument session.
    """
    gui_pixel_checkpoint()
    try:
        if raw_detector is not None and hasattr(raw_detector, "read_averaged"):
            prepare_null_scope_scale(raw_detector)
            result = (None, None, None, None)
            for _attempt in range(int(NULL_SCOPE_AUTORANGE_RETRIES)):
                result = raw_detector.read_averaged(
                    n=int(NULL_SCOPE_READ_AVERAGES),
                    auto_scale=True,
                )
                mean_v, _std_v, power_w, vdiv = result
                if _null_scope_range_is_settled(mean_v, vdiv):
                    break
            mean_v, _std_v, power_w, _vdiv = result
            try:
                mean_v = float(mean_v)
                power_w = float(power_w)
            except (TypeError, ValueError) as exc:
                raise CriticalHardwareTransportError(
                    "Oscilloscope detector telemetry unavailable during fast-map null check"
                ) from exc
            if not (np.isfinite(mean_v) and np.isfinite(power_w)):
                raise CriticalHardwareTransportError(
                    "Oscilloscope detector telemetry unavailable during fast-map null check"
                )
            return power_w, mean_v * 1e3

        power_w, detector_v = detector.read_power_w_stable()
        try:
            power_w = float(power_w)
            detector_v = float(detector_v)
        except (TypeError, ValueError) as exc:
            raise CriticalHardwareTransportError(
                "Oscilloscope detector telemetry unavailable during fast-map null check"
            ) from exc
        if not (np.isfinite(power_w) and np.isfinite(detector_v)):
            raise CriticalHardwareTransportError(
                "Oscilloscope detector telemetry unavailable during fast-map null check"
            )
        return power_w, detector_v * 1e3
    finally:
        gui_pixel_checkpoint()


class CriticalHardwareTransportError(RuntimeError):
    """A hardware session is no longer safe to reuse for another pixel."""


def is_fatal_hardware_transport_error(exc: BaseException) -> bool:
    """Recognise VISA/serial/USB session loss through wrapped exceptions.

    Component-level measurement errors can remain resumable, but continuing a
    campaign after Windows has invalidated one or more instrument handles is
    unsafe: subsequent commands can target stale hardware state.  Walk both
    explicit causes and implicit exception contexts because the VISA error is
    commonly wrapped by a function-generator verification RuntimeError.
    """
    pending = [exc]
    seen: set[int] = set()
    message_markers = (
        "vi_error_system_error",
        "vi_error_conn_lost",
        "vi_error_inv_object",
        "vi_error_io",
        "vi_error_rsrc_locked",
        "visaioerror",
        "writefile failed",
        "clearcommerror failed",
        "getoverlappedresult failed",
        "access is denied",
        "device disconnected",
        "device not connected",
        "device is not connected",
        "serial port is closed",
        "invalid session",
        "resource is invalid",
        "oscilloscope detector read failed",
        "oscilloscope detector telemetry unavailable",
    )

    while pending:
        current = pending.pop()
        if current is None or id(current) in seen:
            continue
        seen.add(id(current))

        if isinstance(current, CriticalHardwareTransportError):
            return True
        class_name = type(current).__name__.lower()
        if (class_name.endswith("visaioerror") or "serialexception" in class_name
                or "serialtimeoutexception" in class_name
                or "devicenotconnectedexception" in class_name):
            return True
        if isinstance(current, PermissionError):
            return True
        if getattr(current, "errno", None) in (5, 13, 19):
            return True
        if getattr(current, "winerror", None) in (5, 31, 1167):
            return True

        message = str(current).lower()
        if any(marker in message for marker in message_markers):
            return True

        cause = getattr(current, "__cause__", None)
        context = getattr(current, "__context__", None)
        if cause is not None:
            pending.append(cause)
        if context is not None:
            pending.append(context)

    return False


def hardware_transport_stop_message(exc: BaseException, context: str) -> str:
    return (
        f"{context}: instrument USB/VISA/serial transport failed "
        f"({type(exc).__name__}: {exc}). Aborting this pixel's interrupted "
        "measurement; automatic hardware recovery is required before the next pixel."
    )


def raise_if_fatal_hardware_transport_error(exc: BaseException, context: str) -> None:
    """Unwind the interrupted component to the campaign recovery handler."""
    if not is_fatal_hardware_transport_error(exc):
        return
    if isinstance(exc, CriticalHardwareTransportError):
        raise exc
    raise CriticalHardwareTransportError(
        hardware_transport_stop_message(exc, context)
    ) from exc


def ensure_fast_map_outputs_off(funcgen, smu, context: str) -> None:
    """Attempt both shutdowns; failed verification requires session recovery."""
    interrupted = isinstance(sys.exc_info()[1], KeyboardInterrupt)
    errors = []
    try:
        pockels._funcgen_set_sweep_output(
            funcgen, False, verify_command=True, required=True, context=context,
        )
    except Exception as exc:
        errors.append(exc)
    try:
        auto.smu_output_off(smu, context)
        state = str(smu.query("OUTPut:STATe?")).strip().upper()
        if state not in ("0", "OFF"):
            raise RuntimeError(f"SMU output OFF readback was {state!r}")
    except Exception as exc:
        errors.append(exc)
    if errors:
        detail = "; ".join(f"{type(exc).__name__}: {exc}" for exc in errors)
        if interrupted:
            print(f"  [WARN] Output shutdown could not be verified during Stop: {detail}")
            return
        raise CriticalHardwareTransportError(
            f"{context}: output shutdown could not be verified; {detail}"
        ) from errors[0]
    gui_update_state(ac_voltage_on=False, dc_voltage_on=False, current_vpp=None, current_slope_side="")


def fast_rotator_move_or_fallback(
    rot,
    target_deg: float,
    *,
    fast: bool = True,
    verify: bool = False,
    tol_deg: float = 0.5,
    label: str = "rotator",
) -> dict:
    """Move a rotator quickly, optionally read back and recover safely.

    The default fast path keeps the direct absolute move behavior used by the
    screening workflow, but calls it through a small compatibility layer so
    older/simple rotator classes do not fail because of keyword differences.
    When verify=True, require consecutive final readbacks inside tolerance;
    if the landing is still outside tol_deg, retry direct and then safe moves
    before escalating the interrupted pixel to hardware recovery.
    """
    target = wrap360(target_deg)
    corrected = False
    fallback_safe_move = False
    recovery_attempts = 0
    actual = float("nan")
    error = float("nan")
    readback_samples = 0
    readback_ok_samples = 0
    boundary_safe_move = False
    gui_pixel_checkpoint()
    try:
        if fast:
            needs_safe_path, current_for_path, boundary_reason = rotator_move_needs_boundary_safe_path(
                rot, target
            )
            gui_pixel_checkpoint()
            if needs_safe_path:
                boundary_safe_move = True
                if np.isfinite(current_for_path):
                    print(
                        f"    [ANGLE] {label} using boundary-safe path "
                        f"{current_for_path:.2f} -> {target:.2f} deg ({boundary_reason})."
                    )
                else:
                    print(
                        f"    [ANGLE] {label} using boundary-safe path to "
                        f"{target:.2f} deg ({boundary_reason})."
                    )
                rotator_safe_move(rot, target, pockels.MOVE_SETTLE_S)
            else:
                rotator_direct_set_angle(rot, target, pockels.MOVE_SETTLE_S, read_back=False)
        else:
            boundary_safe_move = True
            rotator_safe_move(rot, target, pockels.MOVE_SETTLE_S)
        gui_pixel_checkpoint()
    except SkipPixelRequested:
        raise
    except Exception as exc:
        raise_if_fatal_hardware_transport_error(
            exc, f"{label} move to {target:.2f} deg"
        )
        if not verify:
            raise
        if fast and not boundary_safe_move:
            print(
                f"    [ANGLE] {label} direct move to {target:.2f} deg failed "
                f"({exc}); entering verified recovery."
            )
        else:
            print(
                f"    [ANGLE] {label} safe move to {target:.2f} deg failed "
                f"({exc}); entering verified recovery."
            )

    if verify:
        gui_pixel_checkpoint()
        actual, error, readback_samples, readback_ok_samples = rotator_verified_readback(
            rot, target, tol_deg
        )

        def verified_ok() -> bool:
            required = min(2, max(1, int(ANGLE_READBACK_SAMPLES)))
            return np.isfinite(error) and readback_ok_samples >= required

        if not verified_ok():
            if np.isfinite(error):
                print(
                    f"    [ANGLE] {label} target={target:.2f} actual={actual:.2f} "
                    f"err={error:.3f} deg, tolerance={tol_deg:.3f}, "
                    f"stable reads={readback_ok_samples}; correcting once."
                )
            else:
                print(
                    f"    [ANGLE] {label} target={target:.2f} readback unavailable; "
                    "correcting once."
            )
            corrected = True
            try:
                gui_pixel_checkpoint()
                needs_safe_path, _, _ = rotator_move_needs_boundary_safe_path(rot, target)
                if boundary_safe_move or needs_safe_path:
                    rotator_safe_move(rot, target, pockels.MOVE_SETTLE_S)
                else:
                    rotator_direct_set_angle(rot, target, pockels.MOVE_SETTLE_S, read_back=False)
            except SkipPixelRequested:
                raise
            except Exception as exc:
                raise_if_fatal_hardware_transport_error(
                    exc, f"{label} correction to {target:.2f} deg"
                )
                print(f"    [ANGLE] {label} correction failed ({exc}); using recovery retries.")
            gui_pixel_checkpoint()
            actual, error, readback_samples, readback_ok_samples = rotator_verified_readback(
                rot, target, tol_deg
            )

        while not verified_ok() and recovery_attempts < ANGLE_RECOVERY_RETRIES:
            recovery_attempts += 1
            print(
                f"    [ANGLE] {label} recovery safe-wrap retry "
                f"{recovery_attempts}/{ANGLE_RECOVERY_RETRIES}."
            )
            fallback_safe_move = True
            try:
                gui_pixel_checkpoint()
                rotator_safe_move(rot, target, pockels.MOVE_SETTLE_S)
            except SkipPixelRequested:
                raise
            except Exception as exc:
                raise_if_fatal_hardware_transport_error(
                    exc, f"{label} recovery move to {target:.2f} deg"
                )
                print(f"    [ANGLE] {label} safe-wrap retry failed ({exc}).")
                gui_sleep(ANGLE_RECOVERY_PAUSE_S, allow_skip=True)
                actual, error, readback_samples, readback_ok_samples = rotator_verified_readback(
                    rot, target, tol_deg
                )
                continue
            gui_sleep(ANGLE_RECOVERY_PAUSE_S, allow_skip=True)
            actual, error, readback_samples, readback_ok_samples = rotator_verified_readback(
                rot, target, tol_deg
            )
            gui_pixel_checkpoint()

        if recovery_attempts and verified_ok():
            print(
                f"    [ANGLE] {label} recovered: target={target:.2f} "
                f"actual={actual:.2f} err={error:.3f} deg."
            )

        if not verified_ok():
            if np.isfinite(error):
                print(
                    f"    [ANGLE] {label} still off: target={target:.2f} "
                    f"actual={actual:.2f} err={error:.3f} deg."
                )
            else:
                print(f"    [ANGLE] {label} still has no valid readback at target={target:.2f} deg.")

    return {
        "target_deg": target,
        "actual_deg": actual,
        "error_deg": error,
        "corrected": corrected,
        "fallback_safe_move": fallback_safe_move,
        "boundary_safe_move": boundary_safe_move,
        "recovery_attempts": recovery_attempts,
        "readback_samples": readback_samples,
        "readback_ok_samples": readback_ok_samples,
        "ok": (not verify) or (
            np.isfinite(error)
            and readback_ok_samples >= min(2, max(1, int(ANGLE_READBACK_SAMPLES)))
        ),
    }


def gui_angle_from_move(move: dict, target_deg: float) -> float:
    try:
        actual = float(move.get("actual_deg", float("nan")))
    except Exception:
        actual = float("nan")
    return actual if np.isfinite(actual) else wrap360(target_deg)


class CriticalAngleError(RuntimeError):
    """The current point is invalid; recover the hardware at the pixel boundary."""


class CriticalNullError(RuntimeError):
    pass


class CriticalCalibrationNullError(CriticalNullError):
    """The calibration null procedure failed, so the current pixel is invalid."""


def require_verified_move(move: dict | None, label: str) -> None:
    """Reject an invalid point so the pixel handler can recover and continue."""
    if move is None or bool(move.get("ok", True)):
        return
    target = _gui_float(move.get("target_deg"), float("nan"))
    actual = _gui_float(move.get("actual_deg"), float("nan"))
    error = _gui_float(move.get("error_deg"), float("nan"))
    bits = []
    if np.isfinite(target):
        bits.append(f"target={target:.2f} deg")
    if np.isfinite(actual):
        bits.append(f"actual={actual:.2f} deg")
    if np.isfinite(error):
        bits.append(f"err={error:.3f} deg")
    detail = ", ".join(bits) if bits else "readback unavailable"
    gui_update_state(phase=f"ANGLE ERROR: {label}", active_optic=label.split()[0].upper())
    raise CriticalAngleError(f"{label} angle verification failed ({detail})")


def angle_grid_from_start_stop_step(start_deg: float, stop_deg: float, step_deg: float) -> np.ndarray:
    step = float(step_deg)
    if step == 0.0:
        raise ValueError("HWP step must be non-zero")
    values = np.arange(float(start_deg), float(stop_deg) + step / 2.0, step)
    values = np.round(values, 6)
    if values.size == 0:
        raise ValueError("HWP grid is empty; check start/stop/step")
    return values


def hwp_sweep_mode_from_args(args) -> str:
    mode = str(
        getattr(args, "hwp_sweep_mode", DEFAULT_HWP_SWEEP_MODE)
        or DEFAULT_HWP_SWEEP_MODE
    ).strip().lower()
    if mode in ("centered", "centered_180", "centered-180", "centre", "centre-180"):
        return "centered-180"
    return "start-stop"


def hwp_center_span_from_args(args) -> float:
    if getattr(args, "hwp_input_frame", "lab") == "raw":
        return HWP_RAW_CENTER_SWEEP_SPAN_DEG
    return HWP_CENTER_SWEEP_SPAN_DEG


def hwp_center_step_from_args(args) -> float | None:
    step = getattr(args, "hwp_center_step", None)
    if step is None:
        return None
    try:
        step = float(step)
    except (TypeError, ValueError):
        return None
    if not np.isfinite(step) or step <= 0.0:
        return None
    if getattr(args, "hwp_input_frame", "lab") == "raw":
        return step / 2.0
    return step


def hwp_input_grid_from_args(args) -> np.ndarray:
    if hwp_sweep_mode_from_args(args) != "centered-180":
        return angle_grid_from_start_stop_step(args.hwp_start, args.hwp_stop, args.hwp_step)

    span = hwp_center_span_from_args(args)
    step = hwp_center_step_from_args(args)
    if step is not None:
        intervals = int(round(span / step))
        if intervals < 2:
            raise ValueError("Centered HWP sweep step is too large for the sweep span")
        n_points = intervals + 1
    else:
        n_points = int(getattr(args, "hwp_points", DEFAULT_HWP_CENTER_SWEEP_POINTS))
    if n_points < 3:
        raise ValueError("Centered HWP sweep needs at least 3 points")
    if n_points % 2 == 0:
        raise ValueError("Centered HWP sweep point count must be odd so the centre point is measured")
    centre = float(args.hwp_start)
    half_span = span / 2.0
    values = np.linspace(centre - half_span, centre + half_span, n_points)
    return np.round(values, 6)


def hwp_lab_theta_i_grid_from_args(args) -> np.ndarray:
    grid = hwp_input_grid_from_args(args)
    if getattr(args, "hwp_input_frame", "lab") == "raw":
        return np.round([lab_theta_i_from_hwp(v) for v in grid], 6)
    return grid


def hwp_angles_from_args(args) -> np.ndarray:
    grid = hwp_input_grid_from_args(args)
    if getattr(args, "hwp_input_frame", "lab") == "raw":
        return grid
    return np.round([raw_hwp_from_lab_theta_i(v) for v in grid], 6)


def shortest_delta_deg(start_deg: float, end_deg: float) -> float:
    return (float(end_deg) - float(start_deg) + 540.0) % 360.0 - 180.0


def periodic_delta_deg(start_deg: float, end_deg: float, period_deg: float) -> float:
    """Shortest signed end-start delta for angles with a custom optical period."""
    period = float(period_deg)
    return (float(end_deg) - float(start_deg) + 0.5 * period) % period - 0.5 * period


def closest_periodic_equivalent_deg(
    target_deg: float,
    reference_deg: float,
    period_deg: float = 180.0,
    *,
    analyser: bool = False,
) -> float:
    """Choose the raw equivalent of an optical angle that is cheapest from a reference."""
    base = wrap360(target_deg)
    candidates = [wrap360(base + k * period_deg) for k in range(-2, 3)]
    unique: list[float] = []
    for cand in candidates:
        if not any(abs(shortest_delta_deg(cand, existing)) < 1e-6 for existing in unique):
            unique.append(cand)
    try:
        reference = float(reference_deg)
    except Exception:
        reference = base
    if not np.isfinite(reference):
        reference = base
    if analyser:
        return min(unique, key=lambda cand: safe_wrap_move_cost_deg(reference, cand))
    return min(unique, key=lambda cand: abs(shortest_delta_deg(reference, cand)))


def safe_wrap_move_cost_deg(start_deg: float, target_deg: float) -> float:
    """Match safe_move_wrap's boundary rule so target choice avoids long moves."""
    start = wrap360(start_deg)
    target = wrap360(target_deg)
    backlash = float(getattr(auto.analyser, "ROTATOR_BACKLASH_DEG", 0.3))
    approach = wrap360(target - backlash)
    short = shortest_delta_deg(start, approach)
    endpoint = start + short
    if endpoint > 360.0 or endpoint < 0.0:
        safe_delta = short - 360.0 if short > 0.0 else short + 360.0
    else:
        safe_delta = short
    return abs(safe_delta)


def manual_peak_branch_available_for_hwp(
    hwp_deg: float,
    manual_peak_raw: dict | None,
    *,
    window_deg: float = MANUAL_PEAK_BRANCH_HWP_WINDOW_DEG,
) -> bool:
    if not manual_peak_raw:
        return False
    try:
        manual_hwp = float(manual_peak_raw["hwp_deg"])
        hwp = float(hwp_deg)
    except Exception:
        return False
    if not all(np.isfinite(v) for v in (manual_hwp, hwp)):
        return False
    return abs(periodic_delta_deg(manual_hwp, hwp, 90.0)) <= float(window_deg)


def manual_peak_branch_seed_for_hwp(
    hwp_deg: float,
    manual_peak_raw: dict | None,
    current_q_seed: float,
    current_a_seed: float,
    *,
    qwp_readout_offset_deg: float = DEFAULT_QWP_READOUT_OFFSET_DEG,
    window_deg: float = MANUAL_PEAK_BRANCH_HWP_WINDOW_DEG,
) -> dict | None:
    """Infer the null branch whose readout QWP and +/-45 analyser point hit a raw peak."""
    if not manual_peak_branch_available_for_hwp(
        hwp_deg,
        manual_peak_raw,
        window_deg=window_deg,
    ):
        return None
    try:
        manual_hwp = float(manual_peak_raw["hwp_deg"])
        manual_qwp = float(manual_peak_raw["qwp_deg"])
        manual_anl = float(manual_peak_raw["anl_deg"])
        hwp = float(hwp_deg)
    except Exception:
        return None
    if not all(np.isfinite(v) for v in (manual_hwp, manual_qwp, manual_anl, hwp)):
        return None

    # HWP has a 90 deg optical period because the incident polarization rotates 2x.
    hwp_delta = periodic_delta_deg(manual_hwp, hwp, 90.0)

    # Across the 90 deg HWP optical period, the QWP and analyser branch are
    # expected to track the incident polarization. The manual QWP angle is the
    # readout bias, so convert it back to the underlying QWP null before using
    # it as the automatic null seed.
    try:
        qwp_readout_offset = float(qwp_readout_offset_deg)
    except Exception:
        qwp_readout_offset = 0.0
    if not np.isfinite(qwp_readout_offset):
        qwp_readout_offset = 0.0
    q_seed_raw = manual_qwp - qwp_readout_offset + 2.0 * hwp_delta
    q_readout_raw = manual_qwp + 2.0 * hwp_delta
    anl_peak_raw = manual_anl + 2.0 * hwp_delta
    q_seed = closest_periodic_equivalent_deg(q_seed_raw, current_q_seed, 180.0)

    null_bases = (anl_peak_raw - 45.0, anl_peak_raw + 45.0)
    candidates: list[float] = []
    for base in null_bases:
        cand = closest_periodic_equivalent_deg(
            base,
            current_a_seed,
            180.0,
            analyser=True,
        )
        if not any(abs(shortest_delta_deg(cand, existing)) < 1e-6 for existing in candidates):
            candidates.append(cand)
    candidates.sort(key=lambda cand: safe_wrap_move_cost_deg(current_a_seed, cand))
    return {
        "hwp_delta_deg": float(hwp_delta),
        "q_seed_deg": float(q_seed),
        "q_readout_seed_deg": float(wrap360(q_readout_raw)),
        "qwp_readout_offset_deg": float(qwp_readout_offset),
        "anl_peak_deg": float(wrap360(anl_peak_raw)),
        "a_null_candidates_deg": candidates,
    }


AUTO_READOUT_PEAK_STEPS_DEG = (5.0, 2.0, 0.75)
AUTO_READOUT_PEAK_MIN_IMPROVE_UV = 0.50
AUTO_READOUT_PEAK_NOISE_SIGMA = 2.0

# Legacy locked-QWP peak-search strategy.  The production triplet path now
# runs its own adaptive S9 operating-point certificate: a compact fit on the
# first calibration pixel, then quick triplet checks with fit-on-failure on
# later pixels.  This switch remains for non-triplet diagnostic workflows.
AUTO_PEAK_REFINE_MODE = "two-point"    # "two-point" (default), "fit", "greedy"
AUTO_READOUT_PEAK_MAX_ITER_PER_STEP = 2
AUTO_PEAK_GLOBAL_GRID_STEP_DEG = 15.0
AUTO_PEAK_GLOBAL_TOP_SEEDS = 2
AUTO_PEAK_FAST_SEED_PAIR_OFFSETS_DEG = (
    (0.0, -45.0), (0.0, 45.0),
    (0.0, -75.0), (0.0, 75.0),
    (0.0, -90.0), (0.0, 90.0),
    (-30.0, -75.0), (30.0, 75.0),
    (-30.0, 75.0), (30.0, -75.0),
    (-15.0, -60.0), (15.0, 60.0),
    (-15.0, 60.0), (15.0, -60.0),
    (-45.0, -90.0), (45.0, 90.0),
    (-45.0, 90.0), (45.0, -90.0),
    (-30.0, -45.0), (30.0, 45.0),
    (-30.0, 45.0), (30.0, -45.0),
    (-45.0, -45.0), (45.0, 45.0),
    (0.0, -30.0), (0.0, 30.0),
    (-60.0, -75.0), (60.0, 75.0),
    (-60.0, 75.0), (60.0, -75.0),
    (0.0, 0.0),
)


def lockin_peak_improvement_threshold_uV(*rows: dict | None) -> float:
    """Minimum accepted peak gain using the combined phasor standard error."""
    sems_uV: list[float] = []
    for row in rows:
        if not row:
            continue
        sem = _finite_float_or_none(row.get("lockin_net_mag_sem_V"))
        if sem is None:
            sem = _finite_float_or_none(row.get("lockin_mag_sem_V"))
        if sem is not None and sem >= 0.0:
            sems_uV.append(float(sem) * 1e6)
    combined_sem_uV = math.sqrt(sum(value * value for value in sems_uV))
    return max(
        float(AUTO_READOUT_PEAK_MIN_IMPROVE_UV),
        float(AUTO_READOUT_PEAK_NOISE_SIGMA) * combined_sem_uV,
    )
AUTO_PEAK_COARSE_Q_OFFSETS_DEG = (
    45.0, -45.0, 75.0, -75.0, 90.0, -90.0,
    60.0, -60.0, 30.0, -30.0, 15.0, -15.0, 0.0,
)
AUTO_PEAK_COARSE_A_OFFSETS_DEG = (
    -75.0, 75.0, -90.0, 90.0,
    -45.0, 45.0, -30.0, 30.0, -15.0, 15.0, 0.0,
)


def auto_peak_readout_offset_from_context(base_null_context: dict | None) -> float:
    value = None
    if isinstance(base_null_context, dict):
        value = _finite_float_or_none(base_null_context.get("qwp_readout_offset_from_null_deg"))
    if value is None:
        value = DEFAULT_QWP_READOUT_OFFSET_DEG
    return float(value)


def auto_peak_seed_candidates_from_null(
    q_null: float,
    a_null: float,
    base_null_context: dict | None,
    max_coarse_probes: int | None,
) -> list[tuple[float, float, float, float]]:
    """Return bounded QWP/analyser seed candidates around the null branch.

    The old first-pixel auto search measured every QWP offset against every
    analyser offset (143 lock-in reads before refinement). This ordered list
    first tests the expected readout branch and nearby coupled alternatives;
    setting max_coarse_probes <= 0 appends the old full grid as a deep rescue.
    """
    try:
        max_probes = int(max_coarse_probes)
    except Exception:
        max_probes = DEFAULT_AUTO_PEAK_MAX_COARSE_PROBES
    readout_offset = auto_peak_readout_offset_from_context(base_null_context)
    candidates: list[tuple[float, float, float, float]] = []
    seen: set[tuple[float, float]] = set()

    def add(q_offset_from_null: float, a_offset_from_null: float) -> None:
        q_try = closest_periodic_equivalent_deg(
            float(q_null) + float(q_offset_from_null),
            float(q_null),
            180.0,
        )
        a_try = closest_periodic_equivalent_deg(
            float(a_null) + float(a_offset_from_null),
            float(a_null),
            180.0,
            analyser=True,
        )
        key = (round(wrap360(q_try), 6), round(wrap360(a_try), 6))
        if key in seen:
            return
        seen.add(key)
        candidates.append((float(q_try), float(a_try), float(q_offset_from_null), float(a_offset_from_null)))

    if max_probes > 0:
        for q_adjust_from_readout, a_offset in AUTO_PEAK_FAST_SEED_PAIR_OFFSETS_DEG:
            add(readout_offset + float(q_adjust_from_readout), float(a_offset))
            if len(candidates) >= max_probes:
                return candidates

    for q_offset in AUTO_PEAK_COARSE_Q_OFFSETS_DEG:
        for a_offset in AUTO_PEAK_COARSE_A_OFFSETS_DEG:
            add(float(q_offset), float(a_offset))
            if max_probes > 0 and len(candidates) >= max_probes:
                return candidates

    return candidates


def periodic_offsets_for_step(step_deg: float, period_deg: float = 180.0) -> tuple[list[float], float]:
    try:
        requested = abs(float(step_deg))
    except Exception:
        requested = AUTO_PEAK_GLOBAL_GRID_STEP_DEG
    if not np.isfinite(requested) or requested <= 0.0:
        requested = AUTO_PEAK_GLOBAL_GRID_STEP_DEG
    n_steps = max(4, int(round(float(period_deg) / requested)))
    actual_step = float(period_deg) / float(n_steps)
    return [idx * actual_step for idx in range(n_steps)], actual_step


def auto_peak_global_seed_candidates_from_null(
    q_null: float,
    a_null: float,
    step_deg: float = AUTO_PEAK_GLOBAL_GRID_STEP_DEG,
) -> tuple[list[tuple[float, float, float, float]], float]:
    """Return a full periodic QWP/analyser grid for strict calibration-pixel peak finding."""
    offsets, actual_step = periodic_offsets_for_step(step_deg, 180.0)
    candidates: list[tuple[float, float, float, float]] = []
    seen: set[tuple[float, float]] = set()
    for q_offset in offsets:
        for a_offset in offsets:
            q_try = closest_periodic_equivalent_deg(float(q_null) + q_offset, float(q_null), 180.0)
            a_try = closest_periodic_equivalent_deg(
                float(a_null) + a_offset,
                float(a_null),
                180.0,
                analyser=True,
            )
            key = (round(wrap360(q_try), 6), round(wrap360(a_try), 6))
            if key in seen:
                continue
            seen.add(key)
            candidates.append((float(q_try), float(a_try), float(q_offset), float(a_offset)))
    return candidates, float(actual_step)


def ordered_slope_targets(a_null: float, current_anl_angle: float | None) -> list[tuple[str, float]]:
    """Choose Malus-equivalent +45/-45 targets that avoid 0/360 wrap moves."""
    try:
        current = float(current_anl_angle)
    except Exception:
        current = float(a_null)
    if not np.isfinite(current):
        current = float(a_null)
    current = wrap360(current)

    candidates = {
        "plus45": [wrap360(a_null + 45.0), wrap360(a_null + 225.0)],
        "minus45": [wrap360(a_null + 135.0), wrap360(a_null + 315.0)],
    }

    best_plan: list[tuple[str, float]] | None = None
    best_cost = float("inf")
    for order in (("plus45", "minus45"), ("minus45", "plus45")):
        first_side, second_side = order
        for first_target in candidates[first_side]:
            for second_target in candidates[second_side]:
                cost = (
                    safe_wrap_move_cost_deg(current, first_target)
                    + safe_wrap_move_cost_deg(first_target, second_target)
                    + 0.25 * safe_wrap_move_cost_deg(second_target, first_target)
                )
                if cost < best_cost:
                    best_cost = cost
                    best_plan = [(first_side, first_target), (second_side, second_target)]

    if best_plan is None:
        return [("plus45", candidates["plus45"][0]), ("minus45", candidates["minus45"][0])]
    return best_plan


def learned_readout_triplet_targets(
    a_peak: float,
    a_null: float,
    current_anl_angle: float | None,
) -> list[tuple[str, float]]:
    """Return the local null and exact opposite quadrature slopes.

    The saved calibration peak is used only to preserve which slope is visited
    first.  Its absolute analyser offset is deliberately not inherited: every
    production pixel is tied to its newly checked local null at exactly +/-45
    degrees, preventing a strong but off-quadrature raw peak from propagating
    across the chip.
    """
    try:
        current = float(current_anl_angle)
    except Exception:
        current = float(a_null)
    if not np.isfinite(current):
        current = float(a_null)

    zero = closest_periodic_equivalent_deg(
        a_null, current, 180.0, analyser=True
    )
    learned_offset = periodic_delta_deg(a_null, a_peak, 180.0)
    peak_offset = -45.0 if np.isfinite(learned_offset) and learned_offset < 0.0 else 45.0
    peak = closest_periodic_equivalent_deg(
        zero + peak_offset, zero, 180.0, analyser=True
    )
    opposite = closest_periodic_equivalent_deg(
        zero - float(peak_offset),
        peak,
        180.0,
        analyser=True,
    )
    return [
        ("learned_zero", zero),
        ("learned_anchor", peak),
        ("learned_opposite", opposite),
    ]


def analyser_offset_from_null_deg(a_null: float, target_deg: float) -> float:
    """Return analyser offset from null in the 180-degree optical frame."""
    return (wrap360(target_deg) - wrap360(a_null) + 90.0) % 180.0 - 90.0


def require_valid_slope_target(slope_side: str, a_null: float, target_deg: float) -> float:
    """Verify that a slope label really maps to the intended optical offset."""
    if str(slope_side) == "plus45":
        expected = 45.0
    elif str(slope_side) == "minus45":
        expected = -45.0
    elif str(slope_side) in (
        "auto_peak",
        "auto_peak_probe",
        "learned_zero",
        "learned_anchor",
        "learned_opposite",
    ) or str(slope_side).startswith("peak_diag_"):
        return analyser_offset_from_null_deg(a_null, target_deg)
    else:
        raise CriticalAngleError(f"Unknown analyser slope side: {slope_side!r}")
    offset = analyser_offset_from_null_deg(a_null, target_deg)
    if abs(offset - expected) > 1e-6:
        raise CriticalAngleError(
            f"Invalid analyser slope target: {slope_side} null={wrap360(a_null):.2f} deg, "
            f"target={wrap360(target_deg):.2f} deg gives optical offset {offset:.3f} deg "
            f"(expected {expected:+.1f} deg)."
        )
    return offset


def qwp_readout_target_from_null(q_null: float, offset_deg: float) -> float:
    """QWP angle used for AC readout after the AC-off QWP/ANL null."""
    q_null_f = float(q_null)
    offset_f = float(offset_deg)
    if not np.isfinite(q_null_f):
        return float("nan")
    if not np.isfinite(offset_f):
        offset_f = 0.0
    return closest_periodic_equivalent_deg(q_null_f + offset_f, q_null_f, 180.0)


def configure_console_noise(args) -> dict:
    previous = {
        "range": getattr(stage, "PRINT_RANGE_CHANGES", None),
        "wrap": getattr(auto.analyser, "PRINT_WRAP_MOVES", None),
    }
    if hasattr(stage, "PRINT_RANGE_CHANGES"):
        stage.PRINT_RANGE_CHANGES = bool(args.show_range_changes)
    if hasattr(auto.analyser, "PRINT_WRAP_MOVES"):
        auto.analyser.PRINT_WRAP_MOVES = bool(args.show_wrap_moves)
    hidden = []
    if not args.show_range_changes:
        hidden.append("[RANGE]")
    if not args.show_wrap_moves:
        hidden.append("successful [WRAP-MOVE]")
    if hidden:
        print(f"Console detail: routine {' and '.join(hidden)} lines hidden.")
    return previous


def restore_console_noise(previous: dict | None) -> None:
    if not previous:
        return
    if previous.get("range") is not None and hasattr(stage, "PRINT_RANGE_CHANGES"):
        stage.PRINT_RANGE_CHANGES = previous["range"]
    if previous.get("wrap") is not None and hasattr(auto.analyser, "PRINT_WRAP_MOVES"):
        auto.analyser.PRINT_WRAP_MOVES = previous["wrap"]


def prepare_optics_for_stage_alignment(
    *,
    hwp_angles: np.ndarray,
    rot_hwp,
    rot_qwp,
    rot_anl,
    null_seed_by_hwp: dict,
    fallback_seed: tuple[float, float],
    funcgen=None,
    fast_rotator_moves: bool = True,
    verify_moves: bool = False,
    verify_tol_deg: float = 0.5,
) -> tuple[float, float]:
    """Reset to a known HWP/QWP/ANL null before bright stage alignment."""
    if funcgen is not None:
        pockels._funcgen_set_sweep_output(
            funcgen,
            False,
            verify_command=True,
            required=True,
            context="stage-alignment optical reset",
        )

    hwp_align = float(hwp_angles[0]) if len(hwp_angles) else 0.0
    hwp_key = f"{hwp_align:.3f}"
    seed = null_seed_by_hwp.get(hwp_key, {})
    q_seed = float(seed.get("q_null_deg", fallback_seed[0]))
    a_seed = float(seed.get("a_null_deg", fallback_seed[1]))

    print(
        f"  Reset optics for alignment: HWP={hwp_align:.1f}, "
        f"QWP={q_seed:.2f}, ANL null={a_seed:.2f} "
        f"(then +{auto.BRIGHTEN_OFFSET_DEG:.0f} deg brighten)"
    )
    hwp_move = fast_rotator_move_or_fallback(
        rot_hwp,
        hwp_align,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label="HWP align",
    )
    require_verified_move(hwp_move, "HWP align")
    q_move = fast_rotator_move_or_fallback(
        rot_qwp,
        q_seed,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label="QWP align null",
    )
    require_verified_move(q_move, "QWP align null")
    a_move = fast_rotator_move_or_fallback(
        rot_anl,
        a_seed,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label="ANL align null",
    )
    require_verified_move(a_move, "ANL align null")
    gui_sleep(0.2, allow_skip=True)
    return q_seed, a_seed


def measure_lockin_null_reference(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    null_context: dict,
    t_start: float,
) -> tuple[int, dict | None, list[dict]]:
    """Read a GUI lock-in reference at analyser null; saved at the next HWP checkpoint."""
    try:
        qwp_readout = float(null_context.get("qwp_readout_deg", q_null))
        gui_update_state(
            current_pixel=int(pixel["pixel"]),
            current_hwp_deg=float(hwp_deg),
            current_hwp_null_deg=float(hwp_deg),
            current_qwp_deg=float(q_null),
            current_qwp_target_deg=wrap360(q_null),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_null_deg=wrap360(a_null),
            current_anl_target_deg=wrap360(a_null),
            current_anl_offset_deg=0.0,
            current_vpp=float(vpp),
            current_slope_side="zero",
            active_optic="QWP",
            phase="Moving QWP/ANL to true null reference",
            ac_voltage_on=True,
        )
        q_null_move = fast_rotator_move_or_fallback(
            rot_qwp,
            q_null,
            fast=fast_rotator_moves,
            verify=verify_moves,
            tol_deg=verify_tol_deg,
            label="QWP true-null lock-in reference",
        )
        require_verified_move(q_null_move, "QWP true-null lock-in reference")
        anl_move = fast_rotator_move_or_fallback(
            rot_anl,
            a_null,
            fast=fast_rotator_moves,
            verify=verify_moves,
            tol_deg=verify_tol_deg,
            label="ANL null lock-in reference",
        )
        require_verified_move(anl_move, "ANL null lock-in reference")
        gui_pixel_checkpoint()
        q_null_actual = gui_angle_from_move(q_null_move, q_null)
        q_null_error = q_null_move.get("error_deg", float("nan"))
        try:
            anl_actual = float(anl_move.get("actual_deg", float("nan")))
        except Exception:
            anl_actual = float("nan")
        if not np.isfinite(anl_actual):
            anl_actual = wrap360(a_null)
        angle_error = pockels.angular_error(float(anl_actual), wrap360(a_null))

        gui_sleep(pockels.LOCKIN_SETTLE_S, allow_skip=True)
        sens_idx, overloaded = check_fixed_lockin_overload(lockin, sens_idx)
        if overloaded:
            gui_sleep(pockels.OVERLOAD_SETTLE_S, allow_skip=True)
        gui_pixel_checkpoint()
        try:
            null_ref_power_w, detector_v = detector.read_power_w_stable()
        except Exception:
            null_ref_power_w = float(p_null)
            detector_v = float(p_null_mV) * 1e-3 if np.isfinite(float(p_null_mV)) else float("nan")
        avg_mag, avg_phase, std_mag, std_phase, raw_mags, raw_phases, raw_ts = (
            pockels.read_lockin_averaged(
                lockin,
                pockels.LOCKIN_AVG_READINGS,
                pockels.LOCKIN_READ_DELAY_S,
            )
        )
        sample_fields = lockin_sample_statistics_fields(
            raw_mags, raw_phases, reference_phase_deg
        )
        avg_mag = sample_fields["lockin_mag_V"]
        avg_phase = sample_fields["lockin_phase_deg"]
        raw_signed = [
            signed_lockin_from_mag_phase(mag, phase, reference_phase_deg)
            for mag, phase in zip(raw_mags, raw_phases)
        ]
        signed_v = sample_fields["lockin_signed_V"]
        sens_table = getattr(pockels, "SENS_TABLE_VOLTS", {})
        sensitivity_v = (
            float(sens_table.get(sens_idx, float("nan")))
            if isinstance(sens_table, dict)
            else float("nan")
        )
        timestamp = datetime.now().isoformat()
        elapsed_s = time.time() - t_start
        flags: list[str] = []
        append_quality(flags, overloaded, "lockin_overload")
        fullscale_fraction = append_lockin_range_quality(
            flags, avg_mag, sensitivity_v
        )
        append_quality(flags, abs(float(q_null_error)) > float(verify_tol_deg), "qwp_true_null_angle_error")
        append_quality(flags, verify_moves and not bool(q_null_move.get("ok", True)), "qwp_true_null_angle_verify_failed")
        append_quality(flags, abs(angle_error) > float(verify_tol_deg), "analyser_angle_error")
        append_quality(flags, verify_moves and not bool(anl_move.get("ok", True)), "analyser_angle_verify_failed")
        append_quality(flags, len(raw_mags) < pockels.LOCKIN_AVG_READINGS, "short_lockin_average")
        for flag in null_context.get("quality_flags", []):
            append_quality(flags, True, str(flag))
        row = {
            "pixel": int(pixel["pixel"]),
            "row": int(pixel.get("j", 0)),
            "col": int(pixel.get("i", 0)),
            "hwp_deg": float(hwp_deg),
            "hwp_actual_deg": null_context.get("hwp_actual_deg", float("nan")),
            "hwp_error_deg": null_context.get("hwp_error_deg", float("nan")),
            "theta_i_deg": theta_i_from_hwp(hwp_deg),
            "seed_q_null_deg": null_context.get("seed_q_null_deg", float("nan")),
            "seed_a_null_deg": null_context.get("seed_a_null_deg", float("nan")),
            "seed_p_null_W": null_context.get("seed_p_null_W", float("nan")),
            "seed_p_null_mV": null_context.get("seed_p_null_mV", float("nan")),
            "q_null_deg": float(q_null),
            "qwp_actual_deg": float(q_null_actual),
            "qwp_error_deg": float(q_null_error),
            "qwp_readout_deg": float(q_null),
            "qwp_readout_actual_deg": float(q_null_actual),
            "qwp_readout_error_deg": float(q_null_error),
            "qwp_readout_offset_from_null_deg": 0.0,
            "a_null_deg": float(a_null),
            "anl_null_actual_deg": null_context.get("anl_null_actual_deg", float("nan")),
            "anl_null_error_deg": null_context.get("anl_null_error_deg", float("nan")),
            "p_null_W": float(p_null),
            "p_null_mV": float(p_null_mV),
            "null_method": null_context.get("null_method", ""),
            "null_n_evals": null_context.get("null_n_evals", ""),
            "null_escalated": null_context.get("null_escalated", ""),
            "null_mV_before_renull": null_context.get("null_mV_before_renull", float("nan")),
            "null_mV_after_renull": null_context.get("null_mV_after_renull", float("nan")),
            "q_delta_deg": null_context.get("q_delta_deg", float("nan")),
            "a_delta_deg": null_context.get("a_delta_deg", float("nan")),
            "slope_side": "zero",
            "anl_target_deg": wrap360(a_null),
            "anl_offset_from_null_deg": 0.0,
            "anl_actual_deg": float(anl_actual),
            "anl_error_deg": float(angle_error),
            "vpp": float(vpp),
            "power_W": float(null_ref_power_w),
            "detector_V": float(detector_v),
            **sample_fields,
            "sensitivity_fullscale_V": sensitivity_v,
            "lockin_fullscale_fraction": fullscale_fraction,
            "n_good_samples": len(raw_mags),
            "timestamp": timestamp,
            "elapsed_s": float(elapsed_s),
            "quality_flags": ";".join(flags),
        }
        row = add_fast_map_lab_angle_fields(row)
        raw_rows = []
        for idx, (mag, phase, signed, ts) in enumerate(zip(raw_mags, raw_phases, raw_signed, raw_ts)):
            raw_rows.append(make_raw_lockin_row(
                pixel=int(pixel["pixel"]),
                hwp_deg=float(hwp_deg),
                slope_side="zero",
                vpp=float(vpp),
                sample_index=idx,
                sample_timestamp=float(ts),
                lockin_mag_v=float(mag),
                lockin_phase_deg=float(phase),
                lockin_signed_v=float(signed),
            ))
        gui_update_lockin_bar(
            "zero",
            pixel=int(pixel["pixel"]),
            hwp_deg=float(hwp_deg),
            vpp=float(vpp),
            a_null=a_null,
            mag_v=float(avg_mag),
            signed_v=float(signed_v),
            phase_deg=float(avg_phase),
        )
        gui_update_state(
            current_pixel=int(pixel["pixel"]),
            current_hwp_deg=float(hwp_deg),
            current_hwp_null_deg=float(hwp_deg),
            current_qwp_deg=float(q_null_actual),
            current_qwp_target_deg=wrap360(q_null),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_deg=float(anl_actual),
            current_anl_null_deg=wrap360(a_null),
            current_anl_target_deg=wrap360(a_null),
            current_anl_offset_deg=0.0,
            current_vpp=float(vpp),
            current_slope_side="zero",
            lockin_mag_V=float(avg_mag),
            lockin_phase_deg=float(avg_phase),
            lockin_signed_V=float(signed_v),
            active_optic="LOCKIN",
            phase="True-null lock-in reference acquired",
        )
        gui_update_state(
            current_pixel=int(pixel["pixel"]),
            current_hwp_deg=float(hwp_deg),
            current_hwp_null_deg=float(hwp_deg),
            current_qwp_target_deg=wrap360(qwp_readout),
            current_qwp_null_deg=wrap360(q_null),
            active_optic="QWP",
            phase="Returning QWP to readout bias",
        )
        q_readout_move = fast_rotator_move_or_fallback(
            rot_qwp,
            qwp_readout,
            fast=fast_rotator_moves,
            verify=verify_moves,
            tol_deg=verify_tol_deg,
            label="QWP readout bias after true-null reference",
        )
        require_verified_move(q_readout_move, "QWP readout bias after true-null reference")
        q_readout_actual = gui_angle_from_move(q_readout_move, qwp_readout)
        gui_update_state(
            current_pixel=int(pixel["pixel"]),
            current_hwp_deg=float(hwp_deg),
            current_hwp_null_deg=float(hwp_deg),
            current_qwp_deg=float(q_readout_actual),
            current_qwp_target_deg=wrap360(qwp_readout),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_deg=float(anl_actual),
            current_anl_null_deg=wrap360(a_null),
            current_anl_target_deg=wrap360(a_null),
            current_anl_offset_deg=0.0,
            current_vpp=float(vpp),
            current_slope_side="zero",
            lockin_mag_V=float(avg_mag),
            lockin_phase_deg=float(avg_phase),
            lockin_signed_V=float(signed_v),
            active_optic="LOCKIN",
            phase="QWP readout bias restored",
        )
        return sens_idx, row, raw_rows
    except CriticalAngleError:
        raise
    except SkipPixelRequested:
        raise
    except Exception as exc:
        print(f"    [GUI] Null lock-in reference skipped: {type(exc).__name__}: {exc}")
    return sens_idx, None, []


def measure_lockin_point(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    slope_side: str,
    anl_target: float,
    vpp: float,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    null_context: dict,
    null_reference_row: dict | None,
    t_start: float,
) -> tuple[dict, list[dict], int]:
    anl_offset = require_valid_slope_target(slope_side, a_null, anl_target)
    qwp_readout = float(null_context.get("qwp_readout_deg", q_null))
    qwp_readout_actual = float(null_context.get("qwp_readout_actual_deg", qwp_readout))
    qwp_readout_error = float(null_context.get("qwp_readout_error_deg", float("nan")))
    qwp_readout_offset = float(null_context.get("qwp_readout_offset_from_null_deg", 0.0))
    gui_update_state(
        current_pixel=int(pixel["pixel"]),
        current_hwp_deg=float(hwp_deg),
        current_hwp_null_deg=float(hwp_deg),
        current_qwp_deg=float(qwp_readout_actual),
        current_qwp_target_deg=wrap360(qwp_readout),
        current_qwp_null_deg=wrap360(q_null),
        current_anl_null_deg=wrap360(a_null),
        current_anl_target_deg=wrap360(anl_target),
        current_anl_offset_deg=float(anl_offset),
        current_vpp=float(vpp),
        current_slope_side=slope_side,
        active_optic="ANL",
        phase=f"Moving analyser {slope_side}",
    )
    anl_move = fast_rotator_move_or_fallback(
        rot_anl,
        anl_target,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"ANL {slope_side}",
    )
    require_verified_move(anl_move, f"ANL {slope_side}")
    gui_pixel_checkpoint()
    anl_actual = anl_move.get("actual_deg")
    if not np.isfinite(float(anl_actual)):
        anl_actual = rotator_read_angle_once(rot_anl)
    if anl_actual is None:
        anl_actual = wrap360(anl_target)
    angle_error = pockels.angular_error(float(anl_actual), wrap360(anl_target))

    gui_sleep(pockels.LOCKIN_SETTLE_S, allow_skip=True)
    sens_idx, overloaded = check_fixed_lockin_overload(lockin, sens_idx)
    if overloaded:
        gui_sleep(pockels.OVERLOAD_SETTLE_S, allow_skip=True)
    gui_pixel_checkpoint()

    timestamp = datetime.now().isoformat()
    elapsed_s = time.time() - t_start
    try:
        power_w, detector_v = detector.read_power_w_stable()
    except Exception:
        power_w, detector_v = float("nan"), float("nan")
    gui_pixel_checkpoint()

    avg_mag, avg_phase, std_mag, std_phase, raw_mags, raw_phases, raw_ts = (
        pockels.read_lockin_averaged(
            lockin,
            pockels.LOCKIN_AVG_READINGS,
            pockels.LOCKIN_READ_DELAY_S,
        )
    )
    sample_fields = lockin_sample_statistics_fields(
        raw_mags, raw_phases, reference_phase_deg
    )
    avg_mag = sample_fields["lockin_mag_V"]
    avg_phase = sample_fields["lockin_phase_deg"]

    raw_signed = [
        signed_lockin_from_mag_phase(mag, phase, reference_phase_deg)
        for mag, phase in zip(raw_mags, raw_phases)
    ]
    signed_v = sample_fields["lockin_signed_V"]

    sens_table = getattr(pockels, "SENS_TABLE_VOLTS", {})
    if isinstance(sens_table, dict):
        sensitivity_v = float(sens_table.get(sens_idx, float("nan")))
    else:
        sensitivity_v = float("nan")

    flags: list[str] = []
    append_quality(flags, overloaded, "lockin_overload")
    fullscale_fraction = append_lockin_range_quality(
        flags, avg_mag, sensitivity_v
    )
    append_quality(flags, abs(qwp_readout_error) > float(verify_tol_deg), "qwp_readout_angle_error")
    append_quality(flags, verify_moves and bool(null_context.get("qwp_readout_verify_failed", False)), "qwp_readout_angle_verify_failed")
    append_quality(flags, abs(angle_error) > float(verify_tol_deg), "analyser_angle_error")
    append_quality(flags, verify_moves and not bool(anl_move.get("ok", True)), "analyser_angle_verify_failed")
    append_quality(flags, len(raw_mags) < pockels.LOCKIN_AVG_READINGS, "short_lockin_average")
    for flag in null_context.get("quality_flags", []):
        append_quality(flags, True, str(flag))

    row = {
        "pixel": int(pixel["pixel"]),
        "row": int(pixel.get("j", 0)),
        "col": int(pixel.get("i", 0)),
        "hwp_deg": float(hwp_deg),
        "hwp_actual_deg": null_context.get("hwp_actual_deg", float("nan")),
        "hwp_error_deg": null_context.get("hwp_error_deg", float("nan")),
        "theta_i_deg": theta_i_from_hwp(hwp_deg),
        "seed_q_null_deg": null_context.get("seed_q_null_deg", float("nan")),
        "seed_a_null_deg": null_context.get("seed_a_null_deg", float("nan")),
        "seed_p_null_W": null_context.get("seed_p_null_W", float("nan")),
        "seed_p_null_mV": null_context.get("seed_p_null_mV", float("nan")),
        "q_null_deg": float(q_null),
        "qwp_actual_deg": qwp_readout_actual,
        "qwp_error_deg": qwp_readout_error,
        "qwp_readout_deg": qwp_readout,
        "qwp_readout_actual_deg": qwp_readout_actual,
        "qwp_readout_error_deg": qwp_readout_error,
        "qwp_readout_offset_from_null_deg": qwp_readout_offset,
        "a_null_deg": float(a_null),
        "anl_null_actual_deg": null_context.get("anl_null_actual_deg", float("nan")),
        "anl_null_error_deg": null_context.get("anl_null_error_deg", float("nan")),
        "p_null_W": float(p_null),
        "p_null_mV": float(p_null_mV),
        "null_method": null_context.get("null_method", ""),
        "null_n_evals": null_context.get("null_n_evals", ""),
        "null_escalated": null_context.get("null_escalated", ""),
        "null_mV_before_renull": null_context.get("null_mV_before_renull", float("nan")),
        "null_mV_after_renull": null_context.get("null_mV_after_renull", float("nan")),
        "q_delta_deg": null_context.get("q_delta_deg", float("nan")),
        "a_delta_deg": null_context.get("a_delta_deg", float("nan")),
        "slope_side": slope_side,
        "anl_target_deg": wrap360(anl_target),
        "anl_offset_from_null_deg": float(anl_offset),
        "anl_actual_deg": float(anl_actual),
        "anl_error_deg": float(angle_error),
        "vpp": float(vpp),
        "power_W": float(power_w),
        "detector_V": float(detector_v),
        **sample_fields,
        "sensitivity_fullscale_V": sensitivity_v,
        "lockin_fullscale_fraction": fullscale_fraction,
        "n_good_samples": len(raw_mags),
        "timestamp": timestamp,
        "elapsed_s": float(elapsed_s),
        "quality_flags": ";".join(flags),
    }
    row = add_fast_map_lab_angle_fields(row)
    row = add_lockin_background_fields(row, null_reference_row, reference_phase_deg)
    row["lockin_metric_V"] = lockin_peak_metric_value(row)
    row["lockin_metric_source"] = lockin_peak_metric_source(row)
    row["snr_estimate"] = lockin_background_snr(row)
    row["background_to_signal_ratio"] = lockin_background_to_signal_ratio(row)
    net_mag_v = lockin_raw_response_value(row, "lockin_net_mag_V")
    net_signed_v = lockin_raw_response_value(row, "lockin_net_signed_V")
    bg_mag_v = lockin_raw_response_value(row, "lockin_bg_mag_V")

    gui_update_lockin_bar(
        slope_side,
        pixel=int(pixel["pixel"]),
        hwp_deg=float(hwp_deg),
        vpp=float(vpp),
        a_null=a_null,
        mag_v=float(avg_mag),
        signed_v=float(signed_v),
        phase_deg=float(avg_phase),
        net_mag_v=float(net_mag_v),
        net_signed_v=float(net_signed_v),
        bg_mag_v=float(bg_mag_v),
    )
    gui_update_state(
        current_pixel=int(pixel["pixel"]),
        current_hwp_deg=float(hwp_deg),
        current_hwp_null_deg=float(hwp_deg),
        current_qwp_deg=float(qwp_readout_actual),
        current_qwp_target_deg=wrap360(qwp_readout),
        current_qwp_null_deg=wrap360(q_null),
        current_anl_deg=float(anl_actual),
        current_anl_null_deg=wrap360(a_null),
        current_anl_target_deg=wrap360(anl_target),
        current_anl_offset_deg=float(anl_offset),
        detector_mV=float(detector_v) * 1e3 if np.isfinite(float(detector_v)) else float("nan"),
        detector_power_W=float(power_w),
        lockin_mag_V=float(avg_mag),
        lockin_phase_deg=float(avg_phase),
        lockin_signed_V=float(signed_v),
        lockin_bg_mag_V=float(row.get("lockin_bg_mag_V", float("nan"))),
        lockin_bg_phase_deg=float(row.get("lockin_bg_phase_deg", float("nan"))),
        lockin_bg_signed_V=float(row.get("lockin_bg_signed_V", float("nan"))),
        lockin_net_mag_V=float(row.get("lockin_net_mag_V", float("nan"))),
        lockin_net_phase_deg=float(row.get("lockin_net_phase_deg", float("nan"))),
        lockin_net_signed_V=float(row.get("lockin_net_signed_V", float("nan"))),
        active_optic="LOCKIN",
        phase="Lock-in point acquired",
    )

    raw_rows = []
    for idx, (mag, phase, signed, ts) in enumerate(zip(raw_mags, raw_phases, raw_signed, raw_ts)):
        raw_rows.append(make_raw_lockin_row(
            pixel=int(pixel["pixel"]),
            hwp_deg=float(hwp_deg),
            slope_side=slope_side,
            vpp=float(vpp),
            sample_index=idx,
            sample_timestamp=float(ts),
            lockin_mag_v=float(mag),
            lockin_phase_deg=float(phase),
            lockin_signed_v=float(signed),
        ))

    return row, raw_rows, sens_idx


def measure_manual_peak_point(
    *,
    pixel: dict,
    hwp_deg: float,
    qwp_deg: float,
    anl_deg: float,
    vpp: float,
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    t_start: float,
    slope_side: str = "manual_peak",
    quality_flag: str = "manual_peak_raw",
    phase_label: str = "Manual raw peak scout",
) -> tuple[dict, list[dict], int]:
    pix = int(pixel["pixel"])
    side = str(slope_side or "manual_peak")
    flag = str(quality_flag or "manual_peak_raw")
    phase_text = str(phase_label or "Manual raw peak scout")
    gui_update_state(
        current_pixel=pix,
        current_hwp_deg=float(hwp_deg),
        current_hwp_target_deg=wrap360(hwp_deg),
        current_qwp_deg=float(qwp_deg),
        current_qwp_target_deg=wrap360(qwp_deg),
        current_anl_deg=float(anl_deg),
        current_anl_target_deg=wrap360(anl_deg),
        current_anl_null_deg=None,
        current_vpp=float(vpp),
        current_slope_side=side,
        active_optic="RAW",
        phase=phase_text,
        ac_voltage_on=True,
    )
    hwp_move = fast_rotator_move_or_fallback(
        rot_hwp,
        hwp_deg,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"HWP {side}",
    )
    require_verified_move(hwp_move, f"HWP {side}")
    qwp_move = fast_rotator_move_or_fallback(
        rot_qwp,
        qwp_deg,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"QWP {side}",
    )
    require_verified_move(qwp_move, f"QWP {side}")
    anl_move = fast_rotator_move_or_fallback(
        rot_anl,
        anl_deg,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"ANL {side}",
    )
    require_verified_move(anl_move, f"ANL {side}")
    gui_pixel_checkpoint()

    hwp_actual = hwp_move.get("actual_deg")
    qwp_actual = qwp_move.get("actual_deg")
    anl_actual = anl_move.get("actual_deg")
    hwp_actual_f = _rotator_float_or_nan(hwp_actual)
    qwp_actual_f = _rotator_float_or_nan(qwp_actual)
    anl_actual_f = _rotator_float_or_nan(anl_actual)
    if not np.isfinite(hwp_actual_f):
        hwp_actual = rotator_read_angle_once(rot_hwp)
        hwp_actual_f = _rotator_float_or_nan(hwp_actual)
    if not np.isfinite(qwp_actual_f):
        qwp_actual = rotator_read_angle_once(rot_qwp)
        qwp_actual_f = _rotator_float_or_nan(qwp_actual)
    if not np.isfinite(anl_actual_f):
        anl_actual = rotator_read_angle_once(rot_anl)
        anl_actual_f = _rotator_float_or_nan(anl_actual)

    hwp_error = pockels.angular_error(hwp_actual_f, wrap360(hwp_deg)) if np.isfinite(hwp_actual_f) else float("nan")
    qwp_error = pockels.angular_error(qwp_actual_f, wrap360(qwp_deg)) if np.isfinite(qwp_actual_f) else float("nan")
    anl_error = pockels.angular_error(anl_actual_f, wrap360(anl_deg)) if np.isfinite(anl_actual_f) else float("nan")

    gui_sleep(pockels.LOCKIN_SETTLE_S, allow_skip=True)
    sens_idx, overloaded = check_fixed_lockin_overload(lockin, sens_idx)
    if overloaded:
        gui_sleep(pockels.OVERLOAD_SETTLE_S, allow_skip=True)
    gui_pixel_checkpoint()

    timestamp = datetime.now().isoformat()
    elapsed_s = time.time() - t_start
    try:
        power_w, detector_v = detector.read_power_w_stable()
    except Exception:
        power_w, detector_v = float("nan"), float("nan")

    avg_mag, avg_phase, std_mag, std_phase, raw_mags, raw_phases, raw_ts = (
        pockels.read_lockin_averaged(
            lockin,
            pockels.LOCKIN_AVG_READINGS,
            pockels.LOCKIN_READ_DELAY_S,
        )
    )
    sample_fields = lockin_sample_statistics_fields(
        raw_mags, raw_phases, reference_phase_deg
    )
    avg_mag = sample_fields["lockin_mag_V"]
    avg_phase = sample_fields["lockin_phase_deg"]
    raw_signed = [
        signed_lockin_from_mag_phase(mag, phase, reference_phase_deg)
        for mag, phase in zip(raw_mags, raw_phases)
    ]
    signed_v = sample_fields["lockin_signed_V"]

    sens_table = getattr(pockels, "SENS_TABLE_VOLTS", {})
    sensitivity_v = (
        float(sens_table.get(sens_idx, float("nan")))
        if isinstance(sens_table, dict)
        else float("nan")
    )

    flags: list[str] = [flag]
    append_quality(flags, overloaded, "lockin_overload")
    fullscale_fraction = append_lockin_range_quality(
        flags, avg_mag, sensitivity_v
    )
    append_quality(flags, abs(hwp_error) > float(verify_tol_deg), "hwp_angle_error")
    append_quality(flags, abs(qwp_error) > float(verify_tol_deg), "qwp_angle_error")
    append_quality(flags, abs(anl_error) > float(verify_tol_deg), "analyser_angle_error")
    append_quality(flags, verify_moves and not bool(hwp_move.get("ok", True)), "hwp_angle_verify_failed")
    append_quality(flags, verify_moves and not bool(qwp_move.get("ok", True)), "qwp_angle_verify_failed")
    append_quality(flags, verify_moves and not bool(anl_move.get("ok", True)), "analyser_angle_verify_failed")
    append_quality(flags, len(raw_mags) < pockels.LOCKIN_AVG_READINGS, "short_lockin_average")

    row = {
        "pixel": pix,
        "row": int(pixel.get("j", 0)),
        "col": int(pixel.get("i", 0)),
        "hwp_deg": float(hwp_deg),
        "hwp_actual_deg": float(hwp_actual_f),
        "hwp_error_deg": float(hwp_error),
        "theta_i_deg": theta_i_from_hwp(hwp_deg),
        "seed_q_null_deg": float("nan"),
        "seed_a_null_deg": float("nan"),
        "seed_p_null_W": float("nan"),
        "seed_p_null_mV": float("nan"),
        "q_null_deg": float(qwp_deg),
        "qwp_actual_deg": float(qwp_actual_f),
        "qwp_error_deg": float(qwp_error),
        "qwp_readout_deg": wrap360(qwp_deg),
        "qwp_readout_actual_deg": float(qwp_actual_f),
        "qwp_readout_error_deg": float(qwp_error),
        "qwp_readout_offset_from_null_deg": 0.0,
        "a_null_deg": float(anl_deg),
        "anl_null_actual_deg": float(anl_actual_f),
        "anl_null_error_deg": float(anl_error),
        "p_null_W": float("nan"),
        "p_null_mV": float("nan"),
        "null_method": flag,
        "null_n_evals": 0,
        "null_escalated": False,
        "null_mV_before_renull": float("nan"),
        "null_mV_after_renull": float("nan"),
        "q_delta_deg": 0.0,
        "a_delta_deg": 0.0,
        "slope_side": side,
        "anl_target_deg": wrap360(anl_deg),
        "anl_offset_from_null_deg": 0.0,
        "anl_actual_deg": float(anl_actual_f),
        "anl_error_deg": float(anl_error),
        "vpp": float(vpp),
        "power_W": float(power_w),
        "detector_V": float(detector_v),
        **sample_fields,
        "sensitivity_fullscale_V": sensitivity_v,
        "lockin_fullscale_fraction": fullscale_fraction,
        "n_good_samples": len(raw_mags),
        "timestamp": timestamp,
        "elapsed_s": float(elapsed_s),
        "quality_flags": ";".join(flags),
    }
    row = add_fast_map_lab_angle_fields(row)

    gui_update_lockin_bar(
        side,
        pixel=pix,
        hwp_deg=float(hwp_deg),
        vpp=float(vpp),
        a_null=float(anl_deg),
        mag_v=float(avg_mag),
        signed_v=float(signed_v),
        phase_deg=float(avg_phase),
    )
    gui_update_state(
        current_pixel=pix,
        current_hwp_deg=float(hwp_actual_f),
        current_hwp_target_deg=wrap360(hwp_deg),
        current_qwp_deg=float(qwp_actual_f),
        current_qwp_target_deg=wrap360(qwp_deg),
        current_anl_deg=float(anl_actual_f),
        current_anl_target_deg=wrap360(anl_deg),
        detector_mV=float(detector_v) * 1e3 if np.isfinite(float(detector_v)) else float("nan"),
        detector_power_W=float(power_w),
        lockin_mag_V=float(avg_mag),
        lockin_phase_deg=float(avg_phase),
        lockin_signed_V=float(signed_v),
        current_vpp=float(vpp),
        current_slope_side=side,
        active_optic="LOCKIN",
        phase=f"{phase_text} acquired",
    )

    raw_rows = []
    for idx, (mag, phase, signed, ts) in enumerate(zip(raw_mags, raw_phases, raw_signed, raw_ts)):
        raw_rows.append(make_raw_lockin_row(
            pixel=pix,
            hwp_deg=float(hwp_deg),
            slope_side=side,
            vpp=float(vpp),
            sample_index=idx,
            sample_timestamp=float(ts),
            lockin_mag_v=float(mag),
            lockin_phase_deg=float(phase),
            lockin_signed_v=float(signed),
        ))

    return row, raw_rows, sens_idx


def auto_refine_lockin_peak_from_seed(
    *,
    pixel: dict,
    hwp_deg: float,
    qwp_seed_deg: float,
    anl_seed_deg: float,
    vpp: float,
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    t_start: float,
) -> tuple[dict, list[dict], int, int]:
    """Small lock-in peak refinement around a predicted readout branch."""

    def measure_candidate(q_deg: float, a_deg: float, side: str, label: str):
        return measure_manual_peak_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_deg=float(q_deg),
            anl_deg=float(a_deg),
            vpp=float(vpp),
            rot_hwp=rot_hwp,
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            t_start=t_start,
            slope_side=side,
            quality_flag=side,
            phase_label=label,
        )

    q_best = wrap360(qwp_seed_deg)
    a_best = wrap360(anl_seed_deg)
    best_row, best_raw, sens_idx = measure_candidate(
        q_best,
        a_best,
        "auto_peak",
        "Auto lock-in peak seed",
    )
    n_probes = 1
    best_mag = lockin_peak_metric_value(best_row)

    expanded = False
    for step in AUTO_READOUT_PEAK_STEPS_DEG:
        step = float(step)
        for _iter in range(AUTO_READOUT_PEAK_MAX_ITER_PER_STEP):
            improved = False
            candidates = [
                (q_best - step, a_best, f"Q-{step:g}"),
                (q_best + step, a_best, f"Q+{step:g}"),
                (q_best, a_best - step, f"A-{step:g}"),
                (q_best, a_best + step, f"A+{step:g}"),
            ]
            for q_try, a_try, label in candidates:
                row, raw, sens_idx = measure_candidate(
                    wrap360(q_try),
                    wrap360(a_try),
                    "auto_peak_probe",
                    f"Auto lock-in peak probe {label}",
                )
                n_probes += 1
                mag = lockin_peak_metric_value(row)
                if (
                    np.isfinite(mag)
                    and (
                        not np.isfinite(best_mag)
                        or (float(mag) - float(best_mag)) * 1e6
                        >= lockin_peak_improvement_threshold_uV(best_row, row)
                    )
                ):
                    best_mag = float(mag)
                    q_best = wrap360(row.get("qwp_readout_deg", q_try))
                    a_best = wrap360(row.get("anl_target_deg", a_try))
                    best_row = row
                    best_raw = raw
                    improved = True
                    expanded = True
            if not improved:
                break

    final_row, final_raw, sens_idx = measure_candidate(
        q_best,
        a_best,
        "auto_peak",
        "Auto lock-in peak final",
    )
    n_probes += 1
    final_mag = lockin_peak_metric_value(final_row)
    if np.isfinite(final_mag) and (
        not np.isfinite(best_mag)
        or float(final_mag) >= float(best_mag)
        or abs((float(final_mag) - float(best_mag)) * 1e6)
        <= lockin_peak_improvement_threshold_uV(best_row, final_row)
    ):
        best_row = final_row
        best_raw = final_raw
    else:
        append_row_quality(best_row, "auto_peak_final_confirm_lower")

    existing_flags = str(best_row.get("quality_flags", ""))
    best_row["quality_flags"] = ";".join(
        flag for flag in (
            existing_flags,
            f"auto_peak_search_probes={n_probes}",
            "auto_peak_search_expanded" if expanded else "",
        )
        if flag
    )
    best_row["slope_side"] = "auto_peak"
    for raw in best_raw:
        raw["slope_side"] = "auto_peak"
    return best_row, best_raw, sens_idx, n_probes


def measure_lockin_qwp_analyser_point(
    *,
    pixel: dict,
    hwp_deg: float,
    qwp_target_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    slope_side: str,
    anl_target: float,
    vpp: float,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    null_reference_row: dict | None,
    t_start: float,
    phase_label: str,
) -> tuple[dict, list[dict], int]:
    gui_update_state(
        current_pixel=int(pixel["pixel"]),
        current_hwp_deg=float(hwp_deg),
        current_hwp_null_deg=float(hwp_deg),
        current_qwp_target_deg=wrap360(qwp_target_deg),
        current_qwp_null_deg=wrap360(q_null),
        current_anl_null_deg=wrap360(a_null),
        current_anl_target_deg=wrap360(anl_target),
        current_vpp=float(vpp),
        current_slope_side=slope_side,
        phase=phase_label,
        ac_voltage_on=True,
        active_optic="QWP",
    )
    q_move = fast_rotator_move_or_fallback(
        rot_qwp,
        qwp_target_deg,
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"QWP {slope_side}",
    )
    gui_pixel_checkpoint()
    require_verified_move(q_move, f"QWP {slope_side}")
    q_actual = _rotator_float_or_nan(gui_angle_from_move(q_move, qwp_target_deg))
    q_error = _rotator_float_or_nan(q_move.get("error_deg", float("nan")))

    context = dict(base_null_context)
    flags = list(context.get("quality_flags", []) or [])
    append_quality(flags, True, "qwp_analyser_peak_search")
    append_quality(
        flags,
        verify_moves and not bool(q_move.get("ok", True)),
        "qwp_readout_angle_verify_failed",
    )
    append_quality(
        flags,
        np.isfinite(float(q_error)) and abs(float(q_error)) > float(verify_tol_deg),
        "qwp_readout_angle_error",
    )
    context.update({
        "qwp_readout_deg": float(qwp_target_deg),
        "qwp_readout_actual_deg": float(q_actual),
        "qwp_readout_error_deg": float(q_error),
        "qwp_readout_offset_from_null_deg": periodic_delta_deg(q_null, qwp_target_deg, 180.0),
        "qwp_readout_verify_failed": verify_moves and not bool(q_move.get("ok", True)),
        "quality_flags": flags,
    })
    row, raw, sens_idx = measure_lockin_point(
        pixel=pixel,
        hwp_deg=float(hwp_deg),
        q_null=float(q_null),
        a_null=float(a_null),
        p_null=float(p_null),
        p_null_mV=float(p_null_mV),
        slope_side=slope_side,
        anl_target=float(anl_target),
        vpp=float(vpp),
        rot_anl=rot_anl,
        detector=detector,
        lockin=lockin,
        sens_idx=sens_idx,
        reference_phase_deg=reference_phase_deg,
        fast_rotator_moves=fast_rotator_moves,
        verify_moves=verify_moves,
        verify_tol_deg=verify_tol_deg,
        null_context=context,
        null_reference_row=null_reference_row,
        t_start=t_start,
    )
    append_row_quality(row, "qwp_analyser_peak_search")
    return row, raw, sens_idx


def peak_diagnostic_probe_plan(step_deg: float) -> list[tuple[str, float, float]]:
    step = abs(float(step_deg))
    return [
        ("q_minus", -step, 0.0),
        ("q_plus", step, 0.0),
        ("a_minus", 0.0, -step),
        ("a_plus", 0.0, step),
        ("center", 0.0, 0.0),
    ]


def run_peak_readout_diagnostic(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    peak_row: dict,
    peak_source: str,
    step_deg: float,
    min_margin_uV: float,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    progress: dict | None,
    precounted_in_progress: bool,
    t_start: float,
) -> tuple[list[dict], list[dict], dict, int]:
    """Probe around a found QWP/ANL peak and certify that nearby points do not beat it."""
    try:
        step = abs(float(step_deg))
    except Exception:
        step = DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG
    if not np.isfinite(step) or step <= 0.0:
        step = DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG
    try:
        margin_uV = abs(float(min_margin_uV))
    except Exception:
        margin_uV = DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV
    if not np.isfinite(margin_uV):
        margin_uV = DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV

    q_center = _finite_float_or_none(peak_row.get("qwp_readout_deg", peak_row.get("q_null_deg")))
    a_center = _finite_float_or_none(peak_row.get("anl_target_deg"))
    center_initial_v = lockin_peak_metric_value(peak_row)
    append_row_quality(peak_row, "peak_diagnostic_checked")

    probe_rows: list[dict] = []
    probe_raw_rows: list[dict] = []
    plan = peak_diagnostic_probe_plan(step)

    if q_center is None or a_center is None or not np.isfinite(center_initial_v):
        append_row_quality(peak_row, "peak_diagnostic_incomplete")
        result = {
            "pixel": int(pixel["pixel"]),
            "hwp_deg": float(hwp_deg),
            "theta_i_deg": theta_i_from_hwp(hwp_deg),
            "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
            "vpp": float(vpp),
            "peak_source": str(peak_source),
            "status": "INCOMPLETE",
            "center_qwp_readout_deg": q_center if q_center is not None else float("nan"),
            "center_anl_target_deg": a_center if a_center is not None else float("nan"),
            "center_initial_mag_uV": float(center_initial_v) * 1e6 if np.isfinite(center_initial_v) else float("nan"),
            "center_repeat_mag_uV": float("nan"),
            "center_best_mag_uV": float("nan"),
            "best_neighbor_label": "",
            "best_neighbor_qwp_deg": float("nan"),
            "best_neighbor_anl_deg": float("nan"),
            "best_neighbor_mag_uV": float("nan"),
            "best_neighbor_minus_center_uV": float("nan"),
            "step_deg": float(step),
            "min_margin_uV": float(margin_uV),
            "n_probes": 0,
            "quality_flags": peak_row.get("quality_flags", ""),
        }
        print(
            f"\nP{int(pixel['pixel']):03d} peak diagnostic INCOMPLETE "
            f"HWP={float(hwp_deg):.4f}: missing peak QWP/ANL or lock-in magnitude"
        )
        return probe_rows, probe_raw_rows, result, sens_idx

    if progress is not None and not bool(precounted_in_progress):
        progress["total_points"] = int(progress.get("total_points", 0)) + len(plan)
        progress["pixel_total_points"] = int(progress.get("pixel_total_points", 0)) + len(plan)

    for label, dq, da in plan:
        gui_pixel_checkpoint()
        q_try = closest_periodic_equivalent_deg(float(q_center) + dq, float(q_center), 180.0)
        a_try = closest_periodic_equivalent_deg(
            float(a_center) + da,
            float(a_center),
            180.0,
            analyser=True,
        )
        row, raw, sens_idx = measure_lockin_qwp_analyser_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_target_deg=float(q_try),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side=f"peak_diag_{label}",
            anl_target=float(a_try),
            vpp=float(vpp),
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=None,
            t_start=t_start,
            phase_label=f"Peak diagnostic {label}",
        )
        append_row_quality(row, "peak_diagnostic_probe")
        probe_rows.append(row)
        probe_raw_rows.extend(raw)
        if progress is not None:
            progress["points_done"] = int(progress.get("points_done", 0)) + 1
            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
            gui_update_state(
                current_pixel=int(pixel["pixel"]),
                current_hwp_deg=float(row.get("hwp_actual_deg", hwp_deg)),
                current_hwp_null_deg=float(hwp_deg),
                current_qwp_deg=float(row.get("qwp_actual_deg", float("nan"))),
                current_qwp_target_deg=wrap360(row.get("qwp_readout_deg", q_try)),
                current_qwp_null_deg=wrap360(q_null),
                current_anl_deg=float(row.get("anl_actual_deg", float("nan"))),
                current_anl_null_deg=wrap360(a_null),
                detector_mV=float(row.get("detector_V", float("nan"))) * 1e3,
                detector_power_W=float(row.get("power_W", float("nan"))),
                lockin_mag_V=float(row.get("lockin_mag_V", float("nan"))),
                lockin_phase_deg=float(row.get("lockin_phase_deg", float("nan"))),
                lockin_signed_V=float(row.get("lockin_signed_V", float("nan"))),
                current_vpp=float(vpp),
                current_slope_side=f"peak_diag_{label}",
                phase="Peak diagnostic point complete",
                chip_points_done=int(progress.get("points_done", 0)),
                chip_total_points=int(progress.get("total_points", 0)),
                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                pixel_total_points=int(progress.get("pixel_total_points", 0)),
                ac_voltage_on=True,
                active_optic="LOCKIN",
            )

    center_repeat_row = next(
        (row for row in reversed(probe_rows) if str(row.get("slope_side", "")) == "peak_diag_center"),
        None,
    )
    neighbor_rows = [
        row for row in probe_rows
        if str(row.get("slope_side", "")) != "peak_diag_center"
        and np.isfinite(lockin_peak_metric_value(row))
    ]
    center_repeat_v = (
        lockin_peak_metric_value(center_repeat_row)
        if center_repeat_row is not None else float("nan")
    )
    center_candidates = [float(center_initial_v)]
    if np.isfinite(center_repeat_v):
        center_candidates.append(float(center_repeat_v))
    center_best_v = max(center_candidates)
    best_neighbor = (
        max(neighbor_rows, key=lockin_peak_metric_value)
        if neighbor_rows else None
    )
    best_neighbor_v = (
        lockin_peak_metric_value(best_neighbor)
        if best_neighbor is not None else float("nan")
    )
    delta_uV = (
        (float(best_neighbor_v) - float(center_best_v)) * 1e6
        if np.isfinite(best_neighbor_v) and np.isfinite(center_best_v)
        else float("nan")
    )

    flags = []
    if not neighbor_rows:
        status = "INCOMPLETE"
        append_row_quality(peak_row, "peak_diagnostic_incomplete")
        flags.append("peak_diagnostic_incomplete")
    elif np.isfinite(delta_uV) and float(delta_uV) > float(margin_uV):
        status = "FAIL"
        append_row_quality(peak_row, "peak_diagnostic_failed")
        append_row_quality(best_neighbor, "peak_diagnostic_beats_center")
        flags.append("peak_diagnostic_failed")
    else:
        status = "PASS"
        if np.isfinite(delta_uV) and float(delta_uV) > 0.0:
            append_row_quality(peak_row, "peak_diagnostic_neighbor_within_margin")
            flags.append("peak_diagnostic_neighbor_within_margin")
    if np.isfinite(center_repeat_v):
        repeat_delta_uV = abs((float(center_repeat_v) - float(center_initial_v)) * 1e6)
        if repeat_delta_uV > max(float(margin_uV), AUTO_READOUT_PEAK_MIN_IMPROVE_UV):
            append_row_quality(peak_row, "peak_diagnostic_center_repeat_drift")
            flags.append("peak_diagnostic_center_repeat_drift")

    best_label = str(best_neighbor.get("slope_side", "")) if best_neighbor else ""
    result = {
        "pixel": int(pixel["pixel"]),
        "hwp_deg": float(hwp_deg),
        "theta_i_deg": theta_i_from_hwp(hwp_deg),
        "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
        "vpp": float(vpp),
        "peak_source": str(peak_source),
        "status": status,
        "center_qwp_readout_deg": float(q_center),
        "center_anl_target_deg": float(a_center),
        "center_initial_mag_uV": float(center_initial_v) * 1e6,
        "center_repeat_mag_uV": float(center_repeat_v) * 1e6 if np.isfinite(center_repeat_v) else float("nan"),
        "center_best_mag_uV": float(center_best_v) * 1e6,
        "best_neighbor_label": best_label,
        "best_neighbor_qwp_deg": float(best_neighbor.get("qwp_readout_deg", float("nan"))) if best_neighbor else float("nan"),
        "best_neighbor_anl_deg": float(best_neighbor.get("anl_target_deg", float("nan"))) if best_neighbor else float("nan"),
        "best_neighbor_mag_uV": float(best_neighbor_v) * 1e6 if np.isfinite(best_neighbor_v) else float("nan"),
        "best_neighbor_minus_center_uV": float(delta_uV) if np.isfinite(delta_uV) else float("nan"),
        "step_deg": float(step),
        "min_margin_uV": float(margin_uV),
        "n_probes": len(probe_rows),
        "quality_flags": ";".join(flags),
    }
    print(
        f"\nP{int(pixel['pixel']):03d} peak diagnostic {status} HWP={float(hwp_deg):.4f}, "
        f"{float(vpp):g} Vpp | center={float(center_best_v) * 1e6:.3f} uV, "
        f"best neighbor={float(best_neighbor_v) * 1e6 if np.isfinite(best_neighbor_v) else float('nan'):.3f} uV, "
        f"neighbor-center={float(delta_uV) if np.isfinite(delta_uV) else float('nan'):+.3f} uV "
        f"(step {float(step):g} deg, margin {float(margin_uV):g} uV)"
    )
    return probe_rows, probe_raw_rows, result, sens_idx


def auto_refine_qwp_analyser_peak_from_seed(
    *,
    pixel: dict,
    hwp_deg: float,
    qwp_seed_deg: float,
    anl_seed_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    t_start: float,
) -> tuple[dict, list[dict], int, int]:
    """First-pixel peak refinement: optimize QWP and analyser around the predicted branch."""

    def measure_candidate(q_deg: float, a_deg: float, side: str, label: str):
        return measure_lockin_qwp_analyser_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_target_deg=float(q_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side=side,
            anl_target=float(a_deg),
            vpp=float(vpp),
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=None,
            t_start=t_start,
            phase_label=label,
        )

    def row_mag(row: dict) -> float:
        return lockin_peak_metric_value(row)

    def improvement_threshold_uV(current_row: dict | None, candidate_row: dict | None) -> float:
        return lockin_peak_improvement_threshold_uV(current_row, candidate_row)

    def candidate_offsets(step: float) -> list[tuple[float, float, str]]:
        return [
            (-step, 0.0, f"Q-{step:g}"),
            (+step, 0.0, f"Q+{step:g}"),
            (0.0, -step, f"A-{step:g}"),
            (0.0, +step, f"A+{step:g}"),
            (-step, -step, f"Q-{step:g}/A-{step:g}"),
            (-step, +step, f"Q-{step:g}/A+{step:g}"),
            (+step, -step, f"Q+{step:g}/A-{step:g}"),
            (+step, +step, f"Q+{step:g}/A+{step:g}"),
        ]

    q_best = wrap360(qwp_seed_deg)
    a_best = wrap360(anl_seed_deg)
    best_row, best_raw, sens_idx = measure_candidate(
        q_best,
        a_best,
        "auto_peak",
        "Auto QWP/analyser peak seed",
    )
    n_probes = 1
    best_mag = row_mag(best_row)
    expanded = False

    for step in AUTO_READOUT_PEAK_STEPS_DEG:
        step = float(step)
        for _iter in range(AUTO_READOUT_PEAK_MAX_ITER_PER_STEP):
            round_best_row = best_row
            round_best_raw = best_raw
            round_best_mag = best_mag
            for dq, da, label in candidate_offsets(step):
                q_try = closest_periodic_equivalent_deg(float(q_best) + dq, float(q_best), 180.0)
                a_try = closest_periodic_equivalent_deg(
                    float(a_best) + da,
                    float(a_best),
                    180.0,
                    analyser=True,
                )
                row, raw, sens_idx = measure_candidate(
                    q_try,
                    a_try,
                    "auto_peak_probe",
                    f"Auto QWP/analyser peak probe {label}",
                )
                n_probes += 1
                mag = row_mag(row)
                if np.isfinite(mag) and (not np.isfinite(round_best_mag) or float(mag) > float(round_best_mag)):
                    round_best_mag = float(mag)
                    round_best_row = row
                    round_best_raw = raw
            threshold_uV = improvement_threshold_uV(best_row, round_best_row)
            improved = (
                np.isfinite(round_best_mag)
                and (
                    not np.isfinite(best_mag)
                    or (float(round_best_mag) - float(best_mag)) * 1e6 >= float(threshold_uV)
                )
            )
            if improved:
                best_mag = float(round_best_mag)
                q_best = wrap360(round_best_row.get("qwp_readout_deg", q_best))
                a_best = wrap360(round_best_row.get("anl_target_deg", a_best))
                best_row = round_best_row
                best_raw = round_best_raw
                expanded = True
                append_row_quality(best_row, f"auto_peak_2d_step_{step:g}_improved")
            else:
                append_row_quality(best_row, f"auto_peak_2d_step_{step:g}_stable")
                break

    final_row, final_raw, sens_idx = measure_candidate(
        q_best,
        a_best,
        "auto_peak",
        "Auto QWP/analyser peak final",
    )
    n_probes += 1
    final_mag = row_mag(final_row)
    final_threshold_uV = improvement_threshold_uV(best_row, final_row)
    if np.isfinite(final_mag) and (
        not np.isfinite(best_mag)
        or float(final_mag) >= float(best_mag)
        or abs((float(final_mag) - float(best_mag)) * 1e6) <= float(final_threshold_uV)
    ):
        best_row = final_row
        best_raw = final_raw
        best_mag = float(final_mag)
    else:
        append_row_quality(best_row, "auto_peak_final_confirm_lower")

    existing_flags = str(best_row.get("quality_flags", ""))
    best_row["quality_flags"] = ";".join(
        flag for flag in (
            existing_flags,
            f"auto_qwp_analyser_peak_search_probes={n_probes}",
            "auto_qwp_analyser_peak_search_2d",
            "auto_qwp_analyser_peak_search_expanded" if expanded else "",
        )
        if flag
    )
    best_row["slope_side"] = "auto_peak"
    for raw in best_raw:
        raw["slope_side"] = "auto_peak"
    return best_row, best_raw, sens_idx, n_probes


def _s9_psi_of_row(row: dict | None, a_null: float) -> float | None:
    if not isinstance(row, dict):
        return None
    null_actual = _first_finite_followup_value(
        row.get("anl_null_actual_deg"), row.get("a_null_deg"), a_null
    )
    analyser_actual = _first_finite_followup_value(
        row.get("anl_actual_deg"), row.get("anl_target_deg")
    )
    if null_actual is None or analyser_actual is None:
        return None
    return periodic_delta_deg(float(null_actual), float(analyser_actual), 180.0)


def _s9_raw_phasor_of_row(row: dict | None) -> complex | None:
    if not isinstance(row, dict):
        return None
    x = _finite_float_or_none(row.get("lockin_x_V"))
    y = _finite_float_or_none(row.get("lockin_y_V"))
    if x is not None and y is not None:
        return complex(x, y)
    return lockin_complex_from_mag_phase(
        row.get("lockin_mag_V"), row.get("lockin_phase_deg")
    )


def _s9_quadrature_rows(
    rows: list[dict], a_null: float
) -> tuple[dict | None, dict | None]:
    plus: tuple[float, dict] | None = None
    minus: tuple[float, dict] | None = None
    for row in rows:
        psi = _s9_psi_of_row(row, a_null)
        if psi is None:
            continue
        plus_error = abs(float(psi) - 45.0)
        minus_error = abs(float(psi) + 45.0)
        if plus is None or plus_error < plus[0]:
            plus = (plus_error, row)
        if minus is None or minus_error < minus[0]:
            minus = (minus_error, row)
    plus_row = plus[1] if plus is not None and plus[0] <= 5.0 else None
    minus_row = minus[1] if minus is not None and minus[0] <= 5.0 else None
    return plus_row, minus_row


def quick_s9_triplet_certificate(
    *,
    null_reference_row: dict | None,
    slope_rows: list[dict],
    a_null: float,
) -> dict:
    """Fast per-pixel operating-point check from null and opposite slopes.

    The first calibration pixel receives the fuller fitted certificate below.
    On later pixels this test normally costs no extra readings; only an
    inconclusive strong-signal triplet escalates to the balanced fit.
    """
    certificate = {
        "status": "needs_fit",
        "method": "null_plus_opposite_quadrature_triplet",
        "reason": "",
        "phase_flip_score": float("nan"),
        "side_symmetry_ratio": float("nan"),
        "dc_balance_error": float("nan"),
        "derivative_residual_fraction": float("nan"),
        "temporal_rank_fraction": float("nan"),
        "analyser_independent_fraction": float("nan"),
    }
    plus_row, minus_row = _s9_quadrature_rows(slope_rows, a_null)
    if not isinstance(null_reference_row, dict) or plus_row is None or minus_row is None:
        certificate["reason"] = "missing_null_or_opposite_quadrature_row"
        return certificate

    all_rows = [null_reference_row, plus_row, minus_row]
    hard_reasons: list[str] = []
    for row in all_rows:
        flags = row_quality_flags(row)
        if "lockin_overload" in flags or "lockin_range_exceeded" in flags:
            hard_reasons.append("lockin_range_invalid")
        if row_has_angle_failure(row):
            hard_reasons.append("verified_motor_geometry_failed")
        if row_has_quality_flag(
            row, "high_null_continued", "high_null_after_adaptive", "null_failed", "null_check_nan"
        ):
            hard_reasons.append("local_null_failed")

    plus_psi = _s9_psi_of_row(plus_row, a_null)
    minus_psi = _s9_psi_of_row(minus_row, a_null)
    if plus_psi is None or minus_psi is None or max(
        abs(float(plus_psi) - 45.0), abs(float(minus_psi) + 45.0)
    ) > float(S9_QUICK_MAX_ANALYSER_QUADRATURE_ERROR_DEG):
        hard_reasons.append("analyser_not_at_opposite_quadrature")

    qwp_errors: list[float] = []
    for row in (plus_row, minus_row):
        q_null = _finite_float_or_none(row.get("q_null_deg"))
        q_actual = _first_finite_followup_value(
            row.get("qwp_readout_actual_deg"),
            row.get("qwp_actual_deg"),
            row.get("qwp_readout_deg"),
        )
        if q_null is not None and q_actual is not None:
            qwp_errors.append(abs(periodic_delta_deg(q_null, q_actual, 180.0)))
    if not qwp_errors or max(qwp_errors) > float(MAX_QWP_OFFSET_FROM_NULL_DEG):
        hard_reasons.append("qwp_not_on_compensating_null")

    v0 = _finite_float_or_none(null_reference_row.get("detector_V"))
    vp = _finite_float_or_none(plus_row.get("detector_V"))
    vm = _finite_float_or_none(minus_row.get("detector_V"))
    z0 = _s9_raw_phasor_of_row(null_reference_row)
    zp = _s9_raw_phasor_of_row(plus_row)
    zm = _s9_raw_phasor_of_row(minus_row)
    joint = None
    if None in (v0, vp, vm) or z0 is None or zp is None or zm is None:
        hard_reasons.append("missing_dc_or_complex_triplet")
    else:
        try:
            joint = joint_senarmont_triplet(
                detector_null_v=float(v0),
                detector_plus_v=float(vp),
                detector_minus_v=float(vm),
                phasor_null=z0,
                phasor_plus=zp,
                phasor_minus=zm,
            )
        except (TypeError, ValueError) as exc:
            hard_reasons.append(f"joint_triplet_failed:{type(exc).__name__}")
    if joint is not None:
        dc_fit = dict(joint["dc_fit"])
        v_min = float(dc_fit["v_min_V"])
        v_max = float(dc_fit["v_max_V"])
        null_leakage = (
            max(0.0, v_min) / max(v_max, 1e-15)
            if np.isfinite(v_min) and np.isfinite(v_max) and v_max > 0.0
            else float("inf")
        )
        plus_midfringe_fraction = dc_malus_fraction_at_psi(
            dc_fit, float(plus_psi)
        )
        plus_midfringe_error = abs(float(plus_midfringe_fraction) - 0.5)
        certificate.update({
            "dc_balance_error": float(joint["dc_balance_error"]),
            "dc_null_offset_deg": abs(float(dc_fit["null_psi_deg"])),
            "null_leakage_fraction": float(null_leakage),
            "midfringe_fraction": float(plus_midfringe_fraction),
            "midfringe_error": float(plus_midfringe_error),
            "derivative_residual_fraction": float(
                joint["derivative_residual_fraction"]
            ),
            "temporal_rank_fraction": float(joint["temporal_rank_fraction"]),
            "analyser_independent_fraction": float(
                joint["analyser_independent_fraction"]
            ),
            "fit_amplitude_V": float(joint["aligned_ac_amplitude_V"]),
            "operating_psi_deg": float(
                dc_fit["plus_quadrature_psi_deg"]
            ),
            "equivalent_rotation_mag_rad_rms": float(
                joint["equivalent_rotation_mag_rad_rms"]
            ),
            "equivalent_rotation_phase_deg": float(
                joint["equivalent_rotation_phase_deg"]
            ),
            # Compatibility alias.  The quantity is not assumed electrical.
            "pickup_fraction": float(joint["analyser_independent_fraction"]),
        })
        if null_leakage > float(S9_MAX_NULL_LEAKAGE_FRACTION):
            hard_reasons.append("dc_null_leakage_above_five_percent")
        if abs(float(dc_fit["null_psi_deg"])) > float(S9_MAX_DC_NULL_SHIFT_DEG):
            hard_reasons.append("dc_extinction_not_at_measured_null")
        if plus_midfringe_error > float(S9_MAX_MIDFRINGE_ERROR):
            hard_reasons.append("measured_positive_branch_not_at_dc_half_fringe")

    phase_flip_score = phase_flip_score_from_rows(plus_row, minus_row)
    symmetry_ratio = side_symmetry_ratio_from_rows(plus_row, minus_row)
    certificate["phase_flip_score"] = float(phase_flip_score)
    certificate["side_symmetry_ratio"] = float(symmetry_ratio)
    snrs = [
        value for value in (
            _finite_float_or_none(plus_row.get("snr_estimate")),
            _finite_float_or_none(minus_row.get("snr_estimate")),
        )
        if value is not None
    ]
    low_signal = bool(snrs and max(snrs) < float(S9_LOW_SIGNAL_SNR))
    certificate["low_signal"] = low_signal

    if hard_reasons:
        certificate["status"] = "failed"
        certificate["reason"] = ";".join(sorted(set(hard_reasons)))
    elif low_signal:
        # At a physical angular node there is no EO peak to locate.  The DC
        # geometry can still be valid; do not waste three extra lock-in reads
        # trying to maximize noise or electrical pickup.
        certificate["status"] = "geometry_only_low_signal"
        certificate["reason"] = "eo_signal_below_triplet_certification_snr"
    elif (
        np.isfinite(phase_flip_score)
        and phase_flip_score >= float(S9_QUICK_MIN_PHASE_FLIP_SCORE)
        and np.isfinite(symmetry_ratio)
        and symmetry_ratio >= float(S9_QUICK_MIN_SIDE_SYMMETRY_RATIO)
        and _finite_float_or_none(certificate.get("dc_balance_error")) is not None
        and float(certificate["dc_balance_error"]) <= float(S9_QUICK_MAX_DC_BALANCE_ERROR)
        and _finite_float_or_none(certificate.get("midfringe_error")) is not None
        and float(certificate["midfringe_error"]) <= float(S9_MAX_MIDFRINGE_ERROR)
        and _finite_float_or_none(
            certificate.get("derivative_residual_fraction")
        ) is not None
        and float(certificate["derivative_residual_fraction"])
        <= float(S9_MAX_DERIVATIVE_RESIDUAL_FRACTION)
        and _finite_float_or_none(certificate.get("temporal_rank_fraction")) is not None
        and float(certificate["temporal_rank_fraction"])
        <= float(S9_MAX_TEMPORAL_RANK_FRACTION)
    ):
        certificate["status"] = "certified_triplet"
        certificate["reason"] = "dc_derivative_aligned_opposite_quadrature_triplet"
    elif not certificate["reason"]:
        certificate["reason"] = "triplet_derivative_alignment_or_symmetry_inconclusive"
    return certificate


def annotate_s9_certificate(rows: list[dict], certificate: dict) -> None:
    status = str(certificate.get("status", "failed") or "failed")
    accepted = status in {
        "certified_fit", "certified_triplet", "geometry_only_low_signal"
    }
    field_map = {
        "s9_method": "method",
        "s9_reason": "reason",
        "s9_n_fit_points": "n_fit_points",
        "s9_complex_r_squared": "complex_r_squared",
        "s9_dc_r_squared": "dc_r_squared",
        "s9_dynamic_peak_offset_deg": "dynamic_peak_offset_deg",
        "s9_peak_shift_deg": "peak_shift_deg",
        "s9_dc_null_offset_deg": "dc_null_offset_deg",
        "s9_null_leakage_fraction": "null_leakage_fraction",
        "s9_midfringe_fraction": "midfringe_fraction",
        "s9_midfringe_error": "midfringe_error",
        "s9_confirm_error_fraction": "confirm_error_fraction",
        "s9_fit_amplitude_V": "fit_amplitude_V",
        "s9_analyser_independent_fraction": "analyser_independent_fraction",
        "s9_derivative_residual_fraction": "derivative_residual_fraction",
        "s9_temporal_rank_fraction": "temporal_rank_fraction",
        "s9_operating_psi_deg": "operating_psi_deg",
        "s9_equivalent_rotation_mag_rad_rms": (
            "equivalent_rotation_mag_rad_rms"
        ),
        "s9_equivalent_rotation_phase_deg": "equivalent_rotation_phase_deg",
        # Compatibility alias for older CSV consumers.  This is analyser-
        # independent modulation and is not assumed to be electrical pickup.
        "s9_pickup_fraction": "pickup_fraction",
        "s9_fit_signal_to_residual": "fit_signal_to_residual",
        "s9_phase_flip_score": "phase_flip_score",
        "s9_side_symmetry_ratio": "side_symmetry_ratio",
        "s9_dc_balance_error": "dc_balance_error",
    }
    for row in rows:
        row["s9_status"] = status
        previous_flags = row_quality_flags(row) - {
            "s9_operating_point_certified",
            "s9_operating_point_failed",
            "s9_low_signal_geometry_only",
        }
        row["quality_flags"] = ";".join(sorted(previous_flags))
        for field, key in field_map.items():
            value = certificate.get(key)
            if value is not None:
                row[field] = value
        append_row_quality(
            row,
            "s9_operating_point_certified" if accepted else "s9_operating_point_failed",
        )
        if status == "geometry_only_low_signal":
            append_row_quality(row, "s9_low_signal_geometry_only")
        row["quality"] = classify_peak_quality(row)


def sinusoid_fit_analyser_peak(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    null_reference_row: dict | None,
    t_start: float,
    seed_records: list[dict],
    best_seed: dict,
) -> tuple[dict | None, list[dict], int, int, dict | None, list[dict]]:
    """Certify a DC-half-fringe S9/Sénarmont operating point.

    The existing null/+45/-45 readings are reused and one bright-fringe
    reading supplies the balanced 0/+45/90/-45 fit.  The analyser is then
    moved to the selected *DC* quadrature for one independent confirmation.
    The fitted AC extremum is only a contamination diagnostic: it is never
    followed as an independently optimised operating point.
    """

    probes: list[tuple[float, float, float]] = []
    dc_probes: list[tuple[float, float]] = []
    probe_rows: list[dict] = []

    def _add_probe(row) -> None:
        if not isinstance(row, dict):
            return
        psi = _s9_psi_of_row(row, a_null)
        phasor = _s9_raw_phasor_of_row(row)
        if psi is None or phasor is None:
            return
        probes.append((float(psi), float(phasor.real), float(phasor.imag)))
        detector_v = _finite_float_or_none(row.get("detector_V"))
        if detector_v is not None:
            dc_probes.append((float(psi), float(detector_v)))
        if not any(existing is row for existing in probe_rows):
            probe_rows.append(row)

    _add_probe(null_reference_row)
    for record in seed_records:
        _add_probe(record.get("row"))

    def _measure(anl_target: float, slope_side: str):
        return measure_lockin_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side=slope_side,
            anl_target=float(anl_target),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            null_context=base_null_context,
            null_reference_row=null_reference_row,
            t_start=t_start,
        )

    raw_rows: list[dict] = []
    n_probes = 0
    preferred_side = str(best_seed.get("side", "plus45") or "plus45").lower()
    side_sign = -1.0 if "minus" in preferred_side else 1.0
    current_anl = rotator_read_angle_once(rot_anl)
    if not np.isfinite(current_anl):
        current_anl = _finite_float_or_none(best_seed.get("anl"))
    if current_anl is None or not np.isfinite(current_anl):
        current_anl = float(a_null) + side_sign * 45.0

    # One fixed bright-fringe probe completes a balanced and well-conditioned
    # 0, +45, 90, -45 degree design.  Do not choose probe angles after looking
    # at which noisy quadrature branch appeared stronger.
    bright_target = closest_periodic_equivalent_deg(
        float(a_null) + 90.0, float(current_anl), 180.0, analyser=True
    )
    gui_pixel_checkpoint()
    bright_row, bright_raw, sens_idx = _measure(
        bright_target, "auto_peak_probe"
    )
    n_probes += 1
    append_row_quality(bright_row, "locked_qwp_balanced_bright_probe")
    bright_row["peak_source"] = "balanced_dc_complex_fit_probe"
    bright_row["peak_track_mode"] = "locked-qwp"
    raw_rows.extend(bright_raw)
    _add_probe(bright_row)
    bright_actual = _finite_float_or_none(bright_row.get("anl_actual_deg"))
    if bright_actual is not None:
        current_anl = bright_actual

    fit: dict = {}
    certificate = {
        "status": "failed",
        "method": "balanced_dc_derivative_complex_fit",
        "reason": "",
        "n_fit_points": len(probes),
    }
    try:
        dc_fit = fit_dc_malus_response(
            [p[0] for p in dc_probes],
            [p[1] for p in dc_probes],
        )
    except Exception as exc:
        certificate["reason"] = f"dc_malus_fit_failed:{type(exc).__name__}:{exc}"
        fit["s9_certificate"] = certificate
        print(f"  [S9 CERT] DC Malus fit failed ({exc}).")
        return None, raw_rows, sens_idx, n_probes, fit, probe_rows

    dc_r_squared_early = float(dc_fit.get("r_squared", float("nan")))
    dc_null_offset_early = abs(periodic_delta_deg(
        0.0, float(dc_fit["null_psi_deg"]), 180.0
    ))
    dc_v_min_early = float(dc_fit.get("v_min_V", float("nan")))
    dc_v_max_early = float(dc_fit.get("v_max_V", float("nan")))
    dc_null_leakage_early = (
        max(0.0, dc_v_min_early) / max(dc_v_max_early, 1e-15)
        if np.isfinite(dc_v_min_early) and np.isfinite(dc_v_max_early)
        and dc_v_max_early > 0.0 else float("inf")
    )
    probe_geometry_reasons: list[str] = []
    for probe_row in probe_rows:
        if row_has_angle_failure(probe_row):
            probe_geometry_reasons.append("verified_motor_geometry_failed")
        probe_q_null = _first_finite_followup_value(
            probe_row.get("q_null_deg"), q_null
        )
        probe_q_actual = _first_finite_followup_value(
            probe_row.get("qwp_readout_actual_deg"),
            probe_row.get("qwp_actual_deg"),
            probe_row.get("qwp_readout_deg"),
        )
        if probe_q_null is None or probe_q_actual is None:
            probe_geometry_reasons.append("missing_qwp_geometry")
        elif abs(periodic_delta_deg(
            float(probe_q_null), float(probe_q_actual), 180.0
        )) > float(MAX_QWP_OFFSET_FROM_NULL_DEG):
            probe_geometry_reasons.append("qwp_not_on_compensating_null")
    operating_psi = float(
        dc_fit[
            "plus_quadrature_psi_deg"
            if side_sign > 0.0
            else "minus_quadrature_psi_deg"
        ]
    )
    assumed_midfringe_fraction = dc_malus_fraction_at_psi(dc_fit, operating_psi)
    assumed_midfringe_error = abs(float(assumed_midfringe_fraction) - 0.5)
    try:
        complex_fit = fit_sinusoid_response(
            [p[0] for p in probes],
            [p[1] for p in probes],
            [p[2] for p in probes],
        )
    except Exception as exc:
        dc_geometry_ok = bool(
            np.isfinite(dc_r_squared_early)
            and dc_r_squared_early >= float(S9_DC_MALUS_MIN_R2)
            and dc_null_offset_early <= float(S9_MAX_DC_NULL_SHIFT_DEG)
            and dc_null_leakage_early <= float(S9_MAX_NULL_LEAKAGE_FRACTION)
            and np.isfinite(assumed_midfringe_error)
            and assumed_midfringe_error <= float(S9_MAX_MIDFRINGE_ERROR)
            and not probe_geometry_reasons
            and not any(
                row_has_quality_flag(row, "lockin_overload", "lockin_range_exceeded")
                for row in probe_rows
            )
        )
        certificate.update({
            "status": "geometry_only_low_signal" if dc_geometry_ok else "failed",
            "reason": (
                "dc_half_fringe_certified_but_no_resolvable_complex_eo_response"
                if dc_geometry_ok
                else f"complex_fit_failed:{type(exc).__name__}:{exc}"
            ),
            "dc_r_squared": dc_r_squared_early,
            "dc_null_offset_deg": dc_null_offset_early,
            "null_leakage_fraction": dc_null_leakage_early,
            "midfringe_fraction": float(assumed_midfringe_fraction),
            "midfringe_error": float(assumed_midfringe_error),
            "operating_psi_deg": float(operating_psi),
        })
        fit["dc_malus_fit"] = dc_fit
        fit["s9_certificate"] = certificate
        print(
            f"  [S9 CERT] {'DC geometry accepted at an EO node' if dc_geometry_ok else 'Complex fit failed'} "
            f"({exc})."
        )
        selected_seed = best_seed.get("row")
        return (
            selected_seed if dc_geometry_ok and isinstance(selected_seed, dict) else None,
            raw_rows,
            sens_idx,
            n_probes,
            fit,
            probe_rows,
        )

    fit.update(complex_fit)
    fit["dc_malus_fit"] = dc_fit
    try:
        joint_fit = joint_senarmont_from_fits(dc_fit, complex_fit)
    except Exception as exc:
        certificate["reason"] = (
            f"joint_dc_ac_derivative_fit_failed:{type(exc).__name__}:{exc}"
        )
        fit["s9_certificate"] = certificate
        return None, raw_rows, sens_idx, n_probes, fit, probe_rows
    fit["joint_senarmont_fit"] = joint_fit

    # The operating point is fixed by the DC fringe.  Find the nearest AC
    # extremum only to quantify disagreement with the Sénarmont model.
    ac_candidates = (
        float(complex_fit["peak_psi_deg"]),
        float(complex_fit["alt_peak_psi_deg"]),
    )
    ac_peak_psi = min(
        ac_candidates,
        key=lambda value: abs(periodic_delta_deg(operating_psi, value, 180.0)),
    )
    shift_deg = abs(periodic_delta_deg(operating_psi, ac_peak_psi, 180.0))
    predicted_phasor = predict_complex_analyser_response(
        complex_fit, operating_psi
    )
    predicted_mag = abs(predicted_phasor)
    r_squared = float(fit.get("r_squared", float("nan")))
    dc_r_squared = float(dc_fit.get("r_squared", float("nan")))
    dc_null_offset = abs(periodic_delta_deg(
        0.0, float(dc_fit["null_psi_deg"]), 180.0
    ))
    null_leakage_fraction = dc_null_leakage_early
    midfringe_fraction = dc_malus_fraction_at_psi(dc_fit, operating_psi)
    midfringe_error = abs(float(midfringe_fraction) - 0.5)
    amplitude = float(joint_fit.get("aligned_ac_amplitude_V", float("nan")))
    analyser_independent_fraction = float(
        joint_fit.get("analyser_independent_fraction", float("nan"))
    )
    derivative_residual = float(
        joint_fit.get("derivative_residual_fraction", float("nan"))
    )
    temporal_rank = float(
        joint_fit.get("temporal_rank_fraction", float("nan"))
    )
    certificate.update({
        "complex_r_squared": r_squared,
        "dc_r_squared": dc_r_squared,
        "dynamic_peak_offset_deg": float(ac_peak_psi),
        "peak_shift_deg": float(shift_deg),
        "operating_psi_deg": float(operating_psi),
        "dc_null_offset_deg": float(dc_null_offset),
        "null_leakage_fraction": float(null_leakage_fraction),
        "midfringe_fraction": float(midfringe_fraction),
        "midfringe_error": float(midfringe_error),
        "fit_amplitude_V": amplitude,
        "analyser_independent_fraction": float(analyser_independent_fraction),
        "pickup_fraction": float(analyser_independent_fraction),
        "derivative_residual_fraction": float(derivative_residual),
        "temporal_rank_fraction": float(temporal_rank),
        "equivalent_rotation_x_rad_rms": joint_fit.get(
            "equivalent_rotation_x_rad_rms"
        ),
        "equivalent_rotation_y_rad_rms": joint_fit.get(
            "equivalent_rotation_y_rad_rms"
        ),
        "equivalent_rotation_mag_rad_rms": joint_fit.get(
            "equivalent_rotation_mag_rad_rms"
        ),
        "equivalent_rotation_phase_deg": joint_fit.get(
            "equivalent_rotation_phase_deg"
        ),
    })

    seed_snrs = [
        value
        for value in (
            _finite_float_or_none((record.get("row") or {}).get("snr_estimate"))
            for record in seed_records
        )
        if value is not None
    ]
    fit_residual = float(fit.get("rms_residual_V", float("nan")))
    fit_signal_to_residual = (
        amplitude / max(fit_residual, 1e-15)
        if np.isfinite(amplitude) and np.isfinite(fit_residual)
        else float("nan")
    )
    certificate["fit_signal_to_residual"] = float(fit_signal_to_residual)
    low_signal = bool(
        (seed_snrs and max(seed_snrs) < float(S9_LOW_SIGNAL_SNR))
        or (
            np.isfinite(amplitude)
            and amplitude < float(S9_MIN_EO_AMPLITUDE_PER_VPP_V) * abs(float(vpp))
        )
        or (
            np.isfinite(fit_signal_to_residual)
            and fit_signal_to_residual < float(S9_LOW_SIGNAL_SNR)
        )
    )
    fit_reasons: list[str] = list(probe_geometry_reasons)
    if any(row_has_quality_flag(row, "lockin_overload", "lockin_range_exceeded") for row in probe_rows):
        fit_reasons.append("lockin_range_invalid")
    if not np.isfinite(dc_r_squared) or dc_r_squared < float(S9_DC_MALUS_MIN_R2):
        fit_reasons.append("dc_malus_low_r_squared")
    if dc_null_offset > float(S9_MAX_DC_NULL_SHIFT_DEG):
        fit_reasons.append("dc_extinction_not_at_measured_null")
    if (
        not np.isfinite(null_leakage_fraction)
        or null_leakage_fraction > float(S9_MAX_NULL_LEAKAGE_FRACTION)
    ):
        fit_reasons.append("dc_null_leakage_above_five_percent")
    if not np.isfinite(midfringe_error) or midfringe_error > float(S9_MAX_MIDFRINGE_ERROR):
        fit_reasons.append("dc_operating_point_not_at_half_fringe")

    if low_signal and not fit_reasons:
        certificate.update({
            "status": "geometry_only_low_signal",
            "reason": "dc_half_fringe_certified_but_eo_signal_too_small_for_derivative_test",
        })
        fit["s9_certificate"] = certificate
        print(
            f"  [S9 CERT] DC geometry accepted at low EO signal: "
            f"DC R2={dc_r_squared:.4f}, null shift={dc_null_offset:.2f} deg."
        )
        selected_seed = best_seed.get("row")
        return (
            selected_seed if isinstance(selected_seed, dict) else None,
            raw_rows,
            sens_idx,
            n_probes,
            fit,
            probe_rows,
        )

    if not np.isfinite(r_squared) or r_squared < float(S9_COMPLEX_MIN_R2):
        fit_reasons.append("complex_eo_low_r_squared")
    if shift_deg > float(S9_MAX_DYNAMIC_PEAK_SHIFT_DEG):
        fit_reasons.append("ac_extremum_displaced_from_dc_quadrature")
    if (
        not np.isfinite(derivative_residual)
        or derivative_residual > float(S9_MAX_DERIVATIVE_RESIDUAL_FRACTION)
    ):
        fit_reasons.append("ac_response_not_aligned_to_dc_derivative")
    if (
        not np.isfinite(temporal_rank)
        or temporal_rank > float(S9_MAX_TEMPORAL_RANK_FRACTION)
    ):
        fit_reasons.append("complex_response_has_multiple_temporal_phases")
    if fit_reasons:
        certificate["reason"] = ";".join(sorted(set(fit_reasons)))
        fit["s9_certificate"] = certificate
        print(
            f"  [S9 CERT] Fit rejected: {certificate['reason']} "
            f"(complex R2={r_squared:.4f}, DC R2={dc_r_squared:.4f}, "
            f"AC/DC shift={shift_deg:.2f} deg, derivative residual="
            f"{derivative_residual:.3f})."
        )
        return None, raw_rows, sens_idx, n_probes, fit, probe_rows

    anl_star = closest_periodic_equivalent_deg(
        float(a_null) + operating_psi,
        float(current_anl),
        180.0,
        analyser=True,
    )
    gui_pixel_checkpoint()
    row, raw, sens_idx = _measure(anl_star, "auto_peak")
    n_probes += 1
    raw_rows.extend(raw)
    probe_rows.append(row)
    append_row_quality(row, "dc_half_fringe_confirmation")
    measured = lockin_peak_metric_value(row)
    measured_raw_phasor = _s9_raw_phasor_of_row(row)
    confirm_error_fraction = (
        abs(measured_raw_phasor - predicted_phasor) / max(amplitude, 1e-15)
        if measured_raw_phasor is not None and np.isfinite(amplitude) and amplitude > 0.0
        else float("nan")
    )
    certificate["confirm_error_fraction"] = float(confirm_error_fraction)
    if (
        not np.isfinite(confirm_error_fraction)
        or confirm_error_fraction > float(S9_MAX_CONFIRM_ERROR_FRACTION)
    ):
        fit_reasons.append("confirmation_mismatched_joint_complex_fit")
        append_row_quality(row, "sinusoid_fit_prediction_mismatch")
    measured_detector_v = _finite_float_or_none(row.get("detector_V"))
    if measured_detector_v is not None:
        observed_midfringe_fraction = (
            (float(measured_detector_v) - float(dc_fit["v_min_V"]))
            / max(float(dc_fit["fringe_swing_V"]), 1e-15)
        )
        observed_midfringe_error = abs(observed_midfringe_fraction - 0.5)
        certificate["midfringe_fraction"] = float(observed_midfringe_fraction)
        certificate["midfringe_error"] = float(observed_midfringe_error)
        if observed_midfringe_error > float(S9_MAX_MIDFRINGE_ERROR):
            fit_reasons.append("confirmation_not_at_measured_dc_half_fringe")
    if row_has_quality_flag(row, "lockin_overload", "lockin_range_exceeded"):
        fit_reasons.append("confirmation_lockin_range_invalid")

    if fit_reasons:
        certificate.update({
            "status": "failed",
            "reason": ";".join(sorted(set(fit_reasons))),
        })
        fit["s9_certificate"] = certificate
        print(
            f"  [S9 CERT] Confirmation rejected: {certificate['reason']} "
            f"(error={confirm_error_fraction:.3f})."
        )
        return None, raw_rows, sens_idx, n_probes, fit, probe_rows

    certificate.update({
        "status": "certified_fit",
        "reason": "dc_half_fringe_derivative_aligned_confirmed",
        "n_fit_points": int(len(probes)),
    })
    fit["s9_certificate"] = certificate

    append_row_quality(row, "s9_dc_quadrature_fit")
    append_row_quality(row, f"s9_dc_quadrature_fit_probes={n_probes}")
    append_row_quality(
        row,
        "joint_fit(psi_dc=%+.2fdeg A=%.3fuV phase=%+.2fdeg R2=%.4f "
        "independent=%.3fuV derivative_resid=%.3f rank=%.3f)" % (
            operating_psi,
            amplitude * 1e6,
            float(joint_fit["equivalent_rotation_phase_deg"]),
            r_squared,
            float(joint_fit["analyser_independent_mag_V"]) * 1e6,
            derivative_residual,
            temporal_rank,
        ),
    )
    print(
        f"  [S9 CERT] CERTIFIED DC quadrature psi={operating_psi:+.2f} deg; "
        f"AC-extremum diagnostic shift={shift_deg:.2f} deg, "
        f"aligned A={amplitude * 1e6:.3f} uV, "
        f"phase={float(joint_fit['equivalent_rotation_phase_deg']):+.2f} deg, "
        f"complex R2={r_squared:.4f}, DC R2={dc_r_squared:.4f}, "
        f"half-fringe={float(certificate['midfringe_fraction']):.3f}, "
        f"derivative residual={derivative_residual:.3f}, "
        f"confirm={float(measured) * 1e6:.3f} uV "
        f"(raw predicted {predicted_mag * 1e6:.3f} uV, "
        f"complex error {confirm_error_fraction:.3f})"
    )
    return row, raw_rows, sens_idx, n_probes, fit, probe_rows


def auto_find_analyser_peak_from_null_locked_qwp(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    previous_peak: dict | None,
    null_reference_row: dict | None,
    t_start: float,
) -> tuple[dict, list[dict], int, int, dict]:
    """Abel-style peak search: lock QWP to the null branch and refine analyser only."""
    qwp_readout = _finite_float_or_none(base_null_context.get("qwp_readout_deg"))
    if qwp_readout is None:
        qwp_readout = qwp_readout_target_from_null(
            q_null,
            auto_peak_readout_offset_from_context(base_null_context),
        )
    qwp_actual = _finite_float_or_none(base_null_context.get("qwp_readout_actual_deg"))
    if qwp_actual is None:
        qwp_actual = float(qwp_readout)
    qwp_error = _finite_float_or_none(base_null_context.get("qwp_readout_error_deg"))
    if qwp_error is None:
        qwp_error = 0.0
    qwp_offset = periodic_delta_deg(q_null, qwp_readout, 180.0)

    current_anl_angle = rotator_read_angle_once(rot_anl)
    if not np.isfinite(current_anl_angle):
        current_anl_angle = a_null
    slope_targets = ordered_slope_targets(a_null, current_anl_angle)
    if previous_peak:
        try:
            prev_hwp = float(previous_peak["hwp_deg"])
            prev_a = float(previous_peak["anl_target_deg"])
            d_hwp = periodic_delta_deg(prev_hwp, hwp_deg, 90.0)
            predicted_a = closest_periodic_equivalent_deg(
                prev_a + 2.0 * d_hwp,
                a_null,
                180.0,
                analyser=True,
            )
            slope_targets.sort(
                key=lambda item: abs(periodic_delta_deg(predicted_a, item[1], 180.0))
            )
        except Exception:
            pass

    print(
        f"\nP{int(pixel['pixel']):03d} locked-QWP analyser peak HWP={float(hwp_deg):.4f}: "
        f"QWP={float(qwp_readout):.4f} "
        f"(offset {float(qwp_offset):+.3f} from null), probing analyser +/-45 from "
        f"a_null={float(a_null):.4f}"
    )

    seed_records: list[dict] = []
    seed_raw_rows: list[dict] = []
    seed_probe_count = 0
    for seed_side, seed_anl in slope_targets:
        gui_pixel_checkpoint()
        row, raw, sens_idx = measure_lockin_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side="auto_peak_probe",
            anl_target=float(seed_anl),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            null_context=base_null_context,
            null_reference_row=null_reference_row,
            t_start=t_start,
        )
        seed_probe_count += 1
        append_row_quality(row, "locked_qwp_theory_slope_seed")
        append_row_quality(row, f"locked_qwp_seed_{seed_side}")
        if abs(float(qwp_offset)) > 1e-6:
            append_row_quality(row, "locked_qwp_nonzero_qwp_readout_offset")
        mag = lockin_peak_metric_value(row)
        row["peak_source"] = "locked_qwp_seed"
        row["peak_track_mode"] = "locked-qwp"
        row["chosen_side"] = str(seed_side)
        seed_records.append({
            "mag": float(mag),
            "row": row,
            "raw": raw,
            "anl": float(row.get("anl_target_deg", seed_anl)),
            "side": seed_side,
        })
        seed_raw_rows.extend(raw)

    finite_seeds = [record for record in seed_records if np.isfinite(float(record["mag"]))]
    if finite_seeds:
        best_seed = max(finite_seeds, key=lambda record: float(record["mag"]))
    elif seed_records:
        best_seed = seed_records[0]
    else:
        best_seed = {"anl": float(a_null) + 45.0, "side": "plus45", "mag": float("nan")}

    seed_rows_by_side = {
        str(record.get("side")): record.get("row")
        for record in seed_records
        if isinstance(record.get("row"), dict)
    }
    phase_flip_score = phase_flip_score_from_rows(
        seed_rows_by_side.get("plus45"),
        seed_rows_by_side.get("minus45"),
    )
    side_symmetry_ratio = side_symmetry_ratio_from_rows(
        seed_rows_by_side.get("plus45"),
        seed_rows_by_side.get("minus45"),
    )
    for record in seed_records:
        seed_row = record.get("row")
        if isinstance(seed_row, dict):
            annotate_peak_readout_row(
                seed_row,
                peak_source="locked_qwp_seed",
                peak_track_mode="locked-qwp",
                chosen_side=str(record.get("side", "")),
                phase_flip_score=phase_flip_score,
                side_symmetry_ratio=side_symmetry_ratio,
            )

    refine_mode = str(AUTO_PEAK_REFINE_MODE).strip().lower()
    if refine_mode not in ("two-point", "fit", "greedy"):
        refine_mode = "two-point"
    mode_description = {
        "two-point": "using +/-45 only (no fit or greedy refine)",
        "fit": "sinusoid-fit analyser refine",
        "greedy": "greedy analyser refine",
    }[refine_mode]
    print(
        f"P{int(pixel['pixel']):03d} locked-QWP seed selected HWP={float(hwp_deg):.4f}: "
        f"{best_seed.get('side')} ANL={float(best_seed['anl']):.4f}, "
        f"metric={float(best_seed.get('mag', float('nan'))) * 1e6:.3f} uV; "
        + mode_description
    )
    row = None
    raw: list[dict] = []
    refine_n = 0
    if refine_mode == "two-point":
        selected_seed_row = best_seed.get("row")
        if not isinstance(selected_seed_row, dict):
            raise RuntimeError(
                "Locked-QWP +/-45 calibration did not produce a usable analyser row."
            )
        row = selected_seed_row
        row["slope_side"] = "auto_peak"
        row["peak_source"] = "locked_qwp_plus_minus_45"
        append_row_quality(row, "locked_qwp_plus_minus_45_only")
    elif refine_mode == "fit" and len(finite_seeds) >= 2:
        preferred_fit_seed = next(
            (
                record
                for record in seed_records
                if str(record.get("side", "")) == "plus45"
            ),
            seed_records[0],
        )
        (
            fit_row,
            fit_raw,
            sens_idx,
            fit_probes,
            _fit_info,
            fit_summary_rows,
        ) = sinusoid_fit_analyser_peak(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=null_reference_row,
            t_start=t_start,
            seed_records=seed_records,
            best_seed=preferred_fit_seed,
        )
        refine_n += int(fit_probes)
        if fit_row is not None:
            fit_certificate = dict((_fit_info or {}).get("s9_certificate") or {})
            if fit_certificate:
                annotate_s9_certificate(fit_summary_rows, fit_certificate)
            row = fit_row
            raw = fit_raw
        else:
            # keep the extra probe samples with the seed data, then fall back
            seed_raw_rows.extend(fit_raw)
    if row is None:
        row, raw, sens_idx, greedy_n = auto_refine_analyser_peak_locked_qwp(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_readout_deg=float(qwp_readout),
            qwp_readout_actual_deg=float(qwp_actual),
            qwp_readout_error_deg=float(qwp_error),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            analyser_seed_deg=float(best_seed["anl"]),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=null_reference_row,
            t_start=t_start,
        )
        refine_n += int(greedy_n)
    append_row_quality(row, "auto_peak_track_mode_locked-qwp")
    if refine_mode == "two-point":
        append_row_quality(row, "locked_qwp_analyser_refine_skipped")
    else:
        append_row_quality(row, "locked_qwp_analyser_refine")
    append_row_quality(row, "peak_seeded_from_current_null_plus_minus_45")
    if abs(float(qwp_offset)) > 1e-6:
        append_row_quality(row, "locked_qwp_nonzero_qwp_readout_offset")
    annotate_peak_readout_row(
        row,
        peak_source="auto_peak_calibration",
        peak_track_mode="locked-qwp",
        chosen_side=str(best_seed.get("side", "")),
        phase_flip_score=phase_flip_score,
        side_symmetry_ratio=side_symmetry_ratio,
        anl_refine_seed_deg=float(best_seed["anl"]),
    )
    # The two physical +/-45 probes are streamed as auto_peak_probe while
    # they are being compared.  Publish the selected winner under the durable
    # auto_peak series so the live HWP graph and a later CSV reload agree.
    gui_update_lockin_bar(
        "auto_peak",
        pixel=int(pixel["pixel"]),
        hwp_deg=float(hwp_deg),
        vpp=float(vpp),
        a_null=float(a_null),
        mag_v=float(row.get("lockin_mag_V", float("nan"))),
        signed_v=float(row.get("lockin_signed_V", float("nan"))),
        phase_deg=float(row.get("lockin_phase_deg", float("nan"))),
        net_mag_v=lockin_raw_response_value(row, "lockin_net_mag_V"),
        net_signed_v=lockin_raw_response_value(row, "lockin_net_signed_V"),
        bg_mag_v=lockin_raw_response_value(row, "lockin_bg_mag_V"),
    )

    peak_state = {
        "hwp_deg": float(hwp_deg),
        "qwp_readout_deg": float(row.get("qwp_readout_deg", qwp_readout)),
        "anl_target_deg": float(row.get("anl_target_deg", best_seed["anl"])),
    }
    return row, seed_raw_rows + raw, sens_idx, seed_probe_count + int(refine_n), peak_state


def auto_find_qwp_analyser_peak_from_null(
    *,
    pixel: dict,
    hwp_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    vpp: float,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    null_reference_row: dict | None,
    previous_peak: dict | None,
    t_start: float,
    max_coarse_probes: int = DEFAULT_AUTO_PEAK_MAX_COARSE_PROBES,
    track_mode: str = DEFAULT_AUTO_PEAK_TRACK_MODE,
) -> tuple[dict, list[dict], int, int, dict]:
    """Find a QWP+analyser lock-in peak seed from calibration, without manual angles."""
    track_mode = str(track_mode or DEFAULT_AUTO_PEAK_TRACK_MODE).strip().lower()
    if track_mode not in ("locked-qwp", "confirm", "refine", "global", "hybrid"):
        track_mode = DEFAULT_AUTO_PEAK_TRACK_MODE
    global_search = track_mode == "global"
    if track_mode == "locked-qwp":
        return auto_find_analyser_peak_from_null_locked_qwp(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            previous_peak=previous_peak,
            null_reference_row=null_reference_row,
            t_start=t_start,
        )
    if previous_peak and not global_search:
        try:
            prev_hwp = float(previous_peak["hwp_deg"])
            prev_q = float(previous_peak["qwp_readout_deg"])
            prev_a = float(previous_peak["anl_target_deg"])
            d_hwp = periodic_delta_deg(prev_hwp, hwp_deg, 90.0)
            q_seed = closest_periodic_equivalent_deg(prev_q + 2.0 * d_hwp, q_null, 180.0)
            a_seed = closest_periodic_equivalent_deg(
                prev_a + 2.0 * d_hwp,
                a_null,
                180.0,
                analyser=True,
            )
            print(
                f"\nP{int(pixel['pixel']):03d} auto peak seed HWP={float(hwp_deg):.4f}: "
                f"predicted from previous peak dH={d_hwp:+.3f} -> "
                f"QWP={q_seed:.4f}, ANL={a_seed:.4f}"
            )
            if track_mode == "confirm":
                row, raw, sens_idx = measure_lockin_qwp_analyser_point(
                    pixel=pixel,
                    hwp_deg=float(hwp_deg),
                    qwp_target_deg=float(q_seed),
                    q_null=float(q_null),
                    a_null=float(a_null),
                    p_null=float(p_null),
                    p_null_mV=float(p_null_mV),
                    slope_side="auto_peak",
                    anl_target=float(a_seed),
                    vpp=float(vpp),
                    rot_qwp=rot_qwp,
                    rot_anl=rot_anl,
                    detector=detector,
                    lockin=lockin,
                    sens_idx=sens_idx,
                    reference_phase_deg=reference_phase_deg,
                    fast_rotator_moves=fast_rotator_moves,
                    verify_moves=verify_moves,
                    verify_tol_deg=verify_tol_deg,
                    base_null_context=base_null_context,
                    null_reference_row=None,
                    t_start=t_start,
                    phase_label="Auto predicted HWP peak confirmation",
                )
                n_probes = 1
                append_row_quality(row, "auto_peak_predicted_from_previous_hwp_confirm_only")
            else:
                row, raw, sens_idx, n_probes = auto_refine_qwp_analyser_peak_from_seed(
                    pixel=pixel,
                    hwp_deg=float(hwp_deg),
                    qwp_seed_deg=float(q_seed),
                    anl_seed_deg=float(a_seed),
                    q_null=float(q_null),
                    a_null=float(a_null),
                    p_null=float(p_null),
                    p_null_mV=float(p_null_mV),
                    vpp=float(vpp),
                    rot_qwp=rot_qwp,
                    rot_anl=rot_anl,
                    detector=detector,
                    lockin=lockin,
                    sens_idx=sens_idx,
                    reference_phase_deg=reference_phase_deg,
                    fast_rotator_moves=fast_rotator_moves,
                    verify_moves=verify_moves,
                    verify_tol_deg=verify_tol_deg,
                    base_null_context=base_null_context,
                    t_start=t_start,
                )
            append_row_quality(row, "auto_peak_seed_predicted_from_previous_hwp")
            append_row_quality(row, f"auto_peak_track_mode_{track_mode}")
            peak_state = {
                "hwp_deg": float(hwp_deg),
                "qwp_readout_deg": float(row.get("qwp_readout_deg", q_seed)),
                "anl_target_deg": float(row.get("anl_target_deg", a_seed)),
            }
            return row, raw, sens_idx, n_probes, peak_state
        except Exception as exc:
            print(
                f"\nP{int(pixel['pixel']):03d} auto peak previous-seed prediction failed "
                f"({type(exc).__name__}: {exc}); running coarse QWP/ANL search."
            )

    if global_search:
        candidates, global_grid_step = auto_peak_global_seed_candidates_from_null(
            float(q_null),
            float(a_null),
            AUTO_PEAK_GLOBAL_GRID_STEP_DEG,
        )
        search_desc = (
            f"global periodic grid, step {float(global_grid_step):g} deg, "
            f"refine top {int(AUTO_PEAK_GLOBAL_TOP_SEEDS)} separated seed(s)"
        )
    else:
        candidates = auto_peak_seed_candidates_from_null(
            float(q_null),
            float(a_null),
            base_null_context,
            max_coarse_probes,
        )
        global_grid_step = float("nan")
        full_grid_count = len(AUTO_PEAK_COARSE_Q_OFFSETS_DEG) * len(AUTO_PEAK_COARSE_A_OFFSETS_DEG)
        search_desc = (
            "full-grid rescue"
            if int(max_coarse_probes or 0) <= 0
            else f"bounded fast search, max {int(max_coarse_probes)}; old full grid {full_grid_count}"
        )
    print(
        f"\nP{int(pixel['pixel']):03d} auto peak coarse search HWP={float(hwp_deg):.4f}: "
        f"{len(candidates)} QWP/ANL seed probes ({search_desc}) "
        f"from null q={float(q_null):.3f}, a={float(a_null):.3f}"
    )

    best_row = None
    best_raw: list[dict] = []
    best_mag = float("nan")
    n_probes = 0
    seed_records: list[dict] = []
    for q_try, a_try, q_offset, a_offset in candidates:
        gui_pixel_checkpoint()
        row, raw, sens_idx = measure_lockin_qwp_analyser_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_target_deg=float(q_try),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side="auto_peak_probe",
            anl_target=float(a_try),
            vpp=float(vpp),
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=None,
            t_start=t_start,
            phase_label=(
                ("Auto global QWP/analyser peak seed " if global_search else "Auto fast QWP/analyser peak seed ")
                +
                f"(Q{q_offset:+g}, A{a_offset:+g})"
            ),
        )
        n_probes += 1
        mag = lockin_peak_metric_value(row)
        if np.isfinite(mag):
            seed_records.append({
                "mag": float(mag),
                "row": row,
                "raw": raw,
                "q": float(row.get("qwp_readout_deg", q_try)),
                "a": float(row.get("anl_target_deg", a_try)),
            })
            if not np.isfinite(best_mag) or float(mag) > float(best_mag):
                best_mag = float(mag)
                best_row = row
                best_raw = raw

    if best_row is None:
        raise CriticalNullError(
            f"HWP {float(hwp_deg):.3f} deg automatic peak seed search found no valid lock-in samples."
        )

    seed_records.sort(key=lambda item: float(item["mag"]), reverse=True)
    selected_seeds: list[dict] = []
    if global_search:
        separation = max(1.0, float(global_grid_step) * 0.75) if np.isfinite(global_grid_step) else 1.0
        for record in seed_records:
            if len(selected_seeds) >= int(AUTO_PEAK_GLOBAL_TOP_SEEDS):
                break
            too_close = False
            for chosen in selected_seeds:
                dq = abs(periodic_delta_deg(float(chosen["q"]), float(record["q"]), 180.0))
                da = abs(periodic_delta_deg(float(chosen["a"]), float(record["a"]), 180.0))
                if dq < separation and da < separation:
                    too_close = True
                    break
            if not too_close:
                selected_seeds.append(record)
    else:
        selected_seeds = seed_records[:1]
    if not selected_seeds:
        selected_seeds = [{
            "mag": float(best_mag),
            "row": best_row,
            "raw": best_raw,
            "q": float(best_row.get("qwp_readout_deg", best_row.get("q_null_deg", q_null))),
            "a": float(best_row.get("anl_target_deg", a_null)),
        }]

    row = None
    raw: list[dict] = []
    refined_mag = float("nan")
    refine_total = 0
    first_q_seed = float(selected_seeds[0]["q"])
    first_a_seed = float(selected_seeds[0]["a"])
    for seed_idx, seed in enumerate(selected_seeds, start=1):
        q_seed = float(seed["q"])
        a_seed = float(seed["a"])
        print(
            f"P{int(pixel['pixel']):03d} auto peak coarse seed {seed_idx}/{len(selected_seeds)} "
            f"HWP={float(hwp_deg):.4f}: QWP={q_seed:.4f}, ANL={a_seed:.4f}, "
            f"raw MAG={float(seed['mag']) * 1e6:.3f} uV; refining"
        )
        candidate_row, candidate_raw, sens_idx, refine_n = auto_refine_qwp_analyser_peak_from_seed(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_seed_deg=float(q_seed),
            anl_seed_deg=float(a_seed),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            vpp=float(vpp),
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            t_start=t_start,
        )
        refine_total += int(refine_n)
        candidate_mag = lockin_peak_metric_value(candidate_row)
        append_row_quality(candidate_row, f"auto_peak_refined_seed_rank_{seed_idx}")
        if np.isfinite(candidate_mag) and (not np.isfinite(refined_mag) or float(candidate_mag) > float(refined_mag)):
            refined_mag = float(candidate_mag)
            row = candidate_row
            raw = candidate_raw

    if row is None:
        row = best_row
        raw = best_raw
        refine_total = 0
    if global_search and len(selected_seeds) > 1:
        selected_q = float(row.get("qwp_readout_deg", first_q_seed))
        selected_a = float(row.get("anl_target_deg", first_a_seed))
        print(
            f"P{int(pixel['pixel']):03d} auto peak global selected HWP={float(hwp_deg):.4f}: "
            f"returning to QWP={selected_q:.4f}, ANL={selected_a:.4f} for final confirmation"
        )
        confirm_row, confirm_raw, sens_idx = measure_lockin_qwp_analyser_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            qwp_target_deg=float(selected_q),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side="auto_peak",
            anl_target=float(selected_a),
            vpp=float(vpp),
            rot_qwp=rot_qwp,
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            base_null_context=base_null_context,
            null_reference_row=None,
            t_start=t_start,
            phase_label="Auto global selected QWP/analyser peak confirmation",
        )
        refine_total += 1
        confirm_mag = lockin_peak_metric_value(confirm_row)
        selected_mag = lockin_peak_metric_value(row)
        append_row_quality(confirm_row, "auto_peak_global_selected_peak_confirm")
        if np.isfinite(confirm_mag) and (
            not np.isfinite(selected_mag)
            or float(confirm_mag) >= float(selected_mag)
            or abs((float(confirm_mag) - float(selected_mag)) * 1e6)
            <= lockin_peak_improvement_threshold_uV(row, confirm_row)
        ):
            row = confirm_row
            raw = confirm_raw
        else:
            append_row_quality(row, "auto_peak_global_selected_peak_confirm_lower")
    append_row_quality(row, "auto_peak_seed_from_coarse_qwp_analyser_search")
    if global_search:
        append_row_quality(row, "auto_peak_global_periodic_grid_search")
        append_row_quality(row, f"auto_peak_global_grid_step_deg={float(global_grid_step):g}")
        append_row_quality(row, f"auto_peak_global_refined_seeds={len(selected_seeds)}")
    q_seed = first_q_seed
    a_seed = first_a_seed
    peak_state = {
        "hwp_deg": float(hwp_deg),
        "qwp_readout_deg": float(row.get("qwp_readout_deg", q_seed)),
        "anl_target_deg": float(row.get("anl_target_deg", a_seed)),
    }
    return row, raw, sens_idx, n_probes + refine_total, peak_state


def auto_refine_analyser_peak_locked_qwp(
    *,
    pixel: dict,
    hwp_deg: float,
    qwp_readout_deg: float,
    qwp_readout_actual_deg: float,
    qwp_readout_error_deg: float,
    q_null: float,
    a_null: float,
    p_null: float,
    p_null_mV: float,
    analyser_seed_deg: float,
    vpp: float,
    rot_anl,
    detector,
    lockin,
    sens_idx: int,
    reference_phase_deg: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    base_null_context: dict,
    null_reference_row: dict | None,
    t_start: float,
) -> tuple[dict, list[dict], int, int]:
    """Fast 1D analyser peak search with QWP already locked at readout."""
    context = dict(base_null_context)
    context.update({
        "qwp_readout_deg": float(qwp_readout_deg),
        "qwp_readout_actual_deg": float(qwp_readout_actual_deg),
        "qwp_readout_error_deg": float(qwp_readout_error_deg),
        "qwp_readout_offset_from_null_deg": periodic_delta_deg(q_null, qwp_readout_deg, 180.0),
    })

    def measure_anl(a_deg: float, side: str, label: str):
        gui_update_state(phase=label, current_slope_side=side)
        return measure_lockin_point(
            pixel=pixel,
            hwp_deg=float(hwp_deg),
            q_null=float(q_null),
            a_null=float(a_null),
            p_null=float(p_null),
            p_null_mV=float(p_null_mV),
            slope_side=side,
            anl_target=float(a_deg),
            vpp=float(vpp),
            rot_anl=rot_anl,
            detector=detector,
            lockin=lockin,
            sens_idx=sens_idx,
            reference_phase_deg=reference_phase_deg,
            fast_rotator_moves=fast_rotator_moves,
            verify_moves=verify_moves,
            verify_tol_deg=verify_tol_deg,
            null_context=context,
            null_reference_row=null_reference_row,
            t_start=t_start,
        )

    a_seed_initial = wrap360(analyser_seed_deg)
    a_best = float(a_seed_initial)
    best_row, best_raw, sens_idx = measure_anl(
        a_best,
        "auto_peak",
        "Auto analyser peak seed",
    )
    n_probes = 1
    best_mag = lockin_peak_metric_value(best_row)
    expanded = False

    for step in AUTO_READOUT_PEAK_STEPS_DEG:
        step = float(step)
        for _iter in range(AUTO_READOUT_PEAK_MAX_ITER_PER_STEP):
            candidates = [
                (a_best - step, f"A-{step:g}"),
                (a_best + step, f"A+{step:g}"),
            ]
            improved = False
            for a_try, label in candidates:
                row, raw, sens_idx = measure_anl(
                    wrap360(a_try),
                    "auto_peak_probe",
                    f"Auto analyser peak probe {label}",
                )
                n_probes += 1
                mag = lockin_peak_metric_value(row)
                if (
                    np.isfinite(mag)
                    and (
                        not np.isfinite(best_mag)
                        or (float(mag) - float(best_mag)) * 1e6
                        >= lockin_peak_improvement_threshold_uV(best_row, row)
                    )
                ):
                    best_mag = float(mag)
                    a_best = wrap360(row.get("anl_target_deg", a_try))
                    best_row = row
                    best_raw = raw
                    improved = True
                    expanded = True
            if not improved:
                break

    final_row, final_raw, sens_idx = measure_anl(
        a_best,
        "auto_peak",
        "Auto analyser peak final",
    )
    n_probes += 1
    final_mag = lockin_peak_metric_value(final_row)
    if np.isfinite(final_mag) and (
        not np.isfinite(best_mag)
        or float(final_mag) >= float(best_mag)
        or abs((float(final_mag) - float(best_mag)) * 1e6)
        <= lockin_peak_improvement_threshold_uV(best_row, final_row)
    ):
        best_row = final_row
        best_raw = final_raw
    else:
        append_row_quality(best_row, "auto_peak_final_confirm_lower")

    existing_flags = str(best_row.get("quality_flags", ""))
    best_row["anl_refine_seed_deg"] = float(a_seed_initial)
    best_row["anl_refine_shift_deg"] = periodic_delta_deg(
        float(a_seed_initial),
        float(best_row.get("anl_target_deg", a_best)),
        180.0,
    )
    best_row["quality_flags"] = ";".join(
        flag for flag in (
            existing_flags,
            f"auto_analyser_peak_search_probes={n_probes}",
            "auto_analyser_peak_search_expanded" if expanded else "",
            "qwp_locked_during_auto_analyser_peak",
        )
        if flag
    )
    best_row["slope_side"] = "auto_peak"
    for raw in best_raw:
        raw["slope_side"] = "auto_peak"
    return best_row, best_raw, sens_idx, n_probes


def args_global_angle_error_limit() -> float:
    # Kept as a function so later CLI wiring does not require touching the
    # measurement helper signature.
    return 0.5


def null_check_label(p_null_mV: float, max_mV: float) -> tuple[str, str]:
    if not np.isfinite(p_null_mV):
        return "NULL?", "null_check_nan"
    if float(p_null_mV) > float(max_mV):
        return "NULL HIGH", "high_seed_null"
    return "NULL OK", ""


def classify_null_certification(
    p_null_mV: float,
    max_mV: float,
    margin_mV: float,
) -> tuple[str, str, bool]:
    """Classify a null as accepted, marginal, or a hard failure.

    ``max_mV`` is the desired null target.  The non-negative margin is an
    explicit certification/noise band: values within it remain measurable but
    are quality-flagged and are not saved as trusted seeds.  Only values above
    target + margin (or invalid readings/limits) are hard failures.
    """
    try:
        value = float(p_null_mV)
        target = float(max_mV)
        margin = float(margin_mV)
    except Exception:
        return "NULL?", "null_check_nan", True
    if not (np.isfinite(value) and np.isfinite(target)):
        return "NULL?", "null_check_nan", True
    if not np.isfinite(margin):
        margin = 0.0
    hard_limit = target + max(0.0, margin)
    if value <= target:
        return "NULL OK", "", False
    if value <= hard_limit:
        return "NULL MARGINAL", "marginal_seed_null", False
    return "NULL HIGH", "high_seed_null", True


def fit_best_hwp_cos4(rows: list[dict]) -> dict | None:
    """v2: sub-grid HWP peak by fitting A + B*cos(4*HWP) + C*sin(4*HWP).

    The Senarmont readout metric varies sinusoidally with the incident
    polarisation (90 deg period in HWP angle), so a linear least-squares fit
    over the measured HWP grid gives an analytic peak angle instead of the
    grid argmax, plus an R^2 model check. Uses the per-HWP maximum
    net-else-raw magnitude across sides/voltages; needs >= 5 distinct HWP
    angles, otherwise returns None.
    """
    by_hwp: dict[float, float] = {}
    for row in rows:
        if row_has_untrusted_null(row):
            continue
        side = str(row.get("slope_side", ""))
        if side in ("zero", "learned_zero", "manual_peak"):
            continue
        try:
            hwp = float(row.get("hwp_deg"))
        except (TypeError, ValueError):
            continue
        metric = lockin_response_value(row, "lockin_net_mag_V", "lockin_mag_V")
        if not np.isfinite(metric):
            continue
        key = round(hwp, 3)
        by_hwp[key] = max(by_hwp.get(key, 0.0), abs(float(metric)))
    if len(by_hwp) < 5:
        return None
    hwp = np.array(sorted(by_hwp))
    mag = np.array([by_hwp[h] for h in hwp])
    phi = np.radians(4.0 * hwp)
    design = np.column_stack([np.ones_like(phi), np.cos(phi), np.sin(phi)])
    try:
        coef, *_ = np.linalg.lstsq(design, mag, rcond=None)
    except Exception:
        return None
    a0, b, c = (float(v) for v in coef)
    amp = math.hypot(b, c)
    model = design @ coef
    ss_res = float(np.sum((mag - model) ** 2))
    ss_tot = float(np.sum((mag - mag.mean()) ** 2))
    r2 = 1.0 - ss_res / ss_tot if ss_tot > 0 else float("nan")
    peak_hwp = (math.degrees(math.atan2(c, b)) / 4.0) % 90.0
    # prefer the 90-deg alias inside (or nearest) the measured span
    lo, hi = float(hwp.min()), float(hwp.max())
    candidates = [peak_hwp + 90.0 * k for k in range(-4, 5)]
    inside = [cand for cand in candidates if lo - 5.0 <= cand <= hi + 5.0]
    if inside:
        peak_hwp = min(inside, key=lambda cand: abs(cand - 0.5 * (lo + hi)))
    return {
        "peak_hwp_deg": float(peak_hwp),
        "peak_theta_i_deg": float(theta_i_from_hwp(peak_hwp)),
        "amplitude_V": amp,
        "offset_V": a0,
        "r_squared": r2,
        "n_hwp_points": int(len(by_hwp)),
        "model": "A + B*cos(4*HWP) + C*sin(4*HWP), 90 deg period",
    }


def certified_peak_row_from_analysis(
    rows: list[dict],
    measurement_analysis: dict,
) -> dict | None:
    """Return a measured motor row at the normalized, geometry-certified HWP."""
    certificate = measurement_analysis.get("peak_certificate") or {}
    if str(certificate.get("status", "")) != "certified":
        return None
    target_hwp = _finite_float_or_none(certificate.get("hwp_deg"))
    if target_hwp is None:
        return None
    allowed_sides = {
        "plus45",
        "minus45",
        "auto_peak",
        "manual_anchor",
        "learned_anchor",
        "learned_opposite",
    }
    candidates: list[tuple[float, float, float, float, float, float, dict]] = []
    for row in rows:
        if str(row.get("slope_side", "")) not in allowed_sides:
            continue
        hwp = _finite_float_or_none(row.get("hwp_deg"))
        if hwp is None or abs(float(hwp) - float(target_hwp)) > 1e-6:
            continue
        if row_has_untrusted_null(row) or row_has_angle_failure(row) or row_has_quality_flag(
            row, "peak_diagnostic_failed", "peak_diagnostic_incomplete"
        ):
            continue
        q_null = _finite_float_or_none(row.get("q_null_deg"))
        q_readout = _first_finite_followup_value(
            row.get("qwp_readout_deg"), q_null
        )
        q_readout_geometry = _first_finite_followup_value(
            row.get("qwp_readout_actual_deg"),
            row.get("qwp_actual_deg"),
            q_readout,
        )
        a_null = _finite_float_or_none(row.get("a_null_deg"))
        a_null_geometry = _first_finite_followup_value(
            row.get("anl_null_actual_deg"), a_null
        )
        a_target = _first_finite_followup_value(
            row.get("anl_actual_deg"), row.get("anl_target_deg")
        )
        if None in (
            q_null, q_readout, q_readout_geometry,
            a_null, a_null_geometry, a_target,
        ):
            continue
        q_error = abs(periodic_delta_deg(
            float(q_null), float(q_readout_geometry), 180.0
        ))
        beta = analyser_offset_from_null_deg(
            float(a_null_geometry), float(a_target)
        )
        quadrature_error = abs(abs(float(beta)) - 45.0)
        if q_error > float(MAX_QWP_OFFSET_FROM_NULL_DEG):
            continue
        if quadrature_error > float(MAX_ANALYSER_QUADRATURE_ERROR_DEG):
            continue
        metric = lockin_peak_metric_value(row)
        if not np.isfinite(metric):
            metric = 0.0
        # The confirmed DC-half-fringe row wins.  For production triplets use
        # the fixed positive branch, avoiding winner-selection bias from a
        # noisy comparison of the two nominally equivalent AC magnitudes.
        s9_preference = 0.0 if (
            str(row.get("s9_status", "")) == "certified_fit"
            and str(row.get("peak_source", ""))
            == "s9_dc_quadrature_operating_point"
        ) else 1.0
        side = str(row.get("slope_side", ""))
        side_preference = {
            "auto_peak": 0.0,
            "plus45": 1.0,
            "learned_anchor": 1.0,
            "manual_anchor": 1.0,
            "minus45": 2.0,
            "learned_opposite": 2.0,
        }.get(side, 3.0)
        operating_psi = _finite_float_or_none(row.get("s9_operating_psi_deg"))
        row_psi = analyser_offset_from_null_deg(
            float(a_null_geometry), float(a_target)
        )
        operating_error = (
            abs(periodic_delta_deg(float(operating_psi), float(row_psi), 180.0))
            if operating_psi is not None
            else quadrature_error
        )
        candidates.append(
            (
                s9_preference,
                side_preference,
                operating_error,
                quadrature_error,
                q_error,
                -abs(float(metric)),
                row,
            )
        )
    if not candidates:
        return None
    return min(candidates, key=lambda item: item[:6])[6]


def summarize_fast_map(pixel: dict, rows: list[dict], voltages: list[float]) -> dict:
    quality_flags: set[str] = set()
    manual_peak_rows = [
        row for row in rows
        if str(row.get("slope_side", "")) == "manual_peak"
    ]
    manual_anchor_rows = [
        row for row in rows
        if str(row.get("slope_side", "")) in (
            "manual_anchor",
            "auto_peak",
            "learned_anchor",
            "learned_opposite",
        )
        and not row_has_quality_flag(row, "peak_diagnostic_failed", "peak_diagnostic_incomplete")
        and not row_has_untrusted_null(row)
        and not row_has_angle_failure(row)
    ]
    manual_raw_rows = manual_peak_rows + manual_anchor_rows
    all_response_rows = [
        row for row in rows
        if str(row.get("slope_side", "")) in ("plus45", "minus45")
    ]
    response_rows = [
        row for row in all_response_rows
        if not row_has_untrusted_null(row) and not row_has_angle_failure(row)
    ]
    all_normalized_slope_rows = [
        row for row in rows
        if str(row.get("slope_side", "")) in (
            "plus45",
            "minus45",
            "learned_anchor",
            "learned_opposite",
        )
    ]
    trusted_normalized_slope_rows = [
        row for row in all_normalized_slope_rows
        if not row_has_untrusted_null(row) and not row_has_angle_failure(row)
    ]
    selection_rows = response_rows + manual_anchor_rows
    if not selection_rows:
        selection_rows = manual_raw_rows
    if manual_anchor_rows:
        quality_flags.add("manual_anchor_included_in_peak_selection")
    if manual_peak_rows and response_rows:
        quality_flags.add("manual_peak_scout_excluded_from_auto_peak")
    for row in rows:
        for flag in str(row.get("quality_flags", "")).split(";"):
            if flag:
                quality_flags.add(flag)
        p_null = float(row.get("p_null_W", float("nan")))
        if np.isfinite(p_null) and p_null > 2.0e-5:
            quality_flags.add("high_null_leakage")
        power_w = float(row.get("power_W", float("nan")))
        if np.isfinite(power_w) and power_w <= 0.0:
            quality_flags.add("low_or_negative_power")

    best_pair = None
    grouped: dict[tuple[float, float], dict[str, dict]] = {}
    for row in response_rows:
        key = (float(row["hwp_deg"]), float(row["vpp"]))
        grouped.setdefault(key, {})[str(row["slope_side"])] = row

    pair_rows = []
    for (hwp_deg, vpp), sides in grouped.items():
        plus = sides.get("plus45")
        minus = sides.get("minus45")
        if not plus or not minus:
            continue
        plus_v = lockin_response_value(plus, "lockin_net_signed_V", "lockin_signed_V")
        minus_v = lockin_response_value(minus, "lockin_net_signed_V", "lockin_signed_V")
        if np.isfinite(plus_v) and np.isfinite(minus_v):
            plus_phasor = lockin_response_phasor(plus)
            minus_phasor = lockin_response_phasor(minus)
            plus_abs = abs(plus_phasor) if plus_phasor is not None else abs(float(plus_v))
            minus_abs = abs(minus_phasor) if minus_phasor is not None else abs(float(minus_v))
            denom = max(plus_abs, minus_abs)
            pair_asymmetry = (
                abs(plus_abs - minus_abs) / denom
                if denom > 0.0
                else float("nan")
            )
            pair_response = 0.5 * (plus_v - minus_v)
            pair_phasor = (
                0.5 * (plus_phasor - minus_phasor)
                if plus_phasor is not None and minus_phasor is not None
                else complex(pair_response, 0.0)
            )
            pair_rows.append({
                "hwp_deg": hwp_deg,
                "theta_i_deg": theta_i_from_hwp(hwp_deg),
                "theta_i_legacy_deg": legacy_theta_i_from_hwp(hwp_deg),
                "vpp": vpp,
                "plus_signed_V": plus_v,
                "minus_signed_V": minus_v,
                "pair_response_V": pair_response,
                "pair_response_mag_V": abs(pair_phasor),
                "pair_response_phase_deg": math.degrees(math.atan2(pair_phasor.imag, pair_phasor.real)),
                "pair_abs_response_V": abs(pair_phasor),
                "pair_asymmetry_fraction": pair_asymmetry,
                "plus_row": plus,
                "minus_row": minus,
            })
            if plus_v * minus_v > 0:
                quality_flags.add("plus_minus_same_sign")
            if np.isfinite(pair_asymmetry) and pair_asymmetry > PAIR_ASYMMETRY_WARN_FRACTION:
                quality_flags.add("plus_minus_asymmetric")
            if best_pair is None or abs(pair_phasor) > best_pair["pair_abs_response_V"]:
                best_pair = pair_rows[-1]

    finite_signed_rows = [
        row for row in selection_rows
        if np.isfinite(lockin_response_value(row, "lockin_net_signed_V", "lockin_signed_V"))
    ]
    finite_mag_rows = [
        row for row in selection_rows
        if np.isfinite(lockin_peak_metric_value(row))
    ]
    finite_manual_peak_rows = [
        row for row in manual_raw_rows
        if np.isfinite(lockin_peak_metric_value(row))
    ]
    best_row = (
        max(finite_signed_rows, key=lambda r: abs(lockin_response_value(r, "lockin_net_signed_V", "lockin_signed_V")))
        if finite_signed_rows
        else None
    )
    best_mag_row = (
        max(finite_mag_rows, key=lockin_peak_metric_value)
        if finite_mag_rows
        else None
    )
    best_manual_peak_row = (
        max(finite_manual_peak_rows, key=lockin_peak_metric_value)
        if finite_manual_peak_rows
        else None
    )

    max_signed = lockin_response_value(best_row, "lockin_net_signed_V", "lockin_signed_V") if best_row else float("nan")
    max_abs = abs(max_signed) if best_row else float("nan")
    max_mag = lockin_peak_metric_value(best_mag_row) if best_mag_row else float("nan")
    best_vpp = float(best_row["vpp"]) if best_row else float("nan")
    pair_response = float(best_pair["pair_response_V"]) if best_pair else float("nan")
    pair_response_mag = float(best_pair["pair_response_mag_V"]) if best_pair else float("nan")
    pair_response_phase = float(best_pair["pair_response_phase_deg"]) if best_pair else float("nan")
    pair_vpp = float(best_pair["vpp"]) if best_pair else float("nan")
    delta_proxy = (
        pair_response_mag / pair_vpp
        if np.isfinite(pair_response_mag) and np.isfinite(pair_vpp) and pair_vpp != 0.0
        else float("nan")
    )
    trusted_analysis_rows = [
        row for row in rows
        if not row_has_untrusted_null(row) and not row_has_angle_failure(row)
    ]
    measurement_analysis = analyse_fast_map_rows(trusted_analysis_rows, BTO_PHYSICS_CONFIG)
    best_rotation_fit = measurement_analysis.get("best_rotation_fit") or {}
    angular_response_fit = measurement_analysis.get("angular_response_fit") or {}
    peak_certificate = dict(measurement_analysis.get("peak_certificate") or {})
    certified_peak_row = certified_peak_row_from_analysis(rows, measurement_analysis)
    if certified_peak_row is not None:
        best_row = certified_peak_row
        best_vpp = float(best_row.get("vpp", best_vpp))
        best_power_w = _finite_float_or_none(best_row.get("power_W"))
        best_detector_v = _finite_float_or_none(best_row.get("detector_V"))
        null_detector_v = _finite_float_or_none(
            best_row.get("detector_null_reference_V")
        )
        null_power_w = _finite_float_or_none(best_row.get("p_null_W"))
        if (
            best_power_w is not None
            and best_detector_v is not None
            and null_detector_v is not None
            and abs(float(best_detector_v)) > 1e-15
        ):
            null_power_w = (
                float(best_power_w)
                * float(null_detector_v)
                / float(best_detector_v)
            )
        bright_power_w = None
        if best_power_w is not None and null_power_w is not None:
            bright_power_w = (
                float(null_power_w)
                + 2.0 * (float(best_power_w) - float(null_power_w))
            )
        eo_lockin_reference_phase_deg = _first_finite_followup_value(
            best_row.get("lockin_net_phase_deg"),
            best_row.get("lockin_phase_deg"),
        )
        peak_certificate.update({
            "slope_side": str(best_row.get("slope_side", "")),
            "q_null_deg": _finite_float_or_none(best_row.get("q_null_deg")),
            "qwp_readout_deg": _first_finite_followup_value(
                best_row.get("qwp_readout_deg"), best_row.get("q_null_deg")
            ),
            "a_null_deg": _finite_float_or_none(best_row.get("a_null_deg")),
            "anl_target_deg": _first_finite_followup_value(
                best_row.get("anl_actual_deg"), best_row.get("anl_target_deg")
            ),
            "vpp": _finite_float_or_none(best_row.get("vpp")),
            "lockin_metric_V": _finite_float_or_none(lockin_peak_metric_value(best_row)),
            "s9_status": str(best_row.get("s9_status", "")),
            "s9_method": str(best_row.get("s9_method", "")),
            "s9_reason": str(best_row.get("s9_reason", "")),
            "s9_complex_r_squared": _finite_float_or_none(
                best_row.get("s9_complex_r_squared")
            ),
            "s9_dc_r_squared": _finite_float_or_none(
                best_row.get("s9_dc_r_squared")
            ),
            "s9_midfringe_fraction": _finite_float_or_none(
                best_row.get("s9_midfringe_fraction")
            ),
            "s9_peak_shift_deg": _finite_float_or_none(
                best_row.get("s9_peak_shift_deg")
            ),
            "s9_null_leakage_fraction": _finite_float_or_none(
                best_row.get("s9_null_leakage_fraction")
            ),
            "s9_fit_signal_to_residual": _finite_float_or_none(
                best_row.get("s9_fit_signal_to_residual")
            ),
            "s9_derivative_residual_fraction": _finite_float_or_none(
                best_row.get("s9_derivative_residual_fraction")
            ),
            "s9_temporal_rank_fraction": _finite_float_or_none(
                best_row.get("s9_temporal_rank_fraction")
            ),
            "s9_analyser_independent_fraction": _finite_float_or_none(
                best_row.get("s9_analyser_independent_fraction")
            ),
            "s9_operating_psi_deg": _finite_float_or_none(
                best_row.get("s9_operating_psi_deg")
            ),
            "eo_lockin_reference_phase_deg": eo_lockin_reference_phase_deg,
            "rotation_reference_phase_deg": _finite_float_or_none(
                best_rotation_fit.get("rotation_slope_phase_deg")
            ),
            "dc_fringe_null_power_W": null_power_w,
            "dc_fringe_quadrature_power_W": best_power_w,
            "dc_fringe_bright_power_W": bright_power_w,
        })
    elif str(peak_certificate.get("status", "")) == "certified":
        peak_certificate["status"] = "invalid"
        peak_certificate.setdefault("quality_flags", []).append(
            "normalized_hwp_has_no_certified_motor_row"
        )
        quality_flags.add("normalized_hwp_has_no_certified_motor_row")
    effective_pockels = measurement_analysis.get("effective_pockels") or {}
    if effective_pockels.get("reason") == "voltage_response_failed_linearity_check":
        quality_flags.add("bto_voltage_response_nonlinear")
    if effective_pockels.get("reason") == "null_leakage_exceeds_five_percent":
        quality_flags.add("bto_null_leakage_too_high")
    if effective_pockels.get("reason") == "qwp_retardance_outside_senarmont_tolerance":
        quality_flags.add("bto_qwp_retardance_invalid")
    if effective_pockels.get("status") == "calculated_linearity_unverified":
        quality_flags.add("bto_linearity_unverified")

    summary = {
        "pixel": int(pixel["pixel"]),
        "row": int(pixel.get("j", 0)),
        "col": int(pixel.get("i", 0)),
        "best_hwp_deg": float(best_row["hwp_deg"]) if best_row else None,
        "best_theta_i_deg": float(best_row.get("theta_i_deg", theta_i_from_hwp(best_row["hwp_deg"]))) if best_row else None,
        "best_theta_i_legacy_deg": float(best_row.get("theta_i_legacy_deg", legacy_theta_i_from_hwp(best_row["hwp_deg"]))) if best_row else None,
        "best_slope_side": str(best_row["slope_side"]) if best_row else None,
        "best_anl_deg": float(best_row["anl_target_deg"]) if best_row else None,
        "best_anl_lab_deg": float(best_row.get("anl_target_lab_deg", analyser_lab_from_raw(best_row["anl_target_deg"]))) if best_row else None,
        "best_anl_theta_ana_deg": float(best_row.get("anl_target_theta_ana_deg", analyser_theta_ana_from_raw(best_row["anl_target_deg"], best_row["hwp_deg"]))) if best_row else None,
        "best_qwp_deg": float(best_row["q_null_deg"]) if best_row else None,
        "best_qwp_axis_lab_deg": float(best_row.get("qwp_axis_lab_deg", qwp_axis_lab_from_raw(best_row["q_null_deg"]))) if best_row else None,
        "best_qwp_theta_wav_deg": float(best_row.get("qwp_theta_wav_deg", qwp_theta_wav_from_raw(best_row["q_null_deg"], best_row["hwp_deg"]))) if best_row else None,
        "best_qwp_readout_deg": float(best_row.get("qwp_readout_deg", best_row["q_null_deg"])) if best_row else None,
        "best_qwp_readout_axis_lab_deg": float(best_row.get("qwp_readout_axis_lab_deg", qwp_axis_lab_from_raw(best_row.get("qwp_readout_deg", best_row["q_null_deg"])))) if best_row else None,
        "best_qwp_readout_theta_wav_deg": float(best_row.get("qwp_readout_theta_wav_deg", qwp_theta_wav_from_raw(best_row.get("qwp_readout_deg", best_row["q_null_deg"]), best_row["hwp_deg"]))) if best_row else None,
        "best_a_null_deg": float(best_row["a_null_deg"]) if best_row else None,
        "best_a_null_lab_deg": float(best_row.get("a_null_lab_deg", analyser_lab_from_raw(best_row["a_null_deg"]))) if best_row else None,
        "best_a_null_theta_ana_deg": float(best_row.get("a_null_theta_ana_deg", analyser_theta_ana_from_raw(best_row["a_null_deg"], best_row["hwp_deg"]))) if best_row else None,
        "best_vpp": best_vpp if best_row else None,
        "max_abs_signed_response_V": max_abs,
        "max_signed_response_V": max_signed if best_row else None,
        "max_lockin_mag_V": max_mag if best_mag_row else None,
        "best_mag_hwp_deg": float(best_mag_row["hwp_deg"]) if best_mag_row else None,
        "best_mag_theta_i_deg": float(best_mag_row.get("theta_i_deg", theta_i_from_hwp(best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_theta_i_legacy_deg": float(best_mag_row.get("theta_i_legacy_deg", legacy_theta_i_from_hwp(best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_slope_side": str(best_mag_row["slope_side"]) if best_mag_row else None,
        "best_mag_anl_deg": float(best_mag_row["anl_target_deg"]) if best_mag_row else None,
        "best_mag_anl_lab_deg": float(best_mag_row.get("anl_target_lab_deg", analyser_lab_from_raw(best_mag_row["anl_target_deg"]))) if best_mag_row else None,
        "best_mag_anl_theta_ana_deg": float(best_mag_row.get("anl_target_theta_ana_deg", analyser_theta_ana_from_raw(best_mag_row["anl_target_deg"], best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_qwp_deg": float(best_mag_row["q_null_deg"]) if best_mag_row else None,
        "best_mag_qwp_axis_lab_deg": float(best_mag_row.get("qwp_axis_lab_deg", qwp_axis_lab_from_raw(best_mag_row["q_null_deg"]))) if best_mag_row else None,
        "best_mag_qwp_theta_wav_deg": float(best_mag_row.get("qwp_theta_wav_deg", qwp_theta_wav_from_raw(best_mag_row["q_null_deg"], best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_qwp_readout_deg": float(best_mag_row.get("qwp_readout_deg", best_mag_row["q_null_deg"])) if best_mag_row else None,
        "best_mag_qwp_readout_axis_lab_deg": float(best_mag_row.get("qwp_readout_axis_lab_deg", qwp_axis_lab_from_raw(best_mag_row.get("qwp_readout_deg", best_mag_row["q_null_deg"])))) if best_mag_row else None,
        "best_mag_qwp_readout_theta_wav_deg": float(best_mag_row.get("qwp_readout_theta_wav_deg", qwp_theta_wav_from_raw(best_mag_row.get("qwp_readout_deg", best_mag_row["q_null_deg"]), best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_a_null_deg": float(best_mag_row["a_null_deg"]) if best_mag_row else None,
        "best_mag_a_null_lab_deg": float(best_mag_row.get("a_null_lab_deg", analyser_lab_from_raw(best_mag_row["a_null_deg"]))) if best_mag_row else None,
        "best_mag_a_null_theta_ana_deg": float(best_mag_row.get("a_null_theta_ana_deg", analyser_theta_ana_from_raw(best_mag_row["a_null_deg"], best_mag_row["hwp_deg"]))) if best_mag_row else None,
        "best_mag_vpp": float(best_mag_row["vpp"]) if best_mag_row else None,
        "best_hwp_fit": fit_best_hwp_cos4(rows),
        "angular_response_fit": angular_response_fit or None,
        "normalized_peak_certificate": peak_certificate,
        "peak_selection_mode": measurement_analysis.get("peak_selection_mode"),
        "manual_peak_raw_mag_V": lockin_raw_response_value(best_manual_peak_row, "lockin_mag_V", "lockin_net_mag_V") if best_manual_peak_row else None,
        "manual_peak_raw_hwp_deg": float(best_manual_peak_row["hwp_deg"]) if best_manual_peak_row else None,
        "manual_peak_raw_qwp_deg": float(best_manual_peak_row["q_null_deg"]) if best_manual_peak_row else None,
        "manual_peak_raw_anl_deg": float(best_manual_peak_row["anl_target_deg"]) if best_manual_peak_row else None,
        "manual_peak_raw_vpp": float(best_manual_peak_row["vpp"]) if best_manual_peak_row else None,
        "pair_response_V": pair_response,
        "pair_response_mag_V": pair_response_mag,
        "pair_response_phase_deg": pair_response_phase,
        "delta_prime_proxy_V_per_Vpp": delta_proxy,
        "pair_response_vpp": pair_vpp if best_pair else None,
        "best_rotation_hwp_deg": best_rotation_fit.get("hwp_deg"),
        "best_rotation_theta_i_deg": best_rotation_fit.get("theta_i_deg"),
        "rotation_slope_rad_per_Vrms": best_rotation_fit.get("rotation_slope_mag_rad_per_Vrms"),
        "rotation_slope_sem_rad_per_Vrms": best_rotation_fit.get("rotation_slope_mag_sem_rad_per_Vrms"),
        "rotation_phase_deg": best_rotation_fit.get("rotation_slope_phase_deg"),
        "eo_lockin_reference_phase_deg": peak_certificate.get(
            "eo_lockin_reference_phase_deg"
        ),
        "dc_fringe_null_power_W": peak_certificate.get(
            "dc_fringe_null_power_W"
        ),
        "dc_fringe_quadrature_power_W": peak_certificate.get(
            "dc_fringe_quadrature_power_W"
        ),
        "dc_fringe_bright_power_W": peak_certificate.get(
            "dc_fringe_bright_power_W"
        ),
        "voltage_linearity_r_squared": best_rotation_fit.get("voltage_linearity_r_squared"),
        "max_null_leakage_fraction": best_rotation_fit.get("max_null_leakage_fraction"),
        "r_eff_abs_pm_per_V": effective_pockels.get("r_eff_abs_pm_per_V"),
        "r_eff_abs_sem_pm_per_V": effective_pockels.get("r_eff_abs_sem_pm_per_V"),
        "r_eff_status": effective_pockels.get("status", "not_calculated"),
        "r_eff_reason": effective_pockels.get("reason"),
        "measurement_analysis": measurement_analysis,
        "n_points": len(all_normalized_slope_rows),
        "n_trusted_points": len(trusted_normalized_slope_rows),
        "n_standard_slope_points": len(all_response_rows),
        "n_learned_slope_points": sum(
            1 for row in all_normalized_slope_rows
            if str(row.get("slope_side", "")) in (
                "learned_anchor", "learned_opposite"
            )
        ),
        "n_untrusted_null_points": sum(
            1 for row in rows if row_has_untrusted_null(row)
        ),
        "n_manual_peak_points": len(manual_peak_rows),
        "n_manual_anchor_points": len(manual_anchor_rows),
        "n_manual_raw_points": len(manual_raw_rows),
        "n_zero_reference_points": sum(
            1 for row in rows
            if str(row.get("slope_side", "")) in ("zero", "learned_zero")
        ),
        "voltages_vpp": [float(v) for v in voltages],
        "quality_flags": sorted(quality_flags),
        "pair_responses": pair_rows_for_json(pair_rows),
        "lab_angle_mapping": lab_angle_mapping_config(),
        "created": datetime.now().isoformat(),
    }
    return summary


def pair_rows_for_json(pair_rows: list[dict]) -> list[dict]:
    return [
        {
            "hwp_deg": float(row["hwp_deg"]),
            "theta_i_deg": float(row["theta_i_deg"]),
            "theta_i_legacy_deg": float(row["theta_i_legacy_deg"]),
            "vpp": float(row["vpp"]),
            "plus_signed_V": float(row["plus_signed_V"]),
            "minus_signed_V": float(row["minus_signed_V"]),
            "pair_response_V": float(row["pair_response_V"]),
            "pair_response_mag_V": float(row["pair_response_mag_V"]),
            "pair_response_phase_deg": float(row["pair_response_phase_deg"]),
            "pair_abs_response_V": float(row["pair_abs_response_V"]),
            "pair_asymmetry_fraction": float(row.get("pair_asymmetry_fraction", float("nan"))),
        }
        for row in pair_rows
    ]


def peak_from_fast_summary(summary: dict) -> dict:
    certificate = dict(summary.get("normalized_peak_certificate") or {})
    certified = str(certificate.get("status", "")) == "certified"
    peak_hwp = _first_finite_followup_value(
        certificate.get("hwp_deg") if certified else None,
        summary.get("best_hwp_deg"),
    )
    peak_theta_i = _first_finite_followup_value(
        certificate.get("theta_i_deg") if certified else None,
        summary.get("best_theta_i_deg"),
    )
    peak_theta_i_legacy = summary.get("best_theta_i_legacy_deg")
    peak_qwp_null = _first_finite_followup_value(
        certificate.get("q_null_deg") if certified else None,
        summary.get("best_qwp_deg"),
    )
    peak_qwp_readout = _first_finite_followup_value(
        certificate.get("qwp_readout_deg") if certified else None,
        summary.get("best_qwp_readout_deg"),
        peak_qwp_null,
    )
    peak_anl = _first_finite_followup_value(
        certificate.get("anl_target_deg") if certified else None,
        summary.get("best_anl_deg"),
    )
    peak_a_null = _first_finite_followup_value(
        certificate.get("a_null_deg") if certified else None,
        summary.get("best_a_null_deg"),
    )
    peak_side = (
        certificate.get("slope_side") if certified else summary.get("best_slope_side")
    )
    peak_vpp = _first_finite_followup_value(
        certificate.get("vpp") if certified else None,
        summary.get("best_vpp"),
    )
    peak_qwp_null_lab = (
        qwp_axis_lab_from_raw(peak_qwp_null) if peak_qwp_null is not None else None
    )
    peak_qwp_null_theta_wav = (
        qwp_theta_wav_from_raw(peak_qwp_null, peak_hwp)
        if peak_qwp_null is not None and peak_hwp is not None else None
    )
    peak_qwp_readout_lab = (
        qwp_axis_lab_from_raw(peak_qwp_readout) if peak_qwp_readout is not None else None
    )
    peak_qwp_readout_theta_wav = (
        qwp_theta_wav_from_raw(peak_qwp_readout, peak_hwp)
        if peak_qwp_readout is not None and peak_hwp is not None else None
    )
    peak_anl_lab = analyser_lab_from_raw(peak_anl) if peak_anl is not None else None
    peak_anl_theta_ana = (
        analyser_theta_ana_from_raw(peak_anl, peak_hwp)
        if peak_anl is not None and peak_hwp is not None else None
    )
    peak_a_null_lab = analyser_lab_from_raw(peak_a_null) if peak_a_null is not None else None
    peak_a_null_theta_ana = (
        analyser_theta_ana_from_raw(peak_a_null, peak_hwp)
        if peak_a_null is not None and peak_hwp is not None else None
    )
    return {
        "source": (
            "fast_map_normalized_senarmont_certificate"
            if certified else "fast_map_uncertified_fallback"
        ),
        "pixel": summary.get("pixel"),
        "theta_i": peak_hwp,
        "theta_i_deg": peak_theta_i,
        "theta_i_legacy_deg": peak_theta_i_legacy,
        "hwp_deg": peak_hwp,
        "qwp_angle": peak_qwp_readout,
        "qwp_axis_lab_deg": peak_qwp_readout_lab,
        "qwp_theta_wav_deg": peak_qwp_readout_theta_wav,
        "qwp_readout": peak_qwp_readout,
        "qwp_readout_axis_lab_deg": peak_qwp_readout_lab,
        "qwp_readout_theta_wav_deg": peak_qwp_readout_theta_wav,
        "q_null": peak_qwp_null,
        "q_null_axis_lab_deg": peak_qwp_null_lab,
        "q_null_theta_wav_deg": peak_qwp_null_theta_wav,
        "anl_angle": peak_anl,
        "anl_lab_deg": peak_anl_lab,
        "anl_theta_ana_deg": peak_anl_theta_ana,
        "a_null": peak_a_null,
        "a_null_lab_deg": peak_a_null_lab,
        "a_null_theta_ana_deg": peak_a_null_theta_ana,
        "slope_side": peak_side,
        "vpp": peak_vpp,
        "mag": (
            certificate.get("rotation_slope_rad_per_Vrms")
            if certified else summary.get("max_abs_signed_response_V")
        ),
        "mag_source": (
            "normalized_rotation_slope_rad_per_Vrms"
            if certified else "uncertified_signed_lockin_V"
        ),
        "normalized_peak_certified": bool(certified),
        "hysteresis_eligible": bool(certified),
        "peak_selection_mode": summary.get("peak_selection_mode"),
        "normalized_peak_certificate": certificate,
        "eo_lockin_reference_phase_deg": _first_finite_followup_value(
            certificate.get("eo_lockin_reference_phase_deg") if certified else None,
            summary.get("eo_lockin_reference_phase_deg"),
        ),
        "rotation_reference_phase_deg": _first_finite_followup_value(
            certificate.get("rotation_reference_phase_deg") if certified else None,
            summary.get("rotation_phase_deg"),
        ),
        "dc_fringe_null_power_W": _first_finite_followup_value(
            certificate.get("dc_fringe_null_power_W") if certified else None,
            summary.get("dc_fringe_null_power_W"),
        ),
        "dc_fringe_quadrature_power_W": _first_finite_followup_value(
            certificate.get("dc_fringe_quadrature_power_W") if certified else None,
            summary.get("dc_fringe_quadrature_power_W"),
        ),
        "dc_fringe_bright_power_W": _first_finite_followup_value(
            certificate.get("dc_fringe_bright_power_W") if certified else None,
            summary.get("dc_fringe_bright_power_W"),
        ),
        "signed_peak_hwp_deg": summary.get("best_hwp_deg"),
        "signed_peak_theta_i_deg": summary.get("best_theta_i_deg"),
        "signed_peak_slope_side": summary.get("best_slope_side"),
        "signed_peak_vpp": summary.get("best_vpp"),
        "max_abs_signed_response_V": summary.get("max_abs_signed_response_V"),
        "signed_response_V": summary.get("max_signed_response_V"),
        "pair_response_V": summary.get("pair_response_V"),
        "delta_prime_proxy_V_per_Vpp": summary.get("delta_prime_proxy_V_per_Vpp"),
        "quality_flags": sorted(set(
            list(summary.get("quality_flags", []) or [])
            + list(certificate.get("quality_flags", []) or [])
        )),
    }


def run_fast_map_for_pixel(
    *,
    pixel: dict,
    pixel_dir: Path,
    hwp_angles: np.ndarray,
    voltages: list[float],
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    renull_detector,
    lockin,
    funcgen,
    sens_idx: int,
    null_seed_by_hwp: dict,
    fallback_seed: tuple[float, float],
    t_start: float,
    reference_phase_deg: float,
    qwp_readout_offset_deg: float,
    renull_mode: str,
    fast_rotator_moves: bool,
    verify_fast_rotator_moves: bool,
    rotator_verify_tol_deg: float,
    null_check_max_mV: float,
    null_certify_margin_mV: float = 1.50,
    progress: dict | None = None,
    sim_state: dict | None = None,
    manual_peak_raw: dict | None = None,
    manual_peak_only: bool = False,
    auto_peak_calibration: bool = False,
    peak_readout_required: bool = False,
    auto_peak_max_coarse_probes: int = DEFAULT_AUTO_PEAK_MAX_COARSE_PROBES,
    auto_peak_track_mode: str = DEFAULT_AUTO_PEAK_TRACK_MODE,
    learned_readout_mode: str = DEFAULT_LEARNED_READOUT_MODE,
    peak_diagnostic: bool = False,
    peak_diagnostic_step_deg: float = DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG,
    peak_diagnostic_min_margin_uV: float = DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV,
) -> tuple[int, tuple[float, float], dict]:
    pixel_dir.mkdir(parents=True, exist_ok=True)
    rows: list[dict] = []
    raw_rows: list[dict] = []
    null_reference_rows: list[dict] = []
    peak_diagnostic_rows: list[dict] = []
    current_q_seed, current_a_seed = fallback_seed
    current_p_ref = 5e-6
    pix_num = int(pixel["pixel"])
    force_full_calibration_null = calibration_pixel_requires_full_null(
        auto_peak_calibration=bool(auto_peak_calibration),
        manual_peak_raw=manual_peak_raw,
        manual_peak_only=bool(manual_peak_only),
    )
    manual_anchor_hwp_points = sum(
        1 for hwp in hwp_angles
        if manual_peak_branch_available_for_hwp(hwp, manual_peak_raw)
    )
    pixel_total_points = fast_map_points_for_pixel(
        hwp_angles=hwp_angles,
        voltages=voltages,
        manual_peak_raw=manual_peak_raw,
        manual_peak_only=manual_peak_only,
        auto_peak_calibration=auto_peak_calibration,
        peak_readout_required=peak_readout_required,
        learned_readout_mode=learned_readout_mode,
        peak_diagnostic=bool(peak_diagnostic),
    )
    if progress is not None:
        progress["current_pixel"] = pix_num
        progress["pixel_points_done"] = 0
        progress["pixel_total_points"] = pixel_total_points
        gui_update_state(
            current_pixel=pix_num,
            pixel_points_done=0,
            pixel_total_points=pixel_total_points,
            chip_points_done=int(progress.get("points_done", 0)),
            chip_total_points=int(progress.get("total_points", 0)),
            phase="Starting pixel measurement",
            current_vpp=None,
            current_slope_side="",
            ac_voltage_on=False,
        )

    write_json(pixel_dir / "pixel_run_info.json", {
        "mode": "fast_map",
        "pixel": pix_num,
        "row": pixel.get("j"),
        "col": pixel.get("i"),
        "stage_calibrated_x_motor": pixel.get("calibrated_x_motor"),
        "stage_calibrated_y_motor": pixel.get("calibrated_y_motor"),
        "hwp_angles_deg": [float(v) for v in hwp_angles],
        "hwp_raw_angles_deg": [float(v) for v in hwp_angles],
        "hwp_lab_theta_i_angles_deg": [float(theta_i_from_hwp(v)) for v in hwp_angles],
        "voltages_vpp": [float(v) for v in voltages],
        "lab_angle_mapping": lab_angle_mapping_config(),
        "reference_phase_deg": float(reference_phase_deg),
        "qwp_readout_offset_deg": float(qwp_readout_offset_deg),
        "qwp_readout_policy": "move QWP to q_null + offset after AC-off null and before lock-in reads",
        "renull_mode": renull_mode,
        "calibration_pixel_full_null": bool(force_full_calibration_null),
        "calibration_null_policy": (
            "forced sample-in coarse-plus-fine 2D QWP/analyser minimisation at every HWP; "
            "high finite nulls continue with untrusted quality flags and are not saved as seeds"
            if force_full_calibration_null
            else "use requested per-HWP renull mode"
        ),
        "calibration_null_failure_policy": (
            "finite_high_measure_flagged_untrusted; "
            "invalid_or_procedure_error_fail_pixel_continue_chip; "
            "verified_angle_error_abort_chip"
        ),
        "null_check_max_mV": float(null_check_max_mV),
        "null_certify_margin_mV": float(null_certify_margin_mV),
        "manual_peak_raw": manual_peak_raw,
        "manual_peak_only": bool(manual_peak_only),
        "auto_peak_calibration": bool(auto_peak_calibration),
        "peak_readout_required": bool(peak_readout_required),
        "auto_peak_max_coarse_probes": int(auto_peak_max_coarse_probes),
        "auto_peak_track_mode": str(auto_peak_track_mode),
        "learned_readout_mode": str(learned_readout_mode),
        "s9_operating_point_policy": (
            "calibration pixel: balanced null/+45/bright/-45 complex and DC fit, "
            "joint AC/DC derivative certificate, and confirmation at the fitted DC "
            "half-fringe; later pixels: existing null/+45/-45 joint triplet with fit "
            "only when inconclusive; the AC extremum is diagnostic and is never "
            "followed; failed certificates cannot select hysteresis"
        ),
        "s9_complex_min_r_squared": float(S9_COMPLEX_MIN_R2),
        "s9_dc_malus_min_r_squared": float(S9_DC_MALUS_MIN_R2),
        "s9_max_peak_shift_deg": float(S9_MAX_DYNAMIC_PEAK_SHIFT_DEG),
        "s9_max_null_leakage_fraction": float(S9_MAX_NULL_LEAKAGE_FRACTION),
        "s9_max_midfringe_error": float(S9_MAX_MIDFRINGE_ERROR),
        "s9_acceptance_thresholds": {
            "complex_min_r_squared": float(S9_COMPLEX_MIN_R2),
            "dc_malus_min_r_squared": float(S9_DC_MALUS_MIN_R2),
            "max_dynamic_peak_shift_deg": float(S9_MAX_DYNAMIC_PEAK_SHIFT_DEG),
            "max_dc_null_shift_deg": float(S9_MAX_DC_NULL_SHIFT_DEG),
            "max_null_leakage_fraction": float(S9_MAX_NULL_LEAKAGE_FRACTION),
            "max_midfringe_error": float(S9_MAX_MIDFRINGE_ERROR),
            "max_confirmation_error_fraction": float(S9_MAX_CONFIRM_ERROR_FRACTION),
            "max_derivative_residual_fraction": float(
                S9_MAX_DERIVATIVE_RESIDUAL_FRACTION
            ),
            "max_temporal_rank_fraction": float(
                S9_MAX_TEMPORAL_RANK_FRACTION
            ),
            "quick_max_analyser_quadrature_error_deg": float(
                S9_QUICK_MAX_ANALYSER_QUADRATURE_ERROR_DEG
            ),
            "quick_min_phase_flip_score": float(S9_QUICK_MIN_PHASE_FLIP_SCORE),
            "quick_min_side_symmetry_ratio": float(S9_QUICK_MIN_SIDE_SYMMETRY_RATIO),
            "quick_max_dc_balance_error": float(S9_QUICK_MAX_DC_BALANCE_ERROR),
            "lockin_fullscale_warn_fraction": float(LOCKIN_FULLSCALE_WARN_FRACTION),
            "lockin_fullscale_fail_fraction": float(LOCKIN_FULLSCALE_FAIL_FRACTION),
        },
        "peak_diagnostic": bool(peak_diagnostic),
        "peak_diagnostic_step_deg": float(peak_diagnostic_step_deg),
        "peak_diagnostic_min_margin_uV": float(peak_diagnostic_min_margin_uV),
        "peak_diagnostic_probe_count": int(PEAK_DIAGNOSTIC_PROBE_COUNT),
        "manual_peak_branch_hwp_window_deg": MANUAL_PEAK_BRANCH_HWP_WINDOW_DEG,
        "manual_anchor_hwp_points": int(manual_anchor_hwp_points),
        "manual_anchor_policy": "measure predicted manual raw-peak branch at each covered HWP/Vpp; use it as a null seed only if the detector confirms it is dark",
        "verify_fast_rotator_moves": bool(verify_fast_rotator_moves),
        "rotator_verify_tol_deg": float(rotator_verify_tol_deg),
        "started": datetime.now().isoformat(),
    })

    if manual_peak_raw:
        pockels._funcgen_set_sweep_output(
            funcgen,
            True,
            verify_command=True,
            required=True,
            context=f"pixel {pix_num:03d} manual-peak acquisition",
        )
        hwp_peak = float(manual_peak_raw["hwp_deg"])
        qwp_peak = float(manual_peak_raw["qwp_deg"])
        anl_peak = float(manual_peak_raw["anl_deg"])
        for vpp in voltages:
            gui_pixel_checkpoint()
            pockels.funcgen_set_voltage(funcgen, float(vpp))
            gui_sleep(pockels.FUNCGEN_SETTLE_S, allow_skip=True)
            row, raw, sens_idx = measure_manual_peak_point(
                pixel=pixel,
                hwp_deg=hwp_peak,
                qwp_deg=qwp_peak,
                anl_deg=anl_peak,
                vpp=float(vpp),
                rot_hwp=rot_hwp,
                rot_qwp=rot_qwp,
                rot_anl=rot_anl,
                detector=detector,
                lockin=lockin,
                sens_idx=sens_idx,
                reference_phase_deg=reference_phase_deg,
                fast_rotator_moves=fast_rotator_moves,
                verify_moves=verify_fast_rotator_moves,
                verify_tol_deg=rotator_verify_tol_deg,
                t_start=t_start,
            )
            rows.append(row)
            raw_rows.extend(raw)
            if progress is not None:
                progress["points_done"] = int(progress.get("points_done", 0)) + 1
                progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_points_done=int(progress.get("pixel_points_done", 0)),
                    pixel_total_points=pixel_total_points,
                    chip_points_done=int(progress.get("points_done", 0)),
                    chip_total_points=int(progress.get("total_points", 0)),
                    phase="Manual raw peak acquired",
                )
            print(
                f"\nP{pix_num:03d} manual raw peak HWP={hwp_peak:.4f}, "
                f"QWP={qwp_peak:.4f}, ANL={anl_peak:.4f}, {float(vpp):g} Vpp"
                f" | raw MAG={float(row['lockin_mag_V']) * 1e6:.3f} uV"
            )
        if manual_peak_only:
            summary = summarize_fast_map(pixel, rows, voltages)
            peak = peak_from_fast_summary(summary)
            write_rows(pixel_dir / FAST_MAP_CSV, rows, FAST_MAP_FIELDS)
            write_rows(pixel_dir / FAST_MAP_RAW_CSV, raw_rows, RAW_FIELDS)
            write_rows(pixel_dir / FAST_MAP_NULL_REF_CSV, null_reference_rows, FAST_MAP_FIELDS)
            write_rows(pixel_dir / FAST_MAP_PEAK_DIAGNOSTIC_CSV, peak_diagnostic_rows, PEAK_DIAGNOSTIC_FIELDS)
            write_json(pixel_dir / FAST_MAP_SUMMARY_JSON, summary)
            write_json(pixel_dir / PEAK_RESPONSE_JSON, peak)
            return sens_idx, (current_q_seed, current_a_seed), peak

    auto_peak_previous: dict | None = None
    for i_hwp, hwp_deg in enumerate(hwp_angles, start=1):
        gui_pixel_checkpoint()
        if progress is not None:
            gui_update_state(
                current_pixel=pix_num,
                current_hwp_index=i_hwp,
                current_hwp_total=len(hwp_angles),
                current_hwp_deg=float(hwp_deg),
                current_hwp_null_deg=float(hwp_deg),
                phase="Nulling HWP point",
                chip_points_done=int(progress.get("points_done", 0)),
                chip_total_points=int(progress.get("total_points", 0)),
                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                current_vpp=None,
                current_slope_side="",
                ac_voltage_on=False,
            )
        hwp_key = f"{float(hwp_deg):.3f}"
        readout_override = None
        if hwp_key in null_seed_by_hwp:
            seed = null_seed_by_hwp[hwp_key]
            current_q_seed = float(seed["q_null_deg"])
            current_a_seed = float(seed["a_null_deg"])
            override = seed.get("readout_override")
            if isinstance(override, dict):
                try:
                    q_override = float(override.get("qwp_readout_deg", float("nan")))
                    a_override = float(override.get("anl_target_deg", float("nan")))
                    if np.isfinite(q_override) and np.isfinite(a_override):
                        readout_override = dict(override)
                except Exception:
                    readout_override = None
            try:
                current_p_ref = float(seed.get("p_null_W", current_p_ref))
            except Exception:
                current_p_ref = 5e-6
            if not np.isfinite(current_p_ref) or current_p_ref <= 0.0:
                current_p_ref = 5e-6

        print(
            f"  HWP {i_hwp:02d}/{len(hwp_angles):02d} raw {float(hwp_deg):6.3f} deg"
            f" / theta_i {theta_i_from_hwp(hwp_deg):6.2f} deg lab",
            end="",
            flush=True,
        )
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_hwp_target_deg=float(hwp_deg),
            current_hwp_null_deg=float(hwp_deg),
            active_optic="HWP",
            phase="Moving HWP",
            ac_voltage_on=False,
        )
        hwp_move = fast_rotator_move_or_fallback(
            rot_hwp,
            float(hwp_deg),
            fast=fast_rotator_moves,
            verify=verify_fast_rotator_moves,
            tol_deg=rotator_verify_tol_deg,
            label="HWP",
        )
        require_verified_move(hwp_move, "HWP")
        gui_pixel_checkpoint()
        current_hwp_actual = gui_angle_from_move(hwp_move, float(hwp_deg))
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_hwp_deg=float(current_hwp_actual),
            current_hwp_target_deg=float(hwp_deg),
            current_hwp_null_deg=float(current_hwp_actual),
            active_optic="QWP/ANL",
            phase="Preparing optical null",
        )
        gui_sleep(0.2, allow_skip=True)

        pockels._funcgen_set_sweep_output(
            funcgen,
            False,
            verify_command=True,
            required=True,
            context=(
                f"pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                "pre-null interlock"
            ),
        )
        null_detector = renull_detector if renull_detector is not None else detector
        prepare_null_scope_scale(null_detector)
        log_rows = []
        t_null = time.time()
        null_method = "seed"
        null_evals = 0
        null_escalated = False
        seed_q_null = float(current_q_seed)
        seed_a_null = float(current_a_seed)
        seed_p_null = float(current_p_ref)
        seed_p_null_mV = float("nan")
        null_mV_before_renull = float("nan")
        null_mV_after_renull = float("nan")
        q_move = {"actual_deg": float("nan"), "error_deg": float("nan"), "ok": True}
        a_move = {"actual_deg": float("nan"), "error_deg": float("nan"), "ok": True}
        null_quality_flags: list[str] = []
        append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(hwp_move.get("ok", True)), "hwp_angle_verify_failed")
        manual_branch_active = False
        manual_branch_seed = manual_peak_branch_seed_for_hwp(
            float(hwp_deg),
            manual_peak_raw,
            seed_q_null,
            seed_a_null,
            qwp_readout_offset_deg=qwp_readout_offset_deg,
        )
        if manual_branch_seed is not None:
            branch_q_seed = float(manual_branch_seed["q_seed_deg"])
            branch_a_candidates = [
                float(v) for v in manual_branch_seed.get("a_null_candidates_deg", [])
            ]
            branch_best: dict | None = None
            append_quality(null_quality_flags, True, "manual_peak_branch_seed")
            print(
                f" | manual-peak branch dH={float(manual_branch_seed['hwp_delta_deg']):+.3f}",
                end="",
                flush=True,
            )
            for branch_i, branch_a_seed in enumerate(branch_a_candidates, start=1):
                try:
                    gui_update_state(
                        current_pixel=pix_num,
                        current_hwp_index=i_hwp,
                        current_hwp_total=len(hwp_angles),
                        current_hwp_deg=float(current_hwp_actual),
                        current_hwp_null_deg=float(current_hwp_actual),
                        current_qwp_target_deg=wrap360(branch_q_seed),
                        current_anl_target_deg=wrap360(branch_a_seed),
                        current_qwp_null_deg=wrap360(branch_q_seed),
                        current_anl_null_deg=wrap360(branch_a_seed),
                        active_optic="QWP/ANL",
                        phase=f"Manual peak null branch probe {branch_i}/{len(branch_a_candidates)}",
                    )
                    q_probe_move, a_probe_move = fast_move_to_null_seed(
                        rot_qwp,
                        rot_anl,
                        branch_q_seed,
                        branch_a_seed,
                        fast_rotator_moves=fast_rotator_moves,
                        verify_moves=verify_fast_rotator_moves,
                        verify_tol_deg=rotator_verify_tol_deg,
                    )
                    gui_pixel_checkpoint()
                    p_probe, p_probe_mV = read_null_check(detector, null_detector)
                    q_probe_actual = gui_angle_from_move(q_probe_move, branch_q_seed)
                    a_probe_actual = gui_angle_from_move(a_probe_move, branch_a_seed)
                    if np.isfinite(p_probe_mV):
                        score = abs(float(p_probe_mV))
                    elif np.isfinite(p_probe):
                        score = abs(float(p_probe))
                    else:
                        score = float("inf")
                    probe = {
                        "q_null": float(q_probe_actual),
                        "a_null": float(a_probe_actual),
                        "p_W": float(p_probe),
                        "p_mV": float(p_probe_mV),
                        "score": float(score),
                        "candidate_a": float(branch_a_seed),
                        "move_cost": safe_wrap_move_cost_deg(seed_a_null, branch_a_seed),
                    }
                    append_quality(
                        null_quality_flags,
                        verify_fast_rotator_moves and not bool(q_probe_move.get("ok", True)),
                        "manual_peak_qwp_branch_verify_failed",
                    )
                    append_quality(
                        null_quality_flags,
                        verify_fast_rotator_moves and not bool(a_probe_move.get("ok", True)),
                        "manual_peak_anl_branch_verify_failed",
                    )
                    if branch_best is None or (probe["score"], probe["move_cost"]) < (
                        branch_best["score"],
                        branch_best["move_cost"],
                    ):
                        branch_best = probe
                except SkipPixelRequested:
                    raise
                except CriticalAngleError:
                    raise
                except Exception as exc:
                    raise_if_fatal_hardware_transport_error(
                        exc,
                        f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                        "manual null-branch probe",
                    )
                    append_quality(null_quality_flags, True, "manual_peak_branch_probe_failed")
                    continue
            if branch_best is not None:
                branch_p_mV = float(branch_best["p_mV"])
                branch_is_dark = (
                    np.isfinite(branch_p_mV)
                    and abs(branch_p_mV) <= float(null_check_max_mV)
                )
                if branch_is_dark:
                    seed_q_null = float(branch_best["q_null"])
                    seed_a_null = float(branch_best["a_null"])
                    seed_p_null = float(branch_best["p_W"])
                    seed_p_null_mV = branch_p_mV
                    current_q_seed = seed_q_null
                    current_a_seed = seed_a_null
                    manual_branch_active = True
                    if np.isfinite(seed_p_null) and seed_p_null > 0.0:
                        current_p_ref = seed_p_null
                    null_method = "manual_peak_seed"
                    print(
                        f" -> Q={seed_q_null:.3f}, A={seed_a_null:.3f}, "
                        f"det={seed_p_null_mV:.3f} mV",
                        end="",
                        flush=True,
                    )
                else:
                    append_quality(null_quality_flags, True, "manual_peak_branch_rejected_high_null")
                    print(
                        f" -> rejected as null: Q={float(branch_best['q_null']):.3f}, "
                        f"A={float(branch_best['a_null']):.3f}, "
                        f"det={branch_p_mV:.3f} mV > {float(null_check_max_mV):.3f} mV; "
                        "keeping substrate seed",
                        end="",
                        flush=True,
                    )
            else:
                append_quality(null_quality_flags, True, "manual_peak_branch_seed_unavailable")
        try:
            if force_full_calibration_null:
                gui_update_state(
                    current_pixel=pix_num,
                    current_hwp_index=i_hwp,
                    current_hwp_total=len(hwp_angles),
                    current_hwp_deg=float(current_hwp_actual),
                    current_hwp_null_deg=float(current_hwp_actual),
                    current_qwp_target_deg=wrap360(seed_q_null),
                    current_anl_target_deg=wrap360(seed_a_null),
                    current_qwp_null_deg=wrap360(seed_q_null),
                    current_anl_null_deg=wrap360(seed_a_null),
                    active_optic="QWP/ANL",
                    phase="Theory calibration: full QWP/ANL null",
                    ac_voltage_on=False,
                )
                print(
                    " | [THEORY NULL] forced sample-in coarse+fine QWP/ANL minimisation",
                    end="",
                    flush=True,
                )
                gui_pixel_checkpoint()
                q_null, a_null, p_null = campaign_first_null_fast(
                    null_detector,
                    rot_qwp,
                    rot_anl,
                    seed_q_null,
                    seed_a_null,
                    log_rows=log_rows,
                )
                gui_pixel_checkpoint()

                # first_null_fast returns the best of its coarse and fine
                # passes. Explicitly land on that returned pair because the
                # coarse result can occasionally beat the fine result.
                q_move, a_move = fast_move_to_null_seed(
                    rot_qwp,
                    rot_anl,
                    q_null,
                    a_null,
                    fast_rotator_moves=fast_rotator_moves,
                    verify_moves=verify_fast_rotator_moves,
                    verify_tol_deg=rotator_verify_tol_deg,
                )
                gui_pixel_checkpoint()
                require_verified_move(q_move, "QWP theory calibration null")
                require_verified_move(a_move, "ANL theory calibration null")
                append_quality(
                    null_quality_flags,
                    verify_fast_rotator_moves and not bool(q_move.get("ok", True)),
                    "qwp_theory_null_angle_verify_failed",
                )
                append_quality(
                    null_quality_flags,
                    verify_fast_rotator_moves and not bool(a_move.get("ok", True)),
                    "anl_theory_null_angle_verify_failed",
                )
                p_check, p_check_mV = read_null_check(detector, null_detector)
                if np.isfinite(p_check):
                    p_null = float(p_check)
                p_null_mV_read = float(p_check_mV)
                null_mV_after_renull = float(p_check_mV)
                null_method = "calibration_full_2d_coarse_fine"
                null_evals = int(len(log_rows))
                null_escalated = True
                null_status = "OK"
                append_quality(
                    null_quality_flags,
                    True,
                    "sample_in_full_null_calibration",
                )
                print(
                    f" -> Q={float(q_null):.3f}, A={float(a_null):.3f}, "
                    f"Vdet={float(p_null_mV_read):.3f} mV "
                    f"({int(null_evals)} scope evaluations)",
                    end="",
                    flush=True,
                )
            elif renull_mode in ("seed-only", "adaptive-renull"):
                q_null, a_null = seed_q_null, seed_a_null
                gui_update_state(
                    current_pixel=pix_num,
                    current_hwp_index=i_hwp,
                    current_hwp_total=len(hwp_angles),
                    current_hwp_deg=float(current_hwp_actual),
                    current_hwp_null_deg=float(current_hwp_actual),
                    current_qwp_target_deg=wrap360(q_null),
                    current_anl_target_deg=wrap360(a_null),
                    current_qwp_null_deg=wrap360(q_null),
                    current_anl_null_deg=wrap360(a_null),
                    active_optic="QWP/ANL",
                    phase="Moving QWP/ANL to null seed",
                )
                q_move, a_move = fast_move_to_null_seed(
                    rot_qwp,
                    rot_anl,
                    q_null,
                    a_null,
                    fast_rotator_moves=fast_rotator_moves,
                    verify_moves=verify_fast_rotator_moves,
                    verify_tol_deg=rotator_verify_tol_deg,
                )
                gui_pixel_checkpoint()
                require_verified_move(q_move, "QWP null seed")
                require_verified_move(a_move, "ANL null seed")
                gui_update_state(
                    current_pixel=pix_num,
                    current_hwp_index=i_hwp,
                    current_hwp_total=len(hwp_angles),
                    current_qwp_deg=gui_angle_from_move(q_move, q_null),
                    current_anl_deg=gui_angle_from_move(a_move, a_null),
                    current_qwp_target_deg=wrap360(q_null),
                    current_anl_target_deg=wrap360(a_null),
                    current_qwp_null_deg=wrap360(q_null),
                    current_anl_null_deg=wrap360(a_null),
                    active_optic="DETECTOR",
                    phase="Checking optical null",
                )
                append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(q_move.get("ok", True)), "qwp_null_angle_verify_failed")
                append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(a_move.get("ok", True)), "anl_null_angle_verify_failed")
                p_null, p_null_mV_read = read_null_check(detector, null_detector)
                seed_p_null = float(p_null)
                seed_p_null_mV = float(p_null_mV_read)
                null_mV_before_renull = seed_p_null_mV
                null_status = "OK"
                null_method = "manual_peak_seed_only" if manual_branch_active else "seed_only"
                seed_label, seed_quality_flag = null_check_label(seed_p_null_mV, null_check_max_mV)
                if renull_mode == "adaptive-renull" and seed_label != "NULL OK":
                    try:
                        gui_update_state(
                            current_pixel=pix_num,
                            current_hwp_index=i_hwp,
                            current_hwp_total=len(hwp_angles),
                            current_qwp_target_deg=wrap360(q_null),
                            current_anl_target_deg=wrap360(a_null),
                            detector_mV=float(seed_p_null_mV),
                            detector_power_W=float(seed_p_null),
                            active_optic="QWP/ANL",
                            phase="Adaptive QWP/ANL re-null",
                        )
                        gui_pixel_checkpoint()
                        prepare_null_scope_scale(null_detector)
                        renull = auto.campaign_fast_renull(
                            null_detector,
                            rot_qwp,
                            rot_anl,
                            q_null,
                            a_null,
                            current_p_ref,
                            log_rows=log_rows,
                        )
                        gui_pixel_checkpoint()
                        q_null = float(renull["q"])
                        a_null = float(renull["a"])
                        p_null = float(renull["p_after"])
                        prefix = "manual_peak_adaptive_" if manual_branch_active else "adaptive_"
                        null_method = prefix + str(renull.get("method", "renull"))
                        null_evals = int(renull.get("n_evals", len(log_rows)))
                        null_escalated = bool(renull.get("escalated", False))
                        q_move, a_move = verify_renull_landing(
                            rot_qwp, rot_anl, q_null, a_null, rotator_verify_tol_deg,
                            label="adaptive null",
                        )
                        # The optimizer's previous power belongs to its old
                        # pose. Re-measure after verifying/correcting the motors.
                        try:
                            p_check, p_check_mV = read_null_check(detector, null_detector)
                            if np.isfinite(p_check):
                                p_null = float(p_check)
                            p_null_mV_read = float(p_check_mV)
                        except SkipPixelRequested:
                            raise
                        except Exception as exc:
                            raise_if_fatal_hardware_transport_error(
                                exc,
                                f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                                "adaptive re-null detector check",
                            )
                            p_null_mV_read = float("nan")
                        null_mV_after_renull = float(p_null_mV_read)
                        gui_pixel_checkpoint()
                        append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(q_move.get("ok", True)), "qwp_null_angle_verify_failed")
                        append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(a_move.get("ok", True)), "anl_null_angle_verify_failed")
                    except SkipPixelRequested:
                        raise
                    except CriticalAngleError:
                        raise
                    except Exception as exc:
                        raise_if_fatal_hardware_transport_error(
                            exc,
                            f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                            "adaptive QWP/analyser re-null",
                        )
                        null_status = f"ADAPTIVE_RENULL_FAIL:{type(exc).__name__}"
                        append_quality(null_quality_flags, True, "adaptive_renull_failed")
                        append_quality(null_quality_flags, bool(seed_quality_flag), seed_quality_flag)
                        p_null_mV_read = seed_p_null_mV
                elif seed_quality_flag:
                    append_quality(null_quality_flags, True, seed_quality_flag)
            else:
                gui_update_state(
                    current_pixel=pix_num,
                    current_hwp_index=i_hwp,
                    current_hwp_total=len(hwp_angles),
                    current_hwp_deg=float(current_hwp_actual),
                    current_hwp_null_deg=float(current_hwp_actual),
                    current_qwp_target_deg=wrap360(seed_q_null),
                    current_anl_target_deg=wrap360(seed_a_null),
                    current_qwp_null_deg=wrap360(seed_q_null),
                    current_anl_null_deg=wrap360(seed_a_null),
                    active_optic="QWP/ANL",
                    phase="Fast QWP/ANL re-null",
                )
                gui_pixel_checkpoint()
                prepare_null_scope_scale(null_detector)
                renull = auto.campaign_fast_renull(
                    null_detector,
                    rot_qwp,
                    rot_anl,
                    seed_q_null,
                    seed_a_null,
                    seed_p_null,
                    log_rows=log_rows,
                )
                gui_pixel_checkpoint()
                q_null = float(renull["q"])
                a_null = float(renull["a"])
                p_null = float(renull["p_after"])
                null_method = str(renull.get("method", "renull"))
                if manual_branch_active:
                    null_method = "manual_peak_" + null_method
                null_evals = int(renull.get("n_evals", len(log_rows)))
                null_escalated = bool(renull.get("escalated", False))
                p_null_mV_read = float("nan")
                null_status = "OK"
                q_move, a_move = verify_renull_landing(
                    rot_qwp, rot_anl, q_null, a_null, rotator_verify_tol_deg,
                    label="fast null",
                )
                gui_pixel_checkpoint()
                append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(q_move.get("ok", True)), "qwp_null_angle_verify_failed")
                append_quality(null_quality_flags, verify_fast_rotator_moves and not bool(a_move.get("ok", True)), "anl_null_angle_verify_failed")
        except SkipPixelRequested:
            raise
        except CriticalAngleError:
            raise
        except Exception as exc:
            raise_if_fatal_hardware_transport_error(
                exc,
                f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f} optical null",
            )
            if force_full_calibration_null:
                raise CriticalCalibrationNullError(
                    f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f}: "
                    "the forced sample-in QWP/analyser calibration null failed "
                    f"({type(exc).__name__}: {exc}). No peak readout was learned."
                ) from exc
            q_null, a_null, p_null = current_q_seed, current_a_seed, float("nan")
            p_null_mV_read = float("nan")
            null_status = f"NULL_FAIL:{type(exc).__name__}"
            append_quality(null_quality_flags, True, "null_failed")

        p_null_mV = float(p_null_mV_read)
        if not np.isfinite(p_null_mV):
            try:
                gui_pixel_checkpoint()
                p_check, p_check_mV = read_null_check(detector, null_detector)
                if np.isfinite(p_check):
                    p_null = float(p_check)
                p_null_mV = float(p_check_mV)
            except SkipPixelRequested:
                raise
            except Exception as exc:
                raise_if_fatal_hardware_transport_error(
                    exc,
                    f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                    "final null detector check",
                )
                p_null_mV = float("nan")
        if not np.isfinite(p_null_mV):
            raise CriticalHardwareTransportError(
                f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f}: "
                "oscilloscope detector telemetry unavailable after nulling. "
                "Stopping before any AC/lock-in measurement is recorded."
            )
        null_hard_fail_mV = float(null_check_max_mV) + max(0.0, float(null_certify_margin_mV))
        null_label, null_quality_flag, null_hard_fail = classify_null_certification(
            p_null_mV,
            null_check_max_mV,
            null_certify_margin_mV,
        )
        null_marginal = null_label == "NULL MARGINAL"
        if force_full_calibration_null and null_hard_fail:
            if np.isfinite(p_null_mV):
                append_quality(
                    null_quality_flags,
                    True,
                    "calibration_null_hard_limit_exceeded",
                )
            else:
                raise CriticalCalibrationNullError(
                    f"Pixel {pix_num:03d} HWP {float(hwp_deg):.3f}: full sample-in "
                    "QWP/analyser minimisation produced no finite detector null "
                    "reading. The current pixel cannot continue."
                )
        if null_marginal and force_full_calibration_null:
            null_status = "NULL_MARGINAL_CONTINUED"
            append_quality(null_quality_flags, True, null_quality_flag)
            append_quality(null_quality_flags, True, "calibration_null_marginal_continued")
            gui_update_state(
                current_pixel=pix_num,
                current_hwp_index=i_hwp,
                current_hwp_total=len(hwp_angles),
                current_hwp_deg=float(current_hwp_actual),
                current_hwp_null_deg=float(current_hwp_actual),
                current_qwp_deg=gui_angle_from_move(q_move, q_null),
                current_anl_deg=gui_angle_from_move(a_move, a_null),
                detector_mV=float(p_null_mV),
                detector_power_W=float(p_null),
                active_optic="DETECTOR",
                phase="NULL MARGINAL: continuing with quality flag",
                ac_voltage_on=False,
            )
            print(
                f" | WARNING marginal calibration null continued: "
                f"Vdet={float(p_null_mV):.3f} mV is above target "
                f"{float(null_check_max_mV):.3f} mV but within hard limit "
                f"{null_hard_fail_mV:.3f} mV",
                end="",
                flush=True,
            )
        elif null_quality_flag and renull_mode != "adaptive-renull":
            append_quality(null_quality_flags, True, null_quality_flag)
        elif null_quality_flag and renull_mode == "adaptive-renull":
            append_quality(
                null_quality_flags,
                True,
                "marginal_null_after_adaptive" if null_marginal else "high_null_after_adaptive",
            )
        null_high_warning = bool(null_quality_flag and not null_marginal)
        if null_high_warning:
            null_status = "NULL_WARN_HIGH_CONTINUED"
            append_quality(null_quality_flags, True, "null_certification_warning_continue")
            append_quality(null_quality_flags, True, "high_null_continued")
            gui_update_state(
                current_pixel=pix_num,
                current_hwp_index=i_hwp,
                current_hwp_total=len(hwp_angles),
                current_hwp_deg=float(current_hwp_actual),
                current_hwp_null_deg=float(current_hwp_actual),
                current_qwp_deg=gui_angle_from_move(q_move, q_null),
                current_anl_deg=gui_angle_from_move(a_move, a_null),
                detector_mV=float(p_null_mV),
                detector_power_W=float(p_null),
                active_optic="DETECTOR",
                phase=f"NULL WARNING: {null_label}",
                ac_voltage_on=False,
            )
            print(
                f" | WARNING high null continued: Vdet={float(p_null_mV):.3f} mV "
                f"> warning {null_hard_fail_mV:.3f} mV "
                f"(target {float(null_check_max_mV):.3f} mV), "
                f"q={float(q_null):.3f}, a={float(a_null):.3f}, "
                f"after {null_method}/{int(null_evals)} probes",
                end="",
                flush=True,
            )
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_hwp_deg=float(current_hwp_actual),
            current_hwp_null_deg=float(current_hwp_actual),
            current_qwp_deg=gui_angle_from_move(q_move, q_null),
            current_anl_deg=gui_angle_from_move(a_move, a_null),
            current_qwp_target_deg=wrap360(q_null),
            current_anl_target_deg=wrap360(a_null),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_null_deg=wrap360(a_null),
            detector_mV=float(p_null_mV),
            detector_power_W=float(p_null),
            active_optic="DETECTOR",
            phase=(
                "Optical null checked with high-null warning"
                if null_high_warning
                else "Optical null checked"
            ),
        )

        null_context = {
            "hwp_actual_deg": hwp_move.get("actual_deg", float("nan")),
            "hwp_error_deg": hwp_move.get("error_deg", float("nan")),
            "seed_q_null_deg": seed_q_null,
            "seed_a_null_deg": seed_a_null,
            "seed_p_null_W": seed_p_null,
            "seed_p_null_mV": seed_p_null_mV,
            "qwp_actual_deg": q_move.get("actual_deg", float("nan")),
            "qwp_error_deg": q_move.get("error_deg", float("nan")),
            "anl_null_actual_deg": a_move.get("actual_deg", float("nan")),
            "anl_null_error_deg": a_move.get("error_deg", float("nan")),
            "null_method": null_method,
            "null_n_evals": null_evals,
            "null_escalated": bool(null_escalated),
            "null_mV_before_renull": null_mV_before_renull,
            "null_mV_after_renull": (
                null_mV_after_renull
                if np.isfinite(null_mV_after_renull)
                else p_null_mV
            ),
            "q_delta_deg": shortest_delta_deg(seed_q_null, q_null),
            "a_delta_deg": shortest_delta_deg(seed_a_null, a_null),
            "quality_flags": null_quality_flags,
        }

        qwp_readout_offset = float(qwp_readout_offset_deg)
        if not np.isfinite(qwp_readout_offset):
            qwp_readout_offset = 0.0
        qwp_readout_deg = qwp_readout_target_from_null(q_null, qwp_readout_offset)
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_hwp_deg=float(current_hwp_actual),
            current_hwp_null_deg=float(current_hwp_actual),
            current_qwp_target_deg=wrap360(qwp_readout_deg),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_target_deg=wrap360(a_null),
            current_anl_null_deg=wrap360(a_null),
            active_optic="QWP",
            phase="Moving QWP to readout bias",
        )
        qwp_readout_move = fast_rotator_move_or_fallback(
            rot_qwp,
            qwp_readout_deg,
            fast=fast_rotator_moves,
            verify=verify_fast_rotator_moves,
            tol_deg=rotator_verify_tol_deg,
            label="QWP readout bias",
        )
        gui_pixel_checkpoint()
        require_verified_move(qwp_readout_move, "QWP readout bias")
        qwp_readout_actual = gui_angle_from_move(qwp_readout_move, qwp_readout_deg)
        qwp_readout_error = qwp_readout_move.get("error_deg", float("nan"))
        append_quality(
            null_quality_flags,
            verify_fast_rotator_moves and not bool(qwp_readout_move.get("ok", True)),
            "qwp_readout_angle_verify_failed",
        )
        if np.isfinite(float(qwp_readout_error)) and abs(float(qwp_readout_error)) > float(rotator_verify_tol_deg):
            append_quality(null_quality_flags, True, "qwp_readout_angle_error")
        null_context.update({
            "qwp_readout_deg": float(qwp_readout_deg),
            "qwp_readout_actual_deg": float(qwp_readout_actual),
            "qwp_readout_error_deg": float(qwp_readout_error),
            "qwp_readout_offset_from_null_deg": periodic_delta_deg(q_null, qwp_readout_deg, 180.0),
            "qwp_readout_verify_failed": verify_fast_rotator_moves and not bool(qwp_readout_move.get("ok", True)),
        })
        if manual_branch_active and manual_branch_seed is not None:
            expected_q_readout = float(manual_branch_seed.get("q_readout_seed_deg", float("nan")))
            if np.isfinite(expected_q_readout):
                q_readout_branch_error = abs(periodic_delta_deg(expected_q_readout, qwp_readout_deg, 180.0))
                null_context["manual_peak_qwp_readout_expected_deg"] = expected_q_readout
                null_context["manual_peak_qwp_readout_error_deg"] = q_readout_branch_error
                append_quality(
                    null_quality_flags,
                    q_readout_branch_error > MANUAL_PEAK_BRANCH_WARN_DEG,
                    "manual_peak_qwp_branch_shift",
                )
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_qwp_deg=float(qwp_readout_actual),
            current_qwp_target_deg=wrap360(qwp_readout_deg),
            current_qwp_null_deg=wrap360(q_null),
            phase="QWP readout bias ready",
        )

        null_seed_accepted = not bool(null_quality_flag)
        if null_seed_accepted:
            current_q_seed, current_a_seed = float(q_null), float(a_null)
            if np.isfinite(p_null) and p_null > 0.0:
                current_p_ref = float(p_null)
        else:
            append_quality(
                null_quality_flags,
                True,
                (
                    "null_seed_not_saved_marginal"
                    if null_marginal
                    else "null_seed_not_saved_high_leakage"
                ),
            )
        if sim_state is not None:
            sim_state["a_null"] = float(a_null)

        if null_seed_accepted:
            seed_entry = dict(null_seed_by_hwp.get(hwp_key, {}))
            seed_entry.update({
                "q_null_deg": float(q_null),
                "a_null_deg": float(a_null),
                "p_null_W": float(p_null),
                "p_null_mV": float(p_null_mV),
                "pixel": pix_num,
                "updated": datetime.now().isoformat(),
            })
            null_seed_by_hwp[hwp_key] = seed_entry
        pockels.save_null_info(
            str(pixel_dir / f"hwp_{float(hwp_deg):05.1f}deg_null_info.json"),
            float(hwp_deg),
            q_null,
            a_null,
            p_null,
            current_q_seed,
            current_a_seed,
            log_rows,
        )

        current_anl_angle = rotator_read_angle_once(rot_anl)
        if not np.isfinite(current_anl_angle):
            current_anl_angle = a_null
        slope_targets = ordered_slope_targets(a_null, current_anl_angle)
        if manual_branch_active and manual_branch_seed is not None:
            expected_anl_peak = float(manual_branch_seed.get("anl_peak_deg", float("nan")))
            if np.isfinite(expected_anl_peak) and slope_targets:
                min_anl_branch_error = min(
                    abs(periodic_delta_deg(expected_anl_peak, target, 180.0))
                    for _side, target in slope_targets
                )
                null_context["manual_peak_anl_expected_deg"] = expected_anl_peak
                null_context["manual_peak_anl_branch_error_deg"] = min_anl_branch_error
                append_quality(
                    null_quality_flags,
                    min_anl_branch_error > MANUAL_PEAK_BRANCH_WARN_DEG,
                    "manual_peak_anl_branch_miss",
                )

        pockels._funcgen_set_sweep_output(
            funcgen,
            True,
            verify_command=True,
            required=True,
            context=(
                f"pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                "AC measurement start"
            ),
        )
        gui_update_state(
            current_pixel=pix_num,
            current_hwp_index=i_hwp,
            current_hwp_total=len(hwp_angles),
            current_hwp_deg=float(current_hwp_actual),
            current_hwp_null_deg=float(current_hwp_actual),
            current_qwp_deg=float(qwp_readout_actual),
            current_qwp_target_deg=wrap360(qwp_readout_deg),
            current_qwp_null_deg=wrap360(q_null),
            current_anl_deg=float(a_null),
            current_anl_null_deg=wrap360(a_null),
            phase="AC measurement",
            ac_voltage_on=True,
            active_optic="LOCKIN",
        )
        hwp_rows = []
        s9_hwp_certificate: dict | None = None
        certificate_vpp = max(float(value) for value in voltages) if voltages else None
        def certify_peak_row(peak_row: dict, peak_source: str, *, precounted_in_progress: bool) -> None:
            nonlocal sens_idx
            if not bool(peak_diagnostic):
                return
            diag_rows, diag_raw, diag_result, sens_idx = run_peak_readout_diagnostic(
                pixel=pixel,
                hwp_deg=float(hwp_deg),
                q_null=float(q_null),
                a_null=float(a_null),
                p_null=float(p_null),
                p_null_mV=float(p_null_mV),
                vpp=float(vpp),
                peak_row=peak_row,
                peak_source=peak_source,
                step_deg=float(peak_diagnostic_step_deg),
                min_margin_uV=float(peak_diagnostic_min_margin_uV),
                rot_qwp=rot_qwp,
                rot_anl=rot_anl,
                detector=detector,
                lockin=lockin,
                sens_idx=sens_idx,
                reference_phase_deg=reference_phase_deg,
                fast_rotator_moves=fast_rotator_moves,
                verify_moves=verify_fast_rotator_moves,
                verify_tol_deg=rotator_verify_tol_deg,
                base_null_context=null_context,
                progress=progress,
                precounted_in_progress=precounted_in_progress,
                t_start=t_start,
            )
            rows.extend(diag_rows)
            hwp_rows.extend(diag_rows)
            raw_rows.extend(diag_raw)
            peak_diagnostic_rows.append(diag_result)

        try:
            for vpp in voltages:
                gui_pixel_checkpoint()
                pockels.funcgen_set_voltage(funcgen, float(vpp))
                gui_sleep(pockels.FUNCGEN_SETTLE_S, allow_skip=True)
                gui_pixel_checkpoint()
                gui_init_lockin_bars(
                    pixel=pix_num,
                    hwp_deg=float(current_hwp_actual),
                    vpp=float(vpp),
                    a_null=a_null,
                )
                used_learned_triplet = False
                null_ref_row = None
                null_ref_raw: list[dict] = []
                s9_null_reference_row = None
                s9_null_context = null_context
                locked_qwp_mode = str(auto_peak_track_mode or DEFAULT_AUTO_PEAK_TRACK_MODE).strip().lower() == "locked-qwp"
                learned_mode = str(
                    learned_readout_mode or DEFAULT_LEARNED_READOUT_MODE
                ).strip().lower()
                robust_paired_mode = bool(
                    locked_qwp_mode and learned_mode == "triplet"
                )
                locked_qwp_two_point = (
                    locked_qwp_mode
                    and str(AUTO_PEAK_REFINE_MODE).strip().lower() == "two-point"
                )
                needs_peak_calibration_reference = (
                    manual_branch_seed is None
                    and locked_qwp_mode
                    and (robust_paired_mode or not locked_qwp_two_point)
                    and not (robust_paired_mode and readout_override is not None)
                    and (
                        auto_peak_calibration
                        or (peak_readout_required and readout_override is None)
                    )
                )
                if needs_peak_calibration_reference:
                    sens_idx, null_ref_row, null_ref_raw = measure_lockin_null_reference(
                        pixel=pixel,
                        hwp_deg=float(hwp_deg),
                        q_null=q_null,
                        a_null=a_null,
                        p_null=p_null,
                        p_null_mV=p_null_mV,
                        vpp=float(vpp),
                        rot_qwp=rot_qwp,
                        rot_anl=rot_anl,
                        detector=detector,
                        lockin=lockin,
                        sens_idx=sens_idx,
                        reference_phase_deg=reference_phase_deg,
                        fast_rotator_moves=fast_rotator_moves,
                        verify_moves=verify_fast_rotator_moves,
                        verify_tol_deg=rotator_verify_tol_deg,
                        null_context=null_context,
                        t_start=t_start,
                    )
                    if null_ref_row is not None:
                        append_row_quality(null_ref_row, "peak_calibration_background_reference")
                        null_reference_rows.append(null_ref_row)
                        raw_rows.extend(null_ref_raw)
                        if progress is not None:
                            progress["points_done"] = int(progress.get("points_done", 0)) + 1
                            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                if manual_branch_seed is not None:
                    q_anchor_raw = float(manual_branch_seed.get("q_readout_seed_deg", float("nan")))
                    a_anchor_raw = float(manual_branch_seed.get("anl_peak_deg", float("nan")))
                    if np.isfinite(q_anchor_raw) and np.isfinite(a_anchor_raw):
                        q_anchor_ref = rotator_read_angle_once(rot_qwp)
                        if not np.isfinite(q_anchor_ref):
                            q_anchor_ref = qwp_readout_actual
                        a_anchor_ref = rotator_read_angle_once(rot_anl)
                        if not np.isfinite(a_anchor_ref):
                            a_anchor_ref = a_null
                        q_anchor = closest_periodic_equivalent_deg(
                            q_anchor_raw,
                            q_anchor_ref,
                            180.0,
                        )
                        a_anchor = closest_periodic_equivalent_deg(
                            a_anchor_raw,
                            a_anchor_ref,
                            180.0,
                            analyser=True,
                        )
                        row, raw, sens_idx = measure_manual_peak_point(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            qwp_deg=float(q_anchor),
                            anl_deg=float(a_anchor),
                            vpp=float(vpp),
                            rot_hwp=rot_hwp,
                            rot_qwp=rot_qwp,
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            t_start=t_start,
                            slope_side="manual_anchor",
                            quality_flag="manual_peak_anchor_raw",
                            phase_label="Manual anchored raw peak",
                        )
                        if not manual_branch_active:
                            existing = str(row.get("quality_flags", ""))
                            row["quality_flags"] = ";".join(
                                flag for flag in (
                                    existing,
                                    "manual_anchor_null_branch_rejected",
                                )
                                if flag
                            )
                        rows.append(row)
                        hwp_rows.append(row)
                        raw_rows.extend(raw)
                        if progress is not None:
                            progress["points_done"] = int(progress.get("points_done", 0)) + 1
                            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                            gui_update_state(
                                current_pixel=pix_num,
                                current_hwp_index=i_hwp,
                                current_hwp_total=len(hwp_angles),
                                current_hwp_deg=float(row.get("hwp_actual_deg", current_hwp_actual)),
                                current_hwp_null_deg=float(current_hwp_actual),
                                current_qwp_deg=float(row.get("qwp_actual_deg", float("nan"))),
                                current_qwp_target_deg=wrap360(q_anchor),
                                current_qwp_null_deg=wrap360(q_null),
                                current_anl_deg=float(row.get("anl_actual_deg", float("nan"))),
                                current_anl_null_deg=wrap360(a_null),
                                detector_mV=float(row.get("detector_V", float("nan"))) * 1e3,
                                detector_power_W=float(row.get("power_W", float("nan"))),
                                lockin_mag_V=float(row.get("lockin_mag_V", float("nan"))),
                                lockin_phase_deg=float(row.get("lockin_phase_deg", float("nan"))),
                                lockin_signed_V=float(row.get("lockin_signed_V", float("nan"))),
                                current_vpp=float(vpp),
                                current_slope_side="manual_anchor",
                                phase="Manual anchored raw peak complete",
                                chip_points_done=int(progress.get("points_done", 0)),
                                chip_total_points=int(progress.get("total_points", 0)),
                                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                                pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                                ac_voltage_on=True,
                                active_optic="LOCKIN",
                            )
                        print(
                            f"\nP{pix_num:03d} manual anchor HWP={float(hwp_deg):.4f}, "
                            f"QWP={float(q_anchor):.4f}, ANL={float(a_anchor):.4f}, "
                            f"{float(vpp):g} Vpp | raw MAG={float(row['lockin_mag_V']) * 1e6:.3f} uV"
                        )
                        auto_row, auto_raw, sens_idx, auto_n = auto_refine_qwp_analyser_peak_from_seed(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            qwp_seed_deg=float(q_anchor),
                            anl_seed_deg=float(a_anchor),
                            q_null=float(q_null),
                            a_null=float(a_null),
                            p_null=float(p_null),
                            p_null_mV=float(p_null_mV),
                            vpp=float(vpp),
                            rot_qwp=rot_qwp,
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            base_null_context=null_context,
                            t_start=t_start,
                        )
                        rows.append(auto_row)
                        hwp_rows.append(auto_row)
                        raw_rows.extend(auto_raw)
                        if progress is not None:
                            progress["total_points"] = int(progress.get("total_points", 0)) + 1
                            progress["points_done"] = int(progress.get("points_done", 0)) + 1
                            progress["pixel_total_points"] = int(progress.get("pixel_total_points", pixel_total_points)) + 1
                            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                            gui_update_state(
                                current_pixel=pix_num,
                                current_hwp_index=i_hwp,
                                current_hwp_total=len(hwp_angles),
                                current_hwp_deg=float(auto_row.get("hwp_actual_deg", current_hwp_actual)),
                                current_hwp_null_deg=float(current_hwp_actual),
                                current_qwp_deg=float(auto_row.get("qwp_actual_deg", float("nan"))),
                                current_qwp_target_deg=wrap360(auto_row.get("qwp_readout_deg", q_anchor)),
                                current_qwp_null_deg=wrap360(q_null),
                                current_anl_deg=float(auto_row.get("anl_actual_deg", float("nan"))),
                                current_anl_null_deg=wrap360(a_null),
                                detector_mV=float(auto_row.get("detector_V", float("nan"))) * 1e3,
                                detector_power_W=float(auto_row.get("power_W", float("nan"))),
                                lockin_mag_V=float(auto_row.get("lockin_mag_V", float("nan"))),
                                lockin_phase_deg=float(auto_row.get("lockin_phase_deg", float("nan"))),
                                lockin_signed_V=float(auto_row.get("lockin_signed_V", float("nan"))),
                                current_vpp=float(vpp),
                                current_slope_side="auto_peak",
                                phase="Auto lock-in peak search complete",
                                chip_points_done=int(progress.get("points_done", 0)),
                                chip_total_points=int(progress.get("total_points", 0)),
                                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                                pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                                ac_voltage_on=True,
                                active_optic="LOCKIN",
                            )
                        print(
                            f"\nP{pix_num:03d} auto peak HWP={float(hwp_deg):.4f}, "
                            f"QWP={float(auto_row.get('qwp_readout_deg', q_anchor)):.4f}, "
                            f"ANL={float(auto_row.get('anl_target_deg', a_anchor)):.4f}, "
                            f"{float(vpp):g} Vpp | raw MAG={float(auto_row['lockin_mag_V']) * 1e6:.3f} uV "
                            f"({auto_n} QWP/ANL probes)"
                        )
                        auto_peak_previous = {
                            "hwp_deg": float(hwp_deg),
                            "qwp_readout_deg": float(auto_row.get("qwp_readout_deg", q_anchor)),
                            "anl_target_deg": float(auto_row.get("anl_target_deg", a_anchor)),
                        }
                        certify_peak_row(
                            auto_row,
                            "manual_anchor_auto_refine",
                            precounted_in_progress=True,
                        )
                        used_learned_triplet = True
                if (
                    (auto_peak_calibration or peak_readout_required)
                    and manual_branch_seed is None
                    and readout_override is None
                    and not robust_paired_mode
                ):
                    auto_row, auto_raw, sens_idx, auto_n, auto_peak_previous = auto_find_qwp_analyser_peak_from_null(
                        pixel=pixel,
                        hwp_deg=float(hwp_deg),
                        q_null=float(q_null),
                        a_null=float(a_null),
                        p_null=float(p_null),
                        p_null_mV=float(p_null_mV),
                        vpp=float(vpp),
                        rot_qwp=rot_qwp,
                        rot_anl=rot_anl,
                        detector=detector,
                        lockin=lockin,
                        sens_idx=sens_idx,
                        reference_phase_deg=reference_phase_deg,
                        fast_rotator_moves=fast_rotator_moves,
                        verify_moves=verify_fast_rotator_moves,
                        verify_tol_deg=rotator_verify_tol_deg,
                        base_null_context=null_context,
                        null_reference_row=null_ref_row,
                        previous_peak=auto_peak_previous,
                        t_start=t_start,
                        max_coarse_probes=int(auto_peak_max_coarse_probes),
                        track_mode=str(auto_peak_track_mode),
                    )
                    rows.append(auto_row)
                    hwp_rows.append(auto_row)
                    raw_rows.extend(auto_raw)
                    if progress is not None:
                        if not bool(auto_peak_calibration):
                            progress["total_points"] = int(progress.get("total_points", 0)) + 1
                            progress["pixel_total_points"] = int(progress.get("pixel_total_points", pixel_total_points)) + 1
                        progress["points_done"] = int(progress.get("points_done", 0)) + 1
                        progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                        gui_update_state(
                            current_pixel=pix_num,
                            current_hwp_index=i_hwp,
                            current_hwp_total=len(hwp_angles),
                            current_hwp_deg=float(auto_row.get("hwp_actual_deg", current_hwp_actual)),
                            current_hwp_null_deg=float(current_hwp_actual),
                            current_qwp_deg=float(auto_row.get("qwp_actual_deg", float("nan"))),
                            current_qwp_target_deg=wrap360(auto_row.get("qwp_readout_deg", q_null)),
                            current_qwp_null_deg=wrap360(q_null),
                            current_anl_deg=float(auto_row.get("anl_actual_deg", float("nan"))),
                            current_anl_null_deg=wrap360(a_null),
                            detector_mV=float(auto_row.get("detector_V", float("nan"))) * 1e3,
                            detector_power_W=float(auto_row.get("power_W", float("nan"))),
                            lockin_mag_V=float(auto_row.get("lockin_mag_V", float("nan"))),
                            lockin_phase_deg=float(auto_row.get("lockin_phase_deg", float("nan"))),
                            lockin_signed_V=float(auto_row.get("lockin_signed_V", float("nan"))),
                            current_vpp=float(vpp),
                            current_slope_side="auto_peak",
                            phase="Automatic peak calibration complete",
                            chip_points_done=int(progress.get("points_done", 0)),
                            chip_total_points=int(progress.get("total_points", 0)),
                            pixel_points_done=int(progress.get("pixel_points_done", 0)),
                            pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                            ac_voltage_on=True,
                            active_optic="LOCKIN",
                        )
                    print(
                        f"\nP{pix_num:03d} auto-cal peak HWP={float(hwp_deg):.4f}, "
                        f"QWP={float(auto_row.get('qwp_readout_deg', q_null)):.4f}, "
                        f"ANL={float(auto_row.get('anl_target_deg', a_null)):.4f}, "
                        f"{float(vpp):g} Vpp | raw MAG={float(auto_row['lockin_mag_V']) * 1e6:.3f} uV "
                        f"({auto_n} automatic QWP/ANL probes)"
                    )
                    certify_peak_row(
                        auto_row,
                        "auto_missing_hwp_peak_search",
                        precounted_in_progress=bool(auto_peak_calibration),
                    )
                    used_learned_triplet = True
                if (
                    auto_peak_calibration
                    and readout_override is not None
                    and manual_branch_seed is None
                    and not used_learned_triplet
                    and not robust_paired_mode
                ):
                    q_seed_ref = rotator_read_angle_once(rot_qwp)
                    if not np.isfinite(q_seed_ref):
                        q_seed_ref = qwp_readout_actual
                    a_seed_ref = rotator_read_angle_once(rot_anl)
                    if not np.isfinite(a_seed_ref):
                        a_seed_ref = a_null
                    q_seed, a_seed, used_offset_override = resolve_peak_readout_override(
                        readout_override,
                        q_null=float(q_null),
                        a_null=float(a_null),
                        q_reference=float(q_seed_ref),
                        a_reference=float(a_seed_ref),
                    )
                    track_mode_now = str(auto_peak_track_mode or DEFAULT_AUTO_PEAK_TRACK_MODE).strip().lower()
                    if track_mode_now == "locked-qwp":
                        auto_row, auto_raw, sens_idx, auto_n, auto_peak_previous = auto_find_qwp_analyser_peak_from_null(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            q_null=float(q_null),
                            a_null=float(a_null),
                            p_null=float(p_null),
                            p_null_mV=float(p_null_mV),
                            vpp=float(vpp),
                            rot_qwp=rot_qwp,
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            base_null_context=null_context,
                            null_reference_row=null_ref_row,
                            previous_peak=auto_peak_previous,
                            t_start=t_start,
                            max_coarse_probes=int(auto_peak_max_coarse_probes),
                            track_mode="locked-qwp",
                        )
                    else:
                        auto_row, auto_raw, sens_idx, auto_n = auto_refine_qwp_analyser_peak_from_seed(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            qwp_seed_deg=float(q_seed),
                            anl_seed_deg=float(a_seed),
                            q_null=float(q_null),
                            a_null=float(a_null),
                            p_null=float(p_null),
                            p_null_mV=float(p_null_mV),
                            vpp=float(vpp),
                            rot_qwp=rot_qwp,
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            base_null_context=null_context,
                            t_start=t_start,
                        )
                    append_row_quality(
                        auto_row,
                        "readout_override_applied_as_null_relative_offset"
                        if used_offset_override else "readout_override_applied_as_absolute_raw_angles",
                    )
                    append_row_quality(
                        auto_row,
                        "auto_peak_locked_qwp_from_learned_override"
                        if track_mode_now == "locked-qwp" else "auto_peak_refined_from_learned_override",
                    )
                    rows.append(auto_row)
                    hwp_rows.append(auto_row)
                    raw_rows.extend(auto_raw)
                    if progress is not None:
                        progress["points_done"] = int(progress.get("points_done", 0)) + 1
                        progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                        gui_update_state(
                            current_pixel=pix_num,
                            current_hwp_index=i_hwp,
                            current_hwp_total=len(hwp_angles),
                            current_hwp_deg=float(auto_row.get("hwp_actual_deg", current_hwp_actual)),
                            current_hwp_null_deg=float(current_hwp_actual),
                            current_qwp_deg=float(auto_row.get("qwp_actual_deg", float("nan"))),
                            current_qwp_target_deg=wrap360(auto_row.get("qwp_readout_deg", q_seed)),
                            current_qwp_null_deg=wrap360(q_null),
                            current_anl_deg=float(auto_row.get("anl_actual_deg", float("nan"))),
                            current_anl_null_deg=wrap360(a_null),
                            detector_mV=float(auto_row.get("detector_V", float("nan"))) * 1e3,
                            detector_power_W=float(auto_row.get("power_W", float("nan"))),
                            lockin_mag_V=float(auto_row.get("lockin_mag_V", float("nan"))),
                            lockin_phase_deg=float(auto_row.get("lockin_phase_deg", float("nan"))),
                            lockin_signed_V=float(auto_row.get("lockin_signed_V", float("nan"))),
                            current_vpp=float(vpp),
                            current_slope_side="auto_peak",
                            phase="Automatic peak calibration refined",
                            chip_points_done=int(progress.get("points_done", 0)),
                            chip_total_points=int(progress.get("total_points", 0)),
                            pixel_points_done=int(progress.get("pixel_points_done", 0)),
                            pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                            ac_voltage_on=True,
                            active_optic="LOCKIN",
                        )
                    print(
                        f"\nP{pix_num:03d} auto-cal refine HWP={float(hwp_deg):.4f}, "
                        f"seed QWP={float(q_seed):.4f}, seed ANL={float(a_seed):.4f} -> "
                        f"QWP={float(auto_row.get('qwp_readout_deg', q_seed)):.4f}, "
                        f"ANL={float(auto_row.get('anl_target_deg', a_seed)):.4f}, "
                        f"{float(vpp):g} Vpp | raw MAG={float(auto_row['lockin_mag_V']) * 1e6:.3f} uV "
                        f"({auto_n} QWP/ANL probes)"
                    )
                    auto_peak_previous = {
                        "hwp_deg": float(hwp_deg),
                        "qwp_readout_deg": float(auto_row.get("qwp_readout_deg", q_seed)),
                        "anl_target_deg": float(auto_row.get("anl_target_deg", a_seed)),
                    }
                    certify_peak_row(
                        auto_row,
                        "auto_refined_learned_override",
                        precounted_in_progress=True,
                    )
                    used_learned_triplet = True
                if readout_override is not None and manual_branch_seed is None and not used_learned_triplet:
                    q_learned_ref = rotator_read_angle_once(rot_qwp)
                    if not np.isfinite(q_learned_ref):
                        q_learned_ref = qwp_readout_actual
                    a_learned_ref = rotator_read_angle_once(rot_anl)
                    if not np.isfinite(a_learned_ref):
                        a_learned_ref = a_null
                    q_learned, a_learned_raw, used_offset_override = resolve_peak_readout_override(
                        readout_override,
                        q_null=float(q_null),
                        a_null=float(a_null),
                        q_reference=float(q_learned_ref),
                        a_reference=float(a_learned_ref),
                    )
                    if robust_paired_mode:
                        # Paper-style production readout stays on the local
                        # compensating QWP null.  The saved first-pixel branch
                        # only chooses the analyser slope ordering.
                        q_learned = closest_periodic_equivalent_deg(
                            float(q_null), float(q_learned_ref), 180.0
                        )
                    gui_update_state(
                        current_pixel=pix_num,
                        current_hwp_index=i_hwp,
                        current_hwp_total=len(hwp_angles),
                        current_hwp_deg=float(current_hwp_actual),
                        current_hwp_null_deg=float(current_hwp_actual),
                        current_qwp_target_deg=wrap360(q_learned),
                        current_qwp_null_deg=wrap360(q_null),
                        current_anl_null_deg=wrap360(a_null),
                        current_vpp=float(vpp),
                        current_slope_side="learned_anchor",
                        phase="Moving QWP to learned readout",
                        ac_voltage_on=True,
                        active_optic="QWP",
                    )
                    q_learned_move = fast_rotator_move_or_fallback(
                        rot_qwp,
                        q_learned,
                        fast=fast_rotator_moves,
                        verify=verify_fast_rotator_moves,
                        tol_deg=rotator_verify_tol_deg,
                        label="QWP learned readout",
                    )
                    gui_pixel_checkpoint()
                    require_verified_move(q_learned_move, "QWP learned readout")
                    q_learned_actual = _rotator_float_or_nan(
                        gui_angle_from_move(q_learned_move, q_learned)
                    )
                    q_learned_error = _rotator_float_or_nan(q_learned_move.get("error_deg", float("nan")))

                    learned_flags = list(null_context.get("quality_flags", []) or [])
                    append_quality(learned_flags, True, "learned_readout")
                    append_quality(learned_flags, True, "qwp_locked_learned_readout")
                    append_quality(
                        learned_flags,
                        True,
                        "readout_override_applied_as_null_relative_offset"
                        if used_offset_override else "readout_override_applied_as_absolute_raw_angles",
                    )
                    append_quality(
                        learned_flags,
                        verify_fast_rotator_moves and not bool(q_learned_move.get("ok", True)),
                        "qwp_readout_angle_verify_failed",
                    )
                    append_quality(
                        learned_flags,
                        np.isfinite(float(q_learned_error)) and abs(float(q_learned_error)) > float(rotator_verify_tol_deg),
                        "qwp_readout_angle_error",
                    )
                    learned_context = dict(null_context)
                    learned_context.update({
                        "qwp_readout_deg": float(q_learned),
                        "qwp_readout_actual_deg": float(q_learned_actual),
                        "qwp_readout_error_deg": float(q_learned_error),
                        "qwp_readout_offset_from_null_deg": periodic_delta_deg(q_null, q_learned, 180.0),
                        "qwp_readout_verify_failed": verify_fast_rotator_moves and not bool(q_learned_move.get("ok", True)),
                        "quality_flags": learned_flags,
                    })
                    s9_null_context = learned_context

                    current_learned_anl = rotator_read_angle_once(rot_anl)
                    if not np.isfinite(current_learned_anl):
                        current_learned_anl = a_null
                    if learned_mode == "triplet":
                        learned_targets = learned_readout_triplet_targets(
                            a_learned_raw,
                            a_null,
                            current_learned_anl,
                        )
                    elif learned_mode == "zero-anchor":
                        # v2: background zero + learned peak (skip the opposite
                        # symmetry point) - net columns at 2 points per HWP.
                        learned_targets = learned_readout_triplet_targets(
                            a_learned_raw,
                            a_null,
                            current_learned_anl,
                        )[:2]
                    else:
                        learned_peak_target = closest_periodic_equivalent_deg(
                            a_learned_raw,
                            current_learned_anl,
                            180.0,
                            analyser=True,
                        )
                        learned_targets = [("learned_anchor", learned_peak_target)]
                    learned_zero_row = None
                    learned_rows_by_side: dict[str, dict] = {}
                    learned_phase = {
                        "learned_zero": "Learned readout recalibrated zero",
                        "learned_anchor": "Learned readout peak",
                        "learned_opposite": "Learned readout opposite check",
                    }
                    for learned_side, learned_anl_target in learned_targets:
                        gui_pixel_checkpoint()
                        row, raw, sens_idx = measure_lockin_point(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            q_null=q_null,
                            a_null=a_null,
                            p_null=p_null,
                            p_null_mV=p_null_mV,
                            slope_side=learned_side,
                            anl_target=learned_anl_target,
                            vpp=float(vpp),
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            null_context=learned_context,
                            null_reference_row=learned_zero_row,
                            t_start=t_start,
                        )
                        append_row_quality(row, "learned_readout")
                        append_row_quality(row, "qwp_locked_learned_readout")
                        append_row_quality(row, f"learned_readout_mode_{learned_mode}")
                        if learned_side == "learned_zero":
                            append_row_quality(row, "learned_recalibrated_zero")
                            learned_zero_row = row
                            s9_null_reference_row = row
                            null_reference_rows.append(row)
                        elif learned_side == "learned_anchor":
                            append_row_quality(row, "learned_peak_readout")
                        elif learned_side == "learned_opposite":
                            append_row_quality(row, "learned_opposite_symmetry_check")
                        if learned_side in ("learned_anchor", "learned_opposite"):
                            annotate_peak_readout_row(
                                row,
                                peak_source="learned_readout",
                                peak_track_mode="locked-qwp",
                                learned_readout_mode=learned_mode,
                                chosen_side=learned_side,
                            )
                        else:
                            row["peak_source"] = "learned_readout"
                            row["peak_track_mode"] = "locked-qwp"
                            row["learned_readout_mode"] = learned_mode
                            row["quality"] = classify_peak_quality(row)
                        if null_status != "OK":
                            append_row_quality(row, null_status)
                        row["quality"] = classify_peak_quality(row)
                        rows.append(row)
                        hwp_rows.append(row)
                        raw_rows.extend(raw)
                        learned_rows_by_side[learned_side] = row
                        if progress is not None:
                            progress["points_done"] = int(progress.get("points_done", 0)) + 1
                            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                            gui_update_state(
                                current_pixel=pix_num,
                                current_hwp_index=i_hwp,
                                current_hwp_total=len(hwp_angles),
                                current_hwp_deg=float(current_hwp_actual),
                                current_hwp_null_deg=float(current_hwp_actual),
                                current_qwp_deg=float(row.get("qwp_actual_deg", q_learned_actual)),
                                current_qwp_target_deg=wrap360(row.get("qwp_readout_deg", q_learned)),
                                current_qwp_null_deg=wrap360(q_null),
                                current_anl_deg=float(row.get("anl_actual_deg", float("nan"))),
                                current_anl_null_deg=wrap360(a_null),
                                detector_mV=float(row.get("detector_V", float("nan"))) * 1e3,
                                detector_power_W=float(row.get("power_W", float("nan"))),
                                lockin_mag_V=float(row.get("lockin_mag_V", float("nan"))),
                                lockin_phase_deg=float(row.get("lockin_phase_deg", float("nan"))),
                                lockin_signed_V=float(row.get("lockin_signed_V", float("nan"))),
                                current_vpp=float(vpp),
                                current_slope_side=learned_side,
                                phase=f"{learned_phase.get(learned_side, learned_side)} complete",
                                chip_points_done=int(progress.get("points_done", 0)),
                                chip_total_points=int(progress.get("total_points", 0)),
                                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                                pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                                ac_voltage_on=True,
                                active_optic="LOCKIN",
                            )

                    def _learned_raw_uV(side: str) -> float:
                        item = learned_rows_by_side.get(side)
                        if not item:
                            return float("nan")
                        return lockin_raw_response_value(item, "lockin_mag_V", "lockin_net_mag_V") * 1e6

                    zero_target = dict(learned_targets).get("learned_zero", float("nan"))
                    peak_target = dict(learned_targets).get("learned_anchor", float("nan"))
                    opposite_target = dict(learned_targets).get("learned_opposite", float("nan"))
                    if learned_mode == "triplet":
                        print(
                            f"\nP{pix_num:03d} learned triplet HWP={float(hwp_deg):.4f}, "
                            f"QWP={float(q_learned):.4f}, "
                            f"ANL0={float(zero_target):.4f}, peak={float(peak_target):.4f}, "
                            f"opp={float(opposite_target):.4f}, {float(vpp):g} Vpp | "
                            f"rawMAG 0={_learned_raw_uV('learned_zero'):.3f} "
                            f"peak={_learned_raw_uV('learned_anchor'):.3f} "
                            f"opp={_learned_raw_uV('learned_opposite'):.3f} uV"
                        )
                    elif learned_mode == "zero-anchor":
                        print(
                            f"\nP{pix_num:03d} learned zero+peak HWP={float(hwp_deg):.4f}, "
                            f"QWP={float(q_learned):.4f}, "
                            f"ANL0={float(zero_target):.4f}, peak={float(peak_target):.4f}, "
                            f"{float(vpp):g} Vpp | "
                            f"rawMAG 0={_learned_raw_uV('learned_zero'):.3f} "
                            f"peak={_learned_raw_uV('learned_anchor'):.3f} uV"
                        )
                    else:
                        print(
                            f"\nP{pix_num:03d} learned peak HWP={float(hwp_deg):.4f}, "
                            f"QWP={float(q_learned):.4f}, ANL={float(peak_target):.4f}, "
                            f"{float(vpp):g} Vpp | rawMAG peak={_learned_raw_uV('learned_anchor'):.3f} uV"
                        )
                    learned_anchor_row = learned_rows_by_side.get("learned_anchor")
                    auto_peak_previous = {
                        "hwp_deg": float(hwp_deg),
                        "qwp_readout_deg": float(
                            (learned_anchor_row or {}).get("qwp_readout_deg", q_learned)
                        ),
                        "anl_target_deg": float(
                            (learned_anchor_row or {}).get("anl_target_deg", peak_target)
                        ),
                        "lockin_mag_V": float(_learned_raw_uV("learned_anchor")) * 1e-6,
                    }
                    used_learned_triplet = True
                if not used_learned_triplet:
                    if null_ref_row is None:
                        sens_idx, null_ref_row, null_ref_raw = measure_lockin_null_reference(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            q_null=q_null,
                            a_null=a_null,
                            p_null=p_null,
                            p_null_mV=p_null_mV,
                            vpp=float(vpp),
                            rot_qwp=rot_qwp,
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            null_context=null_context,
                            t_start=t_start,
                        )
                        if null_ref_row is not None:
                            null_reference_rows.append(null_ref_row)
                            raw_rows.extend(null_ref_raw)
                            if progress is not None:
                                progress["points_done"] = int(progress.get("points_done", 0)) + 1
                                progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                    for slope_side, anl_target in slope_targets:
                        gui_pixel_checkpoint()
                        gui_update_state(
                            current_pixel=pix_num,
                            current_hwp_index=i_hwp,
                            current_hwp_total=len(hwp_angles),
                            current_hwp_deg=float(current_hwp_actual),
                            current_hwp_null_deg=float(current_hwp_actual),
                            current_qwp_deg=float(qwp_readout_actual),
                            current_qwp_target_deg=wrap360(qwp_readout_deg),
                            current_qwp_null_deg=wrap360(q_null),
                            current_anl_null_deg=wrap360(a_null),
                            current_anl_target_deg=wrap360(anl_target),
                            current_vpp=float(vpp),
                            current_slope_side=slope_side,
                            phase="Reading lock-in",
                            ac_voltage_on=True,
                            active_optic="ANL",
                        )
                        row, raw, sens_idx = measure_lockin_point(
                            pixel=pixel,
                            hwp_deg=float(hwp_deg),
                            q_null=q_null,
                            a_null=a_null,
                            p_null=p_null,
                            p_null_mV=p_null_mV,
                            slope_side=slope_side,
                            anl_target=anl_target,
                            vpp=float(vpp),
                            rot_anl=rot_anl,
                            detector=detector,
                            lockin=lockin,
                            sens_idx=sens_idx,
                            reference_phase_deg=reference_phase_deg,
                            fast_rotator_moves=fast_rotator_moves,
                            verify_moves=verify_fast_rotator_moves,
                            verify_tol_deg=rotator_verify_tol_deg,
                            null_context=null_context,
                            null_reference_row=null_ref_row,
                            t_start=t_start,
                        )
                        if null_status != "OK":
                            existing = str(row.get("quality_flags", ""))
                            row["quality_flags"] = ";".join(
                                flag for flag in (existing, null_status) if flag
                            )
                        rows.append(row)
                        hwp_rows.append(row)
                        raw_rows.extend(raw)
                        if progress is not None:
                            progress["points_done"] = int(progress.get("points_done", 0)) + 1
                            progress["pixel_points_done"] = int(progress.get("pixel_points_done", 0)) + 1
                            gui_update_state(
                                current_pixel=pix_num,
                                current_hwp_index=i_hwp,
                                current_hwp_total=len(hwp_angles),
                                current_hwp_deg=float(current_hwp_actual),
                                current_hwp_null_deg=float(current_hwp_actual),
                                current_qwp_deg=float(row.get("qwp_actual_deg", qwp_readout_actual)),
                                current_qwp_target_deg=wrap360(row.get("qwp_readout_deg", qwp_readout_deg)),
                                current_qwp_null_deg=wrap360(q_null),
                                current_anl_deg=float(row.get("anl_actual_deg", float("nan"))),
                                current_anl_null_deg=wrap360(a_null),
                                detector_mV=float(row.get("detector_V", float("nan"))) * 1e3,
                                detector_power_W=float(row.get("power_W", float("nan"))),
                                lockin_mag_V=float(row.get("lockin_mag_V", float("nan"))),
                                lockin_phase_deg=float(row.get("lockin_phase_deg", float("nan"))),
                                lockin_signed_V=float(row.get("lockin_signed_V", float("nan"))),
                                current_vpp=float(vpp),
                                current_slope_side=slope_side,
                                phase="Lock-in point complete",
                                chip_points_done=int(progress.get("points_done", 0)),
                                chip_total_points=int(progress.get("total_points", 0)),
                                pixel_points_done=int(progress.get("pixel_points_done", 0)),
                                pixel_total_points=int(progress.get("pixel_total_points", pixel_total_points)),
                                ac_voltage_on=True,
                                active_optic="LOCKIN",
                            )

                # Adaptive Figure-S9/Senarmont operating-point certificate.
                # The calibration pixel always receives the balanced joint
                # AC/DC fit at the strongest requested Vpp. Later pixels pay only
                # for their existing null/+45/-45 triplet unless that triplet
                # is inconclusive, in which case the same fit is added.
                if (
                    robust_paired_mode
                    and certificate_vpp is not None
                    and abs(float(vpp) - float(certificate_vpp)) <= 1e-9
                ):
                    if s9_null_reference_row is None:
                        s9_null_reference_row = null_ref_row
                    current_slope_rows = [
                        item
                        for item in hwp_rows
                        if abs(float(item.get("vpp", float("nan"))) - float(vpp)) <= 1e-9
                        and str(item.get("slope_side", "")) in {
                            "plus45", "minus45", "learned_anchor", "learned_opposite"
                        }
                    ]
                    quick_certificate = quick_s9_triplet_certificate(
                        null_reference_row=s9_null_reference_row,
                        slope_rows=current_slope_rows,
                        a_null=float(a_null),
                    )
                    quick_status = str(quick_certificate.get("status", "needs_fit"))
                    inherited_s9_status = (
                        str(readout_override.get("s9_status", ""))
                        if isinstance(readout_override, dict) else ""
                    )
                    if (
                        not bool(auto_peak_calibration)
                        and quick_status == "needs_fit"
                        and inherited_s9_status == "geometry_only_low_signal"
                        and str(quick_certificate.get("reason", ""))
                        == "triplet_derivative_alignment_or_symmetry_inconclusive"
                        and _finite_float_or_none(
                            quick_certificate.get("dc_balance_error")
                        ) is not None
                        and float(quick_certificate["dc_balance_error"])
                        <= float(S9_QUICK_MAX_DC_BALANCE_ERROR)
                    ):
                        quick_certificate.update({
                            "status": "geometry_only_low_signal",
                            "method": "triplet_plus_inherited_calibration_node",
                            "reason": "inherited_fitted_angular_node_with_valid_local_dc_triplet",
                        })
                        quick_status = "geometry_only_low_signal"
                    should_fit = bool(
                        quick_status != "failed"
                        and (
                            bool(auto_peak_calibration)
                            or quick_status == "needs_fit"
                        )
                    )
                    certificate = quick_certificate
                    fit_summary_rows: list[dict] = []
                    if should_fit:
                        plus_row, minus_row = _s9_quadrature_rows(
                            current_slope_rows, float(a_null)
                        )
                        if plus_row is None or minus_row is None:
                            certificate = {
                                "status": "failed",
                                "method": "balanced_dc_derivative_complex_fit",
                                "reason": "missing_opposite_quadrature_seeds",
                            }
                        else:
                            seed_records = []
                            for side, seed_row in (("plus45", plus_row), ("minus45", minus_row)):
                                seed_records.append({
                                    "side": side,
                                    "row": seed_row,
                                    "raw": [],
                                    "anl": float(seed_row.get("anl_target_deg", a_null)),
                                    "mag": float(lockin_peak_metric_value(seed_row)),
                                })
                            # Use a fixed branch for the DC quadrature.  Do not
                            # select the branch after comparing noisy AC
                            # magnitudes (winner-selection bias).
                            preferred_seed = next(
                                (
                                    record
                                    for record in seed_records
                                    if str(record.get("side", "")) == "plus45"
                                ),
                                seed_records[0],
                            )
                            (
                                fitted_row,
                                fitted_raw,
                                sens_idx,
                                fitted_probe_count,
                                fit_info,
                                fit_summary_rows,
                            ) = sinusoid_fit_analyser_peak(
                                pixel=pixel,
                                hwp_deg=float(hwp_deg),
                                q_null=float(q_null),
                                a_null=float(a_null),
                                p_null=float(p_null),
                                p_null_mV=float(p_null_mV),
                                vpp=float(vpp),
                                rot_anl=rot_anl,
                                detector=detector,
                                lockin=lockin,
                                sens_idx=sens_idx,
                                reference_phase_deg=reference_phase_deg,
                                fast_rotator_moves=fast_rotator_moves,
                                verify_moves=verify_fast_rotator_moves,
                                verify_tol_deg=rotator_verify_tol_deg,
                                base_null_context=s9_null_context,
                                null_reference_row=s9_null_reference_row,
                                t_start=t_start,
                                seed_records=seed_records,
                                best_seed=preferred_seed,
                            )
                            raw_rows.extend(fitted_raw)
                            existing_row_ids = {id(item) for item in rows}
                            for fitted_probe_row in fit_summary_rows:
                                if fitted_probe_row is s9_null_reference_row:
                                    continue
                                if id(fitted_probe_row) in existing_row_ids:
                                    continue
                                rows.append(fitted_probe_row)
                                hwp_rows.append(fitted_probe_row)
                                existing_row_ids.add(id(fitted_probe_row))
                            if progress is not None and fitted_probe_count:
                                progress["total_points"] = int(progress.get("total_points", 0)) + int(fitted_probe_count)
                                progress["pixel_total_points"] = int(
                                    progress.get("pixel_total_points", pixel_total_points)
                                ) + int(fitted_probe_count)
                                progress["points_done"] = int(progress.get("points_done", 0)) + int(fitted_probe_count)
                                progress["pixel_points_done"] = int(
                                    progress.get("pixel_points_done", 0)
                                ) + int(fitted_probe_count)
                            certificate = dict((fit_info or {}).get("s9_certificate") or {})
                            if not certificate:
                                certificate = {
                                    "status": "failed",
                                    "method": "balanced_dc_derivative_complex_fit",
                                    "reason": "fit_returned_no_certificate",
                                }
                            for diagnostic_key in (
                                "phase_flip_score",
                                "side_symmetry_ratio",
                                "dc_balance_error",
                                "null_leakage_fraction",
                            ):
                                if diagnostic_key not in certificate:
                                    certificate[diagnostic_key] = quick_certificate.get(
                                        diagnostic_key
                                    )
                            if fitted_row is not None:
                                fitted_row["peak_source"] = (
                                    "s9_dc_quadrature_operating_point"
                                    if str(certificate.get("status", "")) == "certified_fit"
                                    else "s9_geometry_only_seed"
                                )
                                fitted_row["peak_track_mode"] = "locked-qwp"

                    s9_hwp_certificate = certificate
                    rows_to_annotate = list(current_slope_rows)
                    rows_to_annotate.extend(fit_summary_rows)
                    if isinstance(s9_null_reference_row, dict):
                        rows_to_annotate.append(s9_null_reference_row)
                    unique_rows_to_annotate = []
                    seen_certificate_rows: set[int] = set()
                    for item in rows_to_annotate:
                        if id(item) not in seen_certificate_rows:
                            unique_rows_to_annotate.append(item)
                            seen_certificate_rows.add(id(item))
                    annotate_s9_certificate(unique_rows_to_annotate, certificate)
                    print(
                        f"  [S9 CERT] Pixel {pix_num:03d} HWP {float(hwp_deg):.3f}: "
                        f"{certificate.get('status', 'failed')} - "
                        f"{certificate.get('reason', '')}"
                    )
        finally:
            try:
                pockels._funcgen_set_sweep_output(
                    funcgen,
                    False,
                    verify_command=True,
                    required=True,
                    context=(
                        f"pixel {pix_num:03d} HWP {float(hwp_deg):.3f} "
                        "AC measurement cleanup"
                    ),
                )
            finally:
                gui_update_state(ac_voltage_on=False, phase="AC output off", current_vpp=None, current_slope_side="")
        gui_pixel_checkpoint()

        if s9_hwp_certificate:
            # One strongest-Vpp certificate establishes the optical geometry
            # for this HWP; propagate it to lower-Vpp slope rows before saving
            # and normalized analysis.
            hwp_certificate_rows = [
                item for item in hwp_rows
                if str(item.get("slope_side", "")) in {
                    "plus45", "minus45", "learned_anchor", "learned_opposite",
                    "auto_peak", "auto_peak_probe",
                }
            ]
            annotate_s9_certificate(hwp_certificate_rows, s9_hwp_certificate)

        branch_failures = manual_anchor_branch_failures(hwp_rows)
        write_rows(pixel_dir / FAST_MAP_CSV, rows, FAST_MAP_FIELDS)
        write_rows(pixel_dir / FAST_MAP_RAW_CSV, raw_rows, RAW_FIELDS)
        write_rows(pixel_dir / FAST_MAP_NULL_REF_CSV, null_reference_rows, FAST_MAP_FIELDS)
        write_rows(pixel_dir / FAST_MAP_PEAK_DIAGNOSTIC_CSV, peak_diagnostic_rows, PEAK_DIAGNOSTIC_FIELDS)
        write_json(pixel_dir / auto.NULL_SEEDS_JSON, null_seed_by_hwp)

        line = concise_hwp_line(
            hwp_rows,
            voltages,
            p_null,
            p_null_mV,
            time.time() - t_null,
            null_method,
            null_evals,
            null_escalated,
            null_label,
            rotator_verify_tol_deg,
            progress=progress,
        )
        print(line)
        peak_learn_rows = [
            row for row in hwp_rows
            if str(row.get("slope_side", "")) in (
                ("manual_anchor", "auto_peak", "plus45", "minus45")
                if auto_peak_calibration
                else ("manual_anchor", "auto_peak")
            )
        ]
        if peak_learn_rows:
            override = learn_readout_override_from_manual_anchor(
                hwp_key=hwp_key,
                hwp_deg=float(hwp_deg),
                rows=hwp_rows,
                null_seed_by_hwp=null_seed_by_hwp,
                pixel_num=pix_num,
                require_standard_comparison=False,
                allow_standard_slopes=bool(auto_peak_calibration),
            )
            if override:
                write_json(pixel_dir / auto.NULL_SEEDS_JSON, null_seed_by_hwp)
                write_peak_lock_table(pixel_dir, null_seed_by_hwp, hwp_angles)
                print(
                    f"  [PEAK LEARN] HWP {float(hwp_deg):.3f} deg saved peak readout "
                    f"QWP={override['qwp_readout_deg']:.3f}, "
                    f"ANL={override['anl_target_deg']:.3f}, "
                    f"metric={float(override.get('lockin_metric_V', float('nan'))) * 1e6:.3f} uV "
                    f"({override.get('lockin_metric_source', 'raw_mag')}) for later pixels."
                )
            elif null_hard_fail:
                print(
                    f"  [PEAK LEARN] HWP {float(hwp_deg):.3f} deg readout was "
                    "measured but not saved for later pixels because its null "
                    "exceeded the hard certification limit."
                )
            elif branch_failures:
                print(
                    f"  [PEAK LEARN] HWP {float(hwp_deg):.3f} deg found peak branch "
                    f"but could not save override: {'; '.join(branch_failures)}."
                )

    summary = summarize_fast_map(pixel, rows, voltages)
    peak = peak_from_fast_summary(summary)
    try:
        from pockels_angular_plots import save_pixel_angular_products

        angular_products = save_pixel_angular_products(pixel_dir, summary)
        summary["angular_products"] = [str(path) for path in angular_products]
        if angular_products:
            print(
                f"  [ANGULAR] Pixel {pix_num:03d}: saved normalized polar/theory "
                f"products ({len(angular_products)} files)."
            )
    except Exception as exc:
        # Plotting is derived output and must never sacrifice completed hardware
        # data. The numerical fit remains available for later replotting.
        summary["angular_plot_error"] = f"{type(exc).__name__}: {exc}"
        print(
            f"  [ANGULAR] WARNING Pixel {pix_num:03d}: plot save failed: "
            f"{type(exc).__name__}: {exc}"
        )
    write_json(pixel_dir / FAST_MAP_SUMMARY_JSON, summary)
    write_json(pixel_dir / PEAK_RESPONSE_JSON, peak)
    write_peak_lock_table(pixel_dir, null_seed_by_hwp, hwp_angles)
    return sens_idx, (current_q_seed, current_a_seed), peak


def progress_suffix(progress: dict | None) -> str:
    if not progress:
        return ""
    done = int(progress.get("points_done", 0))
    total = int(progress.get("total_points", 0))
    start = float(progress.get("start", time.time()))
    elapsed = max(0.0, time.time() - start)
    if done <= 0 or total <= 0:
        return f" | elapsed {fmt_duration(elapsed)}"
    warmup_points = min(total, max(24, int(math.ceil(total * 0.01))))
    if done < warmup_points:
        return f" | {done}/{total} pts | elapsed {fmt_duration(elapsed)} | ETA warming up"
    rate = done / max(elapsed, 1e-9)
    eta = (total - done) / rate if rate > 0 else float("nan")
    return f" | {done}/{total} pts | elapsed {fmt_duration(elapsed)} | ETA {fmt_duration(eta)}"


def manual_anchor_branch_failures(
    rows: list[dict],
    *,
    ratio: float = MANUAL_ANCHOR_PEAK_MISS_RATIO,
    min_delta_uV: float = MANUAL_ANCHOR_PEAK_MISS_MIN_UV,
) -> list[str]:
    failures = []
    by_vpp: dict[float, list[dict]] = {}
    for row in rows:
        try:
            vpp = float(row.get("vpp", float("nan")))
        except Exception:
            continue
        if not np.isfinite(vpp):
            continue
        by_vpp.setdefault(vpp, []).append(row)

    for vpp, group in sorted(by_vpp.items()):
        anchors = [
            row for row in group
            if str(row.get("slope_side", "")) in ("manual_anchor", "auto_peak")
        ]
        for anchor in anchors:
            if row_has_quality_flag(anchor, "peak_diagnostic_failed", "peak_diagnostic_incomplete"):
                anchor_uV = lockin_peak_metric_value(anchor) * 1e6
                failures.append(
                    f"{float(vpp):g} Vpp {anchor.get('slope_side')} peak diagnostic failed "
                    f"at metric={anchor_uV:.3f} uV"
                )
        slopes = [
            row for row in group
            if str(row.get("slope_side", "")) in ("plus45", "minus45")
        ]
        if not anchors or not slopes:
            continue
        anchor = max(
            anchors,
            key=lockin_peak_metric_value,
        )
        slope = max(
            slopes,
            key=lockin_peak_metric_value,
        )
        anchor_uV = lockin_peak_metric_value(anchor) * 1e6
        slope_uV = lockin_peak_metric_value(slope) * 1e6
        if not (np.isfinite(anchor_uV) and np.isfinite(slope_uV)):
            continue
        delta_uV = float(anchor_uV) - float(slope_uV)
        if delta_uV >= float(min_delta_uV) and float(anchor_uV) >= float(ratio) * max(float(slope_uV), 1e-9):
            append_row_quality(anchor, "manual_anchor_peak_missed_by_null_branch")
            append_row_quality(slope, "manual_anchor_peak_missed_by_null_branch")
            failures.append(
                f"{float(vpp):g} Vpp anchor metric={anchor_uV:.3f} uV but best "
                f"{slope.get('slope_side')} metric={slope_uV:.3f} uV"
            )
    return failures


def learn_readout_override_from_manual_anchor(
    *,
    hwp_key: str,
    hwp_deg: float,
    rows: list[dict],
    null_seed_by_hwp: dict,
    pixel_num: int,
    ratio: float = MANUAL_ANCHOR_PEAK_MISS_RATIO,
    min_delta_uV: float = MANUAL_ANCHOR_PEAK_MISS_MIN_UV,
    require_standard_comparison: bool = True,
    allow_standard_slopes: bool = False,
) -> dict | None:
    """Persist a stronger manual-anchor readout branch for later pixels."""
    anchor_sides = {"manual_anchor", "auto_peak"}
    if bool(allow_standard_slopes):
        anchor_sides.update(("plus45", "minus45"))
    anchors_all = [
        row for row in rows
        if str(row.get("slope_side", "")) in anchor_sides
    ]
    anchors = [
        row for row in anchors_all
        if not row_has_quality_flag(row, "peak_diagnostic_failed", "peak_diagnostic_incomplete")
        and not row_has_untrusted_null(row)
        and not row_has_angle_failure(row)
    ]
    slopes = [
        row for row in rows
        if str(row.get("slope_side", "")) in ("plus45", "minus45")
    ]
    if not anchors or (require_standard_comparison and not slopes):
        return None
    anchor = max(
        anchors,
        key=lambda row: (
            int(
                str(row.get("s9_status", "")) == "certified_fit"
                and str(row.get("peak_source", ""))
                == "s9_dc_quadrature_operating_point"
            ),
            lockin_peak_metric_value(row),
        ),
    )
    anchor_mag = lockin_peak_metric_value(anchor)
    if not np.isfinite(anchor_mag):
        return None
    slope = None
    slope_mag = float("nan")
    delta_uV = float("nan")
    if slopes:
        slope = max(
            slopes,
            key=lockin_peak_metric_value,
        )
        slope_mag = lockin_peak_metric_value(slope)
        if not np.isfinite(slope_mag):
            return None
        delta_uV = (float(anchor_mag) - float(slope_mag)) * 1e6
        if (
            require_standard_comparison
            and (
                delta_uV < float(min_delta_uV)
                or float(anchor_mag) < float(ratio) * max(float(slope_mag), 1e-12)
            )
        ):
            return None
    try:
        qwp_deg = float(anchor.get("qwp_readout_deg", anchor.get("q_null_deg")))
        anl_deg = float(anchor.get("anl_target_deg"))
        vpp = float(anchor.get("vpp", float("nan")))
    except Exception:
        return None
    if not (np.isfinite(qwp_deg) and np.isfinite(anl_deg)):
        return None
    has_measured_null = (
        _finite_float_or_none(anchor.get("p_null_mV")) is not None
        or _finite_float_or_none(anchor.get("seed_q_null_deg")) is not None
    )
    q_null = _finite_float_or_none(anchor.get("q_null_deg")) if has_measured_null else None
    a_null = _finite_float_or_none(anchor.get("a_null_deg")) if has_measured_null else None
    q_offset = (
        _finite_float_or_none(anchor.get("qwp_readout_offset_from_null_deg"))
        if has_measured_null else None
    )
    if q_offset is None and q_null is not None:
        q_offset = periodic_delta_deg(q_null, qwp_deg, 180.0)
    a_offset = (
        _finite_float_or_none(anchor.get("anl_offset_from_null_deg"))
        if has_measured_null else None
    )
    if a_offset is None and a_null is not None:
        a_offset = analyser_offset_from_null_deg(a_null, anl_deg)
    anchor_raw_mag = _finite_float_or_none(anchor.get("lockin_mag_V"))
    anchor_net_mag = _finite_float_or_none(anchor.get("lockin_net_mag_V"))
    anchor_phase = _finite_float_or_none(anchor.get("lockin_phase_deg"))

    override = {
        "source": str(anchor.get("slope_side", "manual_anchor")),
        "pixel": int(pixel_num),
        "hwp_deg": float(hwp_deg),
        "qwp_readout_deg": wrap360(qwp_deg),
        "anl_target_deg": wrap360(anl_deg),
        "qwp_readout_offset_from_null_deg": float(q_offset) if q_offset is not None else None,
        "anl_offset_from_null_deg": float(a_offset) if a_offset is not None else None,
        "q_null_deg": float(q_null) if q_null is not None else None,
        "a_null_deg": float(a_null) if a_null is not None else None,
        "vpp": vpp,
        "lockin_metric_V": float(anchor_mag),
        "lockin_metric_source": lockin_peak_metric_source(anchor),
        "lockin_mag_V": float(anchor_raw_mag) if anchor_raw_mag is not None else None,
        "lockin_net_mag_V": float(anchor_net_mag) if anchor_net_mag is not None else None,
        "lockin_phase_deg": float(anchor_phase) if anchor_phase is not None else None,
        "chosen_side": str(anchor.get("chosen_side", anchor.get("slope_side", ""))),
        "phase_flip_score": anchor.get("phase_flip_score", None),
        "side_symmetry_ratio": anchor.get("side_symmetry_ratio", None),
        "snr_estimate": anchor.get("snr_estimate", None),
        "s9_status": anchor.get("s9_status", ""),
        "s9_method": anchor.get("s9_method", ""),
        "s9_reason": anchor.get("s9_reason", ""),
        "s9_complex_r_squared": anchor.get("s9_complex_r_squared", None),
        "s9_dc_r_squared": anchor.get("s9_dc_r_squared", None),
        "s9_midfringe_fraction": anchor.get("s9_midfringe_fraction", None),
        "s9_peak_shift_deg": anchor.get("s9_peak_shift_deg", None),
        "s9_null_leakage_fraction": anchor.get("s9_null_leakage_fraction", None),
        "s9_fit_signal_to_residual": anchor.get("s9_fit_signal_to_residual", None),
        "s9_fit_amplitude_V": anchor.get("s9_fit_amplitude_V", None),
        "s9_pickup_fraction": anchor.get("s9_pickup_fraction", None),
        "quality": anchor.get("quality", ""),
        "quality_flags": anchor.get("quality_flags", ""),
        "best_standard_slope_side": str(slope.get("slope_side", "")) if slope else "",
        "best_standard_lockin_mag_V": float(slope_mag) if np.isfinite(slope_mag) else None,
        "delta_over_standard_uV": float(delta_uV) if np.isfinite(delta_uV) else None,
        "standard_comparison_required": bool(require_standard_comparison),
        "updated": datetime.now().isoformat(),
    }
    seed = dict(null_seed_by_hwp.get(hwp_key, {}))
    seed["readout_override"] = override
    null_seed_by_hwp[hwp_key] = seed
    return override


ANALYSER_SWEEP_SOURCE_SIDES = {
    "auto_peak",
    "manual_anchor",
    "learned_anchor",
    "peak_diag_center",
    "peak_diag_q_minus",
    "peak_diag_q_plus",
    "peak_diag_a_minus",
    "peak_diag_a_plus",
}


def best_hwp_from_fast_map_summary(pixel_dir: Path) -> float | None:
    summary_path = Path(pixel_dir) / FAST_MAP_SUMMARY_JSON
    if not summary_path.is_file():
        return None
    try:
        summary = json.loads(summary_path.read_text(encoding="utf-8"))
    except Exception:
        return None
    certificate = summary.get("normalized_peak_certificate") or {}
    if str(certificate.get("status", "")) == "certified":
        value = _finite_float_or_none(certificate.get("hwp_deg"))
        if value is not None:
            return float(value)
    for key in ("best_hwp_deg", "best_mag_hwp_deg"):
        value = _finite_float_or_none(summary.get(key))
        if value is not None:
            return float(value)
    return None


def filter_analyser_points_to_peak_hwp(
    points: list[dict],
    *,
    pixel_dir: Path | None = None,
    peak_hwp_only: bool = True,
) -> list[dict]:
    if not peak_hwp_only or len(points) <= 1:
        return points

    best_hwp = best_hwp_from_fast_map_summary(pixel_dir) if pixel_dir is not None else None
    if best_hwp is not None:
        selected = min(
            points,
            key=lambda point: abs(periodic_delta_deg(float(best_hwp), float(point["theta_i"]), 360.0)),
        )
    else:
        def point_mag(point: dict) -> float:
            value = _finite_float_or_none(point.get("mag"))
            return abs(value) if value is not None else -1.0

        selected = max(
            points,
            key=point_mag,
        )

    filtered = [dict(selected)]
    filtered[0]["source_hwp_index"] = filtered[0].get("hwp_index")
    filtered[0]["hwp_index"] = 1
    filtered[0]["peak_hwp_only"] = True
    return filtered


def build_analyser_sweep_points_from_fast_map_csv(
    pixel_dir: Path,
    *,
    peak_hwp_only: bool = True,
    allow_untrusted_fallback: bool = False,
) -> list[dict]:
    csv_path = Path(pixel_dir) / FAST_MAP_CSV
    if not csv_path.is_file():
        raise FileNotFoundError(f"Fast-map CSV not found: {csv_path}")
    with csv_path.open("r", newline="") as handle:
        rows = [row for row in csv.DictReader(handle)]
    best_by_hwp: dict[float, dict] = {}
    used_untrusted_fallback = False
    passes = (False, True) if allow_untrusted_fallback else (False,)
    for include_untrusted in passes:
        best_by_hwp = {}
        for row in rows:
            if row_has_untrusted_null(row) and not include_untrusted:
                continue
            if row_has_angle_failure(row):
                continue
            side = str(row.get("slope_side") or "").strip()
            if side not in ANALYSER_SWEEP_SOURCE_SIDES:
                continue
            hwp = _finite_float_or_none(row.get("hwp_deg"))
            qwp = _finite_float_or_none(row.get("qwp_readout_deg"))
            if qwp is None:
                qwp = _finite_float_or_none(row.get("q_null_deg"))
            anl = _finite_float_or_none(row.get("anl_target_deg"))
            if anl is None:
                anl = _finite_float_or_none(row.get("a_null_deg"))
            mag = _finite_float_or_none(row.get("lockin_mag_V"))
            if mag is None:
                mag = _finite_float_or_none(row.get("lockin_net_mag_V"))
            if hwp is None or qwp is None or anl is None or mag is None:
                continue
            key = round(float(hwp), 6)
            old = best_by_hwp.get(key)
            old_mag = _finite_float_or_none((old or {}).get("lockin_mag_V"))
            if old_mag is None:
                old_mag = _finite_float_or_none((old or {}).get("lockin_net_mag_V"))
            if old is None or old_mag is None or abs(float(mag)) > abs(float(old_mag)):
                best_by_hwp[key] = row
        if best_by_hwp:
            used_untrusted_fallback = bool(include_untrusted)
            break

    points: list[dict] = []
    for idx, hwp_key in enumerate(sorted(best_by_hwp), start=1):
        row = best_by_hwp[hwp_key]
        hwp = float(hwp_key)
        qwp_readout = _finite_float_or_none(row.get("qwp_readout_deg"))
        if qwp_readout is None:
            qwp_readout = _finite_float_or_none(row.get("q_null_deg"))
        q_null = _finite_float_or_none(row.get("q_null_deg"))
        if q_null is None:
            q_null = qwp_readout
        anl_target = _finite_float_or_none(row.get("anl_target_deg"))
        if anl_target is None:
            anl_target = _finite_float_or_none(row.get("a_null_deg"))
        a_null = _finite_float_or_none(row.get("a_null_deg"))
        if a_null is None:
            a_null = anl_target
        vpp = _finite_float_or_none(row.get("vpp"))
        mag = _finite_float_or_none(row.get("lockin_mag_V"))
        if mag is None:
            mag = _finite_float_or_none(row.get("lockin_net_mag_V"))
        theta_i = _finite_float_or_none(row.get("theta_i_deg"))
        if theta_i is None:
            theta_i = theta_i_from_hwp(hwp)
        points.append({
            "hwp_index": int(idx),
            "theta_i": hwp,
            "hwp_deg": hwp,
            "theta_i_deg": theta_i,
            "theta_i_legacy_deg": (
                _finite_float_or_none(row.get("theta_i_legacy_deg"))
                or legacy_theta_i_from_hwp(hwp)
            ),
            "q_null": float(q_null),
            "q_null_theta_wav_deg": (
                _finite_float_or_none(row.get("qwp_theta_wav_deg"))
                or qwp_theta_wav_from_raw(q_null, theta_i_deg=theta_i)
            ),
            "qwp_angle": float(qwp_readout),
            "qwp_readout": float(qwp_readout),
            "qwp_readout_deg": float(qwp_readout),
            "qwp_readout_axis_lab_deg": (
                _finite_float_or_none(row.get("qwp_readout_axis_lab_deg"))
                or qwp_axis_lab_from_raw(qwp_readout)
            ),
            "qwp_readout_theta_wav_deg": (
                _finite_float_or_none(row.get("qwp_readout_theta_wav_deg"))
                or qwp_theta_wav_from_raw(qwp_readout, theta_i_deg=theta_i)
            ),
            "qwp_theta_wav_deg": (
                _finite_float_or_none(row.get("qwp_readout_theta_wav_deg"))
                or qwp_theta_wav_from_raw(qwp_readout, theta_i_deg=theta_i)
            ),
            "anl_angle": float(anl_target),
            "anl_target_deg": float(anl_target),
            "anl_lab_deg": (
                _finite_float_or_none(row.get("anl_target_lab_deg"))
                or analyser_lab_from_raw(anl_target)
            ),
            "anl_theta_ana_deg": (
                _finite_float_or_none(row.get("anl_target_theta_ana_deg"))
                or analyser_theta_ana_from_raw(anl_target, theta_i_deg=theta_i)
            ),
            "a_null": float(a_null),
            "a_null_lab_deg": (
                _finite_float_or_none(row.get("a_null_lab_deg"))
                or analyser_lab_from_raw(a_null)
            ),
            "a_null_theta_ana_deg": (
                _finite_float_or_none(row.get("a_null_theta_ana_deg"))
                or analyser_theta_ana_from_raw(a_null, theta_i_deg=theta_i)
            ),
            "vpp": float(vpp) if vpp is not None else float("nan"),
            "mag": float(mag) if mag is not None else float("nan"),
            "lockin_mag_V": float(mag) if mag is not None else float("nan"),
            "slope_side": str(row.get("slope_side") or ""),
            "quality_flags": str(row.get("quality_flags") or ""),
            "untrusted_high_null_fallback": bool(used_untrusted_fallback),
        })
    if not points:
        raise ValueError(f"No analyser-sweep source rows found in {csv_path}")
    return filter_analyser_points_to_peak_hwp(
        points,
        pixel_dir=Path(pixel_dir),
        peak_hwp_only=bool(peak_hwp_only),
    )


def run_post_fast_map_analyser_sweeps(
    *,
    pixel: dict,
    pixel_dir: Path,
    vpp_values: list[float],
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    funcgen,
    smu,
    sens_idx: int,
    dc_hold_v: float,
    poling_dwell_s: float,
    anl_start: float,
    anl_stop: float,
    anl_step: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    peak_hwp_only: bool = True,
) -> int:
    points = build_analyser_sweep_points_from_fast_map_csv(
        pixel_dir,
        peak_hwp_only=bool(peak_hwp_only),
    )
    angles = pockels._build_anl_sweep_angles(float(anl_start), float(anl_stop), float(anl_step))
    sweep_root = Path(pixel_dir) / "analyser_sweeps"
    sweep_root.mkdir(parents=True, exist_ok=True)
    metadata_path = sweep_root / "analyser_sweep_plan.json"
    write_json(metadata_path, {
        "pixel": int(pixel.get("pixel", 0) or 0),
        "created": datetime.now().isoformat(),
        "peak_hwp_only": bool(peak_hwp_only),
        "vpp_values": [float(v) for v in vpp_values],
        "analyser_angles_deg": [float(a) for a in angles],
        "dc_hold_v": float(dc_hold_v),
        "poling_dwell_s": float(poling_dwell_s),
        "points": points,
    })
    print(
        f"\n[ANL SWEEP] Pixel {int(pixel.get('pixel', 0) or 0):03d}: "
        f"{len(points)} HWP point(s) x {len(vpp_values)} Vpp value(s) x {len(angles)} analyser angles."
    )
    auto.smu_set_level_output_on(smu, float(dc_hold_v))
    pockels.smu_ensure_output_on(smu)
    total = len(points) * len(vpp_values)
    done = 0
    for point in points:
        gui_pixel_checkpoint()
        print(
            f"\n[ANL SWEEP] HWP {int(point['hwp_index'])}/{len(points)} "
            f"raw {float(point['theta_i']):.3f} deg: QWP={float(point['qwp_angle']):.3f}, "
            f"ANL seed={float(point['anl_angle']):.3f}"
        )
        hwp_move = fast_rotator_move_or_fallback(
            rot_hwp,
            float(point["theta_i"]),
            fast=fast_rotator_moves,
            verify=verify_moves,
            tol_deg=verify_tol_deg,
            label="HWP analyser sweep",
        )
        require_verified_move(hwp_move, "HWP analyser sweep")
        qwp_move = fast_rotator_move_or_fallback(
            rot_qwp,
            float(point["qwp_angle"]),
            fast=fast_rotator_moves,
            verify=verify_moves,
            tol_deg=verify_tol_deg,
            label="QWP analyser sweep",
        )
        require_verified_move(qwp_move, "QWP analyser sweep")
        for i_vpp, vpp in enumerate(vpp_values, start=1):
            gui_pixel_checkpoint()
            done += 1
            gui_update_state(
                current_pixel=int(pixel.get("pixel", 0) or 0),
                current_hwp_deg=float(point["theta_i"]),
                current_qwp_target_deg=float(point["qwp_angle"]),
                current_anl_target_deg=float(point["anl_angle"]),
                current_vpp=float(vpp),
                current_slope_side="analyser_sweep",
                dc_voltage_on=True,
                ac_voltage_on=True,
                phase=f"Analyser sweep {done}/{total}",
            )
            hwp_dir = f"hwp_{int(point['hwp_index']):03d}_{float(point['theta_i']):.3f}deg"
            vpp_dir = f"{float(vpp):g}Vpp"
            out_dir = sweep_root / hwp_dir / vpp_dir
            point_for_vpp = dict(point)
            point_for_vpp["vpp"] = float(vpp)
            run_label = (
                f"pixel_{int(pixel.get('pixel', 0) or 0):03d} "
                f"HWP {int(point['hwp_index'])}/{len(points)} "
                f"{float(vpp):g} Vpp"
            )
            sens_idx = pockels.run_analyser_sweep_at_peak(
                smu,
                rot_anl,
                detector,
                lockin,
                funcgen,
                sens_idx,
                str(out_dir),
                run_label,
                point_for_vpp,
                angles_deg=angles,
                dc_hold_v=float(dc_hold_v),
                vpp=float(vpp),
                poling_dwell_s=float(poling_dwell_s) if i_vpp == 1 else 0.0,
            )
    print(f"\n[ANL SWEEP] Pixel {int(pixel.get('pixel', 0) or 0):03d}: saved under {sweep_root}")
    return sens_idx


def _first_finite_followup_value(*values, default=None):
    for value in values:
        numeric = _finite_float_or_none(value)
        if numeric is not None:
            return numeric
    return default


def raw_magnitude_peak_from_fast_map_csv(
    *,
    pixel: dict,
    pixel_dir: Path,
    allow_untrusted_fallback: bool = False,
) -> dict:
    """Load the largest geometry-valid historical raw row as a legacy fallback.

    A raw-magnitude row is never allowed to outrank optical geometry.  Saved
    angles remain physical motor setpoints, but high-null rows, QWP offsets
    beyond the compensation tolerance, and analyser positions outside the
    quadrature window are excluded.  ``allow_untrusted_fallback`` may return an
    unsafe row for inspection only; it is explicitly ineligible for hysteresis.
    """
    pixel_dir = Path(pixel_dir)
    csv_path = pixel_dir / FAST_MAP_CSV
    if not csv_path.is_file():
        raise FileNotFoundError(f"Fast-map CSV not found: {csv_path}")
    with csv_path.open("r", newline="") as handle:
        rows = [row for row in csv.DictReader(handle)]

    selected: dict | None = None
    selected_mag = float("-inf")
    unsafe_selected: dict | None = None
    unsafe_selected_mag = float("-inf")
    for row in rows:
        hwp = _finite_float_or_none(row.get("hwp_deg"))
        qwp_readout = _first_finite_followup_value(
            row.get("qwp_readout_deg"),
            row.get("q_null_deg"),
        )
        q_null = _first_finite_followup_value(
            row.get("q_null_deg"),
            qwp_readout,
        )
        anl_target = _first_finite_followup_value(
            row.get("anl_target_deg"),
            row.get("a_null_deg"),
        )
        a_null = _first_finite_followup_value(
            row.get("a_null_deg"),
            anl_target,
        )
        qwp_geometry = _first_finite_followup_value(
            row.get("qwp_readout_actual_deg"),
            row.get("qwp_actual_deg"),
            qwp_readout,
        )
        anl_geometry = _first_finite_followup_value(
            row.get("anl_actual_deg"),
            anl_target,
        )
        a_null_geometry = _first_finite_followup_value(
            row.get("anl_null_actual_deg"),
            a_null,
        )
        vpp = _finite_float_or_none(row.get("vpp"))
        mag = _finite_float_or_none(row.get("lockin_mag_V"))
        if any(
            value is None
            for value in (
                hwp, qwp_readout, qwp_geometry, q_null,
                anl_target, anl_geometry, a_null, a_null_geometry, vpp, mag,
            )
        ):
            continue
        if float(vpp) <= 0.0:
            continue
        magnitude = abs(float(mag))
        if magnitude > unsafe_selected_mag:
            unsafe_selected = row
            unsafe_selected_mag = magnitude
        q_error = abs((float(qwp_geometry) - float(q_null) + 90.0) % 180.0 - 90.0)
        beta = (float(anl_geometry) - float(a_null_geometry) + 90.0) % 180.0 - 90.0
        quadrature_error = abs(abs(beta) - 45.0)
        geometry_valid = bool(
            not row_has_untrusted_null(row)
            and not row_has_angle_failure(row)
            and q_error <= float(MAX_QWP_OFFSET_FROM_NULL_DEG)
            and quadrature_error <= float(MAX_ANALYSER_QUADRATURE_ERROR_DEG)
        )
        if geometry_valid and magnitude > selected_mag:
            selected = row
            selected_mag = magnitude

    pix = int(pixel.get("pixel", 0) or 0)
    unsafe_fallback = False
    if selected is None and allow_untrusted_fallback and unsafe_selected is not None:
        selected = unsafe_selected
        selected_mag = unsafe_selected_mag
        unsafe_fallback = True
    if selected is None:
        raise ValueError(
            f"Pixel {pix:03d} has no geometry-certified historical peak row in {csv_path}."
        )

    hwp = float(selected["hwp_deg"])
    qwp_readout = float(
        _first_finite_followup_value(
            selected.get("qwp_readout_deg"),
            selected.get("q_null_deg"),
        )
    )
    q_null = float(
        _first_finite_followup_value(selected.get("q_null_deg"), qwp_readout)
    )
    anl_target = float(
        _first_finite_followup_value(
            selected.get("anl_target_deg"),
            selected.get("a_null_deg"),
        )
    )
    a_null = float(
        _first_finite_followup_value(selected.get("a_null_deg"), anl_target)
    )
    theta_i_deg = _first_finite_followup_value(selected.get("theta_i_deg"))
    selected_has_untrusted_null = row_has_untrusted_null(selected)
    qwp_geometry = float(_first_finite_followup_value(
        selected.get("qwp_readout_actual_deg"),
        selected.get("qwp_actual_deg"),
        qwp_readout,
    ))
    anl_geometry = float(_first_finite_followup_value(
        selected.get("anl_actual_deg"),
        anl_target,
    ))
    a_null_geometry = float(_first_finite_followup_value(
        selected.get("anl_null_actual_deg"),
        a_null,
    ))
    q_error = abs((qwp_geometry - q_null + 90.0) % 180.0 - 90.0)
    beta = (anl_geometry - a_null_geometry + 90.0) % 180.0 - 90.0
    quadrature_error = abs(abs(beta) - 45.0)
    geometry_certified = bool(
        not unsafe_fallback
        and not selected_has_untrusted_null
        and not row_has_angle_failure(selected)
        and q_error <= float(MAX_QWP_OFFSET_FROM_NULL_DEG)
        and quadrature_error <= float(MAX_ANALYSER_QUADRATURE_ERROR_DEG)
    )
    return {
        "source": (
            "historical_fast_map_geometry_certified_raw_fallback"
            if geometry_certified
            else "historical_fast_map_unsafe_raw_inspection_only"
        ),
        "source_fast_map_csv": str(csv_path),
        "source_pixel_dir": str(pixel_dir),
        "source_coordinate_policy": "saved raw physical motor setpoints; no lab-frame reinterpretation",
        "selection_metric": "lockin_mag_V",
        "selection_policy": (
            "largest finite raw magnitude after high-null, QWP-compensation, "
            "and analyser-quadrature gates"
        ),
        "pixel": pix,
        "theta_i": hwp,
        "hwp_deg": hwp,
        "theta_i_deg": theta_i_deg,
        "theta_i_legacy_deg": _first_finite_followup_value(
            selected.get("theta_i_legacy_deg")
        ),
        "q_null": q_null,
        "qwp_null": q_null,
        "q_calibration_null": q_null,
        "qwp_angle": qwp_readout,
        "qwp_readout": qwp_readout,
        "anl_angle": anl_target,
        "anl_target_deg": anl_target,
        "a_null": a_null,
        "vpp": float(selected["vpp"]),
        "mag": float(selected["lockin_mag_V"]),
        "mag_source": "raw_lockin_mag_V",
        "slope_side": str(selected.get("slope_side") or ""),
        "quality_flags": str(selected.get("quality_flags") or ""),
        "quality_flags_ignored_for_selection": False,
        "selected_row_has_untrusted_null": bool(selected_has_untrusted_null),
        "untrusted_high_null_fallback": bool(unsafe_fallback),
        "geometry_certified": bool(geometry_certified),
        "normalized_peak_certified": False,
        "hysteresis_eligible": bool(geometry_certified),
        "qwp_offset_from_null_deg": float(q_error),
        "analyser_offset_from_null_deg": float(beta),
        "analyser_quadrature_error_deg": float(quadrature_error),
        "historical_raw_motor_angles": True,
    }


def normalized_peak_from_fast_map_csv(
    *,
    pixel: dict,
    pixel_dir: Path,
) -> dict:
    """Reanalyse saved rows with the normalized Sénarmont pipeline."""
    pixel_dir = Path(pixel_dir)
    csv_path = pixel_dir / FAST_MAP_CSV
    if not csv_path.is_file():
        raise FileNotFoundError(f"Fast-map CSV not found: {csv_path}")
    with csv_path.open("r", newline="") as handle:
        rows = [row for row in csv.DictReader(handle)]
    voltages = sorted({
        float(value)
        for value in (_finite_float_or_none(row.get("vpp")) for row in rows)
        if value is not None and value > 0.0
    })
    if not rows or not voltages:
        raise ValueError(f"No usable fast-map rows in {csv_path}")
    summary = summarize_fast_map(pixel, rows, voltages)
    peak = peak_from_fast_summary(summary)
    if not bool(peak.get("normalized_peak_certified", False)):
        raise ValueError(
            f"Pixel {int(pixel.get('pixel', 0) or 0):03d} saved rows do not "
            "produce a normalized geometry-certified peak."
        )
    peak.update({
        "source": "historical_fast_map_reanalysed_normalized_senarmont",
        "source_fast_map_csv": str(csv_path),
        "source_pixel_dir": str(pixel_dir),
        "source_coordinate_policy": (
            "saved raw physical motor setpoints; normalized response recomputed "
            "with current quality gates"
        ),
        "historical_raw_motor_angles": True,
        "hysteresis_eligible": True,
    })
    return peak


def legacy_raw_peak_fallback_allowed(
    summary: dict,
    *,
    allow_untrusted_fallback: bool = False,
) -> bool:
    """Keep raw fallback for legacy data, not failed modern certificates."""
    if bool(allow_untrusted_fallback):
        return True
    certificate = summary.get("normalized_peak_certificate")
    is_modern_summary = bool(
        isinstance(certificate, dict)
        and str(certificate.get("status", "")).strip()
    )
    return not is_modern_summary


def fast_map_peak_for_followup(
    *,
    pixel: dict,
    pixel_dir: Path,
    peak_conditions: dict | None = None,
    allow_untrusted_fallback: bool = False,
) -> dict:
    pixel_dir = Path(pixel_dir)
    candidate = dict(peak_conditions or {})
    peak_json = pixel_dir / PEAK_RESPONSE_JSON
    saved_peak = {}
    if peak_json.is_file():
        try:
            saved_peak = json.loads(peak_json.read_text(encoding="utf-8"))
        except Exception:
            saved_peak = {}
    try:
        summary = json.loads((pixel_dir / FAST_MAP_SUMMARY_JSON).read_text(encoding="utf-8"))
    except Exception:
        summary = {}
    summary_peak = peak_from_fast_summary(summary) if summary else {}

    def eligible(item: dict) -> bool:
        return bool(
            item
            and (
                item.get("normalized_peak_certified")
                or item.get("hysteresis_eligible")
            )
        )

    # Prefer a freshly supplied certificate, then the normalized saved
    # summary/peak.  Historical CSV rows are reanalysed before the strictly
    # geometry-gated raw fallback is considered.
    if not eligible(candidate):
        if eligible(summary_peak):
            candidate = dict(summary_peak)
        elif eligible(saved_peak):
            candidate = dict(saved_peak)
        else:
            try:
                candidate = normalized_peak_from_fast_map_csv(
                    pixel=pixel,
                    pixel_dir=pixel_dir,
                )
            except (FileNotFoundError, ValueError):
                candidate = {}
    if not candidate and legacy_raw_peak_fallback_allowed(
        summary,
        allow_untrusted_fallback=bool(allow_untrusted_fallback),
    ):
        try:
            candidate = raw_magnitude_peak_from_fast_map_csv(
                pixel=pixel,
                pixel_dir=pixel_dir,
                allow_untrusted_fallback=bool(allow_untrusted_fallback),
            )
        except (FileNotFoundError, ValueError):
            candidate = {}

    hwp_deg = _first_finite_followup_value(
        candidate.get("theta_i"),
        candidate.get("hwp_deg"),
        summary_peak.get("theta_i"),
        summary_peak.get("hwp_deg"),
        summary.get("best_mag_hwp_deg"),
        summary.get("best_hwp_deg"),
    )
    qwp_readout = _first_finite_followup_value(
        candidate.get("qwp_angle"),
        candidate.get("qwp_readout"),
        summary_peak.get("qwp_angle"),
        summary_peak.get("qwp_readout"),
        summary.get("best_mag_qwp_readout_deg"),
        summary.get("best_qwp_readout_deg"),
    )
    q_null = _first_finite_followup_value(
        candidate.get("q_null"),
        candidate.get("qwp_null"),
        candidate.get("q_calibration_null"),
        summary_peak.get("q_null"),
        summary.get("best_mag_qwp_deg"),
        summary.get("best_qwp_deg"),
        qwp_readout,
    )
    anl_angle = _first_finite_followup_value(
        candidate.get("anl_angle"),
        candidate.get("anl_target_deg"),
        summary_peak.get("anl_angle"),
        summary.get("best_mag_anl_deg"),
        summary.get("best_anl_deg"),
    )
    a_null = _first_finite_followup_value(
        candidate.get("a_null"),
        candidate.get("a_null_deg"),
        summary_peak.get("a_null"),
        summary.get("best_mag_a_null_deg"),
        summary.get("best_a_null_deg"),
        anl_angle,
    )
    vpp = _first_finite_followup_value(
        candidate.get("vpp"),
        summary_peak.get("vpp"),
        summary.get("best_mag_vpp"),
        summary.get("best_vpp"),
    )
    mag = _first_finite_followup_value(
        candidate.get("mag"),
        summary_peak.get("mag"),
        summary.get("max_lockin_mag_V"),
        summary.get("max_abs_signed_response_V"),
        default=float("nan"),
    )
    theta_i_deg = _first_finite_followup_value(
        candidate.get("theta_i_deg"),
        summary_peak.get("theta_i_deg"),
        summary.get("best_mag_theta_i_deg"),
        summary.get("best_theta_i_deg"),
        theta_i_from_hwp(hwp_deg) if hwp_deg is not None else None,
    )
    csv_peak = {}
    if any(value is None for value in (hwp_deg, q_null, anl_angle, vpp)):
        try:
            csv_peak = build_analyser_sweep_points_from_fast_map_csv(
                pixel_dir,
                peak_hwp_only=True,
                allow_untrusted_fallback=bool(allow_untrusted_fallback),
            )[0]
        except Exception:
            csv_peak = {}
        hwp_deg = _first_finite_followup_value(hwp_deg, csv_peak.get("theta_i"), csv_peak.get("hwp_deg"))
        qwp_readout = _first_finite_followup_value(
            qwp_readout,
            csv_peak.get("qwp_angle"),
            csv_peak.get("qwp_readout"),
            csv_peak.get("qwp_readout_deg"),
        )
        q_null = _first_finite_followup_value(q_null, csv_peak.get("q_null"), qwp_readout)
        anl_angle = _first_finite_followup_value(
            anl_angle,
            csv_peak.get("anl_angle"),
            csv_peak.get("anl_target_deg"),
        )
        a_null = _first_finite_followup_value(a_null, csv_peak.get("a_null"), anl_angle)
        vpp = _first_finite_followup_value(vpp, csv_peak.get("vpp"))
        mag = _first_finite_followup_value(mag, csv_peak.get("mag"), default=float("nan"))
        theta_i_deg = _first_finite_followup_value(
            theta_i_deg,
            csv_peak.get("theta_i_deg"),
            theta_i_from_hwp(hwp_deg) if hwp_deg is not None else None,
        )
    missing = [
        name for name, value in (
            ("HWP peak angle", hwp_deg),
            ("QWP null angle", q_null),
            ("analyser peak angle", anl_angle),
            ("AC Vpp", vpp),
        )
        if value is None
    ]
    if missing:
        pix = int(pixel.get("pixel", 0) or 0)
        raise ValueError(f"Pixel {pix:03d} peak conditions are incomplete: {', '.join(missing)}")

    peak = dict(candidate)
    peak.update({
        "source": peak.get("source", "fast_map_gui_post_followup"),
        "source_pixel_dir": str(pixel_dir),
        "pixel": int(pixel.get("pixel", 0) or 0),
        "theta_i": float(hwp_deg),
        "hwp_deg": float(hwp_deg),
        "theta_i_deg": float(theta_i_deg) if theta_i_deg is not None else None,
        "theta_i_legacy_deg": _first_finite_followup_value(
            candidate.get("theta_i_legacy_deg"),
            summary_peak.get("theta_i_legacy_deg"),
            summary.get("best_mag_theta_i_legacy_deg"),
            summary.get("best_theta_i_legacy_deg"),
            legacy_theta_i_from_hwp(hwp_deg),
        ),
        "q_null": float(q_null),
        "qwp_null": float(q_null),
        "q_calibration_null": float(q_null),
        "qwp_angle": float(qwp_readout if qwp_readout is not None else q_null),
        "qwp_readout": float(qwp_readout if qwp_readout is not None else q_null),
        "anl_angle": float(anl_angle),
        "anl_target_deg": float(anl_angle),
        "a_null": float(a_null if a_null is not None else anl_angle),
        "vpp": float(vpp),
        "mag": float(mag),
        "untrusted_high_null_fallback": bool(
            candidate.get("untrusted_high_null_fallback")
            or csv_peak.get("untrusted_high_null_fallback")
        ),
        "lab_angle_mapping": peak.get("lab_angle_mapping", lab_angle_mapping_config()),
    })
    return peak


def load_fast_map_resume_artifacts(
    *,
    pixel: dict,
    pixel_dir: Path,
    peak_conditions: dict | None = None,
) -> tuple[dict, dict, bool]:
    """Load reusable peak data without requiring a historical summary JSON.

    ``fast_map.csv`` is the authoritative source for historical follow-up peak
    selection.  Some older or interrupted chip-map runs saved usable rows but
    never reached the later ``fast_map_summary.json`` save.  Follow-up-only
    measurements must not fail—or rerun the HWP sweep—just because that derived
    summary file is absent.

    Returns ``(summary, peak, summary_is_derived)``.  The derived summary is
    intentionally in-memory metadata for status/progress output; the historical
    source directory is not backfilled or rewritten here.
    """
    pixel_dir = Path(pixel_dir)
    summary = _read_json_dict(pixel_dir / FAST_MAP_SUMMARY_JSON)
    peak = fast_map_peak_for_followup(
        pixel=pixel,
        pixel_dir=pixel_dir,
        peak_conditions=peak_conditions,
        allow_untrusted_fallback=True,
    )
    if summary:
        return summary, peak, False

    hwp_deg = _finite_float_or_none(peak.get("hwp_deg"))
    theta_i_deg = _finite_float_or_none(peak.get("theta_i_deg"))
    theta_i_legacy_deg = _finite_float_or_none(peak.get("theta_i_legacy_deg"))
    q_null = _finite_float_or_none(peak.get("q_null"))
    qwp_readout = _finite_float_or_none(peak.get("qwp_angle"))
    anl_angle = _finite_float_or_none(peak.get("anl_angle"))
    a_null = _finite_float_or_none(peak.get("a_null"))
    vpp = _finite_float_or_none(peak.get("vpp"))
    mag = _finite_float_or_none(peak.get("mag"))
    abs_mag = abs(float(mag)) if mag is not None else None
    summary = {
        "pixel": int(pixel.get("pixel", 0) or 0),
        "row": int(pixel.get("j", 0) or 0),
        "col": int(pixel.get("i", 0) or 0),
        "best_hwp_deg": hwp_deg,
        "best_theta_i_deg": theta_i_deg,
        "best_theta_i_legacy_deg": theta_i_legacy_deg,
        "best_slope_side": str(peak.get("slope_side") or ""),
        "best_qwp_deg": q_null,
        "best_qwp_readout_deg": qwp_readout,
        "best_anl_deg": anl_angle,
        "best_a_null_deg": a_null,
        "best_vpp": vpp,
        "best_mag_hwp_deg": hwp_deg,
        "best_mag_theta_i_deg": theta_i_deg,
        "best_mag_theta_i_legacy_deg": theta_i_legacy_deg,
        "best_mag_slope_side": str(peak.get("slope_side") or ""),
        "best_mag_qwp_deg": q_null,
        "best_mag_qwp_readout_deg": qwp_readout,
        "best_mag_anl_deg": anl_angle,
        "best_mag_a_null_deg": a_null,
        "best_mag_vpp": vpp,
        "max_abs_signed_response_V": abs_mag,
        "max_lockin_mag_V": abs_mag,
        "resume_metadata_only": True,
        "resume_metadata_source": str(
            peak.get("source") or "saved_fast_map_peak"
        ),
        "r_eff_status": "not_calculated_missing_historical_summary",
    }
    return summary, peak, True


def move_to_followup_peak_conditions(
    *,
    peak: dict,
    pixel: dict,
    rot_hwp,
    rot_qwp,
    rot_anl,
    funcgen=None,
    set_funcgen_vpp: bool = False,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    phase_label: str,
) -> None:
    pix = int(pixel.get("pixel", 0) or 0)
    historical_raw_angles = bool(peak.get("historical_raw_motor_angles"))
    qwp_motor_target = _first_finite_followup_value(
        peak.get("qwp_angle") if historical_raw_angles else None,
        peak.get("qwp_readout") if historical_raw_angles else None,
        peak.get("q_null"),
    )
    if qwp_motor_target is None:
        raise ValueError(f"Pixel {pix:03d} has no usable QWP motor target.")
    gui_update_state(
        current_pixel=pix,
        current_hwp_deg=float(peak["theta_i"]),
        current_qwp_target_deg=float(qwp_motor_target),
        current_anl_target_deg=float(peak["anl_angle"]),
        active_optic="HWP/QWP/ANL",
        phase=phase_label,
        ac_voltage_on=False,
    )
    hwp_move = fast_rotator_move_or_fallback(
        rot_hwp,
        float(peak["theta_i"]),
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"{phase_label} HWP",
    )
    require_verified_move(hwp_move, f"{phase_label} HWP")
    qwp_move = fast_rotator_move_or_fallback(
        rot_qwp,
        float(qwp_motor_target),
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"{phase_label} QWP",
    )
    require_verified_move(qwp_move, f"{phase_label} QWP")
    anl_move = fast_rotator_move_or_fallback(
        rot_anl,
        float(peak["anl_angle"]),
        fast=fast_rotator_moves,
        verify=verify_moves,
        tol_deg=verify_tol_deg,
        label=f"{phase_label} ANL",
    )
    require_verified_move(anl_move, f"{phase_label} ANL")
    gui_update_state(
        current_pixel=pix,
        current_hwp_deg=gui_angle_from_move(hwp_move, float(peak["theta_i"])),
        current_qwp_deg=gui_angle_from_move(qwp_move, float(qwp_motor_target)),
        current_anl_deg=gui_angle_from_move(anl_move, float(peak["anl_angle"])),
        current_hwp_target_deg=float(peak["theta_i"]),
        current_qwp_target_deg=float(qwp_motor_target),
        current_anl_target_deg=float(peak["anl_angle"]),
        phase=phase_label,
    )
    if set_funcgen_vpp and funcgen is not None:
        pockels.funcgen_set_voltage(funcgen, float(peak["vpp"]))
        pockels._funcgen_set_sweep_output(
            funcgen,
            True,
            verify_command=True,
            required=True,
            context=f"{phase_label} AC output start",
        )
        gui_sleep(pockels.FUNCGEN_SETTLE_S, allow_skip=True)


def run_post_fast_map_ac_vpp_sweep(
    *,
    pixel: dict,
    pixel_dir: Path,
    peak_conditions: dict | None,
    vpp_values: list[float],
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    funcgen,
    smu,
    sens_idx: int,
    dc_hold_v: float,
    pre_measure_dwell_s: float,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
) -> int:
    peak = fast_map_peak_for_followup(pixel=pixel, pixel_dir=pixel_dir, peak_conditions=peak_conditions)
    sweep_root = Path(pixel_dir) / "ac_vpp_sweep"
    sweep_root.mkdir(parents=True, exist_ok=True)
    write_json(sweep_root / "ac_vpp_sweep_plan.json", {
        "pixel": int(pixel.get("pixel", 0) or 0),
        "created": datetime.now().isoformat(),
        "peak_hwp_only": True,
        "peak": peak,
        "vpp_values": [float(v) for v in vpp_values],
        "dc_hold_v": float(dc_hold_v),
        "pre_measure_dwell_s": float(pre_measure_dwell_s),
    })
    print(
        f"\n[AC VPP SWEEP] Pixel {int(pixel.get('pixel', 0) or 0):03d}: "
        f"peak HWP {float(peak['theta_i']):.3f} deg, {len(vpp_values)} Vpp value(s)."
    )
    move_to_followup_peak_conditions(
        peak=peak,
        pixel=pixel,
        rot_hwp=rot_hwp,
        rot_qwp=rot_qwp,
        rot_anl=rot_anl,
        funcgen=funcgen,
        set_funcgen_vpp=False,
        fast_rotator_moves=fast_rotator_moves,
        verify_moves=verify_moves,
        verify_tol_deg=verify_tol_deg,
        phase_label="AC Vpp follow-up peak move",
    )
    auto.smu_set_level_output_on(smu, float(dc_hold_v))
    pockels._funcgen_set_sweep_output(
        funcgen,
        True,
        verify_command=True,
        required=True,
        context="post-fast-map AC Vpp sweep start",
    )
    gui_update_state(
        current_pixel=int(pixel.get("pixel", 0) or 0),
        dc_voltage_on=True,
        dc_voltage_v=float(dc_hold_v),
        ac_voltage_on=True,
        current_slope_side="ac_vpp_sweep",
        phase="AC Vpp follow-up",
    )
    sens_idx = pockels.run_ac_vpp_sweep_at_peak(
        smu,
        detector,
        lockin,
        funcgen,
        sens_idx,
        str(sweep_root),
        f"pixel_{int(pixel.get('pixel', 0) or 0):03d} AC Vpp follow-up",
        peak,
        voltages_vpp=vpp_values,
        dc_hold_v=float(dc_hold_v),
        pre_measure_dwell_s=float(pre_measure_dwell_s),
    )
    print(f"\n[AC VPP SWEEP] Pixel {int(pixel.get('pixel', 0) or 0):03d}: saved under {sweep_root}")
    return sens_idx


def run_post_fast_map_dc_hysteresis_sweep(
    *,
    pixel: dict,
    pixel_dir: Path,
    peak_conditions: dict | None,
    rot_hwp,
    rot_qwp,
    rot_anl,
    detector,
    lockin,
    funcgen,
    smu,
    sens_idx: int,
    poling_dwell_s: float,
    start_from_zero: bool,
    reset_domains: bool,
    fast_rotator_moves: bool,
    verify_moves: bool,
    verify_tol_deg: float,
    vmax_v: float = pockels.DC_HYST_VMAX,
    cycles: int = DEFAULT_HYSTERESIS_CYCLES,
    ac_vpp: float | None = DEFAULT_HYSTERESIS_AC_VPP,
    min_dwell_s: float = 0.5,
    adaptive_window: bool = DEFAULT_HYSTERESIS_ADAPTIVE_WINDOW,
    voltage_step_v: float | None = DEFAULT_HYSTERESIS_VOLTAGE_STEP_V,
    quasi_static: bool = False,
    lockin_tc_index: int | None = None,
    lockin_sensitivity_index: int | None = None,
    dynamic_lockin_range: bool = DEFAULT_HYSTERESIS_DYNAMIC_LOCKIN_RANGE,
) -> int:
    gui_pixel_checkpoint()
    effective_vmax = pockels.validate_hysteresis_voltage_limit(
        vmax_v,
        "DC hysteresis Vmax",
    )
    effective_start_from_zero = bool(start_from_zero and reset_domains)
    if quasi_static:
        # Quasi-static mode keeps the 30 s floor, one cycle and peak dither;
        # the standard centre-dense voltage profile remains the default.
        dwell_floor = float(pockels.DC_HYST_MIN_POLING_DWELL_S)
        cycles = 1
        ac_vpp = None
        adaptive_window = False
        voltage_step_v = None
    else:
        dwell_floor = max(0.0, float(min_dwell_s))
    effective_dwell_s = max(float(poling_dwell_s), dwell_floor)
    if bool(start_from_zero) and not bool(reset_domains):
        print(
            "  [DC HYSTERESIS] Ignoring start-from-zero for non-reset follow-up; "
            "using saturated +Vmax -> -Vmax -> +Vmax trajectory."
        )
    if float(poling_dwell_s) < effective_dwell_s:
        print(
            f"  [DC HYSTERESIS] Requested dwell {float(poling_dwell_s):.2f}s is below "
            f"{effective_dwell_s:.2f}s; using {effective_dwell_s:.2f}s."
        )
    loop_ac_vpp = None
    if ac_vpp is not None and float(ac_vpp) > 0.0:
        loop_ac_vpp = float(ac_vpp)
    effective_voltage_step_v = None
    if not adaptive_window and voltage_step_v is not None:
        effective_voltage_step_v = float(voltage_step_v)
        if not np.isfinite(effective_voltage_step_v) or effective_voltage_step_v <= 0.0:
            raise ValueError("Hysteresis voltage step must be finite and positive.")
    if adaptive_window:
        voltage_grid_profile = "adaptive_vc_windows"
        planned_voltage_levels_v = None
    elif effective_voltage_step_v is not None:
        voltage_grid_profile = "uniform"
        planned_voltage_levels_v = None
    else:
        voltage_grid_profile = DEFAULT_HYSTERESIS_GRID_PROFILE
        planned_voltage_levels_v = [
            float(v)
            for v in pockels._build_center_dense_hysteresis_points(
                effective_vmax
            )
        ]
    peak = fast_map_peak_for_followup(
        pixel=pixel,
        pixel_dir=pixel_dir,
        peak_conditions=peak_conditions,
        allow_untrusted_fallback=False,
    )
    if not bool(peak.get("hysteresis_eligible", False)):
        raise ValueError(
            f"Pixel {int(pixel.get('pixel', 0) or 0):03d} has no normalized or "
            "geometry-certified peak eligible for hysteresis. Re-run the fast "
            "HWP triplet calibration instead of using an unsafe raw maximum."
        )
    sweep_root = Path(pixel_dir) / "dc_hysteresis"
    sweep_root.mkdir(parents=True, exist_ok=True)
    write_json(sweep_root / "dc_hysteresis_plan.json", {
        "pixel": int(pixel.get("pixel", 0) or 0),
        "created": datetime.now().isoformat(),
        "peak_hwp_only": True,
        "peak": peak,
        "poling_dwell_s": float(effective_dwell_s),
        "requested_poling_dwell_s": float(poling_dwell_s),
        "start_from_zero": bool(effective_start_from_zero),
        "requested_start_from_zero": bool(start_from_zero),
        "reset_domains": bool(reset_domains),
        "cycles": int(max(1, int(cycles))),
        "vmax_v": float(effective_vmax),
        "voltage_limits_v": [-float(effective_vmax), float(effective_vmax)],
        "loop_ac_vpp": loop_ac_vpp,
        "voltage_sequence": "dc_only_poling_then_ac_measurement",
        "ac_enabled_during_dc_ramp_or_poling": False,
        "smu_electrical_sample_phase": (
            "after_dc_poling_before_ac_measurement"
        ),
        "smu_voltage_readback": "secondary_live_terminal_voltage",
        "smu_dc_readback_tolerance_V": float(
            pockels.SMU_DC_READBACK_TOLERANCE_V
        ),
        "adaptive_window": bool(adaptive_window),
        "voltage_grid_profile": voltage_grid_profile,
        "planned_voltage_levels_v": planned_voltage_levels_v,
        "requested_voltage_step_v": (
            float(voltage_step_v) if voltage_step_v is not None else None
        ),
        "voltage_step_v": effective_voltage_step_v,
        "quasi_static": bool(quasi_static),
        "lockin_tc_index": (int(lockin_tc_index)
                            if lockin_tc_index is not None else None),
        "lockin_sensitivity_index": (
            int(lockin_sensitivity_index)
            if lockin_sensitivity_index is not None else None
        ),
        "lockin_range_mode": (
            "predictive_hysteretic" if dynamic_lockin_range else "fixed"
        ),
    })
    print(
        f"\n[DC HYSTERESIS] Pixel {int(pixel.get('pixel', 0) or 0):03d}: "
        f"peak HWP {float(peak['theta_i']):.3f} deg; "
        f"grid {voltage_grid_profile}; limits +/-{effective_vmax:g} V."
    )
    # Enter the follow-up with the sample-drive AC physically off, before
    # moving optics or changing/enabling the SMU DC level. CH2 reference is
    # unaffected.
    pockels._funcgen_set_sweep_output(
        funcgen,
        False,
        verify_command=True,
        required=True,
        context="fast-map hysteresis entry handoff",
    )
    move_to_followup_peak_conditions(
        peak=peak,
        pixel=pixel,
        rot_hwp=rot_hwp,
        rot_qwp=rot_qwp,
        rot_anl=rot_anl,
        funcgen=funcgen,
        # The hysteresis core is the sole owner of CH1 during this handoff:
        # it programs the requested amplitude while OFF, then gates it around
        # each measurement window only.
        set_funcgen_vpp=False,
        fast_rotator_moves=fast_rotator_moves,
        verify_moves=verify_moves,
        verify_tol_deg=verify_tol_deg,
        phase_label="DC hysteresis follow-up peak move",
    )
    gui_pixel_checkpoint()
    auto.smu_set_level_output_on(smu, 0.0)
    gui_update_state(
        current_pixel=int(pixel.get("pixel", 0) or 0),
        dc_voltage_on=True,
        dc_voltage_v=0.0,
        # The core sets the final loop amplitude while OFF, then keeps it OFF
        # throughout every DC ramp and complete per-point poling dwell.
        ac_voltage_on=False,
        current_vpp=float(loop_ac_vpp if loop_ac_vpp is not None else peak["vpp"]),
        current_slope_side="dc_hysteresis",
        phase="Preparing DC-only hysteresis sequence (AC off)",
    )
    if reset_domains:
        gui_update_state(
            ac_voltage_on=False,
            phase="DC hysteresis domain reset (AC sample drive OFF)",
        )
        reset_dir = sweep_root / "domain_reset"
        reset_dir.mkdir(parents=True, exist_ok=True)
        pockels.reset_domains_pulsed(
            smu,
            funcgen,
            str(reset_dir),
            f"pixel_{int(pixel.get('pixel', 0) or 0):03d} DC follow-up reset",
            vmax=effective_vmax,
            cancel_callback=gui_pixel_checkpoint,
        )
        # reset_domains_pulsed restores CH1 ON after a completed standalone
        # reset.  A hysteresis follow-up must instead enter its first DC pole
        # with CH1 definitely OFF.
        pockels._funcgen_set_sweep_output(
            funcgen,
            False,
            verify_command=True,
            required=True,
            context="post-reset hysteresis handoff",
        )
        gui_pixel_checkpoint()
    gui_update_state(
        ac_voltage_on=False,
        current_vpp=float(loop_ac_vpp if loop_ac_vpp is not None else peak["vpp"]),
        phase="DC hysteresis ready: AC stays off until each measurement",
    )
    sweep_dir = sweep_root / "sweep"
    sweep_dir.mkdir(parents=True, exist_ok=True)
    pixel_number = int(pixel.get("pixel", 0) or 0)
    persist_live_progress = pockels.make_hysteresis_progress_json_callback(
        sweep_root / pockels.DC_HYSTERESIS_LIVE_JSON,
        pixel_number,
    )

    def update_hysteresis_live(event: dict) -> None:
        """Persist every point and mirror the latest read into gui_state.json."""
        gui_pixel_checkpoint()
        persist_live_progress(event)
        event_type = str(event.get("event", "") or "")
        stage = str(event.get("sweep_stage", "") or "main")
        point_index = int(event.get("point_index", 0) or 0)
        total_points = int(event.get("total_points", 0) or 0)
        point = event.get("point") if isinstance(event.get("point"), dict) else {}
        branch = str(
            event.get("branch", point.get("branch", "")) or ""
        )
        phase_stage = "coarse recon" if stage == "recon" else "main loop"
        point_label = f"{point_index}/{total_points}"
        if event_type == "start":
            phase_text = (
                f"DC hysteresis {phase_stage} starting "
                "(DC-only poling; AC OFF)"
            )
        elif event_type == "dc_poling":
            phase_text = (
                f"DC hysteresis {phase_stage} DC-only poling "
                f"{point_label} (AC OFF)"
            )
        elif event_type == "ac_measurement":
            phase_text = (
                f"DC hysteresis {phase_stage} AC measurement "
                f"{point_label}"
            )
        elif event_type == "point":
            phase_text = (
                f"DC hysteresis {phase_stage} point {point_label} saved "
                "(AC OFF)"
            )
        elif event_type == "complete":
            phase_text = f"DC hysteresis {phase_stage} complete (AC OFF)"
        else:
            phase_text = (
                f"DC hysteresis {phase_stage} "
                f"{point_label}"
            )
        updates = {
            "current_pixel": pixel_number,
            "current_slope_side": (
                f"dc_hysteresis_{branch}" if branch else "dc_hysteresis"
            ),
            "phase": phase_text,
            "hysteresis_live_updated_ts": time.time(),
            "dwell_remaining_s": None,
        }
        if "ac_output_on" in event:
            updates["ac_voltage_on"] = bool(event.get("ac_output_on"))
        elif event_type in {"start", "dc_poling", "point", "complete"}:
            updates["ac_voltage_on"] = False
        if event_type in {"start", "ac_measurement"}:
            updates["current_vpp"] = float(
                loop_ac_vpp if loop_ac_vpp is not None else peak["vpp"]
            )
        v_dc = _finite_float_or_none(
            event.get("v_dc", point.get("v_dc"))
        )
        lockin_mag = _finite_float_or_none(point.get("li_mag"))
        lockin_phase = _finite_float_or_none(point.get("li_phase"))
        ac_drive = _finite_float_or_none(
            event.get("ac_vpp", point.get("ac_vpp"))
        )
        if v_dc is not None:
            updates["dc_voltage_v"] = v_dc
        if lockin_mag is not None:
            updates["lockin_mag_V"] = lockin_mag
        if lockin_phase is not None:
            updates["lockin_phase_deg"] = lockin_phase
        if ac_drive is not None:
            updates["current_vpp"] = ac_drive
        gui_update_state(**updates)
        gui_pixel_checkpoint()

    sens_idx = pockels.run_dc_hysteresis_sweep(
        smu,
        detector,
        lockin,
        sens_idx,
        str(sweep_dir),
        f"pixel_{int(pixel.get('pixel', 0) or 0):03d} DC hysteresis follow-up",
        peak,
        hold_voltage_v=0.0,
        poling_dwell_s=float(effective_dwell_s),
        start_from_zero=bool(effective_start_from_zero),
        cycles=int(max(1, int(cycles))),
        min_dwell_s=dwell_floor,
        funcgen=funcgen,
        ac_vpp=loop_ac_vpp,
        adaptive_fine=bool(adaptive_window),
        voltage_step_v=effective_voltage_step_v,
        vmax_v=effective_vmax,
        lockin_tc_index=(int(lockin_tc_index)
                         if lockin_tc_index is not None else None),
        lockin_sensitivity_index=(
            int(lockin_sensitivity_index)
            if lockin_sensitivity_index is not None else None
        ),
        lockin_range_mode=(
            "predictive_hysteretic" if dynamic_lockin_range else "fixed"
        ),
        progress_callback=update_hysteresis_live,
        cancel_callback=gui_pixel_checkpoint,
    )
    gui_pixel_checkpoint()
    print(f"\n[DC HYSTERESIS] Pixel {int(pixel.get('pixel', 0) or 0):03d}: saved under {sweep_root}")
    return sens_idx


def adaptive_poling_dwell(
    *,
    args,
    pixel_dir: Path,
    live_view,
    lockin,
    funcgen,
    rot_anl,
    sens_idx: int,
    null_seed_by_hwp: dict,
    hwp_angles,
    fallback_seed,
    voltages,
) -> int:
    """v2: monitor the EO response during the DC poling dwell, stop at plateau.

    Physics: at a fixed small AC dither the 1f lock-in magnitude tracks the
    net switched polarization in the illuminated gap, so poling is complete
    when it stops growing. The analyser sits at the first-HWP null seed, where
    the Malus slope is ~zero, so it is moved to seed+45 deg for the monitor
    and returned afterwards. Early stop requires ALL of: a minimum elapsed
    time, `stable_count` consecutive quiet intervals, and a minimum signal
    level - low-signal (dead or noisy) pixels always get the full dwell, and
    any failure falls back to the plain fixed sleep for the remaining time.
    Samples are logged to poling_kinetics.csv (per-pixel poling time constant
    comes for free).
    """
    max_dwell = max(0.0, float(args.poling_dwell))
    min_dwell = min(max_dwell, max(0.0, float(args.adaptive_poling_min_s)))
    poll_s = max(1.0, float(args.adaptive_poling_poll_s))
    stable_frac = max(0.0, float(args.adaptive_poling_stable_pct)) / 100.0
    stable_count = max(1, int(args.adaptive_poling_stable_count))
    min_signal_v = max(0.0, float(args.adaptive_poling_min_signal_uv)) * 1e-6

    monitor_vpp = float(args.adaptive_poling_monitor_vpp)
    if monitor_vpp <= 0.0:
        monitor_vpp = float(min(voltages)) if len(voltages) else 1.0

    hwp_key = f"{float(hwp_angles[0]):.3f}" if len(hwp_angles) else ""
    seed = null_seed_by_hwp.get(hwp_key, {})
    a_seed = float(seed.get("a_null_deg", fallback_seed[1]))
    slope_target = a_seed + 45.0

    t0 = time.time()
    samples = []
    moved_anl = False
    early_stop = False
    try:
        move = fast_rotator_move_or_fallback(
            rot_anl, slope_target,
            fast=bool(args.fast_rotator_moves),
            verify=bool(args.verify_fast_rotator_moves),
            tol_deg=float(args.rotator_verify_tol),
            label="ANL poling monitor",
        )
        require_verified_move(move, "ANL poling monitor")
        moved_anl = True
        pockels.funcgen_set_voltage(funcgen, monitor_vpp)
        pockels._funcgen_set_sweep_output(
            funcgen,
            True,
            verify_command=True,
            required=True,
            context="adaptive poling monitor start",
        )
        gui_sleep(float(args.funcgen_settle), live_view=live_view,
                  phase="DC poling dwell (adaptive)")

        prev_mag = None
        streak = 0
        while (time.time() - t0) < max_dwell:
            gui_sleep(min(poll_s, max(0.1, max_dwell - (time.time() - t0))),
                      live_view=live_view,
                      phase="DC poling dwell (adaptive)", allow_skip=True)
            sens_idx, changed = check_fixed_lockin_overload(lockin, sens_idx)
            avg_mag, avg_phase, _sm, _sp, raw_mags, _rp, _rt = \
                pockels.read_lockin_averaged(lockin, 3, 0.05)
            elapsed = time.time() - t0
            samples.append((elapsed, avg_mag, avg_phase, sens_idx))
            if changed or not raw_mags or not np.isfinite(avg_mag):
                streak = 0
                prev_mag = None
                continue
            if prev_mag is not None:
                delta = abs(avg_mag - prev_mag)
                if delta < max(stable_frac * abs(avg_mag), 0.05e-6):
                    streak += 1
                else:
                    streak = 0
            prev_mag = avg_mag
            if (streak >= stable_count and elapsed >= min_dwell
                    and abs(avg_mag) >= min_signal_v):
                early_stop = True
                print(f"  [ADAPTIVE POLING] Plateau after {elapsed:.0f}s "
                      f"(|M|={avg_mag*1e6:.2f} uV, {streak} quiet intervals) - "
                      f"saved {max_dwell - elapsed:.0f}s.")
                break
    except Exception as exc:
        raise_if_fatal_hardware_transport_error(
            exc,
            "Adaptive poling monitor",
        )
        remaining = max(0.0, max_dwell - (time.time() - t0))
        print(f"  [ADAPTIVE POLING] Monitor failed ({type(exc).__name__}: {exc}); "
              f"falling back to fixed dwell for the remaining {remaining:.0f}s.")
        if remaining > 0:
            gui_sleep(remaining, live_view=live_view,
                      phase="DC poling dwell", allow_skip=True)
    finally:
        pockels._funcgen_set_sweep_output(
            funcgen,
            False,
            verify_command=True,
            required=True,
            context="adaptive poling monitor cleanup",
        )
        if moved_anl:
            try:
                move = fast_rotator_move_or_fallback(
                    rot_anl, a_seed,
                    fast=bool(args.fast_rotator_moves),
                    verify=bool(args.verify_fast_rotator_moves),
                    tol_deg=float(args.rotator_verify_tol),
                    label="ANL poling monitor return",
                )
                require_verified_move(move, "ANL poling monitor return")
            except Exception as exc:
                raise_if_fatal_hardware_transport_error(
                    exc,
                    "Adaptive poling analyser return",
                )
                print(f"  [ADAPTIVE POLING] WARNING: analyser return failed: {exc}")
        try:
            kin_path = Path(pixel_dir) / "poling_kinetics.csv"
            with open(kin_path, "w", newline="") as f:
                writer = csv.writer(f)
                writer.writerow(["t_s", "lockin_mag_V", "lockin_phase_deg",
                                 "sens_idx", "monitor_vpp", "anl_monitor_deg",
                                 "early_stop"])
                for t_s, m, p, s in samples:
                    writer.writerow([f"{t_s:.2f}", f"{m:.6e}", f"{p:.4f}",
                                     s, monitor_vpp, f"{slope_target:.3f}",
                                     int(early_stop)])
        except Exception:
            pass
    if not early_stop:
        print(f"  [ADAPTIVE POLING] Full {max_dwell:.0f}s dwell used "
              f"({len(samples)} monitor samples).")
    return sens_idx


def concise_hwp_line(
    rows: list[dict],
    voltages: list[float],
    p_null: float,
    p_null_mV: float,
    null_s: float,
    null_method: str,
    null_evals: int,
    null_escalated: bool,
    null_label: str,
    rotator_verify_tol_deg: float,
    progress: dict | None = None,
) -> str:
    suffix = progress_suffix(progress)
    null_desc = f"{null_method}/{null_evals} probes"
    expected_rows = max(0, len(voltages) * 2)
    def valid_lockin_row(row: dict) -> bool:
        try:
            signed = lockin_response_value(row, "lockin_net_signed_V", "lockin_signed_V")
            n_good = int(row.get("n_good_samples", 0))
        except Exception:
            return False
        return np.isfinite(signed) and n_good > 0

    valid_rows = [row for row in rows if valid_lockin_row(row)]
    response_valid_rows = [
        row for row in valid_rows
        if str(row.get("slope_side", "")) in ("plus45", "minus45")
    ]
    learned_valid_rows = [
        row for row in valid_rows
        if str(row.get("slope_side", "")) in (
            "learned_zero",
            "learned_anchor",
            "learned_opposite",
        )
    ]
    peak_search_valid_rows = [
        row for row in valid_rows
        if str(row.get("slope_side", "")) in ("manual_anchor", "auto_peak")
    ]
    peak_search_only = bool(peak_search_valid_rows) and not response_valid_rows and not learned_valid_rows
    if peak_search_only:
        expected_rows = len(peak_search_valid_rows)
        measured_rows = len(peak_search_valid_rows)
        measurement_desc = f"PEAK SEARCH {measured_rows} pts"
    elif learned_valid_rows and not response_valid_rows:
        learned_sides = {str(row.get("slope_side", "")) for row in learned_valid_rows}
        learned_points_per_voltage = 3 if {"learned_zero", "learned_opposite"} & learned_sides else 1
        expected_rows = max(0, len(voltages) * learned_points_per_voltage)
        measured_rows = len(learned_valid_rows)
        measurement_desc = (
            f"MEASURED {measured_rows}/{expected_rows}"
            if measured_rows == expected_rows
            else f"INCOMPLETE {measured_rows}/{expected_rows}"
        )
    else:
        measured_rows = len(response_valid_rows)
        measurement_desc = (
            f"MEASURED {measured_rows}/{expected_rows}"
            if measured_rows == expected_rows
            else f"INCOMPLETE {measured_rows}/{expected_rows}"
        )
    angle_desc = angle_status_desc(rows, rotator_verify_tol_deg)
    if null_escalated:
        null_desc += ", escalated"
    if not rows:
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV "
            f"({null_s:.1f}s, {null_desc}, {null_label}) | {measurement_desc} | {angle_desc} | no lock-in rows{suffix}"
        )
    preferred_vpp = max(float(v) for v in voltages)
    by_side = {
        row["slope_side"]: row
        for row in response_valid_rows
        if abs(float(row["vpp"]) - preferred_vpp) < 1e-9
    }
    anchor_rows = [
        row for row in valid_rows
        if str(row.get("slope_side", "")) in (
            "manual_anchor",
            "auto_peak",
            "learned_anchor",
            "learned_opposite",
        )
        and abs(float(row["vpp"]) - preferred_vpp) < 1e-9
    ]
    anchor_desc = ""
    if anchor_rows:
        anchor = max(
            anchor_rows,
            key=lambda r: lockin_raw_response_value(r, "lockin_mag_V", "lockin_net_mag_V"),
        )
        anchor_u = lockin_raw_response_value(anchor, "lockin_mag_V", "lockin_net_mag_V") * 1e6
        if np.isfinite(anchor_u):
            anchor_desc = f" anchorRAW={anchor_u:.3f} uV"
    plus = by_side.get("plus45")
    minus = by_side.get("minus45")
    if plus and minus:
        plus_u = lockin_response_value(plus, "lockin_net_signed_V", "lockin_signed_V") * 1e6
        minus_u = lockin_response_value(minus, "lockin_net_signed_V", "lockin_signed_V") * 1e6
        asym_denom = max(abs(plus_u), abs(minus_u))
        asym_frac = (
            abs(abs(plus_u) - abs(minus_u)) / asym_denom
            if asym_denom > 0.0 else float("nan")
        )
        bg_u = lockin_response_value(plus, "lockin_bg_mag_V", "lockin_bg_mag_V") * 1e6
        bg_desc = f" bg={bg_u:.3f} uV" if np.isfinite(bg_u) else ""
        plus_raw_u = lockin_raw_response_value(plus, "lockin_mag_V") * 1e6
        minus_raw_u = lockin_raw_response_value(minus, "lockin_mag_V") * 1e6
        if np.isfinite(bg_u) and np.isfinite(plus_raw_u) and np.isfinite(minus_raw_u):
            raw_desc = (
                f" rawMAG 0={bg_u:.3f} +45={plus_raw_u:.3f}"
                f" -45={minus_raw_u:.3f}{anchor_desc} uV"
            )
        else:
            raw_desc = anchor_desc
        oppose = "OK" if plus_u * minus_u <= 0 else "SIGN?"
        asym_desc = (
            f" ASYM={asym_frac:.2f}"
            if np.isfinite(asym_frac) and asym_frac > PAIR_ASYMMETRY_WARN_FRACTION
            else ""
        )
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
            f" {null_desc} {null_label}"
            f" | {preferred_vpp:g} Vpp net +45={plus_u:+.3f} uV"
            f" -45={minus_u:+.3f} uV{bg_desc}{raw_desc} | {measurement_desc} | {angle_desc} | {oppose}{asym_desc}{suffix}"
        )
    peak_search_rows = [
        row for row in peak_search_valid_rows
        if abs(float(row["vpp"]) - preferred_vpp) < 1e-9
    ]
    if peak_search_rows and not learned_valid_rows:
        best_peak = max(
            peak_search_rows,
            key=lambda r: lockin_raw_response_value(r, "lockin_mag_V", "lockin_net_mag_V"),
        )
        peak_u = lockin_raw_response_value(best_peak, "lockin_mag_V", "lockin_net_mag_V") * 1e6
        side = str(best_peak.get("slope_side", "peak"))
        qwp = float(best_peak.get("qwp_readout_deg", best_peak.get("q_null_deg", float("nan"))))
        anl = float(best_peak.get("anl_target_deg", float("nan")))
        angle_text = (
            f" QWP={qwp:.3f} ANL={anl:.3f}"
            if np.isfinite(qwp) and np.isfinite(anl) else ""
        )
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
            f" {null_desc} {null_label}"
            f" | {preferred_vpp:g} Vpp peak {side} raw={peak_u:.3f} uV{angle_text}"
            f" | {measurement_desc} | {angle_desc}{suffix}"
        )
    learned_by_side = {
        str(row["slope_side"]): row
        for row in learned_valid_rows
        if abs(float(row["vpp"]) - preferred_vpp) < 1e-9
    }
    learned_zero = learned_by_side.get("learned_zero")
    learned_peak = learned_by_side.get("learned_anchor")
    learned_opposite = learned_by_side.get("learned_opposite")
    if learned_peak and not learned_opposite:
        peak_u = lockin_response_value(learned_peak, "lockin_net_signed_V", "lockin_signed_V") * 1e6
        peak_raw_u = lockin_raw_response_value(learned_peak, "lockin_mag_V") * 1e6
        qwp = float(learned_peak.get("qwp_readout_deg", learned_peak.get("q_null_deg", float("nan"))))
        anl = float(learned_peak.get("anl_target_deg", float("nan")))
        angle_text = (
            f" QWP={qwp:.3f} ANL={anl:.3f}"
            if np.isfinite(qwp) and np.isfinite(anl) else ""
        )
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
            f" {null_desc} {null_label}"
            f" | {preferred_vpp:g} Vpp learned peak raw={peak_raw_u:.3f} uV"
            f" net={peak_u:+.3f} uV{angle_text} | {measurement_desc} | {angle_desc}{suffix}"
        )
    if learned_peak and learned_opposite:
        peak_u = lockin_response_value(learned_peak, "lockin_net_signed_V", "lockin_signed_V") * 1e6
        opposite_u = lockin_response_value(learned_opposite, "lockin_net_signed_V", "lockin_signed_V") * 1e6
        zero_raw_u = (
            lockin_raw_response_value(learned_zero, "lockin_mag_V") * 1e6
            if learned_zero else float("nan")
        )
        peak_raw_u = lockin_raw_response_value(learned_peak, "lockin_mag_V") * 1e6
        opposite_raw_u = lockin_raw_response_value(learned_opposite, "lockin_mag_V") * 1e6
        raw_desc = ""
        if np.isfinite(zero_raw_u) and np.isfinite(peak_raw_u) and np.isfinite(opposite_raw_u):
            raw_desc = (
                f" rawMAG 0={zero_raw_u:.3f} peak={peak_raw_u:.3f}"
                f" opp={opposite_raw_u:.3f} uV"
            )
        oppose = "OK" if peak_u * opposite_u <= 0 else "SIGN?"
        asym_denom = max(abs(peak_u), abs(opposite_u))
        asym_frac = (
            abs(abs(peak_u) - abs(opposite_u)) / asym_denom
            if asym_denom > 0.0 else float("nan")
        )
        asym_desc = (
            f" ASYM={asym_frac:.2f}"
            if np.isfinite(asym_frac) and asym_frac > PAIR_ASYMMETRY_WARN_FRACTION
            else ""
        )
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
            f" {null_desc} {null_label}"
            f" | {preferred_vpp:g} Vpp learned net peak={peak_u:+.3f} uV"
            f" opp={opposite_u:+.3f} uV{raw_desc} | {measurement_desc} | {angle_desc} | {oppose}{asym_desc}{suffix}"
        )
    if not valid_rows:
        return (
            f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
            f" {null_desc} {null_label}"
            f" | {measurement_desc} | {angle_desc} | no valid lock-in samples{suffix}"
        )
    best = max(valid_rows, key=lambda r: abs(float(r["lockin_signed_V"])))
    return (
        f" | null P={p_null:.2e} W, Vdet={p_null_mV:.2f} mV ({null_s:.1f}s)"
        f" {null_desc} {null_label}"
        f" | {measurement_desc} | {angle_desc} | best {float(best['lockin_signed_V']) * 1e6:+.3f} uV{anchor_desc}{suffix}"
    )


def angle_status_desc(rows: list[dict], tol_deg: float) -> str:
    """Compact operator-facing proof that measured rows used verified angles."""
    errors = []
    angle_flag = False
    for row in rows:
        flags = str(row.get("quality_flags", "") or "")
        if "angle_error" in flags or "angle_verify_failed" in flags:
            angle_flag = True
        for key in ("hwp_error_deg", "qwp_error_deg", "qwp_readout_error_deg", "anl_null_error_deg", "anl_error_deg"):
            try:
                value = abs(float(row.get(key, float("nan"))))
            except Exception:
                value = float("nan")
            if np.isfinite(value):
                errors.append(value)
    if angle_flag:
        if errors:
            return f"ANGLE CHECK max_err={max(errors):.3f} deg"
        return "ANGLE CHECK"
    if errors:
        max_err = max(errors)
        if max_err <= float(tol_deg):
            return f"ANGLES OK max_err={max_err:.3f} deg"
        return f"ANGLE CHECK max_err={max_err:.3f} deg"
    return "ANGLES UNVERIFIED"


def write_chip_summary(root_dir: Path, pixels: list[dict]) -> None:
    root_dir = Path(root_dir)
    run_config = _read_json_dict(root_dir / "run_config.json")
    chip_id = str(run_config.get("chip_id") or "").strip()
    rows = []
    for pixel in pixels:
        summary = pixel.get("fast_map_summary") or {}
        if not summary:
            continue
        angular_fit = summary.get("angular_response_fit") or {}
        peak_certificate = summary.get("normalized_peak_certificate") or {}
        rows.append({
            "chip_id": chip_id,
            "pixel": pixel.get("pixel"),
            "row": pixel.get("j"),
            "col": pixel.get("i"),
            "status": pixel.get("measurement_status", ""),
            "best_hwp_deg": summary.get("best_hwp_deg"),
            "best_theta_i_deg": summary.get("best_theta_i_deg"),
            "best_theta_i_legacy_deg": summary.get("best_theta_i_legacy_deg"),
            "best_slope_side": summary.get("best_slope_side"),
            "best_anl_deg": summary.get("best_anl_deg"),
            "best_anl_lab_deg": summary.get("best_anl_lab_deg"),
            "best_anl_theta_ana_deg": summary.get("best_anl_theta_ana_deg"),
            "best_qwp_deg": summary.get("best_qwp_deg"),
            "best_qwp_axis_lab_deg": summary.get("best_qwp_axis_lab_deg"),
            "best_qwp_theta_wav_deg": summary.get("best_qwp_theta_wav_deg"),
            "best_qwp_readout_deg": summary.get("best_qwp_readout_deg"),
            "best_qwp_readout_axis_lab_deg": summary.get("best_qwp_readout_axis_lab_deg"),
            "best_qwp_readout_theta_wav_deg": summary.get("best_qwp_readout_theta_wav_deg"),
            "best_a_null_deg": summary.get("best_a_null_deg"),
            "best_a_null_lab_deg": summary.get("best_a_null_lab_deg"),
            "best_a_null_theta_ana_deg": summary.get("best_a_null_theta_ana_deg"),
            "best_vpp": summary.get("best_vpp"),
            "max_abs_signed_response_V": summary.get("max_abs_signed_response_V"),
            "max_signed_response_V": summary.get("max_signed_response_V"),
            "max_lockin_mag_V": summary.get("max_lockin_mag_V"),
            "best_mag_hwp_deg": summary.get("best_mag_hwp_deg"),
            "best_mag_theta_i_deg": summary.get("best_mag_theta_i_deg"),
            "best_mag_theta_i_legacy_deg": summary.get("best_mag_theta_i_legacy_deg"),
            "best_mag_slope_side": summary.get("best_mag_slope_side"),
            "best_mag_anl_deg": summary.get("best_mag_anl_deg"),
            "best_mag_anl_lab_deg": summary.get("best_mag_anl_lab_deg"),
            "best_mag_anl_theta_ana_deg": summary.get("best_mag_anl_theta_ana_deg"),
            "best_mag_qwp_deg": summary.get("best_mag_qwp_deg"),
            "best_mag_qwp_axis_lab_deg": summary.get("best_mag_qwp_axis_lab_deg"),
            "best_mag_qwp_theta_wav_deg": summary.get("best_mag_qwp_theta_wav_deg"),
            "best_mag_qwp_readout_deg": summary.get("best_mag_qwp_readout_deg"),
            "best_mag_qwp_readout_axis_lab_deg": summary.get("best_mag_qwp_readout_axis_lab_deg"),
            "best_mag_qwp_readout_theta_wav_deg": summary.get("best_mag_qwp_readout_theta_wav_deg"),
            "best_mag_a_null_deg": summary.get("best_mag_a_null_deg"),
            "best_mag_a_null_lab_deg": summary.get("best_mag_a_null_lab_deg"),
            "best_mag_a_null_theta_ana_deg": summary.get("best_mag_a_null_theta_ana_deg"),
            "best_mag_vpp": summary.get("best_mag_vpp"),
            "pair_response_V": summary.get("pair_response_V"),
            "pair_response_mag_V": summary.get("pair_response_mag_V"),
            "pair_response_phase_deg": summary.get("pair_response_phase_deg"),
            "delta_prime_proxy_V_per_Vpp": summary.get("delta_prime_proxy_V_per_Vpp"),
            "best_rotation_hwp_deg": summary.get("best_rotation_hwp_deg"),
            "best_rotation_theta_i_deg": summary.get("best_rotation_theta_i_deg"),
            "rotation_slope_rad_per_Vrms": summary.get("rotation_slope_rad_per_Vrms"),
            "rotation_slope_sem_rad_per_Vrms": summary.get("rotation_slope_sem_rad_per_Vrms"),
            "rotation_phase_deg": summary.get("rotation_phase_deg"),
            "angular_fit_status": angular_fit.get("status"),
            "angular_fit_r_squared": angular_fit.get("r_squared_complex"),
            "peak_selection_mode": summary.get("peak_selection_mode"),
            "normalized_peak_certified": int(
                str(peak_certificate.get("status", "")) == "certified"
            ),
            "voltage_linearity_r_squared": summary.get("voltage_linearity_r_squared"),
            "max_null_leakage_fraction": summary.get("max_null_leakage_fraction"),
            "r_eff_abs_pm_per_V": summary.get("r_eff_abs_pm_per_V"),
            "r_eff_abs_sem_pm_per_V": summary.get("r_eff_abs_sem_pm_per_V"),
            "r_eff_status": summary.get("r_eff_status"),
            "n_points": summary.get("n_points"),
            "n_trusted_points": summary.get("n_trusted_points"),
            "quality_flags": ";".join(summary.get("quality_flags", [])),
            "output_dir": pixel.get("fast_map_output_dir", ""),
        })
    canonical_path = root_dir / CHIP_SUMMARY_CSV
    write_rows(canonical_path, rows, CHIP_SUMMARY_FIELDS)
    named_path = run_named_output_path(root_dir, CHIP_SUMMARY_CSV)
    if named_path != canonical_path:
        write_rows(named_path, rows, CHIP_SUMMARY_FIELDS)


def build_arg_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(
        description="Fast Pockels 100-pixel slope-point mapping automation"
    )
    parser.add_argument("--chip-id", default=None,
                        help="Chip identifier stored in run metadata and new-run folder/file names")
    parser.add_argument("--run-name", default=None, help="Optional run label appended to the output folder")
    parser.add_argument("--resume-run", default=None, help="Resume an existing pockels_fast_map run folder")
    parser.add_argument("--stage-cal", default=None, help="Existing stage pixel_positions.json or run folder")
    parser.add_argument("--optical-cal", default="latest", help="Optical calibration JSON, 'latest', or 'none'")
    parser.add_argument(
        "--pixels",
        default=DEFAULT_PIXEL_SELECTION,
        help=(
            "Chip-map pixel list/ranges, e.g. '1-10,15,42', all, or none "
            f"[default {DEFAULT_PIXEL_SELECTION}]"
        ),
    )
    parser.add_argument("--skip-complete", action="store_true", help="Skip completed pixels on resume")
    parser.add_argument("--transport-recovery-attempts", type=int, default=0,
                        help="Reconnect attempts after transport loss; 0 keeps retrying until hardware returns or Stop is pressed [default 0]")
    parser.add_argument("--transport-recovery-delay", type=float, default=5.0,
                        help="Initial reconnect delay in seconds; doubles up to 60 s [default 5]")
    parser.add_argument("--no-realign-stage", dest="realign_stage", action="store_false",
                        help="Use loaded calibrated stage coordinates without per-pixel realignment")
    parser.set_defaults(realign_stage=True)

    parser.add_argument("--hwp-input-frame", choices=("lab", "raw"), default="lab",
                        help="Interpret --hwp-start/stop/step as lab-frame theta_i or raw HWP degrees")
    parser.add_argument(
        "--hwp-grid-preset",
        choices=HWP_GRID_PRESET_OPTIONS,
        default=HWP_GRID_PRESET_CUSTOM,
        help=argparse.SUPPRESS,
    )
    parser.add_argument("--hwp-sweep-mode", choices=("centered-180", "start-stop"),
                        default=DEFAULT_HWP_SWEEP_MODE,
                        help=("centered-180 uses --hwp-start as the centre. In lab frame it "
                              "measures theta_i centre +/-90 deg; in raw frame it measures "
                              "HWP raw centre +/-45 deg, which is still 180 deg of theta_i. "
                              "start-stop uses --hwp-start/stop/step directly"))
    parser.add_argument("--hwp-points", type=int, default=DEFAULT_HWP_CENTER_SWEEP_POINTS,
                        help=f"Odd point count for --hwp-sweep-mode centered-180 "
                             f"[default {DEFAULT_HWP_CENTER_SWEEP_POINTS}]")
    parser.add_argument("--hwp-center-step", type=float, default=None,
                        help=("Incident theta_i step for centered-180 mode. "
                              "When --hwp-input-frame raw is used, the raw HWP motor step is half this value."))
    parser.add_argument(
        "--hwp-start",
        type=float,
        default=lab_theta_i_from_hwp(DEFAULT_HWP_GRID_CENTER_RAW_DEG),
        help=(
            "Start angle, or centre for centered-180 mode "
            f"[default theta_i {lab_theta_i_from_hwp(DEFAULT_HWP_GRID_CENTER_RAW_DEG):.4f} "
            f"deg lab = HWP raw {DEFAULT_HWP_GRID_CENTER_RAW_DEG:.4f} deg]"
        ),
    )
    parser.add_argument("--hwp-stop", type=float, default=165.0)
    parser.add_argument("--hwp-step", type=float, default=15.0)
    parser.add_argument("--manual-peak-hwp", type=float, default=None,
                        help="Optional exact raw HWP angle for a manual lock-in peak scout")
    parser.add_argument("--manual-peak-qwp", type=float, default=None,
                        help="Optional exact raw QWP angle for a manual lock-in peak scout")
    parser.add_argument("--manual-peak-anl", type=float, default=None,
                        help="Optional exact raw analyser angle for a manual lock-in peak scout")
    parser.add_argument("--manual-peak-only", action="store_true",
                        help="Only measure the manual raw peak point(s), skipping the normal null/slope sweep")
    parser.add_argument("--manual-peak-calibration-pixels", type=int, default=1,
                        help=("Number of selected pixels that run the manual raw/anchor branch certification. "
                              "Later pixels use the calibrated null/readout branch without extra manual-anchor reads."))
    parser.add_argument(
        "--calibration-pixel",
        type=int,
        default=None,
        help=(
            "Physical chip pixel used first for per-HWP null calibration and "
            "full EO/readout calibration. It must be in --pixels. When omitted, "
            "the first selected pixel is used for backward compatibility."
        ),
    )
    parser.add_argument("--auto-peak-calibration-pixels", type=int,
                        default=DEFAULT_AUTO_PEAK_CALIBRATION_PIXELS,
                        help=("Number of pixels, starting with --calibration-pixel, that establish "
                              "the full per-HWP sample null and normalized readout table [default 1]. The robust "
                              "locked-QWP/triplet path adds a compact complex EO + DC Malus "
                              "operating-point certificate, not a raw-magnitude peak search."))
    parser.add_argument("--auto-peak-max-coarse-probes", type=int,
                        default=DEFAULT_AUTO_PEAK_MAX_COARSE_PROBES,
                        help=("Maximum QWP/analyser seed probes for the first-HWP automatic peak search. "
                              "Use 0 for the old exhaustive 143-probe coarse grid."))
    parser.add_argument("--auto-peak-track-mode", choices=("locked-qwp", "confirm", "refine", "global", "hybrid"),
                        default=DEFAULT_AUTO_PEAK_TRACK_MODE,
                        help=("How later HWP angles are handled after the first automatic peak. "
                              "locked-qwp keeps the QWP on the null-compensated branch and only refines the "
                              "analyser near the theoretical +/-45 slope point; confirm measures the predicted "
                              "QWP/ANL point once; refine runs a 2D QWP/ANL local maximizer around the prediction; "
                              "global runs a full periodic QWP/ANL grid plus refinement at every HWP on the calibration pixel; hybrid runs the "
                              "bounded coarse search once, then prediction plus 2D refinement for later HWP angles."))
    parser.add_argument("--peak-refine-mode", choices=("two-point", "fit", "greedy"),
                        default=AUTO_PEAK_REFINE_MODE,
                        help=("Legacy peak-search analyser strategy; the standard locked-QWP/triplet "
                              "workflow uses its separate adaptive S9 certificate and ignores this option. "
                              "'two-point' measures only analyser +45/-45; 'fit' "
                              "solves the exact P + A*sin(2*psi+phi) model over the null/+45/-45 "
                              "points plus two extra probes (~6 lock-in points, analytic peak, "
                              "pickup phasor and R2 gate, greedy fallback on any gate failure); "
                              "'greedy' is the legacy hill-climb (~16 points)."))
    parser.add_argument("--learned-readout-mode",
                        choices=("peak-only", "zero-anchor", "triplet"),
                        default=DEFAULT_LEARNED_READOUT_MODE,
                        help=("How pixels after the calibration pixel use learned HWP peak angles. "
                              "triplet [default] measures the local AC background and both opposite "
                              "quadrature slopes for normalized phase/pickup rejection; zero-anchor "
                              "omits the opposite slope; peak-only is a legacy speed diagnostic."))
    parser.add_argument("--peak-diagnostic", action="store_true",
                        help=("After each calibration peak readout, probe QWP/ANL +/- step and repeat the "
                              "center to certify the lock-in peak for that HWP."))
    parser.add_argument("--peak-diagnostic-step", type=float, default=DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG,
                        help=f"QWP/ANL step in degrees for peak certification probes [default {DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG:g}]")
    parser.add_argument("--peak-diagnostic-min-margin-uv", type=float, default=DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV,
                        help=("Allowed amount by which a neighboring diagnostic probe may exceed the center "
                              f"before failing certification [default {DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV:g} uV]"))
    parser.add_argument("--post-analyser-sweep-pixels", default="",
                        help="Pixel list that should run analyser-angle sweeps before pixel cleanup.")
    parser.add_argument("--post-analyser-sweep-vpp-values", default="",
                        help="Comma-separated AC Vpp values for post-fast-map analyser sweeps.")
    parser.add_argument("--post-analyser-sweep-start", type=float, default=15.0,
                        help="Start analyser raw angle for post-fast-map analyser sweeps.")
    parser.add_argument("--post-analyser-sweep-stop", type=float, default=195.0,
                        help="Stop analyser raw angle for post-fast-map analyser sweeps.")
    parser.add_argument("--post-analyser-sweep-step", type=float, default=10.0,
                        help="Analyser raw-angle step for post-fast-map analyser sweeps.")
    parser.add_argument("--post-analyser-sweep-dc-hold", type=float, default=pockels.DC_POLING_V_PHASE_A,
                        help="SMU DC hold voltage during post-fast-map analyser sweeps.")
    parser.add_argument("--post-analyser-sweep-dwell", type=float, default=5.0,
                        help="Extra DC dwell before the first analyser sweep at each HWP.")
    parser.add_argument("--post-analyser-sweep-all-hwp", dest="post_analyser_sweep_peak_only",
                        action="store_false",
                        help="Run post-fast-map analyser sweeps at every saved HWP point instead of only the peak HWP.")
    parser.set_defaults(post_analyser_sweep_peak_only=True)
    parser.add_argument("--post-ac-vpp-sweep-pixels", default="",
                        help="Pixel list that should run fixed-peak AC Vpp sweeps before pixel cleanup.")
    parser.add_argument("--post-ac-vpp-sweep-values", default="1,3,5,7,9",
                        help="Comma-separated AC Vpp values for post-fast-map fixed-peak AC sweeps.")
    parser.add_argument("--post-ac-vpp-sweep-dc-hold", type=float, default=pockels.DC_POLING_V_PHASE_A,
                        help="SMU DC hold voltage during post-fast-map AC Vpp sweeps.")
    parser.add_argument("--post-ac-vpp-sweep-dwell", type=float, default=pockels.AC_VPP_PRE_MEASURE_DWELL_S,
                        help="DC/AC hold time before each post-fast-map AC Vpp measurement.")
    parser.add_argument("--post-dc-hysteresis-pixels", default="",
                        help="Pixel list that should run fixed-peak DC hysteresis before pixel cleanup.")
    parser.add_argument("--post-dc-hysteresis-dwell", type=float,
                        default=DEFAULT_HYSTERESIS_DWELL_S,
                        help="Per-step DC-only poling dwell for post-fast-map "
                             "DC hysteresis sweeps "
                             f"[default {DEFAULT_HYSTERESIS_DWELL_S:g} s]. Loop shape is "
                             "rate-dependent - keep the dwell fixed within a campaign.")
    parser.add_argument("--post-dc-hysteresis-reset-domains", action="store_true",
                        help="Run domain reset before each post-fast-map DC hysteresis sweep.")
    parser.add_argument("--post-dc-hysteresis-start-from-zero", dest="post_dc_hysteresis_start_from_zero",
                        action="store_true", default=False,
                        help="Start post-fast-map DC hysteresis from 0 V.")
    parser.add_argument("--post-dc-hysteresis-start-from-vmax", dest="post_dc_hysteresis_start_from_zero",
                        action="store_false",
                        help="Start post-fast-map DC hysteresis from +Vmax.")
    parser.add_argument("--post-dc-hysteresis-cycles", type=int,
                        default=DEFAULT_HYSTERESIS_CYCLES,
                        help="Full down+up loop cycles per pixel "
                             f"[default {DEFAULT_HYSTERESIS_CYCLES}].")
    parser.add_argument("--post-dc-hysteresis-vmax", type=float,
                        default=pockels.DC_HYST_VMAX,
                        help="Symmetric DC hysteresis endpoint in volts. May be "
                             f"reduced but cannot exceed {pockels.DC_HYST_VMAX:g} V "
                             f"[default {pockels.DC_HYST_VMAX:g} V].")
    parser.add_argument("--post-dc-hysteresis-voltage-step", type=float,
                        default=DEFAULT_HYSTERESIS_VOLTAGE_STEP_V,
                        help="Optional uniform DC voltage-spacing override. "
                             "Unset uses the centre-dense profile; at the "
                             "default +/-40 V limit this is 45 points with "
                             "1.25/2.5 V resolution near 0 V.")
    parser.add_argument("--post-dc-hysteresis-ac-vpp", type=float,
                        default=DEFAULT_HYSTERESIS_AC_VPP,
                        help="AC probe amplitude (Vpp), gated on only for each "
                             "post-poling lock-in measurement window "
                             f"[default {DEFAULT_HYSTERESIS_AC_VPP:g} Vpp; "
                             "<=0 keeps the fast-map peak Vpp].")
    parser.add_argument(
        "--post-dc-hysteresis-dynamic-lockin-range",
        dest="post_dc_hysteresis_dynamic_lockin_range",
        action="store_true",
        default=DEFAULT_HYSTERESIS_DYNAMIC_LOCKIN_RANGE,
        help=(
            "Enable predictive hysteretic 5-200 uV RMS DSP7230 ranging for "
            "DC hysteresis only. Planned changes occur while the AC probe is "
            "off during the existing DC dwell."
        ),
    )
    parser.add_argument(
        "--post-dc-hysteresis-fixed-lockin-range",
        dest="post_dc_hysteresis_dynamic_lockin_range",
        action="store_false",
        help="Keep the selected lock-in sensitivity fixed during DC hysteresis.",
    )
    parser.add_argument("--post-dc-hysteresis-min-dwell", type=float, default=0.5,
                        help="Dwell floor for map-mode loops [default 0.5 s].")
    parser.add_argument("--post-dc-hysteresis-adaptive-window",
                        dest="post_dc_hysteresis_adaptive_window",
                        action="store_true", default=DEFAULT_HYSTERESIS_ADAPTIVE_WINDOW,
                        help="Coarse recon loop first, then centre the fine grid on the "
                             "detected coercive voltages. When enabled, this overrides "
                             "the standard grid and any uniform-step override.")
    parser.add_argument("--post-dc-hysteresis-fixed-window",
                        dest="post_dc_hysteresis_adaptive_window", action="store_false",
                        help="Disable adaptive reconnaissance and use the standard "
                             "centre-dense grid, or the configured uniform override.")
    parser.add_argument("--post-dc-hysteresis-quasi-static",
                        dest="post_dc_hysteresis_quasi_static",
                        action="store_true", default=False,
                        help="Legacy physics mode: 30 s dwell floor, 1 cycle, peak Vpp "
                             "dither, standard centre-dense voltage grid.")
    parser.add_argument(
        "--voltages",
        default=str(DEFAULT_FAST_MAP_AC_VPP),
        help=(
            "Comma-separated AC Vpp list "
            f"[default {DEFAULT_FAST_MAP_AC_VPP:g}; use 1,3,5,9 for linearity]"
        ),
    )
    # Present for compatibility with auto.configure_shared_measurement_globals.
    parser.add_argument("--anl-start", type=float, default=pockels.ANL_START)
    parser.add_argument("--anl-stop", type=float, default=pockels.ANL_STOP)

    parser.add_argument("--poling-voltage", type=float, default=pockels.DC_POLING_V_PHASE_A)
    parser.add_argument("--poling-dwell", type=float, default=FAST_MAP_POLING_DWELL_S,
                        help="Per-pixel DC poling hold before fast-map reads [default 180 s; "
                             "with --adaptive-poling this is the CAP, not the fixed time]")
    parser.add_argument("--adaptive-poling", dest="adaptive_poling",
                        action="store_true", default=True,
                        help="v2: monitor the lock-in during poling and stop at plateau "
                             "[default on; --poling-dwell becomes the cap].")
    parser.add_argument("--fixed-poling-dwell", dest="adaptive_poling",
                        action="store_false",
                        help="Disable adaptive poling; always sleep the full --poling-dwell.")
    parser.add_argument("--adaptive-poling-min-s", type=float, default=60.0,
                        help="Minimum poling time before an early stop is allowed [60 s].")
    parser.add_argument("--adaptive-poling-poll-s", type=float, default=10.0,
                        help="Monitor sampling interval during poling [10 s].")
    parser.add_argument("--adaptive-poling-stable-pct", type=float, default=2.0,
                        help="Relative |M| change per interval counted as quiet [2 %%].")
    parser.add_argument("--adaptive-poling-stable-count", type=int, default=3,
                        help="Consecutive quiet intervals required to stop [3].")
    parser.add_argument("--adaptive-poling-min-signal-uv", type=float, default=2.0,
                        help="Minimum |M| (uV) for early stop; weaker pixels always "
                             "get the full dwell [2 uV].")
    parser.add_argument("--adaptive-poling-monitor-vpp", type=float, default=0.0,
                        help="AC dither during poling monitor; <=0 uses the lowest "
                             "--voltages value.")
    parser.add_argument("--smu-port", default=auto.AUTO_PORT)
    parser.add_argument(
        "--smu-compliance",
        type=float,
        default=pockels.SMU_COMPLIANCE_A,
        help=(
            "SMU4201 source-voltage current compliance in amperes "
            f"[default {pockels.SMU_COMPLIANCE_A:g} A = "
            f"{pockels.SMU_COMPLIANCE_A * 1e3:g} mA]"
        ),
    )
    parser.add_argument("--smu-ramp-step", type=float, default=pockels.SMU_RAMP_STEP_V)
    parser.add_argument("--smu-ramp-dwell", type=float, default=pockels.SMU_RAMP_DWELL_S)
    parser.add_argument("--require-smu", dest="require_smu", action="store_true", default=True,
                        help="Stop if the SMU4201 cannot be opened")
    parser.add_argument("--allow-fake-smu", dest="require_smu", action="store_false",
                        help="Allow FakeSMU fallback if the SMU4201 cannot be opened")

    parser.add_argument("--lockin-settle", type=float, default=DEFAULT_LOCKIN_SETTLE_S)
    parser.add_argument("--lockin-avg-readings", type=int, default=DEFAULT_LOCKIN_AVG_READINGS)
    parser.add_argument("--lockin-read-delay", type=float, default=DEFAULT_LOCKIN_READ_DELAY_S)
    parser.add_argument("--lockin-tc-index", type=int, default=DEFAULT_LOCKIN_TC_INDEX,
                        help="DSP7230 time-constant index [default 14 = 500 ms]")
    parser.add_argument("--lockin-filter-slope-db", type=int, choices=(6, 12, 18, 24),
                        default=DEFAULT_LOCKIN_FILTER_SLOPE_DB,
                        help="DSP7230 output filter slope in dB/oct [default 12]")
    parser.add_argument("--lockin-sensitivity-index", type=int, choices=range(3, 28),
                        default=DEFAULT_LOCKIN_SENSITIVITY_INDEX,
                        help="Fixed DSP7230 voltage sensitivity index; the fast-map "
                             "workflow never changes it automatically "
                             "[default 16 = 200 uV RMS full scale]")
    parser.add_argument("--lockin-reference-source",
                        choices=("external-analog", "external-ttl", "internal"),
                        default="external-analog",
                        help="DSP7230 reference input [default external analog from function-generator CH2]")
    parser.add_argument("--lockin-reference-tolerance-hz", type=float, default=1.0,
                        help="Minimum allowed DSP7230 reference-frequency error; 1 percent is also allowed")
    parser.add_argument("--allow-unlocked-reference", action="store_true",
                        help="Continue despite a zero or mismatched DSP7230 FRQ readback")
    parser.add_argument("--lockin-reference-phase", type=float, default=0.0,
                        help="Reference phase for signed mag*cos(phase-ref) calculation")
    parser.add_argument("--qwp-readout-offset", type=float, default=DEFAULT_QWP_READOUT_OFFSET_DEG,
                        help=("QWP offset from the AC-off null used for lock-in readout. "
                              "0 keeps the Abel null-compensation geometry; 45 deg is the separate quadrature-bias protocol."))
    parser.add_argument("--require-lockin", dest="require_lockin", action="store_true", default=True,
                        help="Stop if the DSP7230 lock-in cannot be opened")
    parser.add_argument("--allow-fake-lockin", dest="require_lockin", action="store_false",
                        help="Explicitly allow FakeLockin fallback if the DSP7230 cannot be opened")
    parser.add_argument("--simulate-lockin", action="store_true",
                        help="Use FakeLockin immediately")

    parser.add_argument("--funcgen-freq", type=float, default=pockels.FUNCGEN_FREQ_HZ)
    parser.add_argument("--funcgen-settle", type=float, default=0.2)
    parser.add_argument("--bto-wavelength-nm", type=float, default=1550.0)
    parser.add_argument("--bto-film-thickness-nm", type=float, default=None)
    parser.add_argument("--bto-film-thickness-std-nm", type=float, default=None)
    parser.add_argument("--bto-electrode-gap-um", type=float, default=None)
    parser.add_argument("--bto-electrode-gap-std-um", type=float, default=None)
    parser.add_argument("--bto-field-correction", type=float, default=None,
                        help="alpha in E = alpha*V_device/g; obtain for this electrode/beam geometry from FEM")
    parser.add_argument("--bto-field-correction-std", type=float, default=None)
    parser.add_argument("--bto-refractive-index", type=float, default=2.1)
    parser.add_argument("--bto-refractive-index-std", type=float, default=None)
    parser.add_argument("--bto-device-vpp-scale", type=float, default=None,
                        help="measured device Vpp / programmed function-generator Vpp")
    parser.add_argument("--bto-device-vpp-scale-std", type=float, default=None)
    parser.add_argument("--bto-detector-ac-gain-over-dc-gain", type=float, default=None,
                        help="lock-in channel V/W at modulation frequency divided by scope DC channel V/W")
    parser.add_argument("--bto-detector-ac-gain-over-dc-gain-std", type=float, default=None)
    parser.add_argument("--bto-geometry-confirmed", action="store_true",
                        help="Confirm the null-slope Senarmont geometry and enable |r_eff| calculation")
    parser.add_argument("--bto-sine-drive-confirmed", action="store_true",
                        help="Confirm CH1 is a zero-offset sine so Vpp/(2*sqrt(2)) is valid")
    parser.add_argument("--no-laser", dest="use_laser", action="store_false",
                        help="Disable KLS1550 laser control")
    parser.set_defaults(use_laser=True)
    parser.add_argument("--laser-power-mw", type=float, default=7.0,
                        help="KLS1550 laser absolute power setpoint in mW")
    parser.add_argument("--laser-serial", default=None,
                        help="Optional KLS1550 serial; default auto-detect")
    parser.add_argument("--laser-off-start", dest="laser_on_start", action="store_false",
                        help="Connect the KLS1550 but leave emission off at startup")
    parser.set_defaults(laser_on_start=True)

    parser.add_argument("--arduino-port", default=auto.AUTO_PORT)
    parser.add_argument("--arduino-baud", type=int, default=stage.ARDUINO_BAUD)
    parser.add_argument("--arduino-settle", type=float, default=stage.VOLTAGE_SETTLE_S)
    parser.add_argument("--no-arduino", action="store_true")
    parser.add_argument("--allow-no-arduino", action="store_true")
    parser.add_argument("--manual-probing", action="store_true",
                        help="Pause after each pixel alignment for manual probe placement; disables Arduino routing")
    parser.add_argument("--list-serial-ports", action="store_true",
                        help="List detected lab COM ports and exit")
    parser.add_argument("--show-bluetooth-ports", action="store_true",
                        help="Include Bluetooth serial links in --list-serial-ports output")
    parser.add_argument("--show-range-changes", action="store_true",
                        help="Show routine oscilloscope [RANGE] autorange messages")
    parser.add_argument("--show-wrap-moves", action="store_true",
                        help="Show successful analyser [WRAP-MOVE] messages")

    parser.add_argument("--min-signal-mv", type=float, default=50.0)
    parser.add_argument("--null-check-max-mv", type=float, default=14.5,
                        help="Substrate seed/adaptive null acceptance threshold in detector mV")
    parser.add_argument("--null-certify-margin-mv", type=float, default=1.50,
                        help=("Final detector-read continuation margin above "
                              "--null-check-max-mv; marginal and high finite nulls "
                              "continue with quality flags, while high nulls are not "
                              "saved as trusted seeds/readouts [default 1.50]"))
    parser.add_argument("--stage-brighten-offset", type=float, default=45.0,
                        help="Analyzer offset from null used only for stage alignment brightness")
    parser.add_argument("--conservative-rotator-moves", dest="fast_rotator_moves",
                        action="store_false",
                        help="Use slower boundary-safe chunked moves for analyzer slope points")
    parser.set_defaults(fast_rotator_moves=True)
    parser.add_argument("--renull-mode", choices=("seed-only", "adaptive-renull", "fast-renull"),
                        default=DEFAULT_RENULL_MODE,
                        help=("seed-only uses the substrate HWP null table; adaptive-renull [default] re-nulls "
                              "QWP/ANL only if the seed null check is high; fast-renull optimizes "
                              "QWP/ANL at every pixel/HWP"))
    parser.add_argument("--no-verify-fast-rotator-moves", dest="verify_fast_rotator_moves",
                        action="store_false",
                        help="Disable readback/correct-once verification for fast direct rotator moves")
    parser.set_defaults(verify_fast_rotator_moves=DEFAULT_VERIFY_FAST_ROTATOR_MOVES)
    parser.add_argument("--rotator-verify-tol", type=float,
                        default=DEFAULT_ROTATOR_VERIFY_TOL_DEG,
                        help="Angle error tolerance in degrees before a fast move gets one corrective retry")
    parser.add_argument("--rotator-velocity-pct", type=int, default=DEFAULT_FAST_ROTATOR_VELOCITY_PCT,
                        help="Elliptec rotator velocity percent for continuous direct moves [default 50]")
    parser.add_argument("--skip-stage-home", action="store_true")
    parser.add_argument("--no-camera", action="store_true")
    parser.add_argument("--no-rotator-home", action="store_true")
    parser.add_argument("--yes", action="store_true", help="Skip prompts")

    parser.add_argument("--phase-substrate", choices=("load", "do", "skip"), default="do",
                        help="Load/do/skip substrate HWP null seeds [default do]")
    parser.add_argument("--substrate-cal", default=None,
                        help="substrate_calibration.json or run folder")
    parser.add_argument(
        "--substrate-cal-pixel",
        type=int,
        default=None,
        help=(
            "Advanced override for the physical pixel used if --phase-substrate do. "
            "By default --calibration-pixel is used; 0 keeps the current position."
        ),
    )
    parser.add_argument("--substrate-null-tol", type=float, default=0.05,
                        help="Substrate calibration descent tolerance in degrees when doing Phase 1")
    parser.add_argument("--substrate-null-max-evals", type=int, default=220,
                        help="Maximum descent probes per HWP during substrate calibration")
    parser.add_argument("--gui-stop-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-skip-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-manual-probe-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-camera-frame-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-state-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-alignment-file", default=None, help=argparse.SUPPRESS)
    parser.add_argument("--gui-laser-command-file", default=None, help=argparse.SUPPRESS)
    return parser


def main(argv: list[str] | None = None) -> int:
    global GUI_STOP_FILE, GUI_SKIP_FILE, GUI_MANUAL_PROBE_FILE, GUI_CAMERA_FRAME_FILE, GUI_STATE_FILE, GUI_ALIGNMENT_FILE, GUI_LASER_COMMAND_FILE, GUI_PIXEL_SKIP_ENABLED, GUI_PIXEL_SKIP_LATCHED, GUI_PIXEL_SKIP_ACKED
    args = build_arg_parser().parse_args(argv)
    if args.transport_recovery_attempts < 0:
        raise ValueError("--transport-recovery-attempts must be >= 0")
    if not np.isfinite(args.transport_recovery_delay) or not 0 < args.transport_recovery_delay <= 60:
        raise ValueError("--transport-recovery-delay must be > 0 and <= 60 seconds")
    if args.manual_probing:
        args.no_arduino = True
        args.allow_no_arduino = True
    manual_peak_values = [args.manual_peak_hwp, args.manual_peak_qwp, args.manual_peak_anl]
    manual_peak_requested = any(value is not None for value in manual_peak_values)
    if manual_peak_requested and not all(value is not None for value in manual_peak_values):
        raise ValueError(
            "Manual raw peak scout requires all three angles: "
            "--manual-peak-hwp, --manual-peak-qwp, and --manual-peak-anl."
        )
    manual_peak_raw = None
    if manual_peak_requested:
        manual_peak_raw = {
            "hwp_deg": wrap360(float(args.manual_peak_hwp)),
            "qwp_deg": wrap360(float(args.manual_peak_qwp)),
            "anl_deg": wrap360(float(args.manual_peak_anl)),
        }
        if not args.no_rotator_home:
            print(
                "\n[MANUAL PEAK] Exact raw rotator angles were supplied; "
                "forcing --no-rotator-home so these coordinates are not re-tared."
            )
            args.no_rotator_home = True
    elif args.manual_peak_only:
        raise ValueError("--manual-peak-only requires manual peak HWP/QWP/ANL angles.")
    args.manual_peak_calibration_pixels = max(0, int(args.manual_peak_calibration_pixels))
    args.auto_peak_calibration_pixels = max(0, int(args.auto_peak_calibration_pixels))
    args.auto_peak_max_coarse_probes = max(0, int(args.auto_peak_max_coarse_probes))
    try:
        args.peak_diagnostic_step = abs(float(args.peak_diagnostic_step))
    except Exception:
        args.peak_diagnostic_step = DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG
    if not np.isfinite(float(args.peak_diagnostic_step)) or float(args.peak_diagnostic_step) <= 0.0:
        args.peak_diagnostic_step = DEFAULT_PEAK_DIAGNOSTIC_STEP_DEG
    try:
        args.peak_diagnostic_min_margin_uv = abs(float(args.peak_diagnostic_min_margin_uv))
    except Exception:
        args.peak_diagnostic_min_margin_uv = DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV
    if not np.isfinite(float(args.peak_diagnostic_min_margin_uv)):
        args.peak_diagnostic_min_margin_uv = DEFAULT_PEAK_DIAGNOSTIC_MIN_MARGIN_UV
    if manual_peak_raw and not args.manual_peak_only and args.manual_peak_calibration_pixels <= 0:
        print("\n[MANUAL PEAK] Calibration-pixel count was 0; using 1 so the branch is proven before the chip sweep.")
        args.manual_peak_calibration_pixels = 1
    if (
        bool(args.peak_diagnostic)
        and not manual_peak_raw
        and not args.manual_peak_only
        and args.auto_peak_calibration_pixels <= 0
    ):
        print("\n[PEAK DIAG] Peak diagnostic needs an automatic peak-calibration pixel; using 1.")
        args.auto_peak_calibration_pixels = 1
    if bool(args.bto_geometry_confirmed) and str(args.learned_readout_mode) != "triplet":
        print(
            "\n[BTO PHYSICS] Enabling learned-readout triplets so every coefficient point "
            "has a null pickup reference and an opposite-slope check."
        )
        args.learned_readout_mode = "triplet"
    if args.manual_peak_only and args.phase_substrate == "do":
        print(
            "\n[MANUAL PEAK] --manual-peak-only does not use substrate null seeds; "
            "switching --phase-substrate from do to skip for a fast diagnostic."
        )
        args.phase_substrate = "skip"
    if manual_peak_raw and not args.manual_peak_only and args.renull_mode == "seed-only":
        print(
            "\n[MANUAL PEAK] Manual raw peak anchoring requires adaptive renull; "
            "switching --renull-mode seed-only -> adaptive-renull."
        )
        args.renull_mode = "adaptive-renull"
    args.post_dc_hysteresis_vmax = pockels.validate_hysteresis_voltage_limit(
        args.post_dc_hysteresis_vmax,
        "Post-map DC hysteresis Vmax",
    )
    if (
        args.post_dc_hysteresis_voltage_step is not None
        and float(args.post_dc_hysteresis_voltage_step)
        > 2.0 * float(args.post_dc_hysteresis_vmax)
    ):
        raise ValueError(
            "Post-map DC hysteresis voltage step cannot exceed the full "
            f"{2.0 * float(args.post_dc_hysteresis_vmax):g} V sweep span."
        )
    GUI_STOP_FILE = Path(args.gui_stop_file).expanduser().resolve() if args.gui_stop_file else None
    GUI_SKIP_FILE = Path(args.gui_skip_file).expanduser().resolve() if args.gui_skip_file else None
    GUI_MANUAL_PROBE_FILE = Path(args.gui_manual_probe_file).expanduser().resolve() if args.gui_manual_probe_file else None
    GUI_CAMERA_FRAME_FILE = Path(args.gui_camera_frame_file).expanduser().resolve() if args.gui_camera_frame_file else None
    GUI_STATE_FILE = Path(args.gui_state_file).expanduser().resolve() if args.gui_state_file else None
    GUI_ALIGNMENT_FILE = Path(args.gui_alignment_file).expanduser().resolve() if args.gui_alignment_file else None
    GUI_LASER_COMMAND_FILE = Path(args.gui_laser_command_file).expanduser().resolve() if args.gui_laser_command_file else None
    if GUI_SKIP_FILE is not None:
        install_gui_skip_hooks()
    gui_update_state(
        running=True,
        dc_voltage_on=False,
        ac_voltage_on=False,
        laser_on=False,
        laser_power_mW=float(args.laser_power_mw),
        manual_probing=bool(args.manual_probing),
        manual_probe_waiting=False,
        phase="Initializing",
    )
    args.anl_points = 2

    if args.list_serial_ports:
        auto.print_serial_ports(include_bluetooth=args.show_bluetooth_ports)
        return 0

    spyder_interactive_setup(args, argv)
    maybe_prompt_substrate_cal(args)
    auto.resolve_instrument_serial_ports(args)
    voltages = configure_fast_globals(args)
    rotator_velocity_pct = configure_rotator_velocity(args)
    root_dir = make_fast_run_dir(args)
    stage_dir = root_dir / auto.DEFAULT_STAGE_SUBDIR
    pixels_dir = root_dir / auto.DEFAULT_PIXELS_SUBDIR
    stage_dir.mkdir(parents=True, exist_ok=True)
    pixels_dir.mkdir(parents=True, exist_ok=True)
    auto.set_stage_output_dir(stage_dir)

    resumed_pixels, records, resumed_seeds = auto.load_resume_state(root_dir)
    resume_state_loaded = resumed_pixels is not None
    if resumed_pixels is not None:
        pixels = resumed_pixels
        null_seed_by_hwp = resumed_seeds
        print(f"Resuming {root_dir}: {len(records)} pixel records loaded.")
    else:
        pixels, n_stage_calibrated = auto.load_stage_pixels(args.stage_cal)
        null_seed_by_hwp = {}
        print(f"Stage calibrated positions loaded: {n_stage_calibrated}/{len(pixels)}")

    total = len(pixels)
    selected_pixels = parse_chip_pixel_selection(args.pixels, total)
    originally_selected_pixels = list(selected_pixels)
    calibration_pixel, selected_pixels = resolve_calibration_pixel(
        selected_pixels,
        getattr(args, "calibration_pixel", None),
        total,
        include_if_missing=bool(args.resume_run),
    )
    args.calibration_pixel = calibration_pixel
    if calibration_pixel is not None and calibration_pixel not in originally_selected_pixels:
        print(
            f"\n[RESUME] Reinserted calibration pixel {calibration_pixel:03d} "
            "into the work queue; completed artifacts will still be skipped."
        )
    if args.substrate_cal_pixel is None:
        args.substrate_cal_pixel = calibration_pixel if calibration_pixel is not None else 0
    else:
        args.substrate_cal_pixel = int(args.substrate_cal_pixel)
        if args.substrate_cal_pixel < 0 or args.substrate_cal_pixel > total:
            raise ValueError(
                f"Substrate calibration pixel must be 0 or between 1 and {total}."
            )
    post_analyser_pixels = (
        set(auto.parse_pixel_selection(args.post_analyser_sweep_pixels, total))
        if str(args.post_analyser_sweep_pixels or "").strip()
        else set()
    )
    post_ac_pixels = (
        set(auto.parse_pixel_selection(args.post_ac_vpp_sweep_pixels, total))
        if str(args.post_ac_vpp_sweep_pixels or "").strip()
        else set()
    )
    post_dc_pixels = (
        set(auto.parse_pixel_selection(args.post_dc_hysteresis_pixels, total))
        if str(args.post_dc_hysteresis_pixels or "").strip()
        else set()
    )
    post_analyser_vpp_values = (
        _parse_gui_number_list(
            args.post_analyser_sweep_vpp_values or args.voltages,
            label="Post-map analyser AC Vpp",
        )
        if post_analyser_pixels
        else []
    )
    post_ac_vpp_values = (
        _parse_gui_number_list(args.post_ac_vpp_sweep_values, label="Post-map AC Vpp")
        if post_ac_pixels
        else []
    )
    selected_pixel_set = set(int(p) for p in selected_pixels)
    post_followup_pixels = post_analyser_pixels | post_ac_pixels | post_dc_pixels
    if not selected_pixels and not post_followup_pixels:
        print(
            "\n[ERROR] No chip-map pixels and no follow-up pixels were selected. "
            "Set Pixels to a list/all, or set DC/AC/ANL follow-up pixels."
        )
        return 2
    if args.resume_run and not selected_pixels and post_followup_pixels:
        metadata_backups = preserve_historical_followup_source_metadata(root_dir)
        if metadata_backups:
            print(
                "\n[HISTORICAL FOLLOW-UP] Original run metadata preserved before "
                "adding follow-up results:"
            )
            for backup_path in metadata_backups:
                print(f"  {backup_path}")
    pixel_work_queue = ordered_pixel_work_queue(
        selected_pixels,
        post_analyser_pixels,
        post_ac_pixels,
        post_dc_pixels,
        first_pixel=calibration_pixel,
    )
    followup_only_initial = sorted(post_followup_pixels - selected_pixel_set)
    if followup_only_initial:
        print(
            "\n[ORDER] Follow-up-only pixels are merged into the numeric per-pixel "
            "queue and use saved chip-sweep peak conditions: "
            + _format_pixel_ranges(followup_only_initial)
        )
    hwp_input_grid = hwp_input_grid_from_args(args)
    hwp_angles = hwp_angles_from_args(args)
    hwp_lab_theta_i_angles = hwp_lab_theta_i_grid_from_args(args)
    hwp_input_step = (
        float(hwp_input_grid[1] - hwp_input_grid[0])
        if len(hwp_input_grid) > 1 else float("nan")
    )
    peak_readout_required = peak_readout_mode_requested(args, manual_peak_raw)
    reuse_resume_peak_calibration = can_reuse_resume_peak_calibration(
        resume_state_loaded=resume_state_loaded,
        peak_readout_required=peak_readout_required,
        hwp_angles=hwp_angles,
        null_seed_by_hwp=resumed_seeds,
    )
    if reuse_resume_peak_calibration:
        print(
            "\n[RESUME] Saved peak calibration covers every requested HWP angle; "
            "later pixels will reuse it without assigning a new calibration pixel."
        )
    manual_cal_pixel_count = sum(
        1 for seq, _pix in enumerate(selected_pixels, start=1)
        if (
            not reuse_resume_peak_calibration
            and manual_peak_enabled_for_pixel_sequence(args, seq, manual_peak_raw)
        )
    )
    auto_peak_cal_pixel_count = sum(
        1 for seq, _pix in enumerate(selected_pixels, start=1)
        if (
            not reuse_resume_peak_calibration
            and auto_peak_enabled_for_pixel_sequence(args, seq, manual_peak_raw)
        )
    )
    normal_points_per_pixel = fast_map_points_for_pixel(
        hwp_angles=hwp_angles,
        voltages=voltages,
        manual_peak_raw=None,
        manual_peak_only=bool(args.manual_peak_only),
        auto_peak_calibration=False,
        peak_readout_required=bool(peak_readout_required),
        learned_readout_mode=str(args.learned_readout_mode),
        peak_diagnostic=False,
    )
    calibration_points_per_pixel = fast_map_points_for_pixel(
        hwp_angles=hwp_angles,
        voltages=voltages,
        manual_peak_raw=manual_peak_raw,
        manual_peak_only=bool(args.manual_peak_only),
        auto_peak_calibration=False,
        peak_readout_required=bool(peak_readout_required),
        learned_readout_mode=str(args.learned_readout_mode),
        peak_diagnostic=bool(args.peak_diagnostic),
    )
    auto_peak_calibration_points_per_pixel = fast_map_points_for_pixel(
        hwp_angles=hwp_angles,
        voltages=voltages,
        manual_peak_raw=None,
        manual_peak_only=bool(args.manual_peak_only),
        auto_peak_calibration=True,
        peak_readout_required=bool(peak_readout_required),
        learned_readout_mode=str(args.learned_readout_mode),
        peak_diagnostic=bool(args.peak_diagnostic),
    )
    total_points = (
        manual_cal_pixel_count * calibration_points_per_pixel
        + auto_peak_cal_pixel_count * auto_peak_calibration_points_per_pixel
        + (len(selected_pixels) - manual_cal_pixel_count - auto_peak_cal_pixel_count) * normal_points_per_pixel
    )
    points_per_pixel = (
        calibration_points_per_pixel if manual_cal_pixel_count
        else auto_peak_calibration_points_per_pixel if auto_peak_cal_pixel_count
        else normal_points_per_pixel
    )
    gui_update_state(
        selected_pixels=selected_pixels,
        selected_pixel_count=len(selected_pixels),
        hwp_input_frame=getattr(args, "hwp_input_frame", "lab"),
        hwp_sweep_mode=hwp_sweep_mode_from_args(args),
        hwp_angles_deg=[float(v) for v in hwp_angles],
        hwp_raw_angles_deg=[float(v) for v in hwp_angles],
        hwp_lab_theta_i_angles_deg=[float(v) for v in hwp_lab_theta_i_angles],
        pixel_total_points=points_per_pixel,
        chip_total_points=total_points,
        chip_points_done=0,
        qwp_readout_offset_deg=float(args.qwp_readout_offset),
        funcgen_freq_hz=float(args.funcgen_freq),
        phase="Ready to start",
    )

    config = {
        "script": "pockels_fast_map_gui.py",
        "mode": "fast_map",
        "root_dir": str(root_dir),
        "chip_id": str(args.chip_id or "").strip(),
        "run_name": str(args.run_name or "").strip(),
        "run_file_stem": auto.sanitize_run_name(root_dir.name),
        "selected_pixels": selected_pixels,
        "stage_cal": args.stage_cal,
        "optical_cal": args.optical_cal,
        "hwp_grid_preset": str(
            getattr(args, "hwp_grid_preset", HWP_GRID_PRESET_CUSTOM)
            or HWP_GRID_PRESET_CUSTOM
        ),
        "hwp_input_frame": getattr(args, "hwp_input_frame", "lab"),
        "hwp_sweep_mode": hwp_sweep_mode_from_args(args),
        "hwp_input_center_deg": (
            float(args.hwp_start) if hwp_sweep_mode_from_args(args) == "centered-180" else None
        ),
        "hwp_input_span_deg": (
            hwp_center_span_from_args(args) if hwp_sweep_mode_from_args(args) == "centered-180" else None
        ),
        "hwp_input_points": int(len(hwp_input_grid)),
        "hwp_input_start_deg": float(hwp_input_grid[0]),
        "hwp_input_stop_deg": float(hwp_input_grid[-1]),
        "hwp_input_step_deg": hwp_input_step,
        "hwp_center_step_theta_i_deg": float(args.hwp_center_step) if args.hwp_center_step is not None else None,
        "hwp_angles_deg": [float(v) for v in hwp_angles],
        "hwp_raw_angles_deg": [float(v) for v in hwp_angles],
        "hwp_lab_theta_i_angles_deg": [float(v) for v in hwp_lab_theta_i_angles],
        "manual_peak_raw": manual_peak_raw,
        "manual_peak_only": bool(args.manual_peak_only),
        "manual_peak_calibration_pixels": int(args.manual_peak_calibration_pixels),
        "manual_peak_calibration_pixel_count": int(manual_cal_pixel_count),
        "calibration_pixel": (
            int(calibration_pixel) if calibration_pixel is not None else None
        ),
        "substrate_calibration_pixel": int(args.substrate_cal_pixel),
        "auto_peak_calibration_pixels": int(args.auto_peak_calibration_pixels),
        "auto_peak_calibration_pixel_count": int(auto_peak_cal_pixel_count),
        "resume_reused_peak_calibration": bool(reuse_resume_peak_calibration),
        "auto_peak_max_coarse_probes": int(args.auto_peak_max_coarse_probes),
        "auto_peak_track_mode": str(args.auto_peak_track_mode),
        "learned_readout_mode": str(args.learned_readout_mode),
        "peak_readout_required": bool(peak_readout_required),
        "peak_readout_policy": (
            "the operator-selected physical calibration pixel is measured first "
            "and establishes each HWP local null and exact "
            "null/+45/-45 readout, adds a balanced bright probe, then jointly fits "
            "the unrestricted complex response and DC Malus derivative with a "
            "DC-half-fringe confirmation; later pixels reuse the table, check their "
            "own local triplet, and add the balanced fit only when certification "
            "is inconclusive"
        ),
        "s9_acceptance_thresholds": {
            "complex_min_r_squared": float(S9_COMPLEX_MIN_R2),
            "dc_malus_min_r_squared": float(S9_DC_MALUS_MIN_R2),
            "max_dynamic_peak_shift_deg": float(S9_MAX_DYNAMIC_PEAK_SHIFT_DEG),
            "max_dc_null_shift_deg": float(S9_MAX_DC_NULL_SHIFT_DEG),
            "max_null_leakage_fraction": float(S9_MAX_NULL_LEAKAGE_FRACTION),
            "max_midfringe_error": float(S9_MAX_MIDFRINGE_ERROR),
            "max_confirmation_error_fraction": float(S9_MAX_CONFIRM_ERROR_FRACTION),
            "max_derivative_residual_fraction": float(
                S9_MAX_DERIVATIVE_RESIDUAL_FRACTION
            ),
            "max_temporal_rank_fraction": float(
                S9_MAX_TEMPORAL_RANK_FRACTION
            ),
            "quick_max_analyser_quadrature_error_deg": float(
                S9_QUICK_MAX_ANALYSER_QUADRATURE_ERROR_DEG
            ),
            "quick_min_phase_flip_score": float(S9_QUICK_MIN_PHASE_FLIP_SCORE),
            "quick_min_side_symmetry_ratio": float(S9_QUICK_MIN_SIDE_SYMMETRY_RATIO),
            "quick_max_dc_balance_error": float(S9_QUICK_MAX_DC_BALANCE_ERROR),
            "lockin_fullscale_warn_fraction": float(LOCKIN_FULLSCALE_WARN_FRACTION),
            "lockin_fullscale_fail_fraction": float(LOCKIN_FULLSCALE_FAIL_FRACTION),
        },
        "peak_readout_autofill_missing_hwp": bool(peak_readout_required),
        "peak_diagnostic_enabled": bool(args.peak_diagnostic),
        "peak_diagnostic_policy": (
            "after each calibration peak readout, probe QWP +/- step, analyser +/- step, "
            "and repeat the center; fail the HWP if a neighbor beats the center beyond the uV margin"
        ),
        "peak_diagnostic_step_deg": float(args.peak_diagnostic_step),
        "peak_diagnostic_min_margin_uV": float(args.peak_diagnostic_min_margin_uv),
        "peak_diagnostic_probe_count": int(PEAK_DIAGNOSTIC_PROBE_COUNT),
        "post_analyser_sweep_pixels": sorted(int(p) for p in post_analyser_pixels),
        "post_analyser_sweep_vpp_values": [float(v) for v in post_analyser_vpp_values],
        "post_analyser_sweep_start_deg": float(args.post_analyser_sweep_start),
        "post_analyser_sweep_stop_deg": float(args.post_analyser_sweep_stop),
        "post_analyser_sweep_step_deg": float(args.post_analyser_sweep_step),
        "post_analyser_sweep_dc_hold_v": float(args.post_analyser_sweep_dc_hold),
        "post_analyser_sweep_dwell_s": float(args.post_analyser_sweep_dwell),
        "post_analyser_sweep_peak_hwp_only": bool(args.post_analyser_sweep_peak_only),
        "post_ac_vpp_sweep_pixels": sorted(int(p) for p in post_ac_pixels),
        "post_ac_vpp_sweep_values": [float(v) for v in post_ac_vpp_values],
        "post_ac_vpp_sweep_dc_hold_v": float(args.post_ac_vpp_sweep_dc_hold),
        "post_ac_vpp_sweep_dwell_s": float(args.post_ac_vpp_sweep_dwell),
        "post_dc_hysteresis_pixels": sorted(int(p) for p in post_dc_pixels),
        "post_dc_hysteresis_dwell_s": float(args.post_dc_hysteresis_dwell),
        "post_dc_hysteresis_start_from_zero": bool(args.post_dc_hysteresis_start_from_zero),
        "post_dc_hysteresis_reset_domains": bool(args.post_dc_hysteresis_reset_domains),
        "post_dc_hysteresis_cycles": int(args.post_dc_hysteresis_cycles),
        "post_dc_hysteresis_vmax_v": float(args.post_dc_hysteresis_vmax),
        "post_dc_hysteresis_voltage_limits_v": [
            -float(args.post_dc_hysteresis_vmax),
            float(args.post_dc_hysteresis_vmax),
        ],
        "post_dc_hysteresis_grid_profile": (
            "adaptive_vc_windows"
            if bool(args.post_dc_hysteresis_adaptive_window)
            else (
                "uniform"
                if args.post_dc_hysteresis_voltage_step is not None
                else DEFAULT_HYSTERESIS_GRID_PROFILE
            )
        ),
        "post_dc_hysteresis_voltage_step_v": (
            float(args.post_dc_hysteresis_voltage_step)
            if args.post_dc_hysteresis_voltage_step is not None
            else None
        ),
        "post_dc_hysteresis_ac_vpp": float(args.post_dc_hysteresis_ac_vpp),
        "post_dc_hysteresis_dynamic_lockin_range": bool(
            args.post_dc_hysteresis_dynamic_lockin_range
        ),
        "post_dc_hysteresis_lockin_range_mode": (
            "predictive_hysteretic"
            if bool(args.post_dc_hysteresis_dynamic_lockin_range)
            else "fixed"
        ),
        "post_dc_hysteresis_min_dwell_s": float(args.post_dc_hysteresis_min_dwell),
        "post_dc_hysteresis_adaptive_window": bool(args.post_dc_hysteresis_adaptive_window),
        "post_dc_hysteresis_quasi_static": bool(args.post_dc_hysteresis_quasi_static),
        "adaptive_poling": bool(args.adaptive_poling),
        "adaptive_poling_min_s": float(args.adaptive_poling_min_s),
        "adaptive_poling_poll_s": float(args.adaptive_poling_poll_s),
        "adaptive_poling_stable_pct": float(args.adaptive_poling_stable_pct),
        "adaptive_poling_stable_count": int(args.adaptive_poling_stable_count),
        "adaptive_poling_min_signal_uv": float(args.adaptive_poling_min_signal_uv),
        "adaptive_poling_monitor_vpp": float(args.adaptive_poling_monitor_vpp),
        "peak_refine_mode": str(args.peak_refine_mode),
        "s9_balanced_probe_offsets_deg": [0.0, 45.0, 90.0, -45.0],
        "auto_peak_fast_seed_pair_offsets_deg": [
            [float(q), float(a)] for q, a in AUTO_PEAK_FAST_SEED_PAIR_OFFSETS_DEG
        ],
        "auto_peak_refine_steps_deg": [float(v) for v in AUTO_READOUT_PEAK_STEPS_DEG],
        "auto_peak_refine_max_iter_per_step": int(AUTO_READOUT_PEAK_MAX_ITER_PER_STEP),
        "auto_peak_refine_min_improve_uV": float(AUTO_READOUT_PEAK_MIN_IMPROVE_UV),
        "auto_peak_refine_noise_sigma": float(AUTO_READOUT_PEAK_NOISE_SIGMA),
        "auto_peak_global_grid_step_deg": float(AUTO_PEAK_GLOBAL_GRID_STEP_DEG),
        "auto_peak_global_top_seeds": int(AUTO_PEAK_GLOBAL_TOP_SEEDS),
        "calibration_null_policy": (
            "calibration pixels always run a sample-in coarse-plus-fine 2D "
            "QWP/analyser minimisation at every HWP; requested renull mode "
            "applies to subsequent pixels; high finite nulls remain measurable "
            "with untrusted quality flags and are not learned for later pixels"
        ),
        "calibration_null_failure_policy": (
            "finite_high_measure_flagged_untrusted; "
            "invalid_or_procedure_error_fail_pixel_continue_chip; "
            "verified_angle_error_abort_chip"
        ),
        "auto_peak_coarse_q_offsets_deg": [float(v) for v in AUTO_PEAK_COARSE_Q_OFFSETS_DEG],
        "auto_peak_coarse_anl_offsets_deg": [float(v) for v in AUTO_PEAK_COARSE_A_OFFSETS_DEG],
        "voltages_vpp": [float(v) for v in voltages],
        "lab_angle_mapping": lab_angle_mapping_config(),
        "logical_slope_offsets_deg": [-45.0, 45.0],
        "slope_target_policy": "choose 180-deg-equivalent analyser targets with minimum boundary-safe travel",
        "qwp_readout_offset_deg": float(args.qwp_readout_offset),
        "qwp_readout_policy": "null QWP/ANL with AC off, then move QWP to q_null + offset before lock-in reads",
        "lockin_reference_phase_deg": args.lockin_reference_phase,
        "poling_voltage_v": args.poling_voltage,
        "poling_dwell_s": args.poling_dwell,
        "stage_brighten_offset_deg": args.stage_brighten_offset,
        "renull_mode": args.renull_mode,
        "lockin_settle_s": args.lockin_settle,
        "lockin_avg_readings": args.lockin_avg_readings,
        "lockin_read_delay_s": args.lockin_read_delay,
        "lockin_time_constant_index": int(args.lockin_tc_index),
        "lockin_time_constant_s": DSP7230_TIME_CONSTANT_SECONDS[int(args.lockin_tc_index)],
        "lockin_filter_slope_db_per_oct": int(args.lockin_filter_slope_db),
        "lockin_sensitivity_index": int(args.lockin_sensitivity_index),
        "lockin_sensitivity_mode": "fixed",
        "lockin_automatic_ac_gain_enabled": False,
        "lockin_overload_policy": "report_and_keep_fixed_range",
        "lockin_reference_source": str(args.lockin_reference_source),
        "lockin_required_settle_s": minimum_lockin_settle_s(
            args.lockin_tc_index, args.lockin_filter_slope_db
        ),
        "lockin_reference_tolerance_hz": float(args.lockin_reference_tolerance_hz),
        "allow_unlocked_reference": bool(args.allow_unlocked_reference),
        "lockin_averaging_domain": "complex X/Y phasor (never arithmetic magnitude)",
        "funcgen_freq_hz": args.funcgen_freq,
        "funcgen_settle_s": args.funcgen_settle,
        "bto_physics": dict(BTO_PHYSICS_CONFIG),
        "use_laser": bool(args.use_laser),
        "laser_power_mw": float(args.laser_power_mw),
        "laser_serial": args.laser_serial,
        "laser_on_start": bool(args.laser_on_start),
        "min_signal_mv": args.min_signal_mv,
        "null_check_max_mv": args.null_check_max_mv,
        "null_certify_margin_mv": args.null_certify_margin_mv,
        "fast_rotator_moves": bool(args.fast_rotator_moves),
        "verify_fast_rotator_moves": bool(args.verify_fast_rotator_moves),
        "rotator_verify_tol_deg": float(args.rotator_verify_tol),
        "rotator_velocity_pct": int(rotator_velocity_pct),
        "arduino_port": None if args.no_arduino else args.arduino_port,
        "manual_probing": bool(args.manual_probing),
        "pixel_to_pin": getattr(stage, "PIXEL_TO_PIN", {}),
        "transport_recovery_attempts": args.transport_recovery_attempts,
        "transport_recovery_delay_s": args.transport_recovery_delay,
        "transport_recovery_policy": "reconnect_then_next_pixel",
        "smu_port": None if getattr(args, "_smu_auto_not_found", False) else args.smu_port,
        "smu_compliance_A": float(args.smu_compliance),
        "smu_compliance_mA": float(args.smu_compliance) * 1e3,
        "phase_substrate": args.phase_substrate,
        "substrate_cal": args.substrate_cal,
    }
    write_run_json(root_dir, "run_config.json", config)
    if not confirm_start(args, root_dir, selected_pixels, total_points):
        return 0
    console_noise_state = configure_console_noise(args)
    gui_stop_checkpoint()

    device_x = device_y = None
    stage_detector = None
    live_view = None
    switch_matrix = None
    smu = None
    lockin = None
    funcgen = None
    laser = None
    rot_hwp = rot_qwp = rot_anl = None
    sens_idx = int(args.lockin_sensitivity_index)

    from serial.tools import list_ports as recovery_ports
    try:
        port_identities = serial_port_identities(recovery_ports.comports())
    except Exception as exc:
        port_identities = {}
        print(f"  [WARN] USB identity snapshot unavailable; recovery will use configured ports: {exc}")

    def recover_after_pixel_hardware_fault(pix_num, exc):
        nonlocal device_x, device_y, stage_detector, detector_adapter
        nonlocal switch_matrix, smu, lockin, funcgen, rot_hwp, rot_qwp, rot_anl, sens_idx
        global GUI_PIXEL_SKIP_ENABLED, GUI_PIXEL_SKIP_LATCHED, GUI_PIXEL_SKIP_ACKED
        GUI_PIXEL_SKIP_ENABLED = False
        GUI_PIXEL_SKIP_LATCHED = False
        GUI_PIXEL_SKIP_ACKED = False
        gui_clear_skip_request()
        # Persist the failed/partial pixel before spending time reconnecting.
        write_chip_summary(root_dir, pixels)
        auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)
        if live_view is not None:
            live_view.pause_scope_reads()
            live_view.detector = None
        hardware = {
            "device_x": device_x, "device_y": device_y,
            "stage_detector": stage_detector, "switch_matrix": switch_matrix,
            "smu": smu, "lockin": lockin, "funcgen": funcgen,
            "rot_hwp": rot_hwp, "rot_qwp": rot_qwp, "rot_anl": rot_anl,
        }

        def report(event, **details):
            entry = {
                "timestamp": datetime.now().isoformat(), "pixel": int(pix_num),
                "event": event, **details,
            }
            with (root_dir / "transport_recovery.jsonl").open("a", encoding="utf-8") as stream:
                stream.write(json.dumps(entry) + "\n")
            if event == "waiting":
                phase = (
                    f"Hardware recovery: attempt {details['attempt']} in "
                    f"{details['delay_s']:g}s (Stop to cancel)"
                )
            elif event == "recovered":
                phase = f"Hardware reconnected after pixel {pix_num:03d}; continuing to next pixel"
            elif event == "attempt_failed":
                phase = f"Hardware recovery attempt {details['attempt']} failed; waiting for hardware"
            else:
                phase = f"Hardware recovery: {event.replace('_', ' ')}"
            print(f"  [HARDWARE RECOVERY] {phase}" + (f": {details['error']}" if details.get("error") else ""))
            gui_update_state(
                running=True, phase=phase, hardware_recovery_event=event,
                hardware_recovery_attempt=details.get("attempt"),
                hardware_recovery_pixel=int(pix_num),
                dc_voltage_on=False if event == "recovered" else None,
                ac_voltage_on=False if event == "recovered" else None,
                current_vpp=None, current_slope_side="", manual_probe_waiting=False,
                dwell_remaining_s=None,
            )

        report(
            "angle_verification_failed" if isinstance(exc, CriticalAngleError) else "transport_lost",
            error=f"{type(exc).__name__}: {exc}",
        )
        recovery = FastMapHardwareRecovery(
            hardware, args=args, auto=auto, pockels=pockels, stage=stage,
            voltages=voltages, configure_lockin=configure_lockin_for_fast_map,
            simulated_lockin=use_fake_lockin, sim_state=sim_state,
            wait=lambda seconds: gui_sleep(seconds, live_view=live_view),
            checkpoint=gui_stop_checkpoint, report=report,
            port_identities=port_identities, list_ports=recovery_ports.comports,
        )
        try:
            configuration = recovery.run()
        except Exception:
            gui_update_state(running=False, phase="Hardware recovery attempt limit reached; run saved for resume")
            raise
        finally:
            # Adopt ownership even if reconnect/Stop failed halfway through.
            # Outer cleanup must never retain stale handles or leak new ones.
            device_x, device_y = hardware["device_x"], hardware["device_y"]
            stage_detector = hardware["stage_detector"]
            switch_matrix, smu = hardware["switch_matrix"], hardware["smu"]
            lockin, funcgen = hardware["lockin"], hardware["funcgen"]
            rot_hwp, rot_qwp, rot_anl = (hardware[key] for key in ("rot_hwp", "rot_qwp", "rot_anl"))
            if live_view is not None:
                live_view.detector = stage_detector
        detector_adapter = auto.StageScopePockelsAdapter(stage_detector)
        install_gui_alignment_export(stage_detector, GUI_ALIGNMENT_FILE)
        install_gui_rotator_export(rot_hwp, rot_qwp, rot_anl)
        sens_idx = int(configuration.get("sensitivity_index_effective", args.lockin_sensitivity_index))
        write_json(root_dir / "lockin_configuration.json", configuration)
        print(
            f"  [HARDWARE RECOVERY] Pixel {pix_num:03d} remains failed/partial and resumable; "
            "saved measurements were retained. Continuing the selected pixel queue."
        )

    try:
        if not args.simulate_lockin:
            try:
                gui_update_state(phase="Connecting lock-in")
                lockin, sens_idx = pockels._connect_lockin()
                sensitivity_table = getattr(pockels, "SENS_TABLE_VOLTS", {})
                requested_fullscale_v = (
                    sensitivity_table.get(int(args.lockin_sensitivity_index))
                    if isinstance(sensitivity_table, dict)
                    else None
                )
                requested_range_text = (
                    f"{float(requested_fullscale_v) * 1e6:g} uV RMS full scale"
                    if requested_fullscale_v is not None
                    else f"sensitivity index {int(args.lockin_sensitivity_index)}"
                )
                print(
                    "  [LOCKIN] The readback above is the pre-configuration "
                    "front-panel state. Fast map will force fixed "
                    f"{requested_range_text} before any measurement."
                )
                sens_idx = int(args.lockin_sensitivity_index)
            except Exception as exc:
                if args.require_lockin:
                    print_lockin_connection_help(exc)
                    return 2
                print_lockin_connection_help(exc)
                print("  Continuing with FakeLockin because fake lock-in fallback was allowed.")

        gui_update_state(phase="Connecting XY stage")
        device_x, device_y = auto.connect_stage_hardware(args)
        gui_update_state(phase="Connecting oscilloscope")
        stage_detector = auto.connect_stage_scope()
        gui_update_state(phase="Starting camera live view")
        live_view = auto.connect_live_view(args, stage_detector)
        install_gui_camera_export(live_view, GUI_CAMERA_FRAME_FILE)
        install_gui_alignment_export(stage_detector, GUI_ALIGNMENT_FILE)
        detector_adapter = auto.StageScopePockelsAdapter(stage_detector)
        gui_update_state(phase="Connecting switch matrix")
        switch_matrix = auto.connect_switch_matrix(args)
        gui_update_state(phase="Connecting KLS1550 laser")
        laser = gui_connect_laser(args)

        print("\nInitializing optical/electrical instruments...")
        sim_state = {"vpp": float(max(voltages)), "a_null": 0.0}
        use_fake_lockin = bool(args.simulate_lockin)
        if use_fake_lockin:
            auto.install_funcgen_vpp_spy(sim_state)
        gui_update_state(phase="Configuring function generator")
        funcgen = auto.configure_funcgen_safe(initial_vpp=min(voltages))
        gui_update_state(phase="Connecting rotators")
        rot_hwp, rot_qwp, rot_anl = connect_rotators_for_fast_map(
            do_home=not args.no_rotator_home
        )
        install_gui_rotator_export(rot_hwp, rot_qwp, rot_anl)
        gui_update_state(phase="Homing/taring rotators" if not args.no_rotator_home else "Reading rotators")
        auto.boot_rotators(rot_hwp, rot_qwp, rot_anl, do_home=not args.no_rotator_home)

        if use_fake_lockin:
            print("\n[SIM] Using FakeLockin.")
            lockin = auto.FakeLockin(rot_anl, sim_state)
            lockin.connect()
        elif lockin is None:
            auto.install_funcgen_vpp_spy(sim_state)
            lockin = auto.FakeLockin(rot_anl, sim_state)
            lockin.connect()
            use_fake_lockin = True

        gui_update_state(phase="Configuring fixed lock-in range")
        lockin_configuration = configure_lockin_for_fast_map(
            lockin,
            args,
            simulated=use_fake_lockin,
        )
        if not use_fake_lockin:
            sens_idx = int(
                lockin_configuration.get(
                    "sensitivity_index_effective",
                    args.lockin_sensitivity_index,
                )
            )
        write_json(root_dir / "lockin_configuration.json", lockin_configuration)
        if lockin_configuration.get("reference_locked") is False:
            print("[LOCKIN] WARNING: reference readback reports unlocked/mismatched.")

        if getattr(args, "_smu_auto_not_found", False):
            if args.require_smu:
                raise RuntimeError("SMU auto-detect did not find an SMU4201.")
            print("\n[WARN] SMU auto-detect failed; using FakeSMU.")
            smu = auto.FakeSMU()
        else:
            try:
                gui_update_state(phase="Connecting SMU")
                smu = pockels._connect_smu(0.0)
            except Exception as exc:
                if args.require_smu:
                    raise
                print(f"\n[WARN] SMU failed ({type(exc).__name__}: {exc}); using FakeSMU.")
                smu = auto.FakeSMU()
        armed_label = "armed at 0 V until manual probe confirmation" if args.manual_probing else "armed at 0 V until Arduino routing"
        auto.smu_output_off(smu, armed_label)

        gui_update_state(phase="Loading optical calibration")
        optical_cal = auto.resolve_optical_calibration(args.optical_cal)
        auto.save_loaded_optical_calibration(root_dir, optical_cal)
        update_bto_config_from_optical_calibration(optical_cal)
        config["bto_physics"] = dict(BTO_PHYSICS_CONFIG)
        write_run_json(root_dir, "run_config.json", config)
        fallback_seed = auto.move_to_loaded_optical_calibration(rot_hwp, rot_qwp, rot_anl, optical_cal)
        current_hwp = rotator_read_angle_once(rot_hwp)
        if not np.isfinite(current_hwp):
            current_hwp = optical_cal.get("hwp_deg", float("nan"))
        current_qwp = rotator_read_angle_once(rot_qwp)
        if not np.isfinite(current_qwp):
            current_qwp = fallback_seed[0]
        current_anl = rotator_read_angle_once(rot_anl)
        if not np.isfinite(current_anl):
            current_anl = fallback_seed[1]
        gui_update_state(
            current_hwp_deg=float(current_hwp) if current_hwp is not None else float("nan"),
            current_qwp_deg=float(current_qwp) if current_qwp is not None else float("nan"),
            current_anl_deg=float(current_anl) if current_anl is not None else float("nan"),
            active_optic="",
            phase="Optical calibration loaded",
        )

        chip_map_requested = bool(selected_pixels)

        if args.phase_substrate == "load" and chip_map_requested:
            gui_update_state(phase="Loading substrate HWP seeds")
            loaded_seeds = auto.load_substrate_optical_calibration(args.substrate_cal)
            if resume_state_loaded and null_seed_by_hwp:
                null_seed_by_hwp = merge_null_seed_tables_preserving_readout(null_seed_by_hwp, loaded_seeds)
                print("  Resume seed table kept; substrate cal filled only missing HWP/null fields.")
            else:
                null_seed_by_hwp.update(loaded_seeds)
        elif args.phase_substrate == "do" and chip_map_requested:
            gui_update_state(phase="Running substrate calibration")
            sub_pix = int(args.substrate_cal_pixel or 0)
            if sub_pix > 0:
                pixel_for_sub = pixels[sub_pix - 1]
                stage.run_with_display(
                    live_view,
                    gui_align_and_capture_pixel,
                    sub_pix - 1,
                    pixel_for_sub,
                    pixels,
                    total,
                    0,
                    device_x,
                    device_y,
                    stage_detector,
                    live_view,
                    args,
                    rot_anl,
                )
                stage.save_json(pixels, sum(1 for p in pixels if p.get("calibrated_x_motor") is not None))
                stage.save_csv(pixels)
            sub_table = stage.run_with_display(
                live_view,
                auto.run_substrate_optical_calibration,
                root_dir,
                hwp_angles,
                rot_hwp,
                rot_qwp,
                rot_anl,
                detector_adapter,
                fallback_seed,
            )
            null_seed_by_hwp.update(sub_table)
        else:
            if chip_map_requested:
                print("\nSubstrate seed loading skipped; each pixel/HWP will re-null from the current seed.")
            else:
                print("\nChip-map pixel list is empty; skipping substrate seed setup for follow-up-only run.")

        if chip_map_requested and args.renull_mode in ("seed-only", "adaptive-renull"):
            missing_hwp = [
                float(hwp)
                for hwp in hwp_angles
                if f"{float(hwp):.3f}" not in null_seed_by_hwp
            ]
            if missing_hwp:
                raise RuntimeError(
                    f"{args.renull_mode} mode requires a substrate_calibration.json with every HWP seed. "
                    f"Missing HWP seeds: {missing_hwp[:5]}"
                    + (" ..." if len(missing_hwp) > 5 else "")
                    + ". Load/do substrate calibration, or choose fast-renull mode."
                )

        if chip_map_requested and peak_readout_required:
            missing_peak_hwp = missing_peak_readout_hwp_angles(hwp_angles, null_seed_by_hwp)
            if missing_peak_hwp:
                calibration_sweep_complete = bool(
                    calibration_pixel is not None
                    and fast_map_sweep_complete(
                        pixels_dir / f"pixel_{int(calibration_pixel):03d}"
                    )
                )
                if (
                    args.resume_run
                    and args.skip_complete
                    and calibration_sweep_complete
                ):
                    print(
                        "\n[RESUME WARNING] Saved calibration pixel "
                        f"{int(calibration_pixel):03d} already has a completed chip sweep. "
                        "--skip-complete is authoritative, so that saved sweep will be "
                        "preserved and not rerun even though "
                        f"{len(missing_peak_hwp)}/{len(hwp_angles)} HWP angles lack a "
                        "reusable certified readout entry: "
                        f"{format_hwp_preview(missing_peak_hwp)}. Remaining pixels will "
                        "reuse the available calibration entries and acquire their normal "
                        "local fallback reads at those angles."
                    )
                else:
                    print(
                        "\n[PEAK CAL] Per-HWP normalized readout table is incomplete. "
                        f"Missing {len(missing_peak_hwp)}/{len(hwp_angles)} HWP entries: "
                        f"{format_hwp_preview(missing_peak_hwp)}. "
                        "The first calibration pixel will establish their full null and "
                        "null/+45/-45 joint readout before later pixels use them."
                    )
            else:
                print("\n[PEAK CAL] Learned lock-in peak readout table covers every requested HWP.")

        auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)

        print("\n" + "=" * 72)
        print("FAST MAP - PER-PIXEL SLOPE-POINT MEASUREMENT")
        print("=" * 72)
        t_start = time.time()
        initial_done_points = 0
        if args.skip_complete:
            initial_done_points = sum(
                fast_map_points_for_pixel(
                    hwp_angles=hwp_angles,
                    voltages=voltages,
                    manual_peak_raw=(
                        manual_peak_raw
                        if (
                            not reuse_resume_peak_calibration
                            and manual_peak_enabled_for_pixel_sequence(args, seq, manual_peak_raw)
                        )
                        else None
                    ),
                    manual_peak_only=bool(args.manual_peak_only),
                    auto_peak_calibration=bool(
                        not reuse_resume_peak_calibration
                        and auto_peak_enabled_for_pixel_sequence(args, seq, manual_peak_raw)
                    ),
                    peak_readout_required=bool(peak_readout_required),
                    learned_readout_mode=str(args.learned_readout_mode),
                    peak_diagnostic=bool(args.peak_diagnostic),
                )
                for seq, pix in enumerate(selected_pixels, start=1)
                if fast_map_sweep_complete(
                    pixels_dir / f"pixel_{int(pix):03d}"
                )
            )
        progress = {"points_done": initial_done_points, "total_points": total_points, "start": t_start}
        gui_update_state(
            phase="Measurement running",
            chip_points_done=initial_done_points,
            chip_total_points=total_points,
            pixel_total_points=points_per_pixel,
            dc_voltage_on=False,
            ac_voltage_on=False,
        )
        post_analyser_done: set[int] = set()
        post_ac_done: set[int] = set()
        post_dc_done: set[int] = set()
        if resume_state_loaded and args.skip_complete:
            post_dc_done = {
                int(pix)
                for pix in post_dc_pixels
                if dc_hysteresis_sweep_complete(
                    pixels_dir / f"pixel_{int(pix):03d}"
                )
            }
            if post_dc_done:
                print(
                    "\n[RESUME] Verified completed DC hysteresis artifacts: "
                    + _format_pixel_ranges(sorted(post_dc_done))
                )
        operator_skipped_pixels: set[int] = set()
        chip_sequence_by_pixel = {
            int(pix): int(chip_seq)
            for chip_seq, pix in enumerate(selected_pixels, start=1)
        }

        for seq, pix_num in enumerate(pixel_work_queue, start=1):
            gui_stop_checkpoint()
            pixel = pixels[pix_num - 1]
            chip_seq = chip_sequence_by_pixel.get(int(pix_num))
            chip_sweep_requested = chip_seq is not None
            pixel_manual_peak_raw = (
                manual_peak_raw
                if (
                    chip_sweep_requested
                    and not reuse_resume_peak_calibration
                    and manual_peak_enabled_for_pixel_sequence(
                        args,
                        int(chip_seq),
                        manual_peak_raw,
                    )
                )
                else None
            )
            pixel_auto_peak_calibration = bool(
                chip_sweep_requested
                and not reuse_resume_peak_calibration
                and auto_peak_enabled_for_pixel_sequence(
                    args,
                    int(chip_seq),
                    manual_peak_raw,
                )
            )
            missing_peak_hwp_for_pixel: list[float] = []
            if (
                chip_sweep_requested
                and peak_readout_required
                and not bool(args.manual_peak_only)
            ):
                missing_peak_hwp_for_pixel = missing_peak_readout_hwp_angles(hwp_angles, null_seed_by_hwp)
            pixel_points_total = (
                fast_map_points_for_pixel(
                    hwp_angles=hwp_angles,
                    voltages=voltages,
                    manual_peak_raw=pixel_manual_peak_raw,
                    manual_peak_only=bool(args.manual_peak_only),
                    auto_peak_calibration=pixel_auto_peak_calibration,
                    peak_readout_required=bool(peak_readout_required),
                    learned_readout_mode=str(args.learned_readout_mode),
                    peak_diagnostic=bool(args.peak_diagnostic),
                )
                if chip_sweep_requested
                else 0
            )
            pixel_dir = pixels_dir / f"pixel_{pix_num:03d}"
            chip_sweep_needed, dc_hysteresis_needed = resume_pixel_component_needs(
                pixel_dir,
                chip_sweep_requested=chip_sweep_requested,
                dc_hysteresis_requested=pix_num in post_dc_pixels,
                skip_complete=bool(args.skip_complete),
            )
            if missing_peak_hwp_for_pixel and chip_sweep_needed:
                if pixel_manual_peak_raw or pixel_auto_peak_calibration:
                    method = (
                        "manual peak anchoring"
                        if pixel_manual_peak_raw else
                        "full-null normalized triplet calibration"
                    )
                    print(
                        f"\n[PEAK CAL] Pixel {pix_num:03d} will attempt to establish "
                        f"{len(missing_peak_hwp_for_pixel)} missing HWP peak readout(s) "
                        f"with {method}: "
                        f"{format_hwp_preview(missing_peak_hwp_for_pixel)}"
                    )
                else:
                    print(
                        f"\n[PEAK CAL] Pixel {pix_num:03d} has "
                        f"{len(missing_peak_hwp_for_pixel)} HWP angle(s) without a "
                        "reusable certified readout; acquiring local null/triplet "
                        "fallbacks without revisiting the completed calibration pixel: "
                        f"{format_hwp_preview(missing_peak_hwp_for_pixel)}"
                    )
            other_followup_needed = (
                pix_num in post_analyser_pixels
                or pix_num in post_ac_pixels
            )
            if (
                args.skip_complete
                and not chip_sweep_needed
                and not dc_hysteresis_needed
                and not other_followup_needed
            ):
                completed_parts = []
                if chip_sweep_requested:
                    completed_parts.append("chip sweep")
                if pix_num in post_dc_pixels:
                    completed_parts.append("DC hysteresis")
                if not completed_parts:
                    completed_parts.append("requested components")
                print(
                    f"\nPixel {pix_num:03d}: verified "
                    + " + ".join(completed_parts)
                    + " complete on disk; skipping."
                )
                continue
            if not chip_sweep_needed:
                missing_parts = []
                if dc_hysteresis_needed:
                    missing_parts.append("DC hysteresis")
                if pix_num in post_analyser_pixels:
                    missing_parts.append("analyser follow-up")
                if pix_num in post_ac_pixels:
                    missing_parts.append("AC Vpp follow-up")
                print(
                    f"\n[RESUME] Pixel {pix_num:03d}: chip sweep is complete; "
                    f"running only missing component(s): {', '.join(missing_parts)}."
                )
            progress["current_pixel"] = pix_num
            progress["pixel_points_done"] = 0
            progress["pixel_total_points"] = pixel_points_total
            gui_update_state(
                current_pixel=pix_num,
                pixel_sequence=seq,
                selected_pixel_count=len(pixel_work_queue),
                pixel_points_done=0,
                pixel_total_points=pixel_points_total,
                chip_points_done=int(progress.get("points_done", 0)),
                chip_total_points=total_points,
                dc_voltage_on=False,
                ac_voltage_on=False,
                    current_vpp=None,
                    current_slope_side="",
                    manual_probe_waiting=False,
                    phase="Preparing pixel",
                )

            record = None
            for candidate in reversed(records):
                try:
                    same_pixel = int(candidate.get("pixel", 0)) == pix_num
                except Exception:
                    same_pixel = False
                if same_pixel and str(candidate.get("status", "")).lower() != "complete":
                    record = candidate
                    break
            if record is None:
                record = {
                    "pixel": pix_num,
                    "status": "started",
                    "channel": None,
                    "started": datetime.now().isoformat(),
                    "completed": "",
                    "calibrated_x_motor": "",
                    "calibrated_y_motor": "",
                    "smu_poling_voltage_v": args.poling_voltage,
                    "output_dir": str(pixel_dir),
                    "error": "",
                }
                records.append(record)
            else:
                record.update({
                    "status": "started",
                    "channel": None,
                    "started": datetime.now().isoformat(),
                    "completed": "",
                    "calibrated_x_motor": "",
                    "calibrated_y_motor": "",
                    "smu_poling_voltage_v": args.poling_voltage,
                    "output_dir": str(pixel_dir),
                    "error": "",
                })
            pixel["measurement_status"] = "started"
            pixel["measurement_started"] = record["started"]
            auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)

            try:
                GUI_PIXEL_SKIP_LATCHED = False
                GUI_PIXEL_SKIP_ACKED = False
                GUI_PIXEL_SKIP_ENABLED = True
                gui_pixel_checkpoint()
                print(f"\nPixel {pix_num:03d} ({seq}/{len(pixel_work_queue)})")
                n_done = sum(1 for p in pixels if p.get("measurement_status") == "complete")
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_sequence=seq,
                    selected_pixel_count=len(pixel_work_queue),
                    phase="Stage alignment",
                    dc_voltage_on=False,
                    ac_voltage_on=False,
                    current_vpp=None,
                    current_slope_side="",
                )
                stage.run_with_display(
                    live_view,
                    prepare_optics_for_stage_alignment,
                    hwp_angles=hwp_angles,
                    rot_hwp=rot_hwp,
                    rot_qwp=rot_qwp,
                    rot_anl=rot_anl,
                    null_seed_by_hwp=null_seed_by_hwp,
                    fallback_seed=fallback_seed,
                    funcgen=funcgen,
                    fast_rotator_moves=args.fast_rotator_moves,
                    verify_moves=args.verify_fast_rotator_moves,
                    verify_tol_deg=args.rotator_verify_tol,
                )
                gui_pixel_checkpoint()
                stage.run_with_display(
                    live_view,
                    gui_align_and_capture_pixel,
                    pix_num - 1,
                    pixel,
                    pixels,
                    total,
                    n_done,
                    device_x,
                    device_y,
                    stage_detector,
                    live_view,
                    args,
                    rot_anl,
                )
                gui_pixel_checkpoint()
                stage.save_json(pixels, sum(1 for p in pixels if p.get("calibrated_x_motor") is not None))
                stage.save_csv(pixels)

                if args.manual_probing:
                    channel = None
                else:
                    channel = stage.pixel_to_channel(pix_num)
                record["channel"] = channel
                record["manual_probing"] = bool(args.manual_probing)
                pixel["arduino_channel"] = channel
                pixel["manual_probing"] = bool(args.manual_probing)
                pixel["fast_map_output_dir"] = str(pixel_dir)
                if args.manual_probing:
                    arduino_route = "manual probe connection (Arduino disabled)"
                    print(
                        f"  [MANUAL PROBE] Pixel {pix_num:03d}: Arduino switch matrix is disabled; "
                        "connect the bias-tee output directly to the probes."
                    )
                elif channel is None:
                    arduino_route = "unmapped switch-matrix pin/channel"
                    print(f"  [Arduino] Pixel {pix_num:03d}: no mapped switch-matrix pin/channel")
                elif switch_matrix is None:
                    arduino_route = f"switch-matrix pin/channel {channel} (Arduino disabled)"
                    print(f"  [Arduino] Pixel {pix_num:03d}: mapped to switch-matrix pin/channel {channel} (Arduino disabled)")
                else:
                    arduino_route = f"switch-matrix pin/channel {channel}"
                    print(f"  [Arduino] Pixel {pix_num:03d}: enabling {arduino_route}")
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_sequence=seq,
                    selected_pixel_count=len(pixel_work_queue),
                    arduino_channel=channel,
                    arduino_pin=channel,
                    manual_probing=bool(args.manual_probing),
                    phase=f"Manual probing {arduino_route}" if args.manual_probing else f"Routing Arduino {arduino_route}",
                )

                if args.manual_probing:
                    gui_wait_for_manual_probe(pix_num, live_view=live_view)
                    gui_pixel_checkpoint()

                if live_view is not None:
                    live_view.pause_scope_reads()

                pixel_t0 = time.time()
                component_errors: list[str] = []
                with auto.routed_arduino_channel(switch_matrix, channel, args.arduino_settle, require_off=True):
                    try:
                        peak = None
                        if chip_sweep_needed:
                            auto.smu_set_level_output_on(smu, args.poling_voltage)
                            gui_update_state(
                                current_pixel=pix_num,
                                pixel_sequence=seq,
                                selected_pixel_count=len(pixel_work_queue),
                                dc_voltage_on=True,
                                dc_voltage_v=float(args.poling_voltage),
                                ac_voltage_on=False,
                                current_vpp=None,
                                current_slope_side="",
                                phase="DC poling dwell",
                            )
                            print(
                                f"  SMU dwell up to {args.poling_dwell:.1f}s at "
                                f"{args.poling_voltage:+.1f} V"
                                + (
                                    " (adaptive plateau detection)"
                                    if bool(args.adaptive_poling) else ""
                                )
                            )
                            if bool(args.adaptive_poling):
                                sens_idx = adaptive_poling_dwell(
                                    args=args,
                                    pixel_dir=pixel_dir,
                                    live_view=live_view,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    rot_anl=rot_anl,
                                    sens_idx=sens_idx,
                                    null_seed_by_hwp=null_seed_by_hwp,
                                    hwp_angles=hwp_angles,
                                    fallback_seed=fallback_seed,
                                    voltages=voltages,
                                )
                            else:
                                gui_sleep(
                                    args.poling_dwell,
                                    live_view=live_view,
                                    phase="DC poling dwell",
                                    allow_skip=True,
                                )
                            gui_update_state(
                                current_pixel=pix_num,
                                dc_voltage_on=True,
                                dwell_remaining_s=None,
                                current_vpp=None,
                                current_slope_side="",
                                phase="Fast-map measurement",
                            )
                            sens_idx, fallback_seed, peak = stage.run_with_display(
                                live_view,
                                run_fast_map_for_pixel,
                                pixel=pixel,
                                pixel_dir=pixel_dir,
                                hwp_angles=hwp_angles,
                                voltages=voltages,
                                rot_hwp=rot_hwp,
                                rot_qwp=rot_qwp,
                                rot_anl=rot_anl,
                                detector=detector_adapter,
                                renull_detector=stage_detector,
                                lockin=lockin,
                                funcgen=funcgen,
                                sens_idx=sens_idx,
                                null_seed_by_hwp=null_seed_by_hwp,
                                fallback_seed=fallback_seed,
                                t_start=t_start,
                                reference_phase_deg=args.lockin_reference_phase,
                                qwp_readout_offset_deg=args.qwp_readout_offset,
                                renull_mode=args.renull_mode,
                                fast_rotator_moves=args.fast_rotator_moves,
                                verify_fast_rotator_moves=args.verify_fast_rotator_moves,
                                rotator_verify_tol_deg=args.rotator_verify_tol,
                                null_check_max_mV=args.null_check_max_mv,
                                null_certify_margin_mV=args.null_certify_margin_mv,
                                progress=progress,
                                sim_state=sim_state if use_fake_lockin else None,
                                manual_peak_raw=pixel_manual_peak_raw,
                                manual_peak_only=bool(args.manual_peak_only),
                                auto_peak_calibration=bool(pixel_auto_peak_calibration),
                                peak_readout_required=bool(peak_readout_required),
                                auto_peak_max_coarse_probes=int(args.auto_peak_max_coarse_probes),
                                auto_peak_track_mode=str(args.auto_peak_track_mode),
                                learned_readout_mode=str(args.learned_readout_mode),
                                peak_diagnostic=bool(args.peak_diagnostic),
                                peak_diagnostic_step_deg=float(args.peak_diagnostic_step),
                                peak_diagnostic_min_margin_uV=float(
                                    args.peak_diagnostic_min_margin_uv
                                ),
                            )
                        else:
                            print(
                                f"  [RESUME] Pixel {pix_num:03d}: reusing saved "
                                "fast-map sweep and peak rows."
                            )
                        summary, peak, summary_is_derived = (
                            load_fast_map_resume_artifacts(
                                pixel=pixel,
                                pixel_dir=pixel_dir,
                                peak_conditions=peak,
                            )
                        )
                        if summary_is_derived:
                            print(
                                f"  [RESUME] Pixel {pix_num:03d}: "
                                f"{FAST_MAP_SUMMARY_JSON} is absent; using "
                                f"saved {FAST_MAP_CSV} peak metadata in memory "
                                "(no chip sweep rerun)."
                            )
                        pixel["fast_map_summary"] = summary
                        pixel["peak_response"] = peak
                        if pix_num in post_analyser_pixels:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_analyser_sweeps,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    vpp_values=post_analyser_vpp_values,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    dc_hold_v=float(args.post_analyser_sweep_dc_hold),
                                    poling_dwell_s=float(args.post_analyser_sweep_dwell),
                                    anl_start=float(args.post_analyser_sweep_start),
                                    anl_stop=float(args.post_analyser_sweep_stop),
                                    anl_step=float(args.post_analyser_sweep_step),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                    peak_hwp_only=bool(args.post_analyser_sweep_peak_only),
                                )
                                post_analyser_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} post-map analyser sweep",
                                )
                                component_errors.append(
                                    f"analyser follow-up: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map analyser sweep failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                        if pix_num in post_ac_pixels:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_ac_vpp_sweep,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    peak_conditions=peak,
                                    vpp_values=post_ac_vpp_values,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    dc_hold_v=float(args.post_ac_vpp_sweep_dc_hold),
                                    pre_measure_dwell_s=float(args.post_ac_vpp_sweep_dwell),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                )
                                post_ac_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} post-map AC Vpp sweep",
                                )
                                component_errors.append(
                                    f"AC Vpp follow-up: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map AC Vpp sweep failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                        if dc_hysteresis_needed:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_dc_hysteresis_sweep,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    peak_conditions=peak,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    poling_dwell_s=float(args.post_dc_hysteresis_dwell),
                                    start_from_zero=bool(args.post_dc_hysteresis_start_from_zero),
                                    reset_domains=bool(args.post_dc_hysteresis_reset_domains),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                    vmax_v=float(args.post_dc_hysteresis_vmax),
                                    cycles=int(args.post_dc_hysteresis_cycles),
                                    voltage_step_v=(
                                        float(args.post_dc_hysteresis_voltage_step)
                                        if args.post_dc_hysteresis_voltage_step is not None
                                        else None
                                    ),
                                    ac_vpp=float(args.post_dc_hysteresis_ac_vpp),
                                    min_dwell_s=float(args.post_dc_hysteresis_min_dwell),
                                    adaptive_window=bool(args.post_dc_hysteresis_adaptive_window),
                                    quasi_static=bool(args.post_dc_hysteresis_quasi_static),
                                    lockin_tc_index=int(args.lockin_tc_index),
                                    lockin_sensitivity_index=int(args.lockin_sensitivity_index),
                                    dynamic_lockin_range=bool(
                                        args.post_dc_hysteresis_dynamic_lockin_range
                                    ),
                                )
                                gui_pixel_checkpoint()
                                if not dc_hysteresis_sweep_complete(pixel_dir):
                                    raise RuntimeError(
                                        "DC hysteresis returned without a completed "
                                        "main-sweep artifact"
                                    )
                                post_dc_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} post-map DC hysteresis",
                                )
                                component_errors.append(
                                    f"DC hysteresis: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map DC hysteresis failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                    finally:
                        ensure_fast_map_outputs_off(funcgen, smu, "before switching pins")
                        gui_update_state(dc_voltage_on=False, phase="Pixel cleanup")

                finished_at = datetime.now().isoformat()
                component_error_text = " | ".join(component_errors)
                components_complete = not component_errors
                if components_complete:
                    pixel["measurement_status"] = "complete"
                    pixel["measurement_completed"] = finished_at
                    pixel.pop("measurement_partial", None)
                    pixel.pop("measurement_error", None)
                    record["status"] = "complete"
                    record["error"] = ""
                else:
                    # A saved chip sweep is not the same thing as a completed
                    # pixel when one of its requested follow-ups failed.  Keep
                    # the pixel resumable and preserve the exact missing
                    # component instead of writing a false "complete" status.
                    pixel["measurement_status"] = "partial"
                    pixel["measurement_partial"] = finished_at
                    pixel["measurement_error"] = component_error_text
                    record["status"] = "partial"
                    record["error"] = component_error_text
                record["completed"] = finished_at
                record["calibrated_x_motor"] = pixel.get("calibrated_x_motor")
                record["calibrated_y_motor"] = pixel.get("calibrated_y_motor")
                summary = pixel.get("fast_map_summary", {})
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_sequence=seq,
                    selected_pixel_count=len(pixel_work_queue),
                    pixel_points_done=pixel_points_total,
                    pixel_total_points=pixel_points_total,
                    chip_points_done=int(progress.get("points_done", 0)),
                    chip_total_points=total_points,
                    dc_voltage_on=False,
                    ac_voltage_on=False,
                    manual_probe_waiting=False,
                    current_vpp=None,
                    current_slope_side="",
                    phase=(
                        "Pixel complete"
                        if components_complete
                        else "Pixel partial: requested follow-up incomplete"
                    ),
                )
                rotation_slope = _finite_float_or_none(summary.get("rotation_slope_rad_per_Vrms"))
                r_eff = _finite_float_or_none(summary.get("r_eff_abs_pm_per_V"))
                physics_text = (
                    f" | |r_eff| {r_eff:.2f} pm/V"
                    if r_eff is not None
                    else (
                        f" | rotation {rotation_slope:.3e} rad/Vrms "
                        f"({summary.get('r_eff_status', 'not_calculated')})"
                        if rotation_slope is not None else ""
                    )
                )
                if components_complete:
                    print(
                        f"Pixel {pix_num:03d} complete | best HWP "
                        f"{summary.get('best_hwp_deg')} deg | "
                        f"theta_i {summary.get('best_theta_i_deg')} deg lab | "
                        f"max {float(summary.get('max_abs_signed_response_V', float('nan'))) * 1e6:.3f} uV"
                        f"{physics_text} | "
                        f"{(time.time() - pixel_t0) / 60.0:.1f} min"
                    )
                else:
                    print(
                        f"Pixel {pix_num:03d} partial | chip sweep saved | "
                        f"incomplete requested component(s): {component_error_text} | "
                        "will retry on resume"
                    )

            except KeyboardInterrupt:
                raise
            except SkipPixelRequested as exc:
                skipped_at = datetime.now().isoformat()
                print(f"\nPixel {pix_num:03d} skipped by operator request; continuing to next selected pixel.")
                gui_clear_skip_request()
                operator_skipped_pixels.add(int(pix_num))
                pixel["measurement_status"] = "skipped"
                pixel["measurement_skipped"] = skipped_at
                pixel["measurement_error"] = str(exc)
                record["status"] = "skipped"
                record["completed"] = skipped_at
                record["error"] = str(exc)
                try:
                    pockels._funcgen_set_sweep_output(funcgen, False)
                except Exception:
                    pass
                gui_update_state(ac_voltage_on=False, current_vpp=None, current_slope_side="")
                try:
                    auto.smu_output_off(smu, "after pixel skip")
                except Exception:
                    pass
                try:
                    if switch_matrix is not None:
                        switch_matrix.turn_all_off()
                except Exception:
                    pass
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_sequence=seq,
                    selected_pixel_count=len(pixel_work_queue),
                    dc_voltage_on=False,
                    ac_voltage_on=False,
                    manual_probe_waiting=False,
                    current_vpp=None,
                    current_slope_side="",
                    phase="Pixel skipped",
                )
            except Exception as exc:
                transport_failure = is_fatal_hardware_transport_error(exc)
                angle_failure = isinstance(exc, CriticalAngleError)
                hardware_recovery_needed = transport_failure or angle_failure
                transport_exc = (
                    exc
                    if isinstance(exc, CriticalHardwareTransportError)
                    else CriticalHardwareTransportError(
                        hardware_transport_stop_message(
                            exc, f"Pixel {pix_num:03d} measurement"
                        )
                    )
                    if transport_failure
                    else exc
                )
                error_tag = "HARDWARE TRANSPORT" if transport_failure else "ANGLE RECOVERY" if angle_failure else "ERROR"
                print(
                    f"\n[{error_tag}] Pixel {pix_num:03d} failed: "
                    f"{type(transport_exc).__name__}: {transport_exc}"
                )
                traceback.print_exc()
                failed_at = datetime.now().isoformat()
                saved_fast_map = bool(
                    hardware_recovery_needed and fast_map_sweep_complete(pixel_dir)
                )
                pixel["measurement_status"] = (
                    "partial" if saved_fast_map else "failed"
                )
                if saved_fast_map:
                    pixel["measurement_partial"] = failed_at
                pixel["measurement_error"] = (
                    f"{type(transport_exc).__name__}: {transport_exc}"
                )
                record["status"] = pixel["measurement_status"]
                record["error"] = pixel["measurement_error"]
                try:
                    pockels._funcgen_set_sweep_output(funcgen, False)
                except Exception:
                    pass
                gui_update_state(ac_voltage_on=False, current_vpp=None, current_slope_side="")
                try:
                    auto.smu_output_off(smu, "after pixel failure")
                except Exception:
                    pass
                gui_update_state(dc_voltage_on=False, manual_probe_waiting=False, phase="Pixel failed")
                try:
                    if switch_matrix is not None:
                        switch_matrix.turn_all_off()
                except Exception:
                    pass
                if hardware_recovery_needed:
                    recover_after_pixel_hardware_fault(pix_num, transport_exc)
                if isinstance(exc, CriticalNullError):
                    gui_update_state(
                        running=True,
                        phase=f"Pixel null/peak issue recorded; continuing: {exc}",
                    )
            finally:
                GUI_PIXEL_SKIP_ENABLED = False
                GUI_PIXEL_SKIP_LATCHED = False
                GUI_PIXEL_SKIP_ACKED = False
                if live_view is not None:
                    try:
                        live_view.resume_scope_reads()
                    except Exception:
                        pass
                write_chip_summary(root_dir, pixels)
                auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)

        # Every requested follow-up is already merged into pixel_work_queue.
        # A failed component remains resumable, but retrying it here would move
        # it behind all later pixels and recreate the old two-pass/non-numeric
        # ordering.  Only a future, genuinely unqueued follow-up may enter the
        # legacy safety-net block below.
        numerically_queued_followups = (
            set(int(pix) for pix in pixel_work_queue) & post_followup_pixels
        )
        incomplete_queued_followups = sorted(
            (
                (post_analyser_pixels - post_analyser_done)
                | (post_ac_pixels - post_ac_done)
                | (post_dc_pixels - post_dc_done)
            )
            & numerically_queued_followups
            - operator_skipped_pixels
        )
        if incomplete_queued_followups:
            print(
                "\n[INCOMPLETE] Follow-up component(s) failed in the numeric "
                "per-pixel queue and will be retried only on resume: "
                + _format_pixel_ranges(incomplete_queued_followups)
            )
        pending_analyser_pixels = (
            post_analyser_pixels
            - post_analyser_done
            - operator_skipped_pixels
            - numerically_queued_followups
        )
        pending_ac_pixels = (
            post_ac_pixels
            - post_ac_done
            - operator_skipped_pixels
            - numerically_queued_followups
        )
        pending_dc_pixels = (
            post_dc_pixels
            - post_dc_done
            - operator_skipped_pixels
            - numerically_queued_followups
        )
        pending_followup_pixels = sorted(pending_analyser_pixels | pending_ac_pixels | pending_dc_pixels)
        if pending_followup_pixels:
            print("\n" + "=" * 72)
            print("POST-MAP FOLLOW-UP-ONLY MEASUREMENTS")
            print("=" * 72)
            print(
                "These pixels will use saved fast-map peak conditions without rerunning "
                "the chip HWP sweep: "
                + _format_pixel_ranges(pending_followup_pixels)
            )

        for followup_seq, pix_num in enumerate(pending_followup_pixels, start=1):
            gui_stop_checkpoint()
            GUI_PIXEL_SKIP_ENABLED = True
            GUI_PIXEL_SKIP_LATCHED = False
            GUI_PIXEL_SKIP_ACKED = False
            gui_clear_skip_request()
            pixel = pixels[pix_num - 1]
            pixel_dir = pixels_dir / f"pixel_{pix_num:03d}"
            kinds = []
            if pix_num in pending_analyser_pixels:
                kinds.append("ANL")
            if pix_num in pending_ac_pixels:
                kinds.append("AC Vpp")
            if pix_num in pending_dc_pixels:
                kinds.append("DC hysteresis")
            print(
                f"\nFollow-up-only pixel {pix_num:03d} "
                f"({followup_seq}/{len(pending_followup_pixels)}): {', '.join(kinds)}"
            )

            try:
                followup_component_errors: list[str] = []
                if not pixel_dir.is_dir():
                    raise FileNotFoundError(
                        f"Pixel {pix_num:03d} has no saved fast-map folder in {pixels_dir}."
                    )

                prepare_optics_for_stage_alignment(
                    hwp_angles=hwp_angles,
                    rot_hwp=rot_hwp,
                    rot_qwp=rot_qwp,
                    rot_anl=rot_anl,
                    null_seed_by_hwp=null_seed_by_hwp,
                    fallback_seed=fallback_seed,
                    funcgen=funcgen,
                    fast_rotator_moves=args.fast_rotator_moves,
                    verify_moves=args.verify_fast_rotator_moves,
                    verify_tol_deg=args.rotator_verify_tol,
                )
                n_done = sum(1 for p in pixels if p.get("measurement_status") == "complete")
                stage.run_with_display(
                    live_view,
                    auto.align_and_capture_pixel,
                    pix_num - 1,
                    pixel,
                    pixels,
                    total,
                    n_done,
                    device_x,
                    device_y,
                    stage_detector,
                    live_view,
                    args,
                    rot_anl,
                )
                gui_pixel_checkpoint()
                stage.save_json(pixels, sum(1 for p in pixels if p.get("calibrated_x_motor") is not None))
                stage.save_csv(pixels)

                if args.manual_probing:
                    channel = None
                    print(
                        f"  [MANUAL PROBE] Pixel {pix_num:03d}: Arduino switch matrix is disabled; "
                        "connect the bias-tee output directly to the probes."
                    )
                else:
                    channel = stage.pixel_to_channel(pix_num)
                    if channel is None:
                        print(f"  [Arduino] Pixel {pix_num:03d}: no mapped switch-matrix pin/channel")
                    elif switch_matrix is None:
                        print(
                            f"  [Arduino] Pixel {pix_num:03d}: mapped to switch-matrix "
                            f"pin/channel {channel} (Arduino disabled)"
                        )
                    else:
                        print(f"  [Arduino] Pixel {pix_num:03d}: enabling switch-matrix pin/channel {channel}")
                pixel["arduino_channel"] = channel
                pixel["manual_probing"] = bool(args.manual_probing)
                gui_update_state(
                    current_pixel=pix_num,
                    pixel_sequence=followup_seq,
                    selected_pixel_count=len(pending_followup_pixels),
                    arduino_channel=channel,
                    arduino_pin=channel,
                    manual_probing=bool(args.manual_probing),
                    phase="Post-map follow-up setup",
                )

                if args.manual_probing:
                    gui_wait_for_manual_probe(pix_num, live_view=live_view)
                    gui_pixel_checkpoint()

                if live_view is not None:
                    live_view.pause_scope_reads()
                with auto.routed_arduino_channel(switch_matrix, channel, args.arduino_settle, require_off=True):
                    try:
                        if pix_num in pending_analyser_pixels:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_analyser_sweeps,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    vpp_values=post_analyser_vpp_values,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    dc_hold_v=float(args.post_analyser_sweep_dc_hold),
                                    poling_dwell_s=float(args.post_analyser_sweep_dwell),
                                    anl_start=float(args.post_analyser_sweep_start),
                                    anl_stop=float(args.post_analyser_sweep_stop),
                                    anl_step=float(args.post_analyser_sweep_step),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                    peak_hwp_only=bool(args.post_analyser_sweep_peak_only),
                                )
                                gui_pixel_checkpoint()
                                post_analyser_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} follow-up-only analyser sweep",
                                )
                                followup_component_errors.append(
                                    f"analyser sweep: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map analyser sweep failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                        if pix_num in pending_ac_pixels:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_ac_vpp_sweep,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    peak_conditions=None,
                                    vpp_values=post_ac_vpp_values,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    dc_hold_v=float(args.post_ac_vpp_sweep_dc_hold),
                                    pre_measure_dwell_s=float(args.post_ac_vpp_sweep_dwell),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                )
                                gui_pixel_checkpoint()
                                post_ac_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} follow-up-only AC Vpp sweep",
                                )
                                followup_component_errors.append(
                                    f"AC Vpp sweep: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map AC Vpp sweep failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                        if pix_num in pending_dc_pixels:
                            try:
                                sens_idx = stage.run_with_display(
                                    live_view,
                                    run_post_fast_map_dc_hysteresis_sweep,
                                    pixel=pixel,
                                    pixel_dir=pixel_dir,
                                    peak_conditions=None,
                                    rot_hwp=rot_hwp,
                                    rot_qwp=rot_qwp,
                                    rot_anl=rot_anl,
                                    detector=detector_adapter,
                                    lockin=lockin,
                                    funcgen=funcgen,
                                    smu=smu,
                                    sens_idx=sens_idx,
                                    poling_dwell_s=float(args.post_dc_hysteresis_dwell),
                                    start_from_zero=bool(args.post_dc_hysteresis_start_from_zero),
                                    reset_domains=bool(args.post_dc_hysteresis_reset_domains),
                                    fast_rotator_moves=bool(args.fast_rotator_moves),
                                    verify_moves=bool(args.verify_fast_rotator_moves),
                                    verify_tol_deg=float(args.rotator_verify_tol),
                                    vmax_v=float(args.post_dc_hysteresis_vmax),
                                    cycles=int(args.post_dc_hysteresis_cycles),
                                    voltage_step_v=(
                                        float(args.post_dc_hysteresis_voltage_step)
                                        if args.post_dc_hysteresis_voltage_step is not None
                                        else None
                                    ),
                                    ac_vpp=float(args.post_dc_hysteresis_ac_vpp),
                                    min_dwell_s=float(args.post_dc_hysteresis_min_dwell),
                                    adaptive_window=bool(args.post_dc_hysteresis_adaptive_window),
                                    quasi_static=bool(args.post_dc_hysteresis_quasi_static),
                                    lockin_tc_index=int(args.lockin_tc_index),
                                    lockin_sensitivity_index=int(args.lockin_sensitivity_index),
                                    dynamic_lockin_range=bool(
                                        args.post_dc_hysteresis_dynamic_lockin_range
                                    ),
                                )
                                gui_pixel_checkpoint()
                                if not dc_hysteresis_sweep_complete(pixel_dir):
                                    raise RuntimeError(
                                        "DC hysteresis returned without a completed "
                                        "main-sweep artifact"
                                    )
                                post_dc_done.add(int(pix_num))
                            except (SkipPixelRequested, CriticalAngleError):
                                raise
                            except Exception as exc:
                                raise_if_fatal_hardware_transport_error(
                                    exc,
                                    f"Pixel {pix_num:03d} follow-up-only DC hysteresis",
                                )
                                followup_component_errors.append(
                                    f"DC hysteresis: {type(exc).__name__}: {exc}"
                                )
                                print(
                                    f"\n[ERROR] Post-map DC hysteresis failed for pixel {pix_num:03d}: "
                                    f"{type(exc).__name__}: {exc}"
                                )
                                traceback.print_exc()
                    finally:
                        ensure_fast_map_outputs_off(funcgen, smu, "after follow-up-only pixel")
                        gui_update_state(dc_voltage_on=False, phase="Post-map follow-up cleanup")
                followup_finished_at = datetime.now().isoformat()
                if followup_component_errors:
                    error_text = " | ".join(followup_component_errors)
                    pixel["measurement_status"] = "partial"
                    pixel["measurement_partial"] = followup_finished_at
                    pixel["measurement_error"] = error_text
                    print(
                        f"Follow-up-only pixel {pix_num:03d} partial: {error_text} | "
                        "will retry on resume"
                    )
                else:
                    pixel["followup_measurement_completed"] = followup_finished_at
                    pixel["measurement_status"] = "complete"
                    pixel["measurement_completed"] = followup_finished_at
                    pixel.pop("measurement_partial", None)
                    pixel.pop("measurement_error", None)
            except KeyboardInterrupt:
                raise
            except SkipPixelRequested as exc:
                print(f"\nFollow-up-only pixel {pix_num:03d} skipped by operator request: {exc}")
                gui_clear_skip_request()
            except Exception as exc:
                transport_failure = is_fatal_hardware_transport_error(exc)
                angle_failure = isinstance(exc, CriticalAngleError)
                hardware_recovery_needed = transport_failure or angle_failure
                transport_exc = (
                    exc
                    if isinstance(exc, CriticalHardwareTransportError)
                    else CriticalHardwareTransportError(
                        hardware_transport_stop_message(
                            exc, f"Pixel {pix_num:03d} follow-up-only measurement"
                        )
                    )
                    if transport_failure
                    else exc
                )
                error_tag = "HARDWARE TRANSPORT" if transport_failure else "ANGLE RECOVERY" if angle_failure else "ERROR"
                print(
                    f"\n[{error_tag}] Follow-up-only pixel {pix_num:03d} failed: "
                    f"{type(transport_exc).__name__}: {transport_exc}"
                )
                traceback.print_exc()
                failed_at = datetime.now().isoformat()
                pixel["measurement_status"] = "partial"
                pixel["measurement_partial"] = failed_at
                pixel["measurement_error"] = (
                    f"{type(transport_exc).__name__}: {transport_exc}"
                )
                try:
                    pockels._funcgen_set_sweep_output(funcgen, False)
                except Exception:
                    pass
                try:
                    auto.smu_output_off(smu, "after follow-up-only failure")
                except Exception:
                    pass
                if hardware_recovery_needed:
                    recover_after_pixel_hardware_fault(pix_num, transport_exc)
            finally:
                GUI_PIXEL_SKIP_ENABLED = False
                GUI_PIXEL_SKIP_LATCHED = False
                GUI_PIXEL_SKIP_ACKED = False
                if live_view is not None:
                    try:
                        live_view.resume_scope_reads()
                    except Exception:
                        pass
                auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)

        incomplete_chip_pixels = sorted(
            int(pix)
            for pix in selected_pixels
            if (
                int(pix) not in operator_skipped_pixels
                and not fast_map_sweep_complete(
                    pixels_dir / f"pixel_{int(pix):03d}"
                )
            )
        )
        incomplete_dc_pixels = sorted(
            int(pix)
            for pix in post_dc_pixels
            if (
                int(pix) not in operator_skipped_pixels
                and not dc_hysteresis_sweep_complete(
                    pixels_dir / f"pixel_{int(pix):03d}"
                )
            )
        )
        incomplete_parts = []
        if incomplete_chip_pixels:
            incomplete_parts.append(
                "chip sweep " + _format_pixel_ranges(incomplete_chip_pixels)
            )
        if incomplete_dc_pixels:
            incomplete_parts.append(
                "DC hysteresis " + _format_pixel_ranges(incomplete_dc_pixels)
            )
        if incomplete_parts:
            final_phase = "Measurement finished with resumable incomplete components"
            print(
                "\n[INCOMPLETE] The run continued to the end, but these requested "
                "components remain resumable: "
                + "; ".join(incomplete_parts)
            )
            print(f"Data saved in: {root_dir}")
        else:
            final_phase = "Measurement complete"
            print(f"\nFast map complete. Data saved in: {root_dir}")
        gui_update_state(
            running=False,
            dc_voltage_on=False,
            ac_voltage_on=False,
            manual_probe_waiting=False,
            phase=final_phase,
            chip_points_done=int(progress.get("points_done", total_points)),
            chip_total_points=total_points,
        )
        return 0

    except KeyboardInterrupt:
        print("\n[INTERRUPTED] Saving progress and shutting down safely.")
        auto.save_progress(root_dir, pixels, records, null_seed_by_hwp, config)
        write_chip_summary(root_dir, pixels)
        gui_update_state(
            running=False,
            dc_voltage_on=False,
            ac_voltage_on=False,
            manual_probe_waiting=False,
            phase="Interrupted",
        )
        return 130
    finally:
        restore_console_noise(console_noise_state)
        gui_cleanup_laser()
        auto.cleanup_hardware(
            device_x=device_x,
            device_y=device_y,
            stage_detector=stage_detector,
            live_view=live_view,
            switch_matrix=switch_matrix,
            smu=smu,
            lockin=lockin,
            funcgen=funcgen,
            rotators=(r for r in (rot_hwp, rot_qwp, rot_anl) if r is not None),
        )
        gui_update_state(
            running=False,
            dc_voltage_on=False,
            ac_voltage_on=False,
            manual_probe_waiting=False,
            phase=GUI_STATE.get("phase", "Cleanup complete"),
        )


try:
    import tkinter as tk
    from tkinter import filedialog, messagebox, ttk
except Exception:
    tk = None
    ttk = None
    filedialog = None
    messagebox = None

try:
    from PIL import Image, ImageTk
except Exception:
    Image = None
    ImageTk = None


def _gui_float(value, default=0.0):
    try:
        return float(value)
    except Exception:
        return default


def _gui_int(value, default=0):
    try:
        return int(value)
    except Exception:
        return default


def lockin_history_key_value(pix: int, vpp) -> tuple[int, float | None]:
    vpp_value = _gui_float(vpp, float("nan"))
    return (
        int(pix),
        round(vpp_value, 6) if np.isfinite(vpp_value) else None,
    )


def record_lockin_history_row(
    history: dict,
    row: dict,
    *,
    source: str = "csv",
) -> bool:
    """Persist one lock-in row for the peripheral per-HWP response graph."""
    pix = _gui_int(row.get("pixel"), 0)
    hwp = _gui_float(row.get("hwp_deg"), float("nan"))
    mag_v = _gui_float(
        row.get("lockin_mag_V"),
        _gui_float(row.get("lockin_net_mag_V"), float("nan")),
    )
    if pix <= 0 or not np.isfinite(hwp) or not np.isfinite(mag_v):
        return False
    vpp = _gui_float(row.get("vpp"), float("nan"))
    key = lockin_history_key_value(pix, vpp)
    hwp_key = round(float(hwp), 6)
    sweep = history.setdefault(key, {})
    is_new = hwp_key not in sweep
    record = sweep.setdefault(
        hwp_key,
        {
            "hwp_deg": float(hwp),
            "vpp": vpp,
            "_order": len(sweep),
        },
    )
    theta_i = _gui_float(
        row.get("theta_i_deg"),
        theta_i_from_hwp(hwp),
    )
    if np.isfinite(theta_i):
        record["theta_i_deg"] = float(theta_i)
    side = str(row.get("slope_side", "") or "").strip()
    if not side:
        return is_new
    signed_v = _gui_float(
        row.get("lockin_signed_V"),
        _gui_float(row.get("lockin_net_signed_V"), float("nan")),
    )
    phase_deg = _gui_float(row.get("lockin_phase_deg"), float("nan"))
    side_record = record.setdefault(side, {})
    side_record["mag_uV"] = abs(float(mag_v)) * 1e6
    if np.isfinite(signed_v):
        side_record["signed_uV"] = float(signed_v) * 1e6
    if np.isfinite(phase_deg):
        side_record["phase_deg"] = float(phase_deg)
    side_record["source"] = str(source)
    side_record["updated_ts"] = time.time()
    return True


def best_available_hwp_response(record: dict) -> dict | None:
    """Choose one raw response point without discarding mixed readout modes.

    A calibrated/manual anchor is preferred when one was measured.  At HWP
    angles that only have the production +/-45 pair, the stronger raw
    magnitude is retained.  Quality flags do not suppress this live/raw
    diagnostic trace; certified scientific selection remains separate.
    """
    preferred = (
        ("manual_anchor", "manual anchor"),
        ("auto_peak", "auto peak"),
        ("learned_anchor", "learned anchor"),
        ("manual_peak", "manual raw"),
    )
    for key, label in preferred:
        entry = record.get(key) if isinstance(record.get(key), dict) else {}
        magnitude = _gui_float(entry.get("mag_uV"), float("nan"))
        if np.isfinite(magnitude):
            return {
                "key": key,
                "label": label,
                "mag_uV": abs(float(magnitude)),
            }

    fallback = []
    for key, label in (
        ("plus45", "+45 fallback"),
        ("minus45", "-45 fallback"),
        ("learned_opposite", "learned opposite fallback"),
    ):
        entry = record.get(key) if isinstance(record.get(key), dict) else {}
        magnitude = _gui_float(entry.get("mag_uV"), float("nan"))
        if np.isfinite(magnitude):
            fallback.append((abs(float(magnitude)), key, label))
    if not fallback:
        return None
    magnitude, key, label = max(fallback, key=lambda item: item[0])
    return {"key": key, "label": label, "mag_uV": magnitude}


def unwrap_hwp_sweep_degrees(raw_angles) -> list[float]:
    """Unwrap a raw-HWP acquisition sequence across the 360/0 boundary."""
    result: list[float] = []
    for raw in raw_angles:
        value = _gui_float(raw, float("nan"))
        if not np.isfinite(value):
            continue
        value = float(value) % 360.0
        if not result:
            result.append(value)
            continue
        previous = result[-1]
        delta = (value - (previous % 360.0) + 540.0) % 360.0 - 180.0
        result.append(previous + delta)
    return result


def _gui_resolve_path(base_dir: Path, raw: str) -> Path:
    path = Path(str(raw).strip()).expanduser()
    if not path.is_absolute():
        path = base_dir / path
    return path.resolve()


def _gui_format_number(value) -> str:
    try:
        value = float(value)
    except Exception:
        return str(value)
    if not np.isfinite(value):
        return str(value)
    return f"{value:g}"


def _gui_format_number_list(values) -> str:
    return ",".join(_gui_format_number(v) for v in values)


def _parse_gui_number_list(raw: str, *, label: str) -> list[float]:
    values: list[float] = []
    for part in str(raw or "").replace(";", ",").split(","):
        item = part.strip()
        if not item:
            continue
        try:
            values.append(float(item))
        except ValueError as exc:
            raise ValueError(f"{label} must be a comma-separated numeric list.") from exc
    if not values:
        raise ValueError(f"{label} must contain at least one value.")
    return values


def _format_pixel_ranges(pixels: list[int] | set[int] | tuple[int, ...]) -> str:
    vals = sorted({int(p) for p in pixels if int(p) > 0})
    if not vals:
        return ""
    ranges: list[str] = []
    start = prev = vals[0]
    for pix in vals[1:]:
        if pix == prev + 1:
            prev = pix
            continue
        ranges.append(str(start) if start == prev else f"{start}-{prev}")
        start = prev = pix
    ranges.append(str(start) if start == prev else f"{start}-{prev}")
    return ",".join(ranges)


def _read_json_dict(path: Path) -> dict:
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
    except Exception:
        return {}
    return data if isinstance(data, dict) else {}


def null_seed_table_covers_hwp_angles(path: Path, hwp_angles) -> bool:
    """Return whether a saved seed table has usable nulls for every HWP."""
    table = _read_json_dict(Path(path))
    angles = [] if hwp_angles is None else list(hwp_angles)
    if not angles:
        return bool(table)
    for angle in angles:
        numeric_angle = _finite_float_or_none(angle)
        if numeric_angle is None:
            return False
        entry = table.get(f"{float(numeric_angle):.3f}")
        if not isinstance(entry, dict):
            return False
        if _finite_float_or_none(entry.get("q_null_deg")) is None:
            return False
        if _finite_float_or_none(entry.get("a_null_deg")) is None:
            return False
    return True


def fast_map_sweep_complete(pixel_dir: Path) -> bool:
    """Return True only when the per-pixel chip sweep reached its save point."""
    pixel_dir = Path(pixel_dir)
    csv_path = pixel_dir / FAST_MAP_CSV
    summary_path = pixel_dir / FAST_MAP_SUMMARY_JSON
    if not csv_path.is_file() or not summary_path.is_file():
        return False
    if not _read_json_dict(summary_path):
        return False
    try:
        with csv_path.open("r", newline="") as handle:
            return next(csv.DictReader(handle), None) is not None
    except Exception:
        return False


def dc_hysteresis_sweep_complete(pixel_dir: Path) -> bool:
    """Return True only for a completed main DC hysteresis acquisition."""
    pixel_dir = Path(pixel_dir)
    hyst_root = pixel_dir / "dc_hysteresis"
    live = _read_json_dict(hyst_root / pockels.DC_HYSTERESIS_LIVE_JSON)
    if (
        bool(live.get("complete"))
        and str(live.get("event", "")).strip().lower() == "complete"
        and str(live.get("sweep_stage", "main")).strip().lower() == "main"
    ):
        return True

    # Older completed runs may pre-date the live-completion marker.  The main
    # CSV is written only after every trajectory point has been acquired and
    # the SMU has been ramped back to zero; partial live sweeps do not create it.
    csv_path = hyst_root / "sweep" / "dc_hysteresis.csv"
    if not csv_path.is_file():
        return False
    try:
        with csv_path.open("r", newline="") as handle:
            rows = (
                line for line in handle
                if line.strip() and not line.lstrip().startswith("#")
            )
            next(rows)  # header
            return next(rows, None) is not None
    except Exception:
        return False


def historical_hysteresis_plan_matches_peak(pixel_dir: Path, peak: dict) -> bool:
    """Return whether the canonical hysteresis folder used this exact peak."""
    plan = _read_json_dict(
        Path(pixel_dir) / "dc_hysteresis" / "dc_hysteresis_plan.json"
    )
    saved_peak = plan.get("peak") if isinstance(plan.get("peak"), dict) else {}
    comparisons = (
        ("hwp_deg", 1e-7),
        ("qwp_angle", 1e-7),
        ("anl_angle", 1e-7),
        ("mag", 1e-12),
    )
    for key, abs_tol in comparisons:
        saved_value = _finite_float_or_none(saved_peak.get(key))
        requested_value = _finite_float_or_none(peak.get(key))
        if saved_value is None or requested_value is None:
            return False
        if not math.isclose(
            float(saved_value),
            float(requested_value),
            rel_tol=1e-9,
            abs_tol=float(abs_tol),
        ):
            return False
    return True


def archive_mismatched_historical_hysteresis(pixel_dir: Path) -> Path | None:
    """Move a previous different-peak hysteresis aside without deleting it."""
    pixel_dir = Path(pixel_dir)
    source = pixel_dir / "dc_hysteresis"
    if not source.is_dir():
        return None
    stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
    target = pixel_dir / f"dc_hysteresis_previous_peak_{stamp}"
    suffix = 1
    while target.exists():
        target = pixel_dir / f"dc_hysteresis_previous_peak_{stamp}_{suffix:02d}"
        suffix += 1
    source.rename(target)
    return target


def resume_pixel_component_needs(
    pixel_dir: Path,
    *,
    chip_sweep_requested: bool = True,
    dc_hysteresis_requested: bool,
    skip_complete: bool,
) -> tuple[bool, bool]:
    """Return ``(chip_sweep_needed, dc_hysteresis_needed)`` for one pixel.

    The ordering contract is deliberately pixel-local: acquire a missing chip
    sweep first and then its requested hysteresis; if only hysteresis is
    missing, reuse the saved chip sweep and run hysteresis at this pixel's
    normal position in the queue.
    """
    if not bool(chip_sweep_requested):
        return (
            False,
            bool(dc_hysteresis_requested)
            and (
                not bool(skip_complete)
                or not dc_hysteresis_sweep_complete(pixel_dir)
            ),
        )
    if not bool(skip_complete):
        return True, bool(dc_hysteresis_requested)
    chip_sweep_needed = not fast_map_sweep_complete(pixel_dir)
    dc_hysteresis_needed = bool(dc_hysteresis_requested) and (
        chip_sweep_needed or not dc_hysteresis_sweep_complete(pixel_dir)
    )
    return chip_sweep_needed, dc_hysteresis_needed


def ordered_pixel_work_queue(
    chip_sweep_pixels,
    *followup_pixel_groups,
    first_pixel: int | None = None,
) -> list[int]:
    """Merge selections, optionally putting a calibration pixel first."""
    queue = {
        int(pix)
        for pix in chip_sweep_pixels
        if int(pix) > 0
    }
    for group in followup_pixel_groups:
        queue.update(
            int(pix)
            for pix in group
            if int(pix) > 0
        )
    ordered = sorted(queue)
    if first_pixel is not None and int(first_pixel) in queue:
        first = int(first_pixel)
        ordered = [first] + [pixel for pixel in ordered if pixel != first]
    return ordered


def _fast_map_run_marker_files(run_dir: Path) -> list[Path]:
    markers = [
        run_dir / "run_config.json",
        run_dir / auto.PROGRESS_JSON,
        run_dir / CHIP_SUMMARY_CSV,
        run_dir / auto.NULL_SEEDS_JSON,
        run_dir / auto.SUBSTRATE_CAL_FILENAME,
        run_dir / "loaded_optical_calibration.json",
    ]
    pixels_dir = run_dir / auto.DEFAULT_PIXELS_SUBDIR
    if pixels_dir.is_dir():
        markers.extend(pixels_dir.glob(f"pixel_*/{FAST_MAP_CSV}"))
        markers.extend(pixels_dir.glob(f"pixel_*/{FAST_MAP_SUMMARY_JSON}"))
    return [path for path in markers if path.exists()]


def find_latest_fast_map_run(repo_dir: Path) -> Path | None:
    root = repo_dir / OUTDIR_ROOT
    if not root.is_dir():
        return None
    candidates: list[tuple[float, Path]] = []
    for run_dir in root.iterdir():
        if not run_dir.is_dir():
            continue
        markers = _fast_map_run_marker_files(run_dir)
        if not markers:
            continue
        if not (
            (run_dir / auto.PROGRESS_JSON).exists()
            or (run_dir / "run_config.json").exists()
            or (run_dir / CHIP_SUMMARY_CSV).exists()
            or (run_dir / auto.DEFAULT_PIXELS_SUBDIR).is_dir()
        ):
            continue
        try:
            mtime = max(path.stat().st_mtime for path in markers)
        except Exception:
            continue
        candidates.append((mtime, run_dir.resolve()))
    if not candidates:
        return None
    return max(candidates, key=lambda item: item[0])[1]


def summarize_fast_map_run(run_dir: Path) -> dict:
    run_dir = Path(run_dir).expanduser().resolve()
    data = _read_json_dict(run_dir / auto.PROGRESS_JSON)
    run_config = _read_json_dict(run_dir / "run_config.json")
    progress_config = data.get("config") if isinstance(data.get("config"), dict) else {}
    config = dict(run_config)
    config.update(progress_config)
    pixels = data.get("pixels") if isinstance(data.get("pixels"), list) else []
    records = data.get("pixel_records") if isinstance(data.get("pixel_records"), list) else []

    selected = []
    if isinstance(config.get("selected_pixels"), list):
        selected = [_gui_int(p, 0) for p in config.get("selected_pixels", [])]
        selected = [p for p in selected if p > 0]

    statuses: dict[int, str] = {}
    for pixel in pixels:
        if not isinstance(pixel, dict):
            continue
        pix = _gui_int(pixel.get("pixel"), 0)
        status = str(pixel.get("measurement_status", "") or "").strip().lower()
        if pix and status:
            statuses[pix] = status
    for record in records:
        if not isinstance(record, dict):
            continue
        pix = _gui_int(record.get("pixel"), 0)
        status = str(record.get("status", "") or "").strip().lower()
        if pix and status and statuses.get(pix) != "complete":
            statuses[pix] = status

    summary_completed: set[int] = set()
    summary_path = run_dir / CHIP_SUMMARY_CSV
    if summary_path.is_file():
        try:
            with summary_path.open("r", newline="") as f:
                for row in csv.DictReader(f):
                    pix = _gui_int(row.get("pixel"), 0)
                    if pix and str(row.get("status", "") or "").strip().lower() == "complete":
                        summary_completed.add(pix)
        except Exception:
            pass

    pixel_csvs: set[int] = set()
    pixel_summaries: set[int] = set()
    chip_sweep_completed: set[int] = set()
    dc_hysteresis_completed: set[int] = set()
    pixels_dir = run_dir / auto.DEFAULT_PIXELS_SUBDIR
    if pixels_dir.is_dir():
        for csv_path in pixels_dir.glob(f"pixel_*/{FAST_MAP_CSV}"):
            try:
                pixel_csvs.add(int(csv_path.parent.name.split("_", 1)[1]))
            except Exception:
                pass
        for json_path in pixels_dir.glob(f"pixel_*/{FAST_MAP_SUMMARY_JSON}"):
            try:
                pixel_summaries.add(int(json_path.parent.name.split("_", 1)[1]))
            except Exception:
                pass
        for pixel_dir in pixels_dir.glob("pixel_*"):
            if not pixel_dir.is_dir():
                continue
            try:
                pix = int(pixel_dir.name.split("_", 1)[1])
            except Exception:
                continue
            if fast_map_sweep_complete(pixel_dir):
                chip_sweep_completed.add(pix)
            if dc_hysteresis_sweep_complete(pixel_dir):
                dc_hysteresis_completed.add(pix)

    requested_dc_pixels = {
        _gui_int(value, 0)
        for value in config.get("post_dc_hysteresis_pixels", [])
    } if isinstance(config.get("post_dc_hysteresis_pixels"), list) else set()
    requested_dc_pixels.discard(0)

    # "Complete" on resume means every requested component is present on
    # disk. Persisted measurement_status alone is not authoritative: older
    # code could mark a pixel complete after a failed/missing hysteresis.
    completed = {
        pix for pix in chip_sweep_completed
        if pix not in requested_dc_pixels or pix in dc_hysteresis_completed
    }
    failed = {pix for pix, status in statuses.items() if status == "failed" and pix not in completed}
    started = {
        pix for pix, status in statuses.items()
        if status in {"started", "partial"} and pix not in completed
    }
    started.update(pixel_csvs - chip_sweep_completed)

    max_seen = max(
        [
            0,
            len(pixels),
            *selected,
            *statuses.keys(),
            *summary_completed,
            *pixel_csvs,
            *pixel_summaries,
            *requested_dc_pixels,
            *dc_hysteresis_completed,
        ]
    )
    total_pixels = max_seen or 100
    if not selected:
        selected = list(range(1, total_pixels + 1))

    # Build one numerically ordered resume queue across component types.  This
    # also pulls in a DC-only selection outside the original chip-pixel list
    # when that pixel already has the prerequisite chip sweep on disk.
    hysteresis_only = sorted(
        requested_dc_pixels
        & chip_sweep_completed
        - dc_hysteresis_completed
    )
    remaining = sorted(
        {pix for pix in selected if pix not in completed}
        | set(hysteresis_only)
    )
    unmeasured = sorted(
        pix for pix in selected
        if pix not in chip_sweep_completed
    )
    first_incomplete = min(remaining) if remaining else None

    loaded_optical = _read_json_dict(run_dir / "loaded_optical_calibration.json")
    optical_source = str(loaded_optical.get("source", "") or "").strip()
    stage_cal_path = run_dir / auto.DEFAULT_STAGE_SUBDIR / "pixel_positions.json"
    substrate_cal_path = run_dir / auto.SUBSTRATE_CAL_FILENAME
    null_seed_path = run_dir / auto.NULL_SEEDS_JSON
    seed_hwp_angles = config.get("hwp_raw_angles_deg")
    if not isinstance(seed_hwp_angles, list) or not seed_hwp_angles:
        seed_hwp_angles = config.get("hwp_angles_deg")
    if not isinstance(seed_hwp_angles, list):
        seed_hwp_angles = []
    null_seed_complete = null_seed_table_covers_hwp_angles(
        null_seed_path,
        seed_hwp_angles,
    )

    return {
        "path": run_dir,
        "config": config,
        "total_pixels": total_pixels,
        "selected_pixels": selected,
        "completed_pixels": sorted(completed),
        "chip_sweep_completed_pixels": sorted(chip_sweep_completed),
        "dc_hysteresis_requested_pixels": sorted(requested_dc_pixels),
        "dc_hysteresis_completed_pixels": sorted(dc_hysteresis_completed),
        "hysteresis_only_pixels": hysteresis_only,
        "failed_pixels": sorted(failed),
        "started_pixels": sorted(started),
        "remaining_pixels": remaining,
        "unmeasured_pixels": unmeasured,
        "first_incomplete_pixel": first_incomplete,
        "last_completed_pixel": max(completed) if completed else None,
        "last_reached_pixel": max(completed | started) if (completed or started) else None,
        "substrate_cal_path": substrate_cal_path if substrate_cal_path.exists() else None,
        "null_seed_path": null_seed_path if null_seed_path.exists() else None,
        "null_seed_complete": bool(null_seed_complete),
        "stage_cal_path": stage_cal_path if stage_cal_path.exists() else None,
        "optical_cal_source": optical_source,
        "has_progress": bool(data),
        "has_run_config": bool(run_config),
    }


def configure_app_process_identity() -> None:
    """Set Windows taskbar grouping/icon identity before creating Tk windows."""
    if sys.platform != "win32":
        return
    try:
        import ctypes

        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID(APP_USER_MODEL_ID)
    except Exception:
        pass


def _square_icon_image(path: Path, size_px: int):
    if Image is None:
        return None
    with Image.open(path) as src:
        img = src.convert("RGBA")
    w, h = img.size
    side = max(1, min(w, h))
    left = max(0, (w - side) // 2)
    top = max(0, (h - side) // 2)
    img = img.crop((left, top, left + side, top + side))
    resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", 1)
    return img.resize((size_px, size_px), resampling)


def _build_bto_go_ico(icon_path: Path) -> Path | None:
    ico_path = Path(__file__).resolve().with_name("bto_go_taskbar_icon.ico")
    if Image is None:
        return ico_path if ico_path.exists() else None
    icon_src = _square_icon_image(icon_path, 256)
    if icon_src is None:
        return None
    icon_src.save(
        ico_path,
        format="ICO",
        bitmap_format="bmp",
        sizes=[(16, 16), (24, 24), (32, 32), (48, 48), (64, 64), (128, 128), (256, 256)],
    )
    return ico_path


def _force_windows_window_icon(root, ico_path: Path) -> None:
    if sys.platform != "win32" or not ico_path.exists():
        return
    try:
        import ctypes
        from ctypes import wintypes

        root.update_idletasks()
        user32 = ctypes.windll.user32
        user32.LoadImageW.restype = wintypes.HANDLE
        user32.GetParent.argtypes = [wintypes.HWND]
        user32.GetParent.restype = wintypes.HWND
        user32.GetAncestor.argtypes = [wintypes.HWND, wintypes.UINT]
        user32.GetAncestor.restype = wintypes.HWND
        user32.SendMessageW.argtypes = [wintypes.HWND, wintypes.UINT, wintypes.WPARAM, wintypes.LPARAM]
        user32.SendMessageW.restype = wintypes.LPARAM
        hwnd = int(root.winfo_id())
        image_icon = 1
        lr_loadfromfile = 0x0010
        lr_defaultsize = 0x0040
        wm_seticon = 0x0080
        icon_small = 0
        icon_big = 1
        gwlp_hicon = -14
        gwlp_hiconsm = -34
        ga_root = 2

        hicon_big = user32.LoadImageW(None, str(ico_path), image_icon, 0, 0, lr_loadfromfile | lr_defaultsize)
        hicon_small = user32.LoadImageW(None, str(ico_path), image_icon, 16, 16, lr_loadfromfile)

        hwnds = {hwnd}
        try:
            parent = int(user32.GetParent(hwnd))
            if parent:
                hwnds.add(parent)
        except Exception:
            pass
        try:
            root_hwnd = int(user32.GetAncestor(hwnd, ga_root))
            if root_hwnd:
                hwnds.add(root_hwnd)
        except Exception:
            pass

        if sys.maxsize > 2**32:
            set_class_long = user32.SetClassLongPtrW
            set_class_long.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_longlong]
            set_class_long.restype = ctypes.c_longlong
        else:
            set_class_long = user32.SetClassLongW
            set_class_long.argtypes = [wintypes.HWND, ctypes.c_int, ctypes.c_long]
            set_class_long.restype = ctypes.c_long

        for target_hwnd in hwnds:
            if hicon_big:
                user32.SendMessageW(target_hwnd, wm_seticon, icon_big, hicon_big)
                try:
                    set_class_long(target_hwnd, gwlp_hicon, int(hicon_big))
                except Exception:
                    pass
            if hicon_small:
                user32.SendMessageW(target_hwnd, wm_seticon, icon_small, hicon_small)
                try:
                    set_class_long(target_hwnd, gwlp_hiconsm, int(hicon_small))
                except Exception:
                    pass

        if hicon_big:
            root._bto_go_hicon_big = hicon_big
        if hicon_small:
            root._bto_go_hicon_small = hicon_small
    except Exception:
        pass


def _apply_tk_icon(root, ico_path: Path | None, icon_photo=None) -> None:
    if ico_path is not None and ico_path.exists():
        for call in (
            lambda: root.iconbitmap(str(ico_path)),
            lambda: root.iconbitmap(default=str(ico_path)),
            lambda: root.wm_iconbitmap(str(ico_path)),
        ):
            try:
                call()
            except Exception:
                pass
    if icon_photo is not None:
        try:
            root.iconphoto(True, icon_photo)
        except Exception:
            pass


def configure_app_window(root) -> None:
    """Apply BTO GO! title and the hardcoded GDS/test-image icon to Tk."""
    try:
        root.title(APP_NAME)
    except Exception:
        pass

    icon_path = resolve_hardcoded_gds_image()
    if icon_path is None or not icon_path.exists() or tk is None:
        print("[GUI] BTO GO! icon image not found; using default Tk icon.")
        return

    try:
        ico_path = _build_bto_go_ico(icon_path) if sys.platform == "win32" else None
        icon_photo = None
        if Image is not None and ImageTk is not None:
            icon_img = _square_icon_image(icon_path, 64)
            if icon_img is None:
                return
            icon_photo = ImageTk.PhotoImage(icon_img)
            root._bto_go_icon_photo = icon_photo
        else:
            icon_photo = tk.PhotoImage(file=str(icon_path))
            root._bto_go_icon_photo = icon_photo

        _apply_tk_icon(root, ico_path, icon_photo)
        if ico_path is not None and ico_path.exists():
            root._bto_go_icon_ico = str(ico_path)

        if ico_path is not None:
            _force_windows_window_icon(root, ico_path)
            root.after(0, lambda p=ico_path, ph=icon_photo: (_apply_tk_icon(root, p, ph), _force_windows_window_icon(root, p)))
            root.after(250, lambda p=ico_path, ph=icon_photo: (_apply_tk_icon(root, p, ph), _force_windows_window_icon(root, p)))
            root.after(1000, lambda p=ico_path, ph=icon_photo: (_apply_tk_icon(root, p, ph), _force_windows_window_icon(root, p)))
            root.bind(
                "<Map>",
                lambda _event, p=ico_path, ph=icon_photo: (_apply_tk_icon(root, p, ph), _force_windows_window_icon(root, p)),
                add="+",
            )
    except Exception as exc:
        print(f"[GUI] Could not set BTO GO! window icon ({type(exc).__name__}: {exc})")


class ScrollableFrame(ttk.Frame):
    def __init__(self, parent):
        super().__init__(parent)
        self.canvas = tk.Canvas(self, highlightthickness=0, bg="#eef2f7")
        self.scrollbar = ttk.Scrollbar(self, orient="vertical", command=self.canvas.yview)
        self.content = ttk.Frame(self.canvas)
        self.content.bind(
            "<Configure>",
            lambda _event: self.canvas.configure(scrollregion=self.canvas.bbox("all")),
        )
        self.window_id = self.canvas.create_window((0, 0), window=self.content, anchor="nw")
        self.canvas.configure(yscrollcommand=self.scrollbar.set)
        self.canvas.grid(row=0, column=0, sticky="nsew")
        self.scrollbar.grid(row=0, column=1, sticky="ns")
        self.grid_rowconfigure(0, weight=1)
        self.grid_columnconfigure(0, weight=1)
        self.canvas.bind("<Configure>", self._on_canvas_resize)

    def _on_canvas_resize(self, event):
        self.canvas.itemconfigure(self.window_id, width=event.width)


class ToolTip:
    def __init__(self, widget, text: str, delay_ms: int = 450):
        self.widget = widget
        self.text = text
        self.delay_ms = delay_ms
        self._after_id = None
        self._tip = None
        widget.bind("<Enter>", self._schedule, add="+")
        widget.bind("<Leave>", self._hide, add="+")
        widget.bind("<ButtonPress>", self._hide, add="+")

    def _schedule(self, _event=None):
        self._cancel()
        self._after_id = self.widget.after(self.delay_ms, self._show)

    def _cancel(self):
        if self._after_id is not None:
            try:
                self.widget.after_cancel(self._after_id)
            except Exception:
                pass
            self._after_id = None

    def _show(self):
        if self._tip is not None:
            return
        x = self.widget.winfo_rootx() + 18
        y = self.widget.winfo_rooty() + self.widget.winfo_height() + 8
        self._tip = tk.Toplevel(self.widget)
        self._tip.wm_overrideredirect(True)
        self._tip.wm_geometry(f"+{x}+{y}")
        label = tk.Label(
            self._tip,
            text=self.text,
            justify="left",
            bg="#fff8d6",
            fg="#111827",
            relief="solid",
            borderwidth=1,
            padx=8,
            pady=5,
            wraplength=340,
        )
        label.pack()

    def _hide(self, _event=None):
        self._cancel()
        if self._tip is not None:
            try:
                self._tip.destroy()
            except Exception:
                pass
            self._tip = None


def add_tooltip(widget, text: str):
    ToolTip(widget, text)
    return widget


class LedIndicator(ttk.Frame):
    def __init__(self, parent, label: str):
        super().__init__(parent, style="Panel.TFrame")
        self.canvas = tk.Canvas(self, width=18, height=18, highlightthickness=0, bd=0, bg="#ffffff")
        self.canvas.grid(row=0, column=0, sticky="w", padx=(0, 6))
        self.label = ttk.Label(self, text=label, style="Panel.TLabel")
        self.label.grid(row=0, column=1, sticky="w")
        self._oval = self.canvas.create_oval(
            3,
            3,
            15,
            15,
            fill="#9ca3af",
            outline="#6b7280",
            width=1,
        )
        self._glow = self.canvas.create_oval(
            1,
            1,
            17,
            17,
            outline="",
            fill="",
        )
        self.canvas.tag_lower(self._glow, self._oval)
        self.set(False)

    def set(self, on: bool):
        if on:
            self.canvas.itemconfigure(self._glow, fill="#bbf7d0")
            self.canvas.itemconfigure(self._oval, fill="#22c55e", outline="#15803d")
        else:
            self.canvas.itemconfigure(self._glow, fill="")
            self.canvas.itemconfigure(self._oval, fill="#9ca3af", outline="#6b7280")


