    def _theme(self) -> dict:
        if self.vars["dark_mode"].get():
            return {
                "bg": "#0f172a",
                "surface": "#162033",
                "panel": "#111827",
                "canvas": "#0b1220",
                "plot": "#111827",
                "entry": "#0b1220",
                "border": "#334155",
                "grid": "#243244",
                "axis": "#cbd5e1",
                "text": "#e5e7eb",
                "muted": "#94a3b8",
                "accent": "#38bdf8",
                "accent_active": "#0ea5e9",
                "danger": "#ef4444",
                "danger_active": "#dc2626",
                "terminal_bg": "#050b14",
                "terminal_fg": "#d1d5db",
                "terminal_insert": "#e5e7eb",
                "disabled": "#1e293b",
                "button_active": "#26364f",
                "progress_trough": "#1e293b",
                "camera_bg": "#020617",
                "tooltip_bg": "#1e293b",
                "tooltip_fg": "#f8fafc",
            }
        return {
            "bg": "#eef2f7",
            "surface": "#f8fafc",
            "panel": "#ffffff",
            "canvas": "#f8fafc",
            "plot": "#ffffff",
            "entry": "#ffffff",
            "border": "#cbd5e1",
            "grid": "#e2e8f0",
            "axis": "#334155",
            "text": "#0f172a",
            "muted": "#475569",
            "accent": "#2563eb",
            "accent_active": "#1d4ed8",
            "danger": "#dc2626",
            "danger_active": "#b91c1c",
            "terminal_bg": "#111418",
            "terminal_fg": "#e8eaed",
            "terminal_insert": "#e8eaed",
            "disabled": "#f1f5f9",
            "button_active": "#e2e8f0",
            "progress_trough": "#e2e8f0",
            "camera_bg": "#111418",
            "tooltip_bg": "#fff8d6",
            "tooltip_fg": "#111827",
        }

    def _apply_theme(self, redraw: bool = False) -> None:
        p = self._theme()
        style = ttk.Style()
        try:
            style.theme_use("clam")
        except Exception:
            pass
        self.root.configure(bg=p["bg"])
        style.configure(".", font=("Segoe UI", 10), background=p["bg"], foreground=p["text"])
        style.configure("TFrame", background=p["bg"])
        style.configure("Panel.TFrame", background=p["panel"])
        style.configure("TLabel", background=p["bg"], foreground=p["text"])
        style.configure("Panel.TLabel", background=p["panel"], foreground=p["text"])
        style.configure("Muted.TLabel", background=p["bg"], foreground=p["muted"])
        style.configure("TCheckbutton", background=p["bg"], foreground=p["text"])
        style.map("TCheckbutton", background=[("active", p["surface"])], foreground=[("disabled", p["muted"])])
        style.configure("TLabelframe", background=p["panel"], bordercolor=p["border"], relief="solid")
        style.configure("TLabelframe.Label", background=p["panel"], foreground=p["text"], font=("Segoe UI", 10, "bold"))
        style.configure("TButton", padding=(10, 6), background=p["surface"], foreground=p["text"], bordercolor=p["border"])
        style.map("TButton", background=[("active", p["button_active"]), ("disabled", p["disabled"])], foreground=[("disabled", p["muted"])])
        style.configure("Accent.TButton", background=p["accent"], foreground="#ffffff", bordercolor=p["accent"])
        style.map("Accent.TButton", background=[("active", p["accent_active"]), ("disabled", "#93c5fd")])
        style.configure("Danger.TButton", background=p["danger"], foreground="#ffffff", bordercolor=p["danger"])
        style.map("Danger.TButton", background=[("active", p["danger_active"]), ("disabled", "#7f1d1d")])
        style.configure("TEntry", fieldbackground=p["entry"], foreground=p["text"], insertcolor=p["text"], bordercolor=p["border"])
        style.configure("TCombobox", fieldbackground=p["entry"], foreground=p["text"], background=p["surface"], bordercolor=p["border"], arrowcolor=p["muted"])
        style.map("TCombobox", fieldbackground=[("readonly", p["entry"])], foreground=[("readonly", p["text"])])
        style.configure("Horizontal.TProgressbar", troughcolor=p["progress_trough"], background=p["accent"], bordercolor=p["progress_trough"], lightcolor=p["accent"], darkcolor=p["accent"])
        style.configure("Vertical.TScrollbar", background=p["border"], troughcolor=p["progress_trough"], bordercolor=p["progress_trough"], arrowcolor=p["muted"])
        if hasattr(self, "terminal"):
            self.terminal.configure(bg=p["terminal_bg"], fg=p["terminal_fg"], insertbackground=p["terminal_insert"])
        if hasattr(self, "notice_text"):
            self.notice_text.configure(bg=p["terminal_bg"], fg=p["terminal_fg"], insertbackground=p["terminal_insert"])
            self._configure_notice_tags()
        for name in ("plc_canvas", "map_canvas", "alignment_canvas", "lockin_canvas", "diagnostic_canvas"):
            if hasattr(self, name):
                getattr(self, name).configure(bg=p["canvas"])
        if hasattr(self, "camera_canvas"):
            self.camera_canvas.configure(bg=p["camera_bg"])
        if hasattr(self, "controls_scroll"):
            self.controls_scroll.canvas.configure(bg=p["bg"])
        for led_name in ("dc_led", "ac_led", "laser_led"):
            led = getattr(self, led_name, None)
            if led is not None:
                led.configure(style="Panel.TFrame")
                led.canvas.configure(bg=p["panel"])
        if redraw:
            self._safe_draw_canvas(self._draw_heatmap, "map_canvas", "Chip map")
            self._safe_draw_canvas(self._draw_alignment_graph, "alignment_canvas", "Stage alignment")
            self._safe_draw_canvas(self._draw_lockin_graph, "lockin_canvas", "Lock-in graph")
            self._safe_draw_canvas(self._draw_plc_panel, "plc_canvas", "Optical train")
            self._safe_draw_canvas(self._draw_detector_diagnostic, "diagnostic_canvas", "Oscilloscope")
            if self.camera_frame_file and self.camera_frame_file.exists():
                self._safe_draw_canvas(self._draw_camera_frame, "camera_canvas", "Camera")
            else:
                self._safe_draw_canvas(self._draw_camera_placeholder, "camera_canvas", "Camera")

    def _toggle_theme(self):
        self._apply_theme(redraw=True)

